def modell_faktoren(spot: Optional["Spot"]) -> Dict[str, float]:
    """Korrekturfaktoren je Modell für einen Spot (None = Referenz Kiel Leuchtturm, also Ostsee)."""
    rid = "ostsee" if spot is None else revier_von(spot)
    return {**MODELL_FAKTOR, **MODELL_FAKTOR_REVIER.get(rid, {})}


def _vorlauf_klasse(vorlauf_h: float) -> str:
    return next(k for a, b, k in [(0, 24, "0–24 h"), (24, 48, "24–48 h"), (48, 72, "48–72 h"), (72, 1e9, "72 h+")]
                if a <= max(0.0, vorlauf_h) < b)


def modell_faktor_vorlauf(rid: str, modell: str, basis: float, vorlauf_h: Optional[float]) -> float:
    """Faktor eines Modells bei gegebenem Vorlauf: MODELL_FAKTOR_VORLAUF, sonst der feste Faktor (basis)."""
    if vorlauf_h is None:
        return basis
    return ((MODELL_FAKTOR_VORLAUF.get(rid) or {}).get(modell) or {}).get(_vorlauf_klasse(vorlauf_h), basis)


def modell_gewichte(spot_name: str) -> Optional[Dict[str, float]]:
    """Gewichte des Spots: eigenes Profil (MODELL_PROFIL_SPOTS), sonst ein Profil mit der Revier-ID
    (z. B. MODELL_GEWICHTE["bodensee"]), sonst alle Modelle gleich."""
    profil = MODELL_PROFIL_SPOTS.get(spot_name)
    if profil is None:
        s = next((x for x in SPOTS if x.name == spot_name), None)
        profil = revier_von(s) if s is not None and revier_von(s) != "ostsee" else ""
    return MODELL_GEWICHTE.get(profil)


def _modell_gewicht(gewichte: Optional[Dict[str, float]], modell: str) -> float:
    if not gewichte:
        return 1.0
    if modell in gewichte:
        return gewichte[modell]
    if modell.startswith("ecmwf_ifs") and "ecmwf_ifs" in gewichte:
        return gewichte["ecmwf_ifs"]
    return 1.0

