FREIE_TAGE: set = set()        # Urlaub/Brückentage, z. B. {date(2026, 11, 2)}
FREIE_WOCHENTAGE: set = set()  # feste freie Wochentage, 0 = Montag … 4 = Freitag


def _ostersonntag(j: int) -> date:
    a, b, c = j % 19, j // 100, j % 100
    d_, e = b // 4, b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d_ - g + 15) % 30
    i, k = c // 4, c % 4
    l_ = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l_) // 451
    mon = (h + l_ - 7 * m + 114) // 31
    return date(j, mon, (h + l_ - 7 * m + 114) % 31 + 1)


def feiertage_sh(j: int) -> set:
    o = _ostersonntag(j)
    return {date(j, 1, 1), date(j, 5, 1), date(j, 10, 3), date(j, 10, 31), date(j, 12, 25), date(j, 12, 26),
            o - timedelta(days=2), o + timedelta(days=1), o + timedelta(days=39), o + timedelta(days=50)}


def ist_arbeitstag(tag: date) -> bool:
    return (tag.weekday() < 5 and tag not in FREIE_TAGE and tag.weekday() not in FREIE_WOCHENTAGE
            and tag not in feiertage_sh(tag.year))


WASSERSTART_SICHER = True    # True: Sicherheitsregeln (Stehbereich, ablandig, 5,7 im Tiefen) aus
                             # 29.10.2026: aus – Ranking nur nach Bedingungen, Entscheidung vor Ort liegt bei dir
# 25.10.26 Westerbergen: 5,3 + 85er bei angesagten 22–25 kn zu wenig (immer wieder abgesoffen), 5,3 + 105er ging.
# Das 85er trägt 90 kg nicht – es braucht Wind fürs 4,8er und kleiner.
BOARD_85_AB_KN = 27          # ab hier immer das 85er
BOARD_85_AB_KN_STEH = 26     # im Stehrevier schon ab hier
FINNE_85 = "Thruster 21 + 2×10"   # einzige Finne fürs 85er (auch bei Seegras)
KLEIN_SEGEL = 5.3            # Empfehlungen mit Segel bis zu dieser Größe werden hervorgehoben


def segel_wahl(w: float) -> Tuple[float, Optional[float]]:
    """Segel mit der besten Mitte für den Wind, dazu die Alternative
    (kleiner, wenn der Wind oben im Bereich liegt, sonst größer)."""
    verf = [s for s in SEGEL if s[0] in SEGEL_VORHANDEN
            and (GROESSTES_SEGEL is None or s[0] <= GROESSTES_SEGEL + 0.01)]
    best = min(verf, key=lambda s: abs(w - (s[1] + s[2]) / 2))
    i = verf.index(best)
    mitte = (best[1] + best[2]) / 2
    alt = None
    if w > mitte + 1 and i + 1 < len(verf):
        alt = verf[i + 1][0]
    elif w < mitte - 1 and i > 0:
        alt = verf[i - 1][0]
    return best[0], alt


def board_grenze(spot: Optional["Spot"] = None) -> int:
    return BOARD_85_AB_KN_STEH if (spot is not None and spot.stehbereich) else BOARD_85_AB_KN


BOEIG_FAKTOR = 1.45          # Böen ≥ so viel × Mittelwind: „böig“ (25.10.26 Westerbergen: 24/35 kn, Löcher und harte Böen)
BOEIG_BOARD_PLUS = 3         # bei böigem Wind das 85er erst so viele kn später (in den Löchern säuft es ab)


def board_wahl(w: float, spot: Optional["Spot"] = None, boe: Optional[float] = None) -> str:
    grenze = board_grenze(spot)
    if boe and w > 0 and boe / w >= BOEIG_FAKTOR:
        grenze += BOEIG_BOARD_PLUS
    if round(w) >= grenze:
        return "85er Wave"
    return "105er"


def finnen_wahl(spot: "Spot", art: str, w: float, board: str, monat: int) -> str:
    if board.startswith("85"):
        return FINNE_85
    if art.startswith("Welle"):
        return "Thruster 27 + 2×10" if w < 22 else "Thruster 23 + 2×10"
    if spot.seegras and monat in SEEGRAS_MONATE:
        return "28 Weed Wave" if w < 22 else "24 X-Weed"
    return "27 Single"


def qm(x: float) -> str:
    return f"{x:.1f}".replace(".", ",")


# =============================================================================
# SPOTS
# =============================================================================

KOMPASS = ["N", "NNO", "NO", "ONO", "O", "OSO", "SO", "SSO",
           "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"]


def kompass(grad: float) -> str:
    return KOMPASS[int(((grad % 360) + 11.25) // 22.5) % 16]


def richtung_text(richtungen) -> str:
    """Fasst Himmelsrichtungen zu Bereichen zusammen, z. B. 'NNO–O, SW'."""
    an = [k in richtungen for k in KOMPASS]
    if all(an):
        return "alle Richtungen"
    if not any(an):
        return ""
    start = next(i for i in range(16) if an[i] and not an[i - 1])   # Anfang eines Bereichs
    teile, i = [], start
    for _ in range(16):
        if an[i % 16] and not an[(i - 1) % 16]:
            j = i
            while an[(j + 1) % 16] and (j + 1) % 16 != i % 16:
                j += 1
            a, b = KOMPASS[i % 16], KOMPASS[j % 16]
            teile.append(a if a == b else f"{a}–{b}")
        i += 1
    return ", ".join(teile)


def bereich(von: str, bis: str) -> List[str]:
    """Himmelsrichtungen im Uhrzeigersinn von 'von' bis 'bis'."""
    i, j = KOMPASS.index(von), KOMPASS.index(bis)
    out = []
    while True:
        out.append(KOMPASS[i])
        if i == j:
            return out
        i = (i + 1) % 16


def R(*eintraege) -> Dict[str, Tuple[int, str, Optional[int]]]:
    """Richtungstabelle: (von, bis, Qualität 1–3, Charakter[, Stufe]).
    Bereiche laufen im Uhrzeigersinn, spätere Einträge überschreiben frühere."""
    d = {}
    for e in eintraege:
        von, bis, q, art = e[:4]
        stufe = e[4] if len(e) > 4 else None
        teil = bereich(von, bis)
        if len(teil) > 8:
            raise ValueError(f"Bereich {von}–{bis} ist größer als 180° – im Uhrzeigersinn angeben?")
        for k in teil:
            d[k] = (q, art, stufe)
    return d


@dataclass
class Spot:
    name: str
    lat: float
    lon: float
    fahrt_min: int
    richtungen: Dict[str, Tuple[int, str, Optional[int]]]
    stufe: int = 1
    seegras: bool = False        # Seegrasfinne sinnvoll (flache Stehgewässer vor Fehmarn)
    pegel: bool = False          # empfindlich für Niedrigwasser bei W/SW
    ost_duese: bool = False      # Eckernförder Bucht: Ostwind verstärkt
    stark: Optional[Tuple[float, str]] = None   # (ab kn, Hinweis)
    see_hoehe: float = 0.0       # Wasserspiegel über NN (Binnensee); für --punkte
    stehbereich: bool = False    # großer Stehbereich (für die 6,1er-Regel)
    strand: Optional[float] = None   # Richtung, in die der Strand aufs Wasser schaut (Grad)
    hinweise: List[str] = field(default_factory=list)

    def gruppe(self) -> str:
        if self.stufe > DEINE_STUFE:
            return "Für später"
        return "Alltag" if self.fahrt_min <= 45 else "Ausflug"


