def lage_zum_strand(spot: "Spot", wd: float) -> Optional[str]:
    """'auflandig' (inkl. schräg auflandig), 'seitlich' oder 'ablandig' (inkl. schräg ablandig)."""
    if spot.strand is None:
        return None
    diff = abs((wd - spot.strand + 180) % 360 - 180)
    return "auflandig" if diff <= 67.5 else ("seitlich" if diff <= 112.5 else "ablandig")

