API = "https://api.open-meteo.com/v1/forecast"
API_MARINE = "https://marine-api.open-meteo.com/v1/marine"
STUNDEN_VARS = ["wind_speed_10m", "wind_gusts_10m", "wind_direction_10m",
                "precipitation", "weather_code", "temperature_2m", "wind_speed_80m"]


@dataclass
class Stunde:
    t: datetime
    ws: float                 # Mittelwind (Modellmittel), kn
    wg: Optional[float]       # Böen, kn
    wd: float                 # Richtung, Grad (woher)
    pr: float                 # Niederschlag mm/h (Maximum der Modelle)
    wc: Optional[int]         # Wettercode (Maximum der Modelle)
    ws_min: float             # kleinster Modellwert
    ws_max: float             # größter Modellwert
    werte: Dict[str, float] = field(default_factory=dict)   # Mittelwind je Modell
    temp: Optional[float] = None                            # Lufttemperatur 2 m (Modellmittel), °C
    richt: Dict[str, float] = field(default_factory=dict)   # Richtung je Modell (Grad, woher)
    scher: Optional[float] = None                           # Wind 10 m / 80 m (Modelle mit 80-m-Wind), roh


@dataclass
class OrtDaten:
    stunden: List[Stunde]
    sonne: Dict[date, Tuple[datetime, datetime]]
    modelle: List[str]
    wellen: Dict[datetime, Tuple[float, Optional[float], Optional[float]]] = field(default_factory=dict)
    wasser: Dict[datetime, float] = field(default_factory=dict)   # Wassertemperatur °C
    meer: Dict[datetime, float] = field(default_factory=dict)     # Meeresspiegel Open-Meteo (cm, Modell)


PAKET_GROESSE = 8      # Orte pro Anfrage
TIMEOUT_S = 30
VERSUCHE = 4           # bei Überlastung/Timeout: Wartezeit 5, 10, 20 s
PAUSE_S = 0.5          # kurze Pause zwischen Anfragen, schont den Server


def _hole_modell(orte, modell: str, tage: int, info: str, zelle: str = "sea") -> list:
    """Ein Modell für alle Orte, in Paketen, mit Wiederholung."""
    pakete = [orte[i:i + PAKET_GROESSE] for i in range(0, len(orte), PAKET_GROESSE)]
    alles = []
    for n, paket in enumerate(pakete, 1):
        print(f"\r\033[2K{info} · Paket {n}/{len(pakete)}" + " " * 20, end="", file=sys.stderr, flush=True)
        for versuch in range(1, VERSUCHE + 1):
            try:
                time_mod.sleep(PAUSE_S)
                alles.extend(_hole_paket(paket, modell, tage, zelle))
                break
            except RuntimeError as e:
                if versuch == VERSUCHE or "meldet einen Fehler" in str(e) or isinstance(e, OmLimit):
                    raise
                warte = 5 * 2 ** (versuch - 1)
                print(f"\r\033[2K{info} · Paket {n}: {str(e)[:50]} – neuer Versuch in {warte} s …" + " " * 10,
                      end="", file=sys.stderr, flush=True)
                time_mod.sleep(warte)
    return alles


def _hat_werte(daten: list) -> bool:
    """True, wenn das Modell für mindestens einen Ort Windwerte liefert
    (außerhalb des Modellgebiets kommen nur None zurück)."""
    for d in daten:
        for key, werte in d.get("hourly", {}).items():
            if key.startswith("wind_speed_10m") and any(v is not None for v in werte):
                return True
    return False


def hole_vorhersage(orte: List[Tuple[float, float]], modelle: str, tage: int,
                    zelle: str = "sea", _nochmal: bool = True) -> Tuple[list, List[str]]:
    """Holt jedes Modell einzeln (ein Ausfall stoppt nicht alles) und führt die
    Ergebnisse pro Ort zu Spalten mit Modell-Suffix zusammen."""
    liste = [m.strip() for m in modelle.split(",") if m.strip()]
    pro_modell: Dict[str, list] = {}
    probleme = []
    for i, m in enumerate(liste, 1):
        kandidaten = [m] + ([MODELL_ERSATZ[m]] if m in MODELL_ERSATZ else [])
        for k in kandidaten:
            if k in pro_modell or (k != m and k in liste):
                break                       # Ersatz wird ohnehin geladen
            try:
                daten = _hole_modell(orte, k, tage, f"Modell {i}/{len(liste)} ({k})", zelle)
                if not _hat_werte(daten):
                    raise RuntimeError("keine Werte für dieses Gebiet")
                pro_modell[k] = daten
                if k != m:
                    probleme.append(f"{m} nicht verfügbar, stattdessen {k}")
                break
            except OmLimit:
                print("\r\033[2K", end="", file=sys.stderr, flush=True)
                raise
            except RuntimeError as e:
                if k == kandidaten[-1]:
                    probleme.append(f"{m} übersprungen: {e}")
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    for p in probleme:
        print(f"Hinweis: {p}", file=sys.stderr)
    if not pro_modell and _nochmal and probleme and all(
            "ausgelastet" in p or "keine Verbindung" in p for p in probleme):
        # Open-Meteo kurz überlastet (02.11.2026): einmal 3 min warten und neu versuchen, statt den Lauf zu verlieren
        print("Open-Meteo überlastet – neuer Versuch in 3 Minuten …", file=sys.stderr)
        time_mod.sleep(180)
        return hole_vorhersage(orte, modelle, tage, zelle, _nochmal=False)
    if not pro_modell:
        raise RuntimeError("Kein Modell konnte geladen werden – Open-Meteo nicht erreichbar oder überlastet. "
                           "Die Seiten vom letzten erfolgreichen Lauf bleiben stehen.")

    zusammen = []
    for o in range(len(orte)):
        basis = None
        stunden: Dict[str, list] = {}
        daily = None
        for m, daten in pro_modell.items():
            d = daten[o]
            h = d["hourly"]
            if basis is None:
                basis = h["time"]
                daily = d.get("daily")
            pos = {t: j for j, t in enumerate(h["time"])}
            for var in STUNDEN_VARS:
                werte = None
                for key in (var, f"{var}_{m}"):
                    if key in h:
                        werte = h[key]
                        break
                if werte is None:
                    continue
                stunden[f"{var}_{m}"] = [werte[pos[t]] if t in pos else None for t in basis]
        stunden["time"] = basis
        zusammen.append({"hourly": stunden, "daily": daily or {}})
    return zusammen, list(pro_modell)


def _hole_paket(orte: List[Tuple[float, float]], modelle: str, tage: int, zelle: str = "sea") -> list:
    params = {
        "latitude": ",".join(f"{lat:.4f}" for lat, _ in orte),
        "longitude": ",".join(f"{lon:.4f}" for _, lon in orte),
        "hourly": ",".join(STUNDEN_VARS),
        "daily": "sunrise,sunset",
        "wind_speed_unit": "kn",
        "timezone": "Europe/Berlin",
        "forecast_days": tage,
        "past_days": 1,
        "models": modelle,
        # Wichtig: Open-Meteo wählt sonst eine LAND-Gitterzelle (cell_selection=land),
        # an der Küste oft Kilometer landeinwärts – mit deutlich weniger Wind.
        "cell_selection": zelle,
    }
    return _get_json(API + "?" + urllib.parse.urlencode(params, safe=","))


class OmLimit(RuntimeError):
    """Open-Meteo-Tages- oder Stundenlimit: Wiederholen ist zwecklos, der ganze Abruf bricht sofort ab."""


OM_LIMIT_TEXT = ("Open-Meteo: {art}limit für freie Abrufe erreicht – {wann}. Der normale Lauf braucht nur wenige "
                 "Abrufe; aufgebraucht wird das Limit durch --klima, --klima-check, --kalibrieren und "
                 "--modellvergleich (Archivabrufe über viele Tage zählen bei Open-Meteo mehrfach). "
                 "Die Seiten vom letzten erfolgreichen Lauf bleiben stehen.")


OM_ZAEHLER_DATEI = Path(__file__).resolve().parent / "om_zaehler.json"
OM_LAUF = {"anfragen": 0, "gewicht": 0.0}
OM_TEILE: Dict[str, float] = {}          # Abrufe dieses Laufs je Art (fürs Log)
OM_ART_JETZT: Optional[str] = None      # gesetzt, solange Kartenfelder geladen werden
OM_SPARGRENZE = 7000                     # ab so vielen Abrufen am Tag (UTC) werden Kartenfelder nicht mehr erneuert


def _om_gewicht(url: str) -> float:
    """Grobe Schätzung, wie Open-Meteo eine Anfrage zählt: Orte × ⌈Variablen/10⌉ × ⌈Tage/14⌉ (laut Open-Meteo
    zählen mehr als 10 Variablen, mehr als 2 Wochen und mehrere Orte mehrfach). Ob mehrere Modelle in einer Anfrage
    zusätzlich zählen, ist nicht bekannt – hier nicht mitgerechnet."""
    q = urllib.parse.parse_qs(urllib.parse.urlparse(url).query)
    orte = len((q.get("latitude") or ["0"])[0].split(","))
    var = sum(len(q[k][0].split(",")) for k in ("hourly", "daily", "current") if k in q) or 1
    if "ensemble" in url:          # Ensemble-API: jede Variable zählt je Member (Quelltext Open-Meteo, 02.11.2026)
        var *= sum(ENS_MEMBER.get(m, 30) for m in (q.get("models") or [""])[0].split(",") if m) or 1
    if "start_date" in q and "end_date" in q:
        try:
            tage = (date.fromisoformat(q["end_date"][0]) - date.fromisoformat(q["start_date"][0])).days + 1
        except ValueError:
            tage = 1
    else:
        tage = int((q.get("forecast_days") or ["7"])[0]) + int((q.get("past_days") or ["0"])[0])
    return orte * max(1.0, var / 10) * max(1.0, tage / 14)


def om_zaehler_melden() -> None:
    """Am Programmende: geschätzte Open-Meteo-Abrufe dieses Laufs und des Tages (UTC) – ins Log."""
    if not OM_LAUF["anfragen"]:
        return
    heute = datetime.now(timezone.utc).date().isoformat()
    try:
        z = json.loads(OM_ZAEHLER_DATEI.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        z = {}
    z = {k: v for k, v in z.items() if k >= (datetime.now(timezone.utc).date() - timedelta(days=14)).isoformat()}
    z[heute] = round(z.get(heute, 0) + OM_LAUF["gewicht"])
    try:
        OM_ZAEHLER_DATEI.write_text(json.dumps(z, indent=0), encoding="utf-8")
    except OSError:
        pass
    teile = ", ".join(f"{k} {v:.0f}" for k, v in sorted(OM_TEILE.items(), key=lambda x: -x[1]))
    print(f"Open-Meteo: dieser Lauf {OM_LAUF['anfragen']} Anfragen, geschätzt ~{OM_LAUF['gewicht']:.0f} Abrufe"
          + (f" ({teile})" if teile else "") + f" · heute (UTC) bisher ~{z[heute]} von 10 000", file=sys.stderr)


def om_heute() -> float:
    """Geschätzte Abrufe heute (UTC) inklusive des laufenden Laufs."""
    try:
        z = json.loads(OM_ZAEHLER_DATEI.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        z = {}
    return z.get(datetime.now(timezone.utc).date().isoformat(), 0) + OM_LAUF["gewicht"]


def _get_json(url: str, _wiederholt: bool = False) -> list:
    if "open-meteo.com" in url and not _wiederholt:
        OM_LAUF["anfragen"] += 1
        try:
            g_ = _om_gewicht(url)
        except (ValueError, KeyError, IndexError):
            g_ = 1
        OM_LAUF["gewicht"] += g_
        art = ("Ensemble" if "ensemble" in url else "Marine" if "marine" in url else "Archiv" if "archive" in url or
               "historical" in url else OM_ART_JETZT or "Spots")
        OM_TEILE[art] = OM_TEILE.get(art, 0) + g_
    req = urllib.request.Request(url, headers={"User-Agent": "windsurf-spots/1.2"})
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT_S) as r:
            daten = json.load(r)
    except urllib.error.HTTPError as e:
        try:
            grund = json.load(e).get("reason", str(e))
        except Exception:
            grund = str(e)
        g = str(grund).lower()
        if e.code == 429 and "daily" in g:
            raise OmLimit(OM_LIMIT_TEXT.format(art="Tages", wann="erst morgen geht es wieder")) from None
        if e.code == 429 and "hourly" in g:
            raise OmLimit(OM_LIMIT_TEXT.format(art="Stunden", wann="in der nächsten Stunde geht es wieder")) from None
        if e.code == 429 and "minute" in str(grund).lower() and not _wiederholt:
            print("\r\033[2KOpen-Meteo: Minutenlimit erreicht – warte 61 s …", end="", file=sys.stderr, flush=True)
            time_mod.sleep(61)
            return _get_json(url, True)
        if e.code == 429 or e.code >= 500 or "overloaded" in str(grund).lower():
            raise RuntimeError(f"Server ausgelastet ({grund})") from None
        raise RuntimeError(f"Open-Meteo meldet einen Fehler: {grund}") from None
    except urllib.error.URLError as e:
        raise RuntimeError(f"keine Verbindung ({e.reason})") from None
    except (TimeoutError, OSError) as e:
        raise RuntimeError(f"Zeitüberschreitung ({e})") from None
    return [_om_ortszeit(x) for x in (daten if isinstance(daten, list) else [daten])]


def _om_ortszeit(d):
    """Open-Meteo rechnet die ganze Antwort mit EINER UTC-Verschiebung (der vom Abrufzeitpunkt). Über die
    Zeitumstellung hinweg wären die Zeiten danach um eine Stunde falsch (im Herbst: 1 h zu spät, Sonnenuntergang
    17:58 statt 16:58). Hier auf echte Ortszeit Berlin umrechnen – nur wenn die Reihe streng stündlich ist, also
    wirklich mit fester Verschiebung geliefert wurde."""
    if not isinstance(d, dict) or d.get("_ortszeit") or d.get("timezone") != "Europe/Berlin":
        return d
    off = d.get("utc_offset_seconds")
    h = d.get("hourly") or {}
    zeiten = h.get("time") or []
    if off is None or len(zeiten) < 2:
        return d
    try:
        ts = [datetime.fromisoformat(z) for z in zeiten]
    except (TypeError, ValueError):
        return d
    if any(b - a != timedelta(hours=1) for a, b in zip(ts, ts[1:])):
        return d                                          # schon zeitumstellungs-bewusst geliefert

    def fix(z: str) -> str:
        return _utc_zu_berlin(datetime.fromisoformat(z) - timedelta(seconds=off)).strftime("%Y-%m-%dT%H:%M")
    neu = [fix(z) for z in zeiten]
    weg = {i for i in range(1, len(neu)) if neu[i] == neu[i - 1]}   # doppelte 02:00 in der Umstellungsnacht
    for k, v in list(h.items()):
        if isinstance(v, list) and len(v) == len(neu) and k != "time":
            h[k] = [x for i, x in enumerate(v) if i not in weg]
    h["time"] = [z for i, z in enumerate(neu) if i not in weg]
    for k, v in (d.get("daily") or {}).items():
        if (k.startswith("sunrise") or k.startswith("sunset")) and isinstance(v, list):
            d["daily"][k] = [fix(z) if isinstance(z, str) else z for z in v]
    d["_ortszeit"] = True
    return d


API_ENSEMBLE = "https://ensemble-api.open-meteo.com/v1/ensemble"


def ensemble_aller_spots(spots: list, tage: int) -> list:
    """Ensemble je Spot aus dem Zwischenspeicher (jünger als ENS_MAX_H, gleiche Spots), sonst neu von Open-Meteo."""
    import gzip
    schluessel = [f"{sp.name}|{sp.lat:.4f}|{sp.lon:.4f}" for sp in spots]
    try:
        c = json.loads(gzip.decompress(ENS_CACHE.read_bytes()).decode("utf-8"))
        if c.get("spots") == schluessel and c.get("tage") == tage:
            alter = datetime.now() - datetime.fromisoformat(c["stand"])
            if alter < timedelta(hours=ENS_MAX_H):
                return c["ens"]
            if alter < timedelta(hours=24) and om_heute() > ENS_SPARGRENZE:   # Kontingent knapp: lieber etwas älter
                print(f"Hinweis: Ensemble vom {c['stand'][11:16]} Uhr bleibt (Open-Meteo heute schon "
                      f"~{om_heute():.0f} Abrufe)", file=sys.stderr)
                return c["ens"]
    except (OSError, ValueError, KeyError):
        c = None
    try:
        ens = hole_ensemble([(sp.lat, sp.lon) for sp in spots], ENSEMBLE_MODELLE, tage)
    except Exception as ex:                               # Zugabe, nie ein Abbruchgrund
        print(f"Hinweis: Ensemble nicht geladen ({ex})", file=sys.stderr)
        return (c or {}).get("ens") if c and c.get("spots") == schluessel else [None] * len(spots)
    if any(e and e.get("member") for e in ens):
        try:
            ENS_CACHE.write_bytes(gzip.compress(json.dumps({"stand": datetime.now().isoformat(timespec="minutes"),
                                                            "spots": schluessel, "tage": tage, "ens": ens},
                                                           separators=(",", ":")).encode("utf-8"), 6))
        except OSError:
            pass
    return ens


def hole_ensemble(orte: List[Tuple[float, float]], modelle: str, tage: int) -> List[dict]:
    """Ensemble-Member je Ort. Rückgabe pro Ort: {"time": [...], "member": {modell: [[kn je Stunde], ...]}}.
    Jedes Modell einzeln, damit ein Ausfall nicht alles stoppt."""
    ergebnis = [{"time": None, "member": {}} for _ in orte]
    for m in [x.strip() for x in modelle.split(",") if x.strip()]:
        print(f"\r\033[2KEnsemble {ENSEMBLE_KURZ.get(m, m)} …", end="", file=sys.stderr, flush=True)
        params = {
            "latitude": ",".join(f"{lat:.4f}" for lat, _ in orte),
            "longitude": ",".join(f"{lon:.4f}" for _, lon in orte),
            "hourly": "wind_speed_10m", "wind_speed_unit": "kn", "timezone": "Europe/Berlin",
            "forecast_days": min(tage, 15), "models": m, "cell_selection": "sea",
        }
        daten = None
        for versuch in range(1, VERSUCHE + 1):
            try:
                time_mod.sleep(PAUSE_S)
                daten = _get_json(API_ENSEMBLE + "?" + urllib.parse.urlencode(params, safe=","))
                break
            except RuntimeError as e:
                if "meldet einen Fehler" in str(e) and "cell_selection" in params:
                    params.pop("cell_selection")          # falls die Ensemble-API das nicht kennt
                    continue
                if versuch == VERSUCHE or "meldet einen Fehler" in str(e):
                    print(f"\r\033[2KHinweis: Ensemble {m} übersprungen: {e}", file=sys.stderr)
                    break
                time_mod.sleep(5 * 2 ** (versuch - 1))
        if not daten or len(daten) != len(orte):
            continue
        for o, d in enumerate(daten):
            h = d.get("hourly", {})
            reihen = [v for k, v in h.items() if k.startswith("wind_speed_10m") and v
                      and any(x is not None for x in v)]
            if not reihen:
                continue
            if ergebnis[o]["time"] is None:
                ergebnis[o]["time"] = h["time"]
            basis = {t: j for j, t in enumerate(h["time"])}
            # auf die Zeitachse des ersten Modells bringen
            ergebnis[o]["member"][m] = [[r[basis[t]] if t in basis else None for t in ergebnis[o]["time"]]
                                        for r in reihen]
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    return ergebnis


def ensemble_quantile(ens: dict) -> Dict[datetime, Tuple[float, float, float, float, float, int]]:
    """Je Stunde: min, p10, Median, p90, max, Anzahl Member.
    Jedes Ensemble-Modell zählt gleich viel (ECMWF hat 51 Member, GFS 31 – sonst dominiert ECMWF)."""
    aus = {}
    if not ens or not ens.get("time"):
        return aus
    for i, t in enumerate(ens["time"]):
        werte = []
        for m, member in ens["member"].items():
            vs = [r[i] for r in member if i < len(r) and r[i] is not None]
            werte += [(v, 1.0 / len(vs)) for v in vs]
        if len(werte) < 3:
            continue
        werte.sort()
        summe = sum(g for _, g in werte)

        def q(p):
            acc = 0.0
            for v, g in werte:
                acc += g
                if acc >= p * summe:
                    return v
            return werte[-1][0]
        aus[datetime.fromisoformat(t)] = (werte[0][0], q(0.1), q(0.5), q(0.9), werte[-1][0], len(werte))
    return aus


def _ens_modell_faktor(m: str, rid: str) -> float:
    """Seit 01.11.2026: dieselben Modellfaktoren wie im Modellmittel (z. B. GFS ×0,78 an der Ostsee) auch für die
    Ensemble-Member der Modellfamilie – sonst wäre die Wahrscheinlichkeit dort optimistischer als die Windzahl."""
    fk = {**MODELL_FAKTOR, **MODELL_FAKTOR_REVIER.get(rid, {})}
    fam = "gfs" if "gfs" in m else "ecmwf" if "ecmwf" in m else "icon" if "icon" in m else m
    return next((v for k, v in fk.items() if fam in k), 1.0)


def ens_wahrscheinlichkeit(e, ens: Optional[dict], d: "OrtDaten", min_kn: float,
                           jetzt: Optional[datetime] = None) -> None:
    """Setzt e.p_ens: Anteil der Ensemble-Member, deren Mittel im Session-Block die Schwelle schafft.
    Jedes Ensemble-Modell zählt gleich viel. Ostwind-Düse wie bei den Modellen eingerechnet."""
    if not ens or not ens.get("time") or e.sp_start is None:
        return
    pos = {datetime.fromisoformat(t): i for i, t in enumerate(ens["time"])}
    rid_ = revier_von(e.spot)
    stunden = {st.t: st for st in d.stunden}

    def faktor(t):
        st = stunden.get(t)
        f = OST_DUESE_FAKTOR if (st and e.spot.ost_duese and 45 <= st.wd <= 135 and duese_ab(t, jetzt)) else 1.0
        f *= niveau_faktor(e.spot.name)
        if st:
            f *= kalib_faktor(e.spot, st.wd, st.ws, st.temp, wasser_zu(d, t), t.month)[0]
        return f
    # je Stunde des fahrbaren Zeitraums: Anteil der Member über der Schwelle (für die Segel-Leiste)
    if getattr(e, "verlauf", None):
        t, t1 = min(t for t, _ in e.verlauf), max(t for t, _ in e.verlauf)
        while t <= t1:
            if t in pos:
                i, f = pos[t], faktor(t)
                anteile = []
                for m, member in ens["member"].items():
                    mf = _ens_modell_faktor(m, rid_)
                    vals = [r[i] * f * mf for r in member if i < len(r) and r[i] is not None]
                    if vals:
                        anteile.append(sum(v >= min_kn for v in vals) / len(vals))
                if anteile:
                    e.p_ens_stunde[t] = sum(anteile) / len(anteile)
            t += timedelta(hours=1)
    idx, fak = [], []
    t = e.sp_start
    while t < e.sp_ende:
        if t in pos:
            idx.append(pos[t])
            fak.append(faktor(t))
        t += timedelta(hours=1)
    if not idx:
        return
    pro_modell, mittel = {}, {}
    for m, member in ens["member"].items():
        mf = _ens_modell_faktor(m, rid_)
        treffer = gesamt = 0
        for r in member:
            vals = [r[i] * f * mf for i, f in zip(idx, fak) if i < len(r) and r[i] is not None]
            if len(vals) < len(idx) / 2:
                continue
            gesamt += 1
            mw = sum(vals) / len(vals)
            treffer += mw >= min_kn
            mittel.setdefault(m, []).append(mw)
        if gesamt:
            pro_modell[m] = treffer / gesamt
    if pro_modell:
        e.p_ens = sum(pro_modell.values()) / len(pro_modell)
        e.p_ens_modelle = pro_modell
        e.p_ens_schwelle = min_kn
        # Spanne: jedes Ensemble-Modell zählt gleich viel (wie bei p_ens)
        werte = sorted((v, 1.0 / (len(vs) * len(mittel))) for vs in mittel.values() for v in vs)

        def q(p):
            acc = 0.0
            for v, g in werte:
                acc += g
                if acc >= p - 1e-9:
                    return v
            return werte[-1][0]
        if len(werte) >= 3:
            e.p_ens_spanne = (q(0.1), q(0.9))


def p_text(e) -> str:
    return f"{e.p_ens * 100:.0f} %" if e.p_ens is not None else ""


def ens_spanne_text(e) -> str:
    """„18–28 kn“: 10–90 % der Ensemble-Member (Mittel im Block)."""
    sp = getattr(e, "p_ens_spanne", None)
    if not sp:
        return ""
    a, b = round(sp[0]), round(sp[1])
    return f"{a} kn" if a == b else f"{a}–{b} kn"


def hole_wellen(orte: List[Tuple[float, float]], tage: int) -> Optional[list]:
    """Wellenhöhe/-periode/-richtung von der Open-Meteo Marine-API (Modell: best match,
    für die Ostsee meist DWD EWAM). Bei Problemen: None, das Skript läuft ohne Wellen."""
    pakete = [orte[i:i + PAKET_GROESSE] for i in range(0, len(orte), PAKET_GROESSE)]
    alles = []
    for n, paket in enumerate(pakete, 1):
        print(f"\rWellen · Paket {n}/{len(pakete)}" + " " * 30, end="", file=sys.stderr, flush=True)
        params = {
            "latitude": ",".join(f"{lat:.4f}" for lat, _ in paket),
            "longitude": ",".join(f"{lon:.4f}" for _, lon in paket),
            "hourly": "wave_height,wave_period,wave_direction,sea_surface_temperature,sea_level_height_msl",
            "timezone": "Europe/Berlin",
            "forecast_days": tage,
            "past_days": 1,
        }
        url = API_MARINE + "?" + urllib.parse.urlencode(params, safe=",")
        for versuch in range(1, VERSUCHE + 1):
            try:
                time_mod.sleep(PAUSE_S)
                alles.extend(_get_json(url))
                break
            except RuntimeError as e:
                if versuch == VERSUCHE or "meldet einen Fehler" in str(e):
                    print("\r\033[2K", end="", file=sys.stderr)
                    print(f"Hinweis: Wellen übersprungen: {e}", file=sys.stderr)
                    return None
                time_mod.sleep(5 * 2 ** (versuch - 1))
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    return alles


def lese_wasser(d: dict) -> Dict[datetime, float]:
    h = d.get("hourly") or {}
    werte = h.get("sea_surface_temperature") or []
    return {datetime.fromisoformat(t): v for t, v in zip(h.get("time", []), werte) if v is not None}


def gefuehlt(luft: Optional[float], wind_kn: float) -> Optional[float]:
    """Gefühlte Temperatur nach der Windchill-Formel (JAG/TI, Wind in km/h). Gilt streng genommen
    bis 10 °C; bis 15 °C wird sie als grobe Näherung genutzt. Nasse Haut nach dem Sturz ist
    kälter, als die Formel sagt – der Wert ist eher eine Untergrenze der Kälte."""
    if luft is None:
        return None
    if luft > 15 or wind_kn <= 2.6:
        return luft
    v = (wind_kn * 1.852) ** 0.16
    return 13.12 + 0.6215 * luft - 11.37 * v + 0.3965 * luft * v


# Deine Anzüge: 5/4 und 6/5 Frontzip mit angesetzter Haube.
# 25.10.26 Westerbergen: Wasser 12 °C, gefühlt ~8 °C – 5/4 perfekt, weder Haube noch Handschuhe nötig.
AUSRUESTUNG = ["", "5/4 + Schuhe", "5/4 + Haube, Handschuhe", "6/5 mit Haube, Handschuhe, Schuhe",
               "6/5 mit Haube, dicke Handschuhe (5 mm), dicke Schuhe"]
NEO_WASSER = (15, 10, 8, 5)      # unter diesen Wassertemperaturen (°C): Stufe 1, 2, 3, 4
NEO_GEFUEHLT = (12, 5, 2, -2)    # unter diesen gefühlten Temperaturen (Windchill, °C): Stufe 1, 2, 3, 4


def neo_stufe(wasser: Optional[float], gef: Optional[float]) -> int:
    """0–4: die strengere von Wasser- und Windchill-Stufe."""
    st = 0
    if wasser is not None:
        st = sum(wasser < g for g in NEO_WASSER)
    if gef is not None:
        st = max(st, sum(gef < g for g in NEO_GEFUEHLT))
    return st


def neo_text(wasser: Optional[float], gef: Optional[float]) -> Optional[str]:
    return AUSRUESTUNG[neo_stufe(wasser, gef)] or None


def luft_text(luft: Optional[float], gef: Optional[float]) -> str:
    if luft is None:
        return ""
    t = f"Luft {luft:.0f} °C"
    if gef is not None and gef <= luft - 1.5:
        t += f", gefühlt {gef:.0f} °C"
    return t


def lese_wellen(d: dict) -> Dict[datetime, Tuple[float, Optional[float], Optional[float]]]:
    h = d.get("hourly") or {}
    out = {}
    for i, t in enumerate(h.get("time", [])):
        hs = (h.get("wave_height") or [None])[i] if h.get("wave_height") else None
        if hs is None:
            continue
        per = h["wave_period"][i] if h.get("wave_period") else None
        rich = h["wave_direction"][i] if h.get("wave_direction") else None
        out[datetime.fromisoformat(t)] = (hs, per, rich)
    return out


def lese_ort(d: dict, faktoren: Optional[Dict[str, float]] = None,
             gewichte: Optional[Dict[str, float]] = None, jetzt: Optional[datetime] = None,
             rid: Optional[str] = None) -> OrtDaten:
    h = d["hourly"]
    zeiten = [datetime.fromisoformat(t) for t in h["time"]]
    n = len(zeiten)

    # Modelle aus den Spaltennamen erkennen: "wind_speed_10m" oder "wind_speed_10m_<modell>"
    suffixe = [k[len("wind_speed_10m"):] for k in h if k.startswith("wind_speed_10m")]
    reihen = {}
    for suf in suffixe:
        ws = h.get("wind_speed_10m" + suf)
        if not ws or all(v is None for v in ws):
            continue
        name = suf.lstrip("_") or "standard"
        f = (faktoren or {}).get(name, 1.0)
        wg = h.get("wind_gusts_10m" + suf) or [None] * n
        # 14.11.2026: Faktor je Stunde nach Vorlauf (nur wenn der Laufzeitpunkt bekannt ist)
        if faktoren is not None and rid and jetzt is not None and (MODELL_FAKTOR_VORLAUF.get(rid) or {}).get(name):
            fs = [modell_faktor_vorlauf(rid, name, f, (t - jetzt).total_seconds() / 3600) for t in zeiten]
        else:
            fs = [f] * n
        reihen[name] = {
            "ws": [None if v is None else v * fi for v, fi in zip(ws, fs)],
            "wg": [None if v is None else v * fi for v, fi in zip(wg, fs)],
            "wd": h.get("wind_direction_10m" + suf) or [None] * n,
            "pr": h.get("precipitation" + suf) or [None] * n,
            "wc": h.get("weather_code" + suf) or [None] * n,
            "tp": h.get("temperature_2m" + suf) or [None] * n,
            "w80": h.get("wind_speed_80m" + suf) or [None] * n,
            "roh": ws,
        }

    stunden = []
    for i, t in enumerate(zeiten):
        ws, wg, pr, wc, tp = [], [], [], [], []
        werte = {}
        richt_m: Dict[str, float] = {}
        verh: List[float] = []
        u = v = 0.0
        g_ws = g_wg = 0.0              # Gewichtssummen (ohne Gewichte: Anzahl der Modelle)
        sum_ws = sum_wg = 0.0
        for name, r in reihen.items():
            s, richtung = r["ws"][i], r["wd"][i]
            if s is None or richtung is None:
                continue
            gw = _modell_gewicht(gewichte, name)
            if jetzt is not None and name == "icon_seamless" and t - jetzt > timedelta(hours=ICON_FEIN_H):
                gw *= ICON_FERN_FAKTOR
            ws.append(s)
            werte[name] = s
            richt_m[name] = richtung
            w80, roh10 = r["w80"][i], r["roh"][i]
            if w80 is not None and roh10 is not None and w80 >= 4:
                verh.append(roh10 / w80)
            g_ws += gw
            sum_ws += gw * s
            rad = math.radians(richtung)
            u += gw * s * math.sin(rad)
            v += gw * s * math.cos(rad)
            if r["wg"][i] is not None:
                wg.append(r["wg"][i])
                g_wg += gw
                sum_wg += gw * r["wg"][i]
            if r["pr"][i] is not None:
                pr.append(r["pr"][i])
            if r["wc"][i] is not None:
                wc.append(r["wc"][i])
            if r["tp"][i] is not None:
                tp.append(r["tp"][i])
        if not ws:
            continue
        wd = (math.degrees(math.atan2(u, v)) + 360) % 360
        stunden.append(Stunde(t, sum_ws / g_ws, sum_wg / g_wg if wg else None, wd,
                              max(pr) if pr else 0.0, max(wc) if wc else None, min(ws), max(ws),
                              werte, sum(tp) / len(tp) if tp else None, richt_m,
                              sum(verh) / len(verh) if verh else None))

    sonne = {}
    dly = d.get("daily") or {}

    def spalte(name):
        if name in dly:
            return dly[name]
        for k, werte in dly.items():
            if k.startswith(name):
                return werte
        return None

    tage, auf, unter = dly.get("time"), spalte("sunrise"), spalte("sunset")
    if tage and auf and unter:
        for tg, a, u_ in zip(tage, auf, unter):
            if a and u_:
                sonne[date.fromisoformat(tg)] = (datetime.fromisoformat(a), datetime.fromisoformat(u_))
    return OrtDaten(stunden, sonne, list(reihen))


def sonnenzeiten(d: OrtDaten, tag: date) -> Tuple[datetime, datetime]:
    return d.sonne.get(tag, (datetime.combine(tag, time(7, 30)), datetime.combine(tag, time(18, 30))))


def vektor_mittel(paare: List[Tuple[float, float]]) -> Tuple[float, float]:
    """(Geschwindigkeit, Richtung) → (mittlere Geschwindigkeit, Vektor-Richtung)."""
    if not paare:
        return 0.0, 0.0
    u = sum(s * math.sin(math.radians(r)) for s, r in paare)
    v = sum(s * math.cos(math.radians(r)) for s, r in paare)
    return sum(s for s, _ in paare) / len(paare), (math.degrees(math.atan2(u, v)) + 360) % 360


# =============================================================================
# BEWERTUNG
# =============================================================================

@dataclass
class Empfehlung:
    spot: Spot
    tag: date
    start: datetime
    ende: datetime
    score: float
    wind: float
    boeen: Optional[float]
    mod_lo: float
    mod_hi: float
    richtung: str
    art: str
    stufe: int
    board: str
    segel: float
    segel_alt: Optional[float]
    finne: str
    warnungen: List[str]
    modelle_ok: List[str] = field(default_factory=list)   # Modelle, die das Fenster über der Schwelle sehen
    modell_wind: Dict[str, float] = field(default_factory=dict)
    chance: bool = False                                  # nur einzelne Modelle sehen genug Wind
    schnitt: float = 0.0                                  # Mittel über das ganze Fenster
    sp_start: Optional[datetime] = None                   # bester Session-Block
    sp_ende: Optional[datetime] = None
    wasser_t: Optional[float] = None                      # Wassertemperatur °C
    welle_h: Optional[float] = None                       # Wellenhöhe draußen (m) in der Spitze
    welle_p: Optional[float] = None                       # Periode (s)
    luft_t: Optional[float] = None                        # Lufttemperatur °C im Block
    gef_t: Optional[float] = None                         # gefühlte Temperatur (Windchill) °C
    p_ens: Optional[float] = None                         # Anteil Ensemble-Member über der Schwelle
    p_guete: Optional[float] = None                       # 14.11.2026: Wahrscheinlichkeit nach Modellgüte
    p_guete_klasse: str = ""
    p_guete_modelle: Dict[str, tuple] = field(default_factory=dict)   # Modell → (p, Gewicht, korrigierter Wind)
    p_ens_modelle: Dict[str, float] = field(default_factory=dict)
    verlauf: List[Tuple[datetime, float]] = field(default_factory=list)   # alle fahrbaren Stunden des Tages
    tief: bool = False                                    # kein Stehbereich (Sicherheitsregeln für große Segel)
    wenn_frei: bool = False                               # Arbeitstag: nur fahrbar, wenn man frei nimmt
    p_ens_stunde: Dict[datetime, float] = field(default_factory=dict)   # Ensemble-Anteil ≥ Schwelle je Stunde
    p_ens_spanne: Optional[Tuple[float, float]] = None    # 10–90 % der Member: Blockmittel in kn
    p_ens_schwelle: Optional[float] = None                # Schwelle (kn), auf die sich p_ens bezieht
    trend: Optional[Tuple[str, str]] = None               # (stabil|steigt|faellt|schwankt, Text) aus früheren Läufen
    schichtung: Optional[Tuple[str, str, str]] = None     # (Klasse, Kurzlabel, Text): Luft gegen Wasser
    gezeiten: List[Tuple[str, datetime, bool]] = field(default_factory=list)   # (HW/NW, Zeit, geschätzt)

    def wellen_text(self) -> str:
        if self.welle_h is None:
            return ""
        t = f"draußen {self.welle_h:.1f}".replace(".", ",") + " m"
        if self.welle_p:
            t += f" / {self.welle_p:.0f} s"
        return t

    def segel_text(self) -> str:
        return qm(self.segel) + (f" (alt. {qm(self.segel_alt)})" if self.segel_alt else "")

    def spitze_text(self) -> str:
        """'Spitze NNW 19 kn 16–18 Uhr (Fenster 08–18, Ø 15)'"""
        t = f"{self.richtung} {self.wind:.0f} kn {self.sp_start:%H}–{self.sp_ende:%H} Uhr"
        if (self.sp_start, self.sp_ende) != (self.start, self.ende):
            t += f" (Fenster {self.start:%H}–{self.ende:%H}, Ø {self.schnitt:.0f})"
        return t



def duese_ab(t: datetime, jetzt: Optional[datetime]) -> bool:
    """Gilt die Ostwind-Düse für diese Stunde? (erst ab OST_DUESE_AB_H Stunden Vorlauf; ohne Bezugszeit immer)"""
    return jetzt is None or t - jetzt > timedelta(hours=OST_DUESE_AB_H)


def eff_wind(spot: Spot, st: Stunde, basis: Optional[float] = None,
             wasser: Optional[float] = None, jetzt: Optional[datetime] = None) -> Tuple[float, List[str]]:
    w, notiz = (st.ws if basis is None else basis), []
    if BOEEN_KORREKTUR and st.wg and w > 0 and st.wg >= 2 * w and st.pr < 0.2:
        w = max(w, 0.7 * st.wg)
        notiz.append("Böen > 2× Mittelwind: Mittelwind auf 70 % der Böen korrigiert")
    gw = modell_gewichte(spot.name)
    if gw:
        notiz.append("Modellmittel gewichtet (" + MODELL_PROFIL_SPOTS.get(spot.name, revier_von(spot)) + ": "
                     + ", ".join(f"{MODELL_KURZ.get(m, m)} ×{x:g}" for m, x in gw.items()) + ")")
    f_spot = None if OEFFENTLICH else SPOT_FAKTOR.get(spot.name)
    if f_spot and f_spot != 1.0:
        w *= f_spot
        notiz.append(f"Logbuch-Faktor ×{f_spot:.2f} eingerechnet")
    if spot.ost_duese and 45 <= st.wd <= 135 and duese_ab(st.t, jetzt):
        w *= OST_DUESE_FAKTOR
        notiz.append(f"Ostwind-Düse eingerechnet (+{(OST_DUESE_FAKTOR - 1) * 100:.0f} %, ab Tag 3)" if jetzt is not None
                     and OST_DUESE_AB_H else f"Ostwind-Düse eingerechnet (+{(OST_DUESE_FAKTOR - 1) * 100:.0f} %)")
    f_k, text_k = kalib_faktor(spot, st.wd, st.ws, st.temp, wasser, st.t.month)
    if text_k:
        w *= f_k
        notiz.append(text_k)
    f_n = niveau_faktor(spot.name)
    if f_n != 1.0:
        w *= f_n
        notiz.append(f"Wasserniveau ×{f_n:.2f} (Modelle unterschätzen den Wind über Wasser)")
    return w, notiz


def wind_faktor(w: float, min_kn: float) -> float:
    if w < min_kn:
        return 0.0
    if w < 18:
        return 0.6 + 0.4 * (w - min_kn) / max(1.0, 18 - min_kn)
    if w <= 26:
        return 1.0
    return max(0.5, 1.0 - (w - 26) * 0.06)


def pegel_niedrig(d: OrtDaten, ende: datetime) -> bool:
    paare = [(st.ws, st.wd) for st in d.stunden if ende - timedelta(hours=24) <= st.t < ende]
    s, r = vektor_mittel(paare)
    return 200 <= r <= 290 and s >= 13


def windigstes_modell(st: "Stunde") -> Optional[str]:
    return max(st.werte, key=st.werte.get) if st.werte else None


def wd_bewertung(st: "Stunde", optimistisch: bool = False) -> float:
    """Richtung für die Bewertung: Modellmittel; bei der Chance die des windigsten Modells – dessen Wind wird
    ja angenommen, also auch seine Richtung (sonst fällt z. B. GFS mit NW durch, weil das Mittel schon auf N steht)."""
    if optimistisch:
        m = windigstes_modell(st)
        if m and m in st.richt:
            return st.richt[m]
    return st.wd


def bewerte(spot: Spot, d: OrtDaten, tag: date, args, jetzt: datetime,
            min_kn: Optional[float] = None, alle: Optional[bool] = None,
            optimistisch: bool = False) -> Optional[Empfehlung]:
    """Bestes zusammenhängendes Zeitfenster eines Spots an einem Tag.
    optimistisch=True: statt des Modellmittels zählt das windigste Modell."""
    min_kn = args.min_kn if min_kn is None else min_kn
    alle = args.alle if alle is None else alle
    sr, ss = sonnenzeiten(d, tag)
    ab = args.werktags_ab if (args.werktags_ab is not None and ist_arbeitstag(tag)) else None
    if ab is not None and spot.fahrt_min > WERKTAGS_MAX_FAHRT:
        return None                                       # Arbeitstag: zu weit weg für nach Feierabend
    frueh = datetime.combine(tag, time(ab)) + timedelta(minutes=spot.fahrt_min) if ab is not None else None

    zeilen = []
    for st in d.stunden:
        if st.t.date() != tag or st.t < jetzt - timedelta(minutes=59):
            continue
        if st.t < sr - timedelta(minutes=20) or st.t + timedelta(hours=1) > ss + timedelta(minutes=30):
            continue
        if frueh is not None and st.t < frueh - timedelta(minutes=30):
            continue                                      # Feierabend + Anfahrt (eine halbe Stunde Kulanz)
        eintrag = richtung_eintrag(spot, wd_bewertung(st, optimistisch))
        w, notiz = eff_wind(spot, st, st.ws_max if optimistisch else None, wasser_zu(d, st.t), jetzt)
        ok, q, art, stufe = False, 0, "", spot.stufe
        if eintrag:
            q, art, stufe_r = eintrag
            stufe = stufe_r or spot.stufe
            gewitter = st.wc is not None and st.wc >= 95
            ok = (min_kn <= w <= MAX_KN and not gewitter
                  and (alle or stufe <= DEINE_STUFE))
        zeilen.append((st, ok, q, art, stufe, w, notiz))

    laeufe, aktuell = [], []
    for z in zeilen:
        if z[1]:
            aktuell.append(z)
        elif aktuell:
            laeufe.append(aktuell)
            aktuell = []
    if aktuell:
        laeufe.append(aktuell)
    laeufe = [l for l in laeufe if len(l) >= MIN_STUNDEN]
    if not laeufe:
        return None

    session = max(1, getattr(args, "session", SESSION_STUNDEN))

    def block_wert(b):
        """Qualität des Blocks für das Ranking zwischen Spots (Richtung zählt voll)."""
        return sum(z[2] * wind_faktor(z[5], min_kn) for z in b)

    def block_wind(b):
        """Für die Wahl der Spitze innerhalb eines Spots: der Wind entscheidet, die Richtung
        nur leicht (±5 % je Qualitätsstufe); über 26 kn zählt Mehrwind nicht mehr als besser."""
        def w(z):
            kn = z[5] if z[5] <= 26 else 26 - (z[5] - 26) * 0.5
            return kn * (1 + 0.05 * (z[2] - 2))
        return sum(w(z) for z in b)

    def bester_block(l):
        """Der windigste Session-Block (z. B. 2 h) innerhalb eines Fensters."""
        n = min(session, len(l))
        return max((l[i:i + n] for i in range(len(l) - n + 1)), key=block_wind)

    def lauf_score(l):
        # Entscheidend ist die beste Session, die Fensterlänge gibt nur einen kleinen Bonus
        return block_wert(bester_block(l)) + 0.15 * len(l)

    best = max(laeufe, key=lambda l: (lauf_score(l), block_wind(bester_block(l))))
    score = lauf_score(best)            # seit 29.10.2026 ohne Anfahrt – Ranking nur nach Bedingungen
    block = bester_block(best)

    schnitt = sum(z[5] for z in best) / len(best)          # Mittel über das ganze Fenster
    wind = sum(z[5] for z in block) / len(block)           # Spitze = bester Session-Block
    stunden = [z[0] for z in block]
    # Korrekturfaktor (Düse/Böen) je Stunde, bezogen auf den jeweils verwendeten Basiswert
    faktoren = []
    for z in block:
        basis = z[0].ws_max if optimistisch else z[0].ws
        faktoren.append(z[5] / basis if basis > 0 else 1.0)
    mod_lo = sum(st.ws_min * f for st, f in zip(stunden, faktoren)) / len(block)
    mod_hi = sum(st.ws_max * f for st, f in zip(stunden, faktoren)) / len(block)
    modell_wind: Dict[str, float] = {}
    for m in d.modelle:
        vals = [st.werte[m] * f for st, f in zip(stunden, faktoren) if m in st.werte]
        if len(vals) >= len(stunden) / 2:
            modell_wind[m] = sum(vals) / len(vals)
    modelle_ok = [m for m, v in sorted(modell_wind.items(), key=lambda x: -x[1]) if v >= min_kn]
    boeen_liste = [st.wg for st in stunden if st.wg is not None]
    boeen = max(boeen_liste) if boeen_liste else None

    richtung = kompass(vektor_mittel([(st.ws, wd_bewertung(st, optimistisch)) for st in stunden])[1])

    wl = [d.wellen[st.t] for st in stunden if st.t in d.wellen]
    welle_h = sum(x[0] for x in wl) / len(wl) if wl else None
    pers = [x[1] for x in wl if x[1] is not None]
    welle_p = sum(pers) / len(pers) if pers else None
    wt = [d.wasser[st.t] for st in stunden if st.t in d.wasser]
    if not wt:   # manche Punkte liefern SST nur in groberem Takt – nächsten Wert des Tages nehmen
        wt = [v for t_, v in d.wasser.items() if t_.date() == tag]
    wasser_t = sum(wt) / len(wt) if wt else None
    lt = [st.temp for st in stunden if st.temp is not None]
    luft_t = sum(lt) / len(lt) if lt else None
    gef_t = gefuehlt(luft_t, wind)

    gewichte = Counter()
    for z in block:
        gewichte[z[3]] += z[2]
    art = gewichte.most_common(1)[0][0]
    if art.startswith("Welle"):
        # mit Wellendaten entscheidet die Höhe, sonst der Wind
        if (welle_h is not None and welle_h < 0.4) or (welle_h is None and wind < 16):
            art = "Kabbel, kaum Welle"
    stufe = max(z[4] for z in best)

    board = board_wahl(wind, spot, boeen)
    segel, segel_alt = segel_wahl(wind)
    finne = finnen_wahl(spot, art, wind, board, tag.month)

    warnungen: List[str] = []
    # --- Sicherheitsregeln, solange der Wasserstart nicht sicher sitzt ---
    lage = lage_zum_strand(spot, vektor_mittel([(st.ws, wd_bewertung(st, optimistisch)) for st in stunden])[1])
    welle_ohne_steh = art.startswith("Welle") and "Stehbereich" not in art
    tief = not spot.stehbereich or welle_ohne_steh
    # Wind lässt nach: Ende des Blocks deutlich schwächer als der Anfang, oder die Stunde danach unter der Schwelle
    danach = [st for st in d.stunden if stunden[-1].t < st.t <= stunden[-1].t + timedelta(hours=1)]
    nachlassend = (block[-1][5] < block[0][5] - 2
                   or any(st.ws * (faktoren[-1] if faktoren else 1) < min_kn - 1 for st in danach))
    if OEFFENTLICH:
        # für alle: Lage zum Strand als Information, ablandig nach hinten – keine persönlichen Segel-/Stufenregeln
        if lage == "ablandig":
            score *= 0.5 if tief else 0.8
            warnungen.append("ablandig – Abdrift aufs offene Wasser"
                             + ("" if tief else ", Stehbereich endet an der Sandbank"))
        # 08.11.2026: kein Hinweis mehr bei seitlichem Wind ohne Stehbereich – sideshore ist der Normalfall und eher
        # günstig; die Regel stammte aus Davids persönlichen Wasserstart-Regeln. Ob es einen Stehbereich gibt, steht
        # jetzt als feste Spot-Angabe auf der Spotseite.
    elif not WASSERSTART_SICHER:
        if tief and lage == "ablandig":
            score *= 0.25
            warnungen.append("ablandig ohne Stehbereich – nicht empfohlen")
        elif STEHBEREICH_AB_SEGEL is not None and segel >= STEHBEREICH_AB_SEGEL:
            if tief:
                score *= 0.25
                warnungen.append(f"mit {qm(segel)} nicht empfohlen – nur Flachwasser mit Stehbereich")
            elif art.startswith("Welle"):
                warnungen.append("innen im Stehbereich bleiben, nicht an die Sandbank")
        elif TIEF_VORSICHT_AB_SEGEL is not None and segel >= TIEF_VORSICHT_AB_SEGEL and tief:
            if nachlassend:
                score *= 0.25
                warnungen.append(f"mit {qm(segel)} im Tiefen und nachlassendem Wind nicht empfohlen")
            else:
                score *= 0.8
                warnungen.append(f"{qm(segel)} im Tiefen: Wind knapp für den Wasserstart – "
                                 "nah am Ufer bleiben" + (", seitlicher Wind" if lage == "seitlich" else ""))
        elif tief and lage == "seitlich":
            warnungen.append("seitlicher Wind ohne Stehbereich – nicht zu weit raus")
    elif lage == "ablandig":
        warnungen.append("ablandig")                      # nur als Information, ohne Abwertung
    for z in block:
        for n in z[6]:
            if n not in warnungen:
                warnungen.append(n)
    if OEFFENTLICH and spot.stark and max(z[5] for z in best) >= spot.stark[0] and art.startswith("Welle"):
        warnungen.append(spot.stark[1])
    abd = ABDECKUNG.get(spot.name)
    if abd and sum(kompass(st.wd) in abd[0] for st in stunden) >= len(stunden) / 2:
        score *= 0.85
        warnungen.append(f"Windabdeckung bei {'/'.join(abd[0])} ({abd[1]}) – böig und löchrig")
    if boeen and wind > 0 and boeen / wind >= BOEIG_FAKTOR:
        if tief and not WASSERSTART_SICHER and not OEFFENTLICH:
            # im Tiefen bei starken Böen: Wasserstart zwischen Löchern und Böen schwer – nach hinten
            score *= 0.6
            warnungen.append(f"böig im Tiefen (Böen bis {boeen:.0f} kn) – Wasserstart schwer")
        else:
            warnungen.append(f"böig (Böen bis {boeen:.0f} kn)")
    if any(st.pr >= 1.0 for st in stunden):
        warnungen.append("Schauer möglich – Radar checken, bei Donner sofort an Land" if OEFFENTLICH else "Schauer möglich")
    if len(d.modelle) > 1 and mod_hi - mod_lo >= 6 and not optimistisch:
        warnungen.append(f"Modelle uneinig ({mod_lo:.0f}–{mod_hi:.0f} kn)")
    fb = [z[0].t for z in zeilen if z[1]]
    pw_w, pw_f, pw_da = pegel_warnungen(spot, stunden[0].t, stunden[-1].t + timedelta(hours=1), jetzt,
                                        min(fb), max(fb) + timedelta(hours=1))
    warnungen += pw_w
    if OEFFENTLICH:
        score *= pw_f                                     # privat: Pegel nur als Information
    # Ablandig im Stehrevier: Stehbereich endet an der Sandbank, bei Hochwasser ist er ganz weg (Pelzerhaken 18.10.)
    if spot.stehbereich and lage == "ablandig" and not tief:
        pw = pegel_im_fenster(spot, stunden[0].t, stunden[-1].t + timedelta(hours=1), jetzt)
        if pw and pw[0] >= HOCHWASSER_WARN_CM and (OEFFENTLICH or not WASSERSTART_SICHER):
            score *= 0.25
            warnungen.append("ablandig bei Hochwasser – kein Stehbereich, Abdrift"
                             + ("" if OEFFENTLICH else ": nicht empfohlen"))
    if spot.pegel and pegel_niedrig(d, best[-1][0].t + timedelta(hours=1)):
        if not pw_da:
            warnungen.append("W/SW-Lage: Niedrigwasser möglich (Pegel Heiligenhafen)")
        elif not any(w.startswith("Niedrigwasser") for w in pw_w):
            pw = pegel_im_fenster(spot, stunden[0].t, stunden[-1].t + timedelta(hours=1), jetzt)
            if pw and "unsicher" in pw[2]:
                warnungen.append(f"W/SW-Lage: Modell zeigt nur {pw[1]:+.0f} cm, unterschätzt Niedrigwasser eher")
    if welle_h is not None and welle_h >= WELLE_WARN_M and art.startswith("Welle"):
        # 15.11.2026: Höhe und Periode statt „groß“ – was das heißt, entscheidet jeder selbst
        warnungen.append(f"Welle draußen {welle_h:.1f} m".replace(".", ",")
                         + (f" / {welle_p:.0f} s" if welle_p else ""))
    if stufe >= 3 and not OEFFENTLICH:          # 15.11.2026: öffentlich keine Einstufung – Könnerstufe ist individuell
        warnungen.append(f"anspruchsvoll (Stufe {stufe} von 5)")

    e = Empfehlung(spot, tag, best[0][0].t, best[-1][0].t + timedelta(hours=1), score, wind,
                   boeen, mod_lo, mod_hi, richtung, art, stufe, board, segel, segel_alt,
                   finne, warnungen, modelle_ok, modell_wind, optimistisch,
                   schnitt, stunden[0].t, stunden[-1].t + timedelta(hours=1), wasser_t, welle_h, welle_p,
                   luft_t, gef_t)
    sv = [st.scher for st in stunden if st.scher is not None]
    e.schichtung = schichtung_bestimmen(luft_t, wasser_t, sum(sv) / len(sv) if sv else None)
    # Alle Stunden des Tages mit passender Richtung und genug Wind – nicht nur die Spitze
    e.verlauf = [(z[0].t, z[5]) for z in zeilen if z[1]]
    e.tief = tief and not WASSERSTART_SICHER
    return e


# Schichtung über dem Wasser aus Luft − Wasser (Block): warme Luft über kaltem Wasser = stabil (Wind entkoppelt, kommt
# unten schwächer und gleichmäßiger an, die Modelle liegen dann eher zu hoch); kalte Luft über warmem Wasser = labil
# (Impuls kommt gut herunter, dafür böig, bei Schauern Böenwalzen). Das 10-m/80-m-Verhältnis der Modelle zeigt, wie
# das Modell selbst die Schichtung sieht (über Wasser neutral ≈ 0,85, stabil deutlich darunter).
SCHICHT_STABIL_K = 2.0
SCHICHT_STARK_K = 4.0


def schichtung_bestimmen(luft: Optional[float], wasser: Optional[float],
                         scher: Optional[float]) -> Optional[Tuple[str, str, str]]:
    if luft is None or wasser is None:
        return None
    dt = luft - wasser
    profil = f" Modell-Windprofil 10 m/80 m: {scher:.2f} (neutral ≈ 0,85).".replace(".", ",", 1) if scher else ""
    if dt >= SCHICHT_STARK_K:
        return ("warn", "stark stabil",
                f"stark stabil: Luft {dt:.0f} K wärmer als das Wasser – Wind entkoppelt, kommt unten oft deutlich "
                f"schwächer an als vorhergesagt und kann abreißen.{profil}")
    if dt >= SCHICHT_STABIL_K:
        return ("", "stabil", f"stabil: Luft {dt:.0f} K wärmer als das Wasser – Wind unten eher etwas schwächer, "
                              f"dafür gleichmäßig.{profil}")
    if dt <= -SCHICHT_STARK_K:
        return ("warn", "stark labil", f"stark labil: Wasser {-dt:.0f} K wärmer als die Luft – Wind kommt voll "
                                       f"herunter, aber böig; bei Schauern kräftige Böen.{profil}")
    if dt <= -SCHICHT_STABIL_K:
        return ("", "labil", f"labil: Wasser {-dt:.0f} K wärmer als die Luft – Wind kommt gut herunter, etwas "
                             f"böiger.{profil}")
    return None


def segel_verfuegbar() -> List[Tuple[float, int, int]]:
    return [x for x in SEGEL if x[0] in SEGEL_VORHANDEN
            and (GROESSTES_SEGEL is None or x[0] <= GROESSTES_SEGEL + 0.01)]


def zeitspannen(stunden: List[datetime]) -> List[Tuple[datetime, datetime]]:
    """[08, 09, 10, 13, 14] → [(08, 11), (13, 15)]  (Ende exklusiv)."""
    aus: List[List[datetime]] = []
    for t in sorted(stunden):
        if aus and t - aus[-1][1] == timedelta(hours=1):
            aus[-1][1] = t
        else:
            aus.append([t, t])
    return [(a, b + timedelta(hours=1)) for a, b in aus]


def spannen_text(sp: List[Tuple[datetime, datetime]]) -> str:
    return ", ".join(f"{a:%H}–{b:%H}" for a, b in sp)


def segel_fenster(e: Empfehlung) -> List[Tuple[float, List[datetime]]]:
    """Für jedes vorhandene Segel (bis zum größten) die Stunden, in denen der Wind in seinem Bereich liegt."""
    aus = []
    for g, lo, hi in segel_verfuegbar():
        if e.tief and STEHBEREICH_AB_SEGEL is not None and g >= STEHBEREICH_AB_SEGEL:
            continue                       # deine Regel: so große Segel nur mit Stehbereich
        st = [t for t, w in e.verlauf if lo <= w <= hi]
        if st:
            aus.append((g, st))
    return aus


def fahrbar_text(e: Empfehlung) -> str:
    """Stunden, in denen mindestens ein erlaubtes Segel passt."""
    return spannen_text(zeitspannen(sorted({t for _, st in segel_fenster(e) for t in st})))


def modell_text(e: Empfehlung) -> str:
    """'GFS 19, ICON 12, ECMWF 11' – windigstes Modell zuerst."""
    teile = sorted(e.modell_wind.items(), key=lambda x: -x[1])
    return ", ".join(f"{MODELL_KURZ.get(m, m)} {v:.0f}" for m, v in teile)


HOCHSTUFEN_P = 0.5     # ab dieser Wahrscheinlichkeit wird eine Chance ein Gleittag (01.11.2026)


def auf_mittel(e: Empfehlung, d: "OrtDaten", jetzt: datetime) -> None:
    """Chance: große Zahl = Modellmittel im Session-Block (mit Spotfaktoren) wie überall sonst; das windigste Modell
    bleibt in e.wind_max (Chip „bis … kn“)."""
    if getattr(e, "wind_max", None) is not None:
        return
    e.wind_max = e.wind
    werte = [eff_wind(e.spot, st, None, wasser_zu(d, st.t), jetzt)[0] for st in d.stunden
             if e.sp_start is not None and e.sp_start <= st.t < e.sp_ende]
    if werte:
        e.wind = sum(werte) / len(werte)
        e.board = board_wahl(e.wind, e.spot, e.boeen)
        e.segel, e.segel_alt = segel_wahl(e.wind)
    if e.verlauf:                                         # Stundenleiste ebenfalls mit dem Mittel statt dem Maximum
        je_t = {st.t: st for st in d.stunden}
        e.verlauf = [(t, eff_wind(e.spot, je_t[t], None, wasser_zu(d, t), jetzt)[0] if t in je_t else w)
                     for t, w in e.verlauf]



def hochstufen(e: Empfehlung, d: "OrtDaten", jetzt: datetime) -> None:
    """Chance → Gleittag (Wahrscheinlichkeit ≥ HOCHSTUFEN_P)."""
    auf_mittel(e, d, jetzt)
    e.chance = False
    e.hochgestuft = True


def chancen_fuer_tag(spot_daten, tag, args, jetzt, schon: set) -> List[Empfehlung]:
    """Spots, die nur mit dem windigsten Modell über die Schwelle kommen."""
    out = []
    for s, d in zip(SPOTS, spot_daten):
        if s.name in schon or len(d.modelle) < 2:
            continue
        e = bewerte(s, d, tag, args, jetzt, optimistisch=True)
        if e:
            out.append(e)
    out.sort(key=lambda e: e.score, reverse=True)
    return out


# =============================================================================
# KONSOLE
# =============================================================================

WOCHENTAGE = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"]


def tag_text(tag: date) -> str:
    return f"{WOCHENTAGE[tag.weekday()]} {tag:%d.%m.}"


def fahrzeit(m: int) -> str:
    return f"{m // 60}:{m % 60:02d} h" if m >= 60 else f"{m} min"


def tageskopf(d: OrtDaten, tag: date) -> str:
    sr, ss = sonnenzeiten(d, tag)
    hs = [st for st in d.stunden if st.t.date() == tag and sr <= st.t <= ss]
    if not hs:
        return ""
    vorm = [(st.ws, st.wd) for st in hs if st.t.hour < 13]
    nachm = [(st.ws, st.wd) for st in hs if st.t.hour >= 13]
    r1 = kompass(vektor_mittel(vorm)[1]) if vorm else None
    r2 = kompass(vektor_mittel(nachm)[1]) if nachm else None
    richtung = f"{r1} → {r2}" if (r1 and r2 and r1 != r2) else (r1 or r2)
    lo, hi = min(st.ws for st in hs), max(st.ws for st in hs)
    g = [st.wg for st in hs if st.wg is not None]
    text = f"{richtung} · {lo:.0f}–{hi:.0f} kn"
    if g:
        text += f", Böen bis {max(g):.0f}"
    if any(st.wc is not None and st.wc >= 95 for st in hs):
        text += " · GEWITTER möglich"
    if len(d.modelle) > 1:
        aktiv = tagesmodelle(d, hs)
        text += f" · {len(aktiv)} Modelle ({', '.join(modell_zelle(m) for m in aktiv)})"
    return text


def tagesmodelle(d: OrtDaten, hs: List[Stunde]) -> List[str]:
    """Modelle, die für mindestens die Hälfte der Tagstunden Werte liefern."""
    return [m for m in d.modelle if sum(1 for st in hs if m in st.werte) >= len(hs) / 2]


def drucke_empfehlung(i: int, e: Empfehlung, mehrere_modelle: bool) -> None:
    s = e.spot
    wind = f"Spitze {e.spitze_text()}"
    if e.boeen:
        wind += f", Böen {e.boeen:.0f}"
    zeile = f"  {i}. {s.name} · {fahrzeit(s.fahrt_min)} · {wind}"
    print(zeile)
    if e.verlauf and not e.chance:
        sf = segel_fenster(e)
        print(f"     fahrbar {fahrbar_text(e)} Uhr"
              + (" · " + " · ".join(f"{qm(g)} {spannen_text(zeitspannen(st))}" for g, st in sf) if sf else ""))
    if e.trend:
        print(f"     Vorhersage {e.trend[1]}")
    if e.schichtung:
        print(f"     Schichtung {e.schichtung[2]}")
    if e.gezeiten:
        print(f"     Tide ({GEZEITEN[s.name]['station']}): {gezeiten_text(e)}"
              + (" (~ fortgeschrieben)" if any(g[2] for g in e.gezeiten) else ""))
    if mehrere_modelle and e.modell_wind:
        print(f"     Modelle: {modell_text(e)}"
              + (f" · Ensemble: {p_text(e)} der Member ≥ {e.p_ens_schwelle or 0:.0f} kn"
                 + (f", Spanne {ens_spanne_text(e)}" if e.p_ens_spanne else "") if e.p_ens is not None else ""))
    art = e.art + (f" ({e.wellen_text()})" if e.welle_h is not None else "")
    print(f"     {art} · {e.board} · {e.segel_text()} · {e.finne}")
    if e.wasser_t is not None or e.luft_t is not None:
        teile = ([f"Wasser {e.wasser_t:.0f} °C"] if e.wasser_t is not None else []) + \
                ([luft_text(e.luft_t, e.gef_t)] if e.luft_t is not None else [])
        print("     " + ", ".join(teile))
    for w in e.warnungen:
        print(f"     ! {w}")
    if s.hinweise:
        print(f"     · {'; '.join(s.hinweise)}")


NICHT_FUER_DICH: Dict[date, list] = {}
WENN_FREI: Dict[date, "Empfehlung"] = {}   # Arbeitstage ohne Feierabend-Spot: bester Spot, wenn man frei nimmt
WENN_FREI_R: Dict[Tuple[date, str], "Empfehlung"] = {}   # dasselbe je Revier (für die Revierseiten)


def nicht_fuer_dich(e) -> bool:
    return any("nicht empfohlen" in w for w in e.warnungen)


def konsole(ref: OrtDaten, ergebnisse, args, quelle: str, jetzt: datetime, jc=None) -> None:
    mehrere = len(ref.modelle) > 1
    print(f"WINDSURF-SPOTS AB ACHTERWEHR · {MARKE} {VERSION} · {quelle} · Stand {jetzt:%d.%m. %H:%M}")
    print(f"Mittelwind ab {args.min_kn:.0f} kn, Tageslicht, Setup für 90 kg"
          + (f", werktags ab {args.werktags_ab} Uhr" if args.werktags_ab is not None else "")
          + ("" if args.alle else f", Spots bis Stufe {DEINE_STUFE}")
          + (f", größtes Segel {qm(GROESSTES_SEGEL)}" if GROESSTES_SEGEL is not None else ""))
    print()
    if jc or PEGEL_JETZT:
        print("JETZT (DWD-Messung gegen Vorhersage)")
        for z in jetzt_zeilen(jc or []):
            print("  " + z)
        if PEGEL_JETZT:
            print("  " + pegel_jetzt_text())
        print()
    if warnungen_uebersicht():
        print("DWD-WARNUNGEN")
        for z in warnungen_uebersicht():
            print("  ! " + z)
        print()

    gute = [(t, l[0]) for t, l, _ in ergebnisse if l]
    chancen = [(t, c[0]) for t, l, c in ergebnisse if not l and c]
    if gute or chancen:
        print("ÜBERBLICK")
        for t, e in sorted(gute, key=lambda x: x[1].score, reverse=True):
            print(f"  {tag_text(t)}  {e.spot.name}, {e.sp_start:%H}–{e.sp_ende:%H} Uhr "
                  f"{e.richtung} {e.wind:.0f} kn, {qm(e.segel)}")
        for t, e in chancen:
            namen = ", ".join(MODELL_KURZ.get(m, m) for m in e.modelle_ok)
            print(f"  {tag_text(t)}  Chance: {e.spot.name}, {e.sp_start:%H}–{e.sp_ende:%H} Uhr "
                  f"{e.richtung} {e.wind:.0f}, bis {getattr(e, 'wind_max', None) or e.wind:.0f} kn ({namen})"
                  + (f", Ensemble {p_text(e)}" if e.p_ens is not None else ""))
    else:
        print("ÜBERBLICK: kein passender Gleitwind im Vorhersagezeitraum, auch nicht in einzelnen Modellen.")
    print()

    for tag, liste, ch in ergebnisse:
        kopf = tageskopf(ref, tag)
        print(f"=== {tag_text(tag)} " + "=" * 8 + (f"  {kopf}" if kopf else ""))
        if seewind_tag_text(tag):
            print("  ☀ " + seewind_tag_text(tag))
        if not liste and tag in WENN_FREI:
            f = WENN_FREI[tag]
            print("  Arbeitstag – nach Feierabend reicht es nicht (Wind oder Tageslicht).")
            print(f"  Wenn du frei nimmst: {f.spot.name} · Spitze {f.richtung} {f.wind:.0f} kn "
                  f"{f.sp_start:%H}–{f.sp_ende:%H} Uhr · fahrbar {fahrbar_text(f)} Uhr · {qm(f.segel)}"
                  + (f" · Ensemble {p_text(f)}" if f.p_ens is not None else ""))
        elif not liste:
            print("  kein passender Spot im Modellmittel")
        for i, e in enumerate(liste[:args.top], 1):
            drucke_empfehlung(i, e, mehrere)
        if NICHT_FUER_DICH.get(tag):
            print("  nicht für dich (Sicherheitsregel):")
            for e in NICHT_FUER_DICH[tag][:3]:
                grund = next(w for w in e.warnungen if "nicht empfohlen" in w)
                print(f"   - {e.spot.name} {e.richtung} {e.wind:.0f} kn {e.sp_start:%H}–{e.sp_ende:%H} Uhr, "
                      f"{qm(e.segel)}: {grund}")
        if ch:
            print("  Chance – nur einzelne Modelle sehen genug Wind:")
            for e in ch[:args.top]:
                namen = ", ".join(MODELL_KURZ.get(m, m) for m in e.modelle_ok)
                print(f"   ~ {e.spot.name} · {fahrzeit(e.spot.fahrt_min)} · Spitze bis {e.spitze_text()} "
                      f"({namen})")
                if e.p_ens is not None:
                    print(f"     Ensemble: {p_text(e)} der Member schaffen die Schwelle")
                print(f"     Modelle: {modell_text(e)} · Setup falls es kommt: {e.board} · "
                      f"{e.segel_text()} · {e.finne}")
        print()


def beste_fenster(spot_daten: List[OrtDaten], tage: List[date], args, jetzt: datetime):
    """Pro Spot und Tag das beste Fenster ab VIS_MIN_KN (auch knapp unter der Schwelle)."""
    raster = {}
    for spot, d in zip(SPOTS, spot_daten):
        for tag in tage:
            # erst das echte Fenster ab der Gleitwind-Schwelle, sonst das "knapp daneben"-Fenster,
            # dazu die Chance, wenn mindestens ein Modell die Schwelle schafft
            e = bewerte(spot, d, tag, args, jetzt, alle=True)
            chance = None
            if e is None:
                e = bewerte(spot, d, tag, args, jetzt, min_kn=VIS_MIN_KN, alle=True)
                if len(d.modelle) > 1:
                    chance = bewerte(spot, d, tag, args, jetzt, alle=True, optimistisch=True)
            raster[(spot.name, tag)] = (e, chance)
    return raster


def konsole_spots(raster, tage: List[date], args) -> None:
    print(f"SPOTS · bestes Fenster der nächsten {len(tage)} Tage "
          f"(passende Richtung, ab {VIS_MIN_KN} kn)")
    breite = max(len(s.name) for s in SPOTS) + 2
    for gruppe in ["Alltag", "Ausflug", "Für später"]:
        spots = [s for s in SPOTS if s.gruppe() == gruppe]
        if gruppe == "Für später" and not args.alle:
            continue
        print(f"\n  {gruppe.upper()}")
        for s in spots:
            kandidaten = [raster[(s.name, t)][0] for t in tage if raster[(s.name, t)][0]]
            chancen = [raster[(s.name, t)][1] for t in tage if raster[(s.name, t)][1]]
            if not kandidaten and not chancen:
                print(f"  {s.name:<{breite}}{fahrzeit(s.fahrt_min):>7}   –  kein passender Wind")
                continue
            if kandidaten:
                e = max(kandidaten, key=lambda x: x.wind)
                marke = "✓" if e.wind >= args.min_kn else f"(unter {args.min_kn:.0f})"
                print(f"  {s.name:<{breite}}{fahrzeit(s.fahrt_min):>7}   {tag_text(e.tag)} "
                      f"{e.sp_start:%H}–{e.sp_ende:%H}  {e.richtung:<4} Spitze {e.wind:3.0f} kn  {marke}")
            for c in sorted(chancen, key=lambda x: -x.wind)[:1]:
                namen = ", ".join(MODELL_KURZ.get(m, m) for m in c.modelle_ok)
                print(f"  {'':<{breite}}{'':>7}   ~ Chance {tag_text(c.tag)} {c.sp_start:%H}–{c.sp_ende:%H} "
                      f"{c.richtung} bis {c.wind:.0f} kn ({namen})")
    print()


