# Großräume für die Darstellung (Kopfleiste, Übersicht, Reiseplaner) – nach Wetterregime statt Land, weil Reviere
# Grenzen überspannen (Westküste DE/DK, Bodensee DE/CH/AT) und innerhalb eines Raums dieselben Lagen wirken.
REVIER_GRUPPEN: List[Tuple[str, Tuple[str, ...]]] = [
    ("Nord- & Ostsee", ("ostsee", "westkueste", "niederlande")),
    ("Alpen", ("bodensee", "walensee", "achensee", "romandie", "garda")),
    ("Mittelmeer & Atlantik", ("leucate", "portugal", "tarifa", "teneriffa")),
]


def reviere_gruppiert() -> List[Tuple[str, List[dict]]]:
    """Aktive Reviere nach Großraum; Reviere ohne Gruppe landen unter „Weitere“."""
    aktiv = [r for r in REVIERE if r["aktiv"]]
    aus, gesehen = [], set()
    for name, ids in REVIER_GRUPPEN:
        liste = [r for i in ids for r in aktiv if r["id"] == i]
        if liste:
            aus.append((name, liste))
            gesehen.update(r["id"] for r in liste)
    rest = [r for r in aktiv if r["id"] not in gesehen]
    if rest:
        aus.append(("Weitere", rest))
    return aus


def revier_von(s: "Spot") -> str:
    for r in REVIERE:
        b = r.get("bbox")
        if b and b[0] <= s.lat <= b[1] and b[2] <= s.lon <= b[3]:
            return r["id"]
    return "westkueste" if ist_westspot(s) else "ostsee"


def spot_modelle(s: "Spot", standard: str) -> str:
    """Open-Meteo-Modellliste für die Vorhersage eines Spots (Revier-eigene Liste, sonst --modelle)."""
    return revier(revier_von(s)).get("modelle") or standard


def revier(rid: str) -> dict:
    return next(r for r in REVIERE if r["id"] == rid)


SPOTS = [s for s in SPOTS if revier(revier_von(s))["aktiv"]]    # inaktive Reviere ganz weglassen


class karten_region:
    """Schaltet die Karten-Einstellungen (Gebiet, Raster, Modelle, Caches) für einen Block um, z. B. auf KARTE_WEST."""
    def __init__(self, cfg: Optional[dict]):
        self.cfg, self.alt = cfg or {}, {}

    def __enter__(self):
        g = globals()
        for k, v in self.cfg.items():
            self.alt[k] = g[k]
            g[k] = v
        return self

    def __exit__(self, *a):
        globals().update(self.alt)
        return False
DMI_EDR = "https://opendataapi.dmi.dk/v1/forecastedr/collections/harmonie_dini_sf"
MET_NORDIC_DAP = "https://thredds.met.no/thredds/dodsC/metpplatest/met_forecast_1_0km_nordic_latest.nc"
MET_SCHRITT = 2                                # MET Nordic hat 1 km – jeder 2. Punkt reicht (2 km)
# Lambert-Projektionen der Modelle (Kugel, ein Standardbreitenkreis) – aus den Metadaten der Dienste
LCC_DMI = {"lat0": 55.5, "lon0": -8.0, "lat1": 55.5, "R": 6371229.0}
LCC_MET = {"lat0": 63.0, "lon0": 15.0, "lat1": 63.0, "R": 6371000.0}
KARTE_FEHLER_DATEI = "karte_fehler.txt"


def _lcc_konst(p: dict) -> Tuple[float, float, float]:
    phi1 = math.radians(p["lat1"])
    n = math.sin(phi1)
    f = math.cos(phi1) * math.tan(math.pi / 4 + phi1 / 2) ** n / n
    rho0 = p["R"] * f / math.tan(math.pi / 4 + math.radians(p["lat0"]) / 2) ** n
    return n, f, rho0


def lcc_vor(lat: float, lon: float, p: dict) -> Tuple[float, float]:
    """Geografische Koordinaten → Lambert x/y (m)."""
    n, f, rho0 = _lcc_konst(p)
    rho = p["R"] * f / math.tan(math.pi / 4 + math.radians(lat) / 2) ** n
    th = n * math.radians(lon - p["lon0"])
    return rho * math.sin(th), rho0 - rho * math.cos(th)


def lcc_rueck(x: float, y: float, p: dict) -> Tuple[float, float]:
    """Lambert x/y (m) → (lat, lon)."""
    n, f, rho0 = _lcc_konst(p)
    dy = rho0 - y
    rho = math.copysign(math.hypot(x, dy), n)
    th = math.atan2(x, dy)
    lat = 2 * math.atan((p["R"] * f / rho) ** (1 / n)) - math.pi / 2
    return math.degrees(lat), p["lon0"] + math.degrees(th / n)


def karte_raster() -> Tuple[List[float], List[float]]:
    """Zielraster: gleichmäßig in Länge und in Mercator-y (so passt es pixelgenau auf die Webkarte).
    Rückgabe (Breiten Süd→Nord, Längen West→Ost)."""
    la0, la1, lo0, lo1 = KARTE_GEBIET
    nx = int(round((lo1 - lo0) / KARTE_DX_GRAD)) + 1
    lons = [lo0 + i * KARTE_DX_GRAD for i in range(nx)]
    merc = lambda la: math.log(math.tan(math.pi / 4 + math.radians(la) / 2))
    m0, m1 = merc(la0), merc(la1)
    dm = math.radians(KARTE_DX_GRAD)
    ny = int(round((m1 - m0) / dm)) + 1
    lats = [math.degrees(2 * math.atan(math.exp(m0 + j * dm)) - math.pi / 2) for j in range(ny)]
    return lats, lons


def _gebiet_proj(p: dict, rand_m: float = 6000.0) -> Tuple[float, float, float, float]:
    """Ausdehnung des Gebiets in der Projektion p (m), mit Rand. Der Rand ist gekrümmt – darum mehrere Punkte."""
    la0, la1, lo0, lo1 = KARTE_GEBIET
    pts = [lcc_vor(la0 + (la1 - la0) * a / 6, lo0 + (lo1 - lo0) * b / 6, p) for a in range(7) for b in range(7)]
    xs, ys = [q[0] for q in pts], [q[1] for q in pts]
    return min(xs) - rand_m, min(ys) - rand_m, max(xs) + rand_m, max(ys) + rand_m


def _fehlertext(roh: str) -> str:
    """Fehlermeldung eines Dienstes kurz: JSON-"message" oder Text einer HTML-Seite ohne Tags."""
    try:
        d = json.loads(roh)
        if isinstance(d, dict) and d.get("message"):
            return str(d["message"])[:300]
    except ValueError:
        pass
    m = re.search(r"<b>Message</b>\s*(.*?)</p>", roh, re.S)
    if m:
        return re.sub(r"<[^>]+>", " ", m.group(1)).strip()[:300]
    return re.sub(r"\s+", " ", re.sub(r"<style.*?</style>|<[^>]+>", " ", roh, flags=re.S)).strip()[:300]


def _karte_get(url: str, timeout: int = 180, versuche: int = 5, daten: Optional[bytes] = None,
               kopf: Optional[dict] = None) -> bytes:
    # eckige Klammern (OPeNDAP-Auswahl) müssen kodiert sein, sonst lehnt der Server mit 400 ab
    url = url.replace("[", "%5B").replace("]", "%5D")
    req = urllib.request.Request(url, data=daten, headers=kopf or {"User-Agent": "Mozilla/5.0 (windsurf_spots)"})
    for versuch in range(1, versuche + 1):
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return r.read()
        except urllib.error.HTTPError as e:
            try:
                text = _fehlertext(e.read().decode("utf-8", "replace"))
            except Exception:
                text = ""
            if (e.code == 429 or e.code >= 500) and versuch < versuche:
                warte = (15 if e.code == 429 else 5) * 2 ** (versuch - 1)
                print(f"\r\033[2K  Server ausgelastet (HTTP {e.code}) – neuer Versuch in {warte} s …",
                      end="", file=sys.stderr, flush=True)
                time_mod.sleep(warte)
                continue
            raise RuntimeError(f"HTTP {e.code}: {text}") from None
        except (urllib.error.URLError, TimeoutError, OSError) as e:
            if versuch < versuche:
                time_mod.sleep(5 * 2 ** (versuch - 1))
                continue
            raise RuntimeError(f"keine Verbindung ({getattr(e, 'reason', e)})") from None
    raise RuntimeError("keine Antwort")


def _karte_fehler(quelle: str, url: str, roh) -> None:
    """Rohantwort für die Fehlersuche ablegen (überschreibt die vorige)."""
    try:
        if isinstance(roh, bytes):
            roh = roh.decode("utf-8", "replace")
        Path(KARTE_FEHLER_DATEI).write_text(f"{quelle}\n{url}\n\n{str(roh)[:200000]}", encoding="utf-8")
    except OSError:
        pass


# --- DMI HARMONIE DINI über die Forecast-EDR-API (CoverageJSON im nativen Lambert-Gitter) ---

def _cov_achse(ax: dict) -> list:
    if "values" in ax:
        return list(ax["values"])
    if "start" in ax and "num" in ax:
        n = int(ax["num"])
        if n <= 1:
            return [ax["start"]]
        return [ax["start"] + (ax["stop"] - ax["start"]) * k / (n - 1) for k in range(n)]
    return []


def dmi_cov_lesen(d: dict) -> dict:
    """CoverageJSON (einzeln oder Collection) → {"x": [...], "y": [...], "t": [ISO...], "u": {t: [y][x]}, "v": …}.
    Achsenreihenfolge kommt aus axisNames/shape der Ranges."""
    covs = d.get("coverages") if d.get("type") == "CoverageCollection" else [d]
    if not covs:
        raise RuntimeError(f"keine Coverage in der Antwort ({str(d)[:200]})")
    xs = ys = None
    aus = {"u": {}, "v": {}}
    zeiten: List[str] = []
    for cov in covs:
        dom = cov.get("domain") or d.get("domain") or {}
        axes = dom.get("axes", {})
        x = _cov_achse(axes.get("x", {}))
        y = _cov_achse(axes.get("y", {}))
        t = _cov_achse(axes.get("t", {})) or [None]
        if not x or not y:
            raise RuntimeError(f"Achsen x/y fehlen ({list(axes)})")
        xs, ys = x, y
        for name, ziel in (("wind-10m-u", "u"), ("wind-10m-v", "v")):
            r = (cov.get("ranges") or {}).get(name)
            if not r:
                raise RuntimeError(f"Parameter {name} fehlt ({list((cov.get('ranges') or {}))})")
            namen = r.get("axisNames") or ["t", "y", "x"][-len(r.get("shape", [0, 0, 0])):]
            form = r.get("shape") or [len(t), len(y), len(x)][-len(namen):]
            werte = r["values"]
            schritt = {}
            s = 1
            for a, k in zip(reversed(namen), reversed(form)):
                schritt[a] = s
                s *= k
            for it, tt in enumerate(t):
                feld = []
                for iy in range(len(y)):
                    basis = schritt.get("t", 0) * it + schritt.get("y", 0) * iy
                    sx = schritt.get("x", 1)
                    feld.append([werte[basis + sx * ix] for ix in range(len(x))])
                aus[ziel][tt] = feld
                if ziel == "u" and tt not in zeiten:
                    zeiten.append(tt)
    aus.update({"x": xs, "y": ys, "t": zeiten})
    return aus


def _zeit_lokal(t) -> datetime:
    if isinstance(t, (int, float)):
        return _utc_zu_berlin(datetime(1970, 1, 1) + timedelta(seconds=t))
    return _utc_zu_berlin(datetime.fromisoformat(str(t).replace("Z", "+00:00")).replace(tzinfo=None))


DMI_BLOCK_H = 3            # Stunden je Abfrage (große Würfel lehnt der Dienst mit "Server is busy" ab)
DMI_PAUSE_MIN = 45         # nach einer Drosselung so lange nicht erneut versuchen (spart Wartezeit bei Handläufen)
DMI_ZEIT_S = 120           # höchstens so lange pro Lauf an DMI-Blöcken laden; der Rest kommt beim nächsten Lauf
DMI_CACHE = Path(__file__).resolve().parent / "karte_dmi_cache.json"
DMI_MIN_STUNDEN = 12       # weniger Stunden vom neuen Modelllauf: lieber den vorigen vollständigen zeigen


def _dmi_wuerfel(basis: str, bbox: str, von: Optional[datetime], bis: Optional[datetime],
                 versuche: int = 2) -> Tuple[str, bytes]:
    url = f"{basis}?bbox={bbox}&crs=native&parameter-name=wind-10m-u,wind-10m-v"
    if von is not None:
        url += f"&datetime={von:%Y-%m-%dT%H:%M:%SZ}/{bis:%Y-%m-%dT%H:%M:%SZ}"
    return url, _karte_get(url, versuche=versuche)


def _dmi_cache_lesen() -> dict:
    try:
        return json.loads(DMI_CACHE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def _dmi_lauf_ende(lauf: str) -> Optional[datetime]:
    """Letzte Vorhersagestunde (UTC) des Laufs aus den Metadaten, sonst None."""
    try:
        m = json.loads(_karte_get(f"{DMI_EDR}/instances/{lauf}", 60, versuche=2))
        iv = m["extent"]["temporal"]["interval"][0]
        return datetime.fromisoformat(iv[1].replace("Z", "+00:00")).replace(tzinfo=None)
    except (RuntimeError, ValueError, KeyError, TypeError, IndexError):
        return None


def hole_dmi_feld() -> dict:
    """Wind 10 m aus HARMONIE DINI im Kartengebiet. Der Dienst drosselt große Abfragen; darum in 6-h-Blöcken,
    mit Zeitbudget und Zwischenspeicher je Modelllauf: was diesmal nicht kommt, holt der nächste Lauf nach."""
    cache = _dmi_cache_lesen()
    gesperrt = cache.get("gedrosselt_um")
    if gesperrt and datetime.now() - datetime.fromisoformat(gesperrt) < timedelta(minutes=DMI_PAUSE_MIN):
        print(f"\r\033[2KHinweis: DMI hat um {gesperrt[11:16]} gedrosselt – nächster Versuch frühestens "
              f"{DMI_PAUSE_MIN} min später", file=sys.stderr)
        return _dmi_aus_cache(cache)
    lauf = ""
    try:
        inst = json.loads(_karte_get(DMI_EDR + "/instances", 60, versuche=3))
        ids = sorted(i["id"] for i in inst.get("instances", []) if i.get("id"))
        lauf = ids[-1] if ids else ""
    except (RuntimeError, ValueError, KeyError, TypeError) as e:
        if cache.get("stunden"):
            print(f"\r\033[2KHinweis: DMI nicht erreichbar ({e}) – zeige gespeicherten Lauf", file=sys.stderr)
            return _dmi_aus_cache(cache)
        raise
    basis = f"{DMI_EDR}/instances/{lauf}/cube" if lauf else DMI_EDR + "/cube"
    if cache.get("lauf") != lauf:
        alt = cache if len(cache.get("stunden", {})) >= DMI_MIN_STUNDEN else cache.get("vorher")
        if alt:
            alt = {k: v for k, v in alt.items() if k != "vorher"}
        cache = {"lauf": lauf, "stunden": {}, "vorher": alt}
    cache.pop("gedrosselt_um", None)
    x0, y0, x1, y1 = _gebiet_proj(LCC_DMI)
    utc0 = datetime.now(timezone.utc).replace(tzinfo=None, minute=0, second=0, microsecond=0) - timedelta(hours=1)
    ende = _dmi_lauf_ende(lauf) if lauf else None
    bis_max = utc0 + timedelta(hours=KARTE_STUNDEN)
    if ende:
        bis_max = min(bis_max, ende)
    bloecke = []
    k = 0
    while utc0 + timedelta(hours=k) <= bis_max:
        a = utc0 + timedelta(hours=k)
        bloecke.append((a, min(a + timedelta(hours=DMI_BLOCK_H - 1), bis_max)))
        k += DMI_BLOCK_H

    def lesen(url, roh):
        try:
            return dmi_cov_lesen(json.loads(roh))
        except (ValueError, RuntimeError, KeyError, TypeError, IndexError) as e:
            _karte_fehler("DMI", url, roh)
            raise RuntimeError(f"Antwort nicht lesbar ({e}) – Rohdaten in {KARTE_FEHLER_DATEI}") from None

    def lokal(t_utc):
        return _utc_zu_berlin(t_utc).strftime("%Y-%m-%dT%H:%M")

    start = time_mod.monotonic()
    gedrosselt = False
    for nr, (von, bis) in enumerate(bloecke, 1):
        stunden = [von + timedelta(hours=h) for h in range(int((bis - von).total_seconds() // 3600) + 1)]
        if all(lokal(t) in cache["stunden"] for t in stunden):
            continue                                   # schon von einem früheren Aufruf da
        if time_mod.monotonic() - start > DMI_ZEIT_S:
            gedrosselt = True
            break
        print(f"\r\033[2KWind-Player: DMI HARMONIE Block {nr}/{len(bloecke)} …", end="", file=sys.stderr, flush=True)
        faktoren = [cache["faktor"]] if cache.get("faktor") else [1000.0, 1.0]
        d = None
        for faktor in faktoren:                        # native Koordinaten laut Doku in km; zur Sicherheit auch m
            bbox = ",".join(f"{v / faktor:.3f}" for v in (x0, y0, x1, y1))
            try:
                url, roh = _dmi_wuerfel(basis, bbox, von, bis)
            except RuntimeError as e:
                if "HTTP 429" in str(e):
                    gedrosselt = True
                    break
                if "No data" in str(e) or "HTTP 404" in str(e):
                    continue
                raise
            d = lesen(url, roh)
            einheit = 1000.0 if max(abs(min(d["x"])), abs(max(d["x"]))) < 20000 else 1.0
            xm, ym = [v * einheit for v in d["x"]], [v * einheit for v in d["y"]]
            if min(xm) <= (x0 + x1) / 2 <= max(xm) and min(ym) <= (y0 + y1) / 2 <= max(ym):
                cache["faktor"] = faktor
                break
            _karte_fehler("DMI", url, roh)
            d = None
        if gedrosselt:
            break
        if d is None:
            if not cache["stunden"]:
                raise RuntimeError("keine Daten im Gebiet")
            break                                      # Ende des Laufs
        if "gedreht" not in cache:
            cache["gedreht"] = _dmi_drehung_pruefen(basis, d, xm, ym)
        try:
            teil = _auf_raster("DMI HARMONIE", lauf, LCC_DMI, xm, ym, d["t"],
                               lambda tt, iy, ix: _uv_zu_kn_grad(d["u"][tt][iy][ix], d["v"][tt][iy][ix]),
                               gitter_gedreht=cache["gedreht"])
        except RuntimeError:
            continue                                   # Block liegt ganz in der Vergangenheit
        for t, sp, ri in zip(teil["t"], teil["sp"], teil["ri"]):
            cache["stunden"][t] = [sp, ri]
        try:
            DMI_CACHE.write_text(json.dumps(cache), encoding="utf-8")
        except OSError:
            pass
        time_mod.sleep(3.0)
    if gedrosselt:
        cache["gedrosselt_um"] = datetime.now().isoformat(timespec="minutes")
        try:
            DMI_CACHE.write_text(json.dumps(cache), encoding="utf-8")
        except OSError:
            pass
        n = len(cache["stunden"])
        print(f"\r\033[2KHinweis: DMI drosselt gerade – {n} Stunden vom Lauf {lauf} geladen, "
              "der Rest kommt beim nächsten Aufruf", file=sys.stderr)
    return _dmi_aus_cache(cache)


def _dmi_aus_cache(cache: dict) -> dict:
    """Stunden des aktuellen Laufs; reicht das nicht, der vorige vollständige Lauf."""
    jetzt = datetime.now().replace(minute=0, second=0, microsecond=0)
    grenze = (jetzt - timedelta(hours=1)).strftime("%Y-%m-%dT%H:%M")

    def zukunft(c):
        return {t: v for t, v in (c or {}).get("stunden", {}).items() if t >= grenze}
    neu = zukunft(cache)
    quelle = cache
    if len(neu) < DMI_MIN_STUNDEN and len(zukunft(cache.get("vorher"))) > len(neu):
        quelle, neu = cache["vorher"], zukunft(cache.get("vorher"))
    if not neu:
        raise RuntimeError("keine DMI-Stunden verfügbar (Dienst drosselt)")
    t = sorted(neu)
    return {"name": "DMI HARMONIE", "lauf": quelle.get("lauf", ""), "t": t,
            "sp": [neu[x][0] for x in t], "ri": [neu[x][1] for x in t]}


def _dmi_drehung_pruefen(basis: str, d: dict, xm: List[float], ym: List[float]) -> bool:
    """u/v der Flächenabfrage sind laut DMI aufs Lambert-Gitter bezogen. Gegenprobe mit der Punktabfrage, die die
    Richtung geografisch liefert: passt die gedrehte oder die ungedrehte Richtung? Ohne Antwort: gedreht."""
    la, lo = 54.50, 10.27                                    # Kiel Leuchtturm, freies Wasser
    x, y = lcc_vor(la, lo, LCC_DMI)
    ix = int(round((x - xm[0]) / ((xm[-1] - xm[0]) / (len(xm) - 1))))
    iy = int(round((y - ym[0]) / ((ym[-1] - ym[0]) / (len(ym) - 1))))
    try:
        url = (basis.replace("/cube", "/position") + f"?coords=POINT({lo}%20{la})&crs=crs84"
               "&parameter-name=wind-dir-10m,wind-speed-10m")
        pos = json.loads(_karte_get(url, 60))
        t_pos = _cov_achse(pos["domain"]["axes"]["t"])
        r_pos = pos["ranges"]["wind-dir-10m"]["values"]
        s_pos = pos["ranges"]["wind-speed-10m"]["values"]
    except (RuntimeError, ValueError, KeyError, TypeError, IndexError) as e:
        print(f"\r\033[2KHinweis: DMI-Richtungsprüfung nicht möglich ({e}) – nehme Gitterbezug an", file=sys.stderr)
        return True
    n = _lcc_konst(LCC_DMI)[0]
    th = n * math.radians(lo - LCC_DMI["lon0"])
    c, s_ = math.cos(th), math.sin(th)
    abw_dreh, abw_roh = [], []
    for tt, r, sp in zip(t_pos, r_pos, s_pos):
        if tt not in d["u"] or r is None or sp is None or sp < 2:
            continue
        ug, vg = d["u"][tt][iy][ix], d["v"][tt][iy][ix]
        if ug is None or vg is None:
            continue
        for uu, vv, ziel in ((ug * c + vg * s_, -ug * s_ + vg * c, abw_dreh), (ug, vg, abw_roh)):
            von = (math.degrees(math.atan2(-uu, -vv)) + 360) % 360
            ziel.append(abs((von - r + 180) % 360 - 180))
    if len(abw_dreh) < 3:
        return True
    m_dreh, m_roh = sorted(abw_dreh)[len(abw_dreh) // 2], sorted(abw_roh)[len(abw_roh) // 2]
    if m_roh + 3 < m_dreh:
        print(f"\r\033[2KHinweis: DMI-Wind ist schon geografisch ausgerichtet (Abweichung {m_roh:.0f}° statt "
              f"{m_dreh:.0f}°) – keine Drehung", file=sys.stderr)
        return False
    return True


def _uv_zu_kn_grad(u, v) -> Optional[Tuple[float, float, float]]:
    if u is None or v is None:
        return None
    return u * 1.943844, v * 1.943844, 0.0      # Komponenten in kn (Drehung folgt in _auf_raster)


# --- MET Nordic über THREDDS/OPeNDAP (Text-Antwort, keine Zusatzpakete) ---

def dap_ascii_lesen(text: str) -> Dict[str, List[Optional[float]]]:
    """OPeNDAP-.ascii-Antwort → {Variablenname: flache Werteliste} (Reihenfolge wie im Datensatz, C-Ordnung)."""
    teile = re.split(r"\n-{20,}\n", text, maxsplit=1)
    rumpf = teile[1] if len(teile) > 1 else text
    aus: Dict[str, List[Optional[float]]] = {}
    cur = None

    def zahl(s: str) -> Optional[float]:
        s = s.strip()
        try:
            v = float(s)
        except ValueError:
            return None
        return None if (v != v or abs(v) > 1e20) else v
    for zeile in rumpf.splitlines():
        z = zeile.strip()
        if not z:
            continue
        m = re.match(r"^([A-Za-z_][\w.]*)((?:\[\d+\])+)$", z)
        if m:
            cur = m.group(1)
            aus[cur] = []
            continue
        if z.startswith("["):
            if cur is not None:
                aus[cur].extend(zahl(s) for s in z.split(",")[1:])
            continue
        m = re.match(r"^([A-Za-z_][\w.]*), (.+)$", z)
        if m and not re.match(r"^[-\d.]", z):
            aus[m.group(1)] = [zahl(m.group(2))]
            cur = None
            continue
        if cur is not None:
            aus[cur].extend(zahl(s) for s in z.split(","))
    return aus


def _dap_wert(d: dict, name: str) -> List[Optional[float]]:
    for k, v in d.items():
        if k == name or k.endswith("." + name):
            return v
    raise RuntimeError(f"{name} fehlt in der Antwort ({list(d)[:6]})")


def hole_met_feld() -> dict:
    print(f"\r\033[2KWind-Player: MET Nordic lädt …", end="", file=sys.stderr, flush=True)
    url = MET_NORDIC_DAP + ".ascii?x,y,time,forecast_reference_time"
    roh = _karte_get(url, 90).decode("utf-8", "replace")
    try:
        k = dap_ascii_lesen(roh)
        xa, ya, ta = _dap_wert(k, "x"), _dap_wert(k, "y"), _dap_wert(k, "time")
        ref = _dap_wert(k, "forecast_reference_time")[0]
    except RuntimeError as e:
        _karte_fehler("MET Koordinaten", url, roh)
        raise RuntimeError(f"{e} – Rohdaten in {KARTE_FEHLER_DATEI}") from None
    x0, y0, x1, y1 = _gebiet_proj(LCC_MET)

    def bereich(achse, a, b):
        idx = [i for i, v in enumerate(achse) if v is not None and a <= v <= b]
        if not idx:
            raise RuntimeError("Gebiet liegt außerhalb von MET Nordic")
        return min(idx), max(idx)
    i0, i1 = bereich(xa, x0, x1)
    j0, j1 = bereich(ya, y0, y1)
    s = MET_SCHRITT
    i1 = i0 + (i1 - i0) // s * s
    j1 = j0 + (j1 - j0) // s * s
    tidx = list(range(0, len(ta), max(1, KARTE_TAKT)))
    nt = len(tidx)
    sel = f"[0:{max(1, KARTE_TAKT)}:{tidx[-1]}][{j0}:{s}:{j1}][{i0}:{s}:{i1}]"
    felder = {}
    for var in ("wind_speed_10m", "wind_direction_10m"):
        url = f"{MET_NORDIC_DAP}.ascii?{var}.{var}{sel}"
        roh = _karte_get(url).decode("utf-8", "replace")
        try:
            felder[var] = _dap_wert(dap_ascii_lesen(roh), var)
        except RuntimeError as e:
            _karte_fehler("MET " + var, url, roh)
            raise RuntimeError(f"{e} – Rohdaten in {KARTE_FEHLER_DATEI}") from None
    nx, ny = (i1 - i0) // s + 1, (j1 - j0) // s + 1
    if len(felder["wind_speed_10m"]) != nt * nx * ny:
        _karte_fehler("MET Größe", url, roh)
        raise RuntimeError(f"unerwartete Datenmenge ({len(felder['wind_speed_10m'])} statt {nt * nx * ny})")
    xm = [xa[i] for i in range(i0, i1 + 1, s)]
    ym = [ya[j] for j in range(j0, j1 + 1, s)]
    ws, wd = felder["wind_speed_10m"], felder["wind_direction_10m"]

    def wert(it, iy, ix):
        k_ = (it * ny + iy) * nx + ix
        a, r = ws[k_], wd[k_]
        if a is None or r is None:
            return None
        kn = a * 1.943844
        rad = math.radians(r)
        return -kn * math.sin(rad), -kn * math.cos(rad), 0.0      # u (Ost), v (Nord) in kn
    lauf = (datetime(1970, 1, 1) + timedelta(seconds=ref)).strftime("%Y-%m-%dT%H%M%SZ") if ref else ""
    return _auf_raster("MET Nordic", lauf, LCC_MET, xm, ym, list(range(nt)), wert, gitter_gedreht=False,
                       zeit_von=lambda it: ta[tidx[it]])


def _auf_raster(name: str, lauf: str, p: dict, xm: List[float], ym: List[float], zeiten: list, wert,
                gitter_gedreht: bool, zeit_von=None, zeitfilter: bool = True) -> dict:
    """Natives Lambert-Gitter → Zielraster (nächster Nachbar). wert(t, iy, ix) liefert (u, v, _) in kn,
    bei gitter_gedreht=True relativ zum Gitter (wird auf geografisch Nord gedreht)."""
    lats, lons = karte_raster()
    dx = (xm[-1] - xm[0]) / (len(xm) - 1) if len(xm) > 1 else 1.0
    dy = (ym[-1] - ym[0]) / (len(ym) - 1) if len(ym) > 1 else 1.0
    n = _lcc_konst(p)[0]
    zuordnung = []
    for la in lats:
        for lo in lons:
            x, y = lcc_vor(la, lo, p)
            ix, iy = int(round((x - xm[0]) / dx)), int(round((y - ym[0]) / dy))
            if 0 <= ix < len(xm) and 0 <= iy < len(ym):
                th = n * math.radians(lo - p["lon0"]) if gitter_gedreht else 0.0
                zuordnung.append((iy, ix, math.cos(th), math.sin(th)))
            else:
                zuordnung.append(None)
    jetzt = datetime.now().replace(minute=0, second=0, microsecond=0)
    aus_t, sp, ri = [], [], []
    for tt in zeiten:
        t_lok = _zeit_lokal(zeit_von(tt) if zeit_von else tt)
        if zeitfilter and (t_lok < jetzt - timedelta(hours=1) or t_lok > jetzt + timedelta(hours=KARTE_STUNDEN)):
            continue
        b_sp, b_ri = bytearray(), bytearray()
        for z in zuordnung:
            w = wert(tt, z[0], z[1]) if z else None
            if w is None:
                b_sp.append(255)
                b_ri.append(0)
                continue
            ug, vg, _ = w
            c, s_ = z[2], z[3]
            u, v = ug * c + vg * s_, -ug * s_ + vg * c      # Gitter → geografisch (Ost, Nord)
            kn = math.hypot(u, v)
            von = (math.degrees(math.atan2(-u, -v)) + 360) % 360
            b_sp.append(min(254, int(round(kn * 4))))
            b_ri.append(int(round(von / 360 * 256)) % 256)
        aus_t.append(t_lok.strftime("%Y-%m-%dT%H:%M"))
        sp.append(base64.b64encode(bytes(b_sp)).decode("ascii"))
        ri.append(base64.b64encode(bytes(b_ri)).decode("ascii"))
    if not aus_t:
        raise RuntimeError("keine Zeitschritte im Zeitraum")
    return {"name": name, "lauf": lauf, "t": aus_t, "sp": sp, "ri": ri}


# --- Küstenlinien für den Player: aus dem Landanteil von MET Nordic (1 km), einmal geladen und gespeichert ---
KUESTE_CACHE = Path(__file__).resolve().parent / "karte_kueste.json"
KUESTE_VERSION = 2
# OpenStreetMap-Küstenlinie (natural=coastline) über die Overpass-API – mehrere öffentliche Server nacheinander
OVERPASS = ["https://overpass-api.de/api/interpreter", "https://overpass.kumi.systems/api/interpreter",
            "https://overpass.private.coffee/api/interpreter"]
# Ersatz, wenn Overpass nicht antwortet: Natural Earth 1:10 Mio. (gröber, aber lagerichtig)
NATURAL_EARTH = ("https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/"
                 "ne_10m_coastline.geojson")
OSM_NEU_VERSUCH_H = 12     # gröbere Küste im Speicher: so oft erneut OSM versuchen
KARTE_ORTE = [("Kiel", 54.323, 10.135), ("Eckernförde", 54.469, 9.838), ("Schleswig", 54.515, 9.565),
              ("Kappeln", 54.662, 9.931), ("Flensburg", 54.785, 9.437), ("Sønderborg", 54.913, 9.792),
              ("Als", 55.03, 9.95), ("Ærø", 54.86, 10.37), ("Langeland", 54.93, 10.74),
              ("Lolland", 54.76, 11.42), ("Fehmarn", 54.47, 11.14), ("Heiligenhafen", 54.373, 10.98),
              ("Oldenburg i. H.", 54.29, 10.88), ("Neustadt", 54.107, 10.815), ("Plön", 54.162, 10.42),
              ("Laboe", 54.402, 10.225), ("Hohwacht", 54.318, 10.674)]


def marching_squares(f: List[List[Optional[float]]], schwelle: float = 0.5) -> List[List[Tuple[float, float]]]:
    """Isolinien von f (Zeilen j, Spalten i) auf Höhe schwelle; Rückgabe in Gitterkoordinaten (i, j) als
    zusammenhängende Linienzüge. Fehlwerte zählen als Wasser."""
    ny, nx = len(f), len(f[0])
    w = lambda j, i: 0.0 if f[j][i] is None else f[j][i]

    def punkt(kante):
        art, j, i = kante
        if art == "h":                                 # zwischen (j,i) und (j,i+1)
            a, b = w(j, i), w(j, i + 1)
            t = 0.5 if a == b else (schwelle - a) / (b - a)
            return (i + t, float(j))
        a, b = w(j, i), w(j + 1, i)                    # zwischen (j,i) und (j+1,i)
        t = 0.5 if a == b else (schwelle - a) / (b - a)
        return (float(i), j + t)
    nachbarn: Dict[tuple, list] = {}
    for j in range(ny - 1):
        for i in range(nx - 1):
            a, b, c, d = w(j, i) > schwelle, w(j, i + 1) > schwelle, w(j + 1, i + 1) > schwelle, w(j + 1, i) > schwelle
            fall = a * 1 + b * 2 + c * 4 + d * 8
            if fall in (0, 15):
                continue
            unten, rechts, oben, links = ("h", j, i), ("v", j, i + 1), ("h", j + 1, i), ("v", j, i)
            mitte = (w(j, i) + w(j, i + 1) + w(j + 1, i + 1) + w(j + 1, i)) / 4 > schwelle
            seg = {1: [(links, unten)], 2: [(unten, rechts)], 3: [(links, rechts)], 4: [(rechts, oben)],
                   5: [(links, oben), (unten, rechts)] if mitte else [(links, unten), (rechts, oben)],
                   6: [(unten, oben)], 7: [(links, oben)], 8: [(oben, links)], 9: [(oben, unten)],
                   10: [(unten, links), (oben, rechts)] if mitte else [(unten, rechts), (oben, links)],
                   11: [(oben, rechts)], 12: [(rechts, links)], 13: [(rechts, unten)], 14: [(unten, links)]}[fall]
            for p, q in seg:
                nachbarn.setdefault(p, []).append(q)
                nachbarn.setdefault(q, []).append(p)
    linien, besucht = [], set()

    def laufe(von):
        kette, akt = [], von
        while True:
            weiter = [q for q in nachbarn[akt] if q not in besucht]
            if not weiter:
                return kette
            akt = weiter[0]
            besucht.add(akt)
            kette.append(akt)
    for start in list(nachbarn):
        if start in besucht:
            continue
        besucht.add(start)
        vor = [start] + laufe(start)
        if len(vor) > 2 and start in nachbarn[vor[-1]]:
            vor.append(start)                          # geschlossener Ring
        else:
            vor = laufe(start)[::-1] + vor
        linien.append([punkt(k) for k in vor])
    return linien


def _vereinfachen(pts: List[Tuple[float, float]], tol: float) -> List[Tuple[float, float]]:
    """Douglas-Peucker (iterativ); geschlossene Ringe werden am weitesten Punkt geteilt."""
    if len(pts) < 3:
        return pts
    if pts[0] == pts[-1]:
        k = max(range(len(pts)), key=lambda q: math.hypot(pts[q][0] - pts[0][0], pts[q][1] - pts[0][1]))
        if 0 < k < len(pts) - 1:
            return _vereinfachen(pts[:k + 1], tol)[:-1] + _vereinfachen(pts[k:], tol)
    behalten = [False] * len(pts)
    behalten[0] = behalten[-1] = True
    stapel = [(0, len(pts) - 1)]
    while stapel:
        a, b = stapel.pop()
        (xa, ya), (xb, yb) = pts[a], pts[b]
        dx, dy = xb - xa, yb - ya
        n = math.hypot(dx, dy) or 1e-12
        best, idx = 0.0, None
        for k in range(a + 1, b):
            dist = abs(dy * (pts[k][0] - xa) - dx * (pts[k][1] - ya)) / n
            if dist > best:
                best, idx = dist, k
        if idx is not None and best > tol:
            behalten[idx] = True
            stapel += [(a, idx), (idx, b)]
    return [p for p, k in zip(pts, behalten) if k]


def kueste_aus_landanteil(f: List[List[Optional[float]]], gitter_zu_geo) -> dict:
    """Landanteil (Zeilen j, Spalten i) → Küstenlinien (lat/lon) und Landmaske auf dem Zielraster.
    gitter_zu_geo(i, j) → (lat, lon) für gebrochene Gitterkoordinaten."""
    linien = []
    for l in marching_squares(f, 0.5):
        if len(l) < 4:
            continue
        geo = [gitter_zu_geo(i, j) for i, j in l]
        geo = _vereinfachen([(la, lo) for la, lo in geo], 0.0015)
        if len(geo) >= 3:
            linien.append([[round(la, 4), round(lo, 4)] for la, lo in geo])
    return {"linien": linien}


def _land_raster(wert_geo) -> str:
    """Landanteil (0–255) auf dem Zielraster, base64; wert_geo(lat, lon) → Anteil 0…1 oder None."""
    lats, lons = karte_raster()
    b = bytearray()
    for la in lats:
        for lo in lons:
            v = wert_geo(la, lo)
            b.append(0 if v is None else max(0, min(255, int(round(v * 255)))))
    return base64.b64encode(bytes(b)).decode("ascii")


def osm_linien_verbinden(wege: List[List[Tuple[float, float]]]) -> List[List[Tuple[float, float]]]:
    """OSM-Küstenwege hängen Ende an Anfang aneinander – zu langen Linienzügen verbinden."""
    offen = [list(w) for w in wege if len(w) >= 2]
    anfang = {}
    for k, w in enumerate(offen):
        anfang.setdefault(w[0], []).append(k)
    benutzt = [False] * len(offen)
    aus = []
    for k in range(len(offen)):
        if benutzt[k]:
            continue
        benutzt[k] = True
        kette = offen[k][:]
        while True:
            nxt = [m for m in anfang.get(kette[-1], []) if not benutzt[m]]
            if not nxt:
                break
            benutzt[nxt[0]] = True
            kette += offen[nxt[0]][1:]
        aus.append(kette)
    # Ketten, deren Ende an den Anfang einer anderen Kette passt, noch einmal zusammenfügen
    geaendert = True
    while geaendert:
        geaendert = False
        start = {k[0]: i for i, k in enumerate(aus)}
        for i, k in enumerate(aus):
            j = start.get(k[-1])
            if j is not None and j != i:
                aus[i] = k + aus[j][1:]
                aus.pop(j)
                geaendert = True
                break
    return aus


def _overpass(abfrage: str) -> dict:
    """Overpass-Abfrage (mit {bbox}-Platzhalter, Gebiet + Rand) über die Server der Reihe nach; JSON-Antwort."""
    la0, la1, lo0, lo1 = KARTE_GEBIET
    r = 0.05
    q = '[out:json][timeout:180];' + abfrage.format(bbox=f"{la0 - r},{lo0 - r},{la1 + r},{lo1 + r}")
    fehler = []
    for server in OVERPASS:
        print(f"\r\033[2KWind-Player: Küstenlinie von OpenStreetMap laden ({server.split('/')[2]}) …",
              end="", file=sys.stderr, flush=True)
        try:
            # POST wie von Overpass vorgesehen; eigener User-Agent (generische werden mit 406 abgewiesen)
            roh = _karte_get(server, 240, versuche=2, daten=urllib.parse.urlencode({"data": q}).encode(),
                             kopf={"User-Agent": "windsurf_spots/1.3 (private Windsurf-Vorhersage, Python urllib)",
                                   "Accept": "application/json",
                                   "Content-Type": "application/x-www-form-urlencoded"})
            d = json.loads(roh)
            if d.get("elements"):
                return d
            fehler.append(f"{server.split('/')[2]}: keine Elemente in der Antwort")
        except (RuntimeError, ValueError, KeyError, TypeError) as e:
            fehler.append(f"{server.split('/')[2]}: {str(e)[:120]}")
    raise RuntimeError(" | ".join(fehler))


def _ketten(wege: List[List[Tuple[float, float]]], min_punkte: int = 2) -> List[List[List[float]]]:
    aus = []
    for kette in osm_linien_verbinden(wege):
        v = _vereinfachen(kette, KUESTE_TOL)
        if len(v) >= min_punkte:
            aus.append([[round(la, 5), round(lo, 5)] for la, lo in v])
    return aus


def _geom(g: list) -> List[Tuple[float, float]]:
    return [(round(x["lat"], 7), round(x["lon"], 7)) for x in g]


def hole_osm_kueste() -> List[List[List[float]]]:
    """Küstenlinie aus OpenStreetMap (Overpass-API), vereinfacht."""
    d = _overpass(KUESTE_OSM_ABFRAGE)
    wege = [_geom(el["geometry"]) for el in d.get("elements", []) if el.get("type") == "way" and el.get("geometry")]
    if not wege:
        raise RuntimeError("keine Küstenlinie in der Antwort")
    return _ketten(wege)


def hole_osm_gewaesser() -> List[List[List[List[float]]]]:
    """Wasserflächen (Seen, Lagunen) aus OSM nach KUESTE_GEWAESSER: je Fläche ihre Ringe (vereinfacht)."""
    d = _overpass(KUESTE_GEWAESSER)
    flaechen = []
    for el in d.get("elements", []):
        if el.get("type") == "relation":
            wege = [_geom(m["geometry"]) for m in el.get("members", []) if m.get("type") == "way" and m.get("geometry")]
        elif el.get("type") == "way" and el.get("geometry"):
            wege = [_geom(el["geometry"])]
        else:
            continue
        ringe = _ketten(wege, 3)
        if ringe:
            flaechen.append(ringe)
    if not flaechen:
        raise RuntimeError("keine Wasserfläche in der Antwort")
    return flaechen


def _in_flaeche(ringe: List[List[List[float]]], la: float, lo: float) -> bool:
    """Gerade/ungerade Schnittzahl über alle Ringstücke einer Fläche (Inseln zählen so als Land)."""
    drin = False
    for ring in ringe:
        for (la1, lo1), (la2, lo2) in zip(ring, ring[1:]):
            if (la1 > la) != (la2 > la):
                if lo1 + (la - la1) * (lo2 - lo1) / (la2 - la1) > lo:
                    drin = not drin
    return drin


def _im_wasser_fn(flaechen: List[List[List[List[float]]]]):
    """Schnelltest gegen alle Flächen (mit Rahmen je Fläche)."""
    rahmen = []
    for f in flaechen:
        pts = [p for r in f for p in r]
        rahmen.append((min(p[0] for p in pts), max(p[0] for p in pts), min(p[1] for p in pts), max(p[1] for p in pts)))

    def im_wasser(la, lo):
        return any(r[0] <= la <= r[1] and r[2] <= lo <= r[3] and _in_flaeche(f, la, lo)
                   for f, r in zip(flaechen, rahmen))
    return im_wasser


def hole_ne_kueste() -> List[List[List[float]]]:
    """Küstenlinie aus Natural Earth 1:10 Mio. (GitHub) – nur die Stücke im Kartengebiet."""
    print("\r\033[2KWind-Player: Küstenlinie von Natural Earth laden …", end="", file=sys.stderr, flush=True)
    d = json.loads(_karte_get(NATURAL_EARTH, 240, versuche=2))
    la0, la1, lo0, lo1 = KARTE_GEBIET
    r = 0.1
    drin = lambda la, lo: la0 - r <= la <= la1 + r and lo0 - r <= lo <= lo1 + r
    linien = []
    for f in d.get("features", []):
        g = f.get("geometry") or {}
        teile = [g.get("coordinates", [])] if g.get("type") == "LineString" else g.get("coordinates", [])
        for linie in teile:
            akt: List[Tuple[float, float]] = []
            for lo, la in linie:
                if drin(la, lo):
                    akt.append((la, lo))
                elif akt:
                    if len(akt) >= 2:
                        linien.append(akt)
                    akt = []
            if len(akt) >= 2:
                linien.append(akt)
    if not linien:
        raise RuntimeError("keine Küste im Gebiet")
    return [[[round(la, 5), round(lo, 5)] for la, lo in l] for l in linien]


def see_ufer() -> dict:
    """Seeufer aus OSM (KUESTE_GEWAESSER) und Landmaske: Land ist alles außerhalb der Wasserflächen."""
    flaechen = hole_osm_gewaesser()
    im_wasser = _im_wasser_fn(flaechen)
    return {"linien": [r for f in flaechen for r in f], "quelle": "© OpenStreetMap-Mitwirkende",
            "gebiet": list(KARTE_GEBIET), "version": KUESTE_VERSION,
            "osm_versuch": datetime.now().isoformat(timespec="minutes"),
            "land": _land_raster(lambda la, lo: 0.0 if im_wasser(la, lo) else 1.0)}


def land_kreuzungen_fn(linien: List[List[List[float]]], seepunkt: Tuple[float, float]):
    """Land/Wasser aus der OSM-Küstenlinie, unabhängig von ihrer Laufrichtung: Wie oft schneidet die Strecke vom
    bekannten Wasserpunkt zur Zelle die Küste? Gerade = Wasser, ungerade = Land. Robust gegen falsch herum
    erfasste Küstenstücke und spitze Molen; die Linien laufen über den Kartenrand hinaus (Abfrage mit Rand)."""
    c = math.cos(math.radians(sum(KARTE_GEBIET[:2]) / 2))
    seg = [(a[1] * c, a[0], b[1] * c, b[0]) for l in linien for a, b in zip(l, l[1:]) if a != b]
    sx, sy = seepunkt[1] * c, seepunkt[0]

    def seite(ax, ay, bx, by, px, py):
        return (bx - ax) * (py - ay) - (by - ay) * (px - ax)

    def land(la, lo):
        px, py = lo * c, la
        x0, x1, y0, y1 = min(sx, px), max(sx, px), min(sy, py), max(sy, py)
        n = 0
        for ax, ay, bx, by in seg:
            if max(ax, bx) < x0 or min(ax, bx) > x1 or max(ay, by) < y0 or min(ay, by) > y1:
                continue
            if (seite(sx, sy, px, py, ax, ay) > 0) != (seite(sx, sy, px, py, bx, by) > 0) and \
                    (seite(ax, ay, bx, by, sx, sy) > 0) != (seite(ax, ay, bx, by, px, py) > 0):
                n += 1
        return float(n % 2)
    return land


def osm_meer_land() -> dict:
    """Meeresküste aus OSM (Land links der Linie) plus Lagunen/Seen aus KUESTE_GEWAESSER – für Reviere ohne
    MET-Nordic-Landmaske (Leucate, Tarifa)."""
    linien = hole_osm_kueste()
    flaechen = []
    if KUESTE_GEWAESSER:
        try:
            flaechen = hole_osm_gewaesser()
        except RuntimeError as e:
            print(f"\r\033[2KHinweis: Lagunen/Seen nicht geladen ({e})", file=sys.stderr)
    land = land_kreuzungen_fn(linien, KUESTE_SEEPUNKT)
    im_wasser = _im_wasser_fn(flaechen) if flaechen else (lambda la, lo: False)
    return {"linien": linien + [r for f in flaechen for r in f], "quelle": "© OpenStreetMap-Mitwirkende",
            "gebiet": list(KARTE_GEBIET), "version": KUESTE_VERSION,
            "osm_versuch": datetime.now().isoformat(timespec="minutes"),
            "land": _land_raster(lambda la, lo: 0.0 if im_wasser(la, lo) else land(la, lo))}


def genaue_kueste(c: dict) -> None:
    """Trägt die beste erreichbare Küstenlinie in c ein (OSM, sonst Natural Earth); sonst bleibt die Modellküste."""
    c["osm_versuch"] = datetime.now().isoformat(timespec="minutes")
    try:
        c["linien"], c["quelle"] = hole_osm_kueste(), "© OpenStreetMap-Mitwirkende"
        return
    except Exception as e:
        print(f"\r\033[2KHinweis: OSM-Küste nicht geladen ({e})", file=sys.stderr)
    if c.get("quelle") == "Natural Earth":
        return
    try:
        c["linien"], c["quelle"] = hole_ne_kueste(), "Natural Earth"
        print("\r\033[2KHinweis: nehme die gröbere Küste von Natural Earth – OSM wird später erneut versucht",
              file=sys.stderr)
    except Exception as e:
        print(f"\r\033[2KHinweis: auch Natural Earth nicht geladen ({e}) – nehme die Modellküste", file=sys.stderr)


def _im_wasser_linien(kueste: dict):
    """Wasser-Test aus den gespeicherten Linien: Seeufer = ungerade Schnittzahl (doppelte Ringe aus sich
    überlappenden OSM-Relationen zählen einmal); Meeresküste = Schnittzahl vom KUESTE_SEEPUNKT aus."""
    if KUESTE_ART == "osm":
        land = land_kreuzungen_fn(kueste.get("linien") or [], KUESTE_SEEPUNKT)
        return lambda la, lo: land(la, lo) < 0.5
    ringe, gesehen = [], set()
    for r in kueste.get("linien") or []:
        k = tuple(map(tuple, r))
        if k in gesehen or tuple(reversed(k)) in gesehen:
            continue
        gesehen.add(k)
        ringe.append(r)
    return lambda la, lo: _in_flaeche(ringe, la, lo)


def _abstand_ufer_m(kueste: dict, la: float, lo: float) -> float:
    c = math.cos(math.radians(la))
    best = float("inf")
    for l in kueste.get("linien") or []:
        for (a1, o1), (a2, o2) in zip(l, l[1:]):
            ax, ay, bx, by, px, py = o1 * c, a1, o2 * c, a2, lo * c, la
            dx, dy = bx - ax, by - ay
            ll = dx * dx + dy * dy
            t = 0.0 if ll == 0 else max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / ll))
            best = min(best, math.hypot(ax + t * dx - px, ay + t * dy - py))
    return best * 111320.0


def spots_an_land(kueste: dict) -> List[Tuple[str, Optional[Tuple[float, float]]]]:
    """Spots des Kartenreviers, die laut OSM-Ufer/Küste an Land liegen, mit Vorschlag: nächster Wasserpunkt
    mindestens 250 m vom Ufer (Suche bis 3 km) oder None."""
    if not kueste or not kueste.get("linien"):
        return []
    im_wasser = _im_wasser_linien(kueste)
    aus = []
    for s in SPOTS:
        if revier_von(s) != KARTE_REVIER or im_wasser(s.lat, s.lon):
            continue
        c = math.cos(math.radians(s.lat))
        kand = sorted(((dy * 100.0) ** 2 + (dx * 100.0) ** 2, s.lat + dy * 100 / 111320, s.lon + dx * 100 / (111320 * c))
                      for dy in range(-30, 31) for dx in range(-30, 31))
        vorschlag = None
        for _, la, lo in kand:
            if im_wasser(la, lo) and _abstand_ufer_m(kueste, la, lo) >= 250:
                vorschlag = (round(la, 4), round(lo, 4))
                break
        aus.append((s.name, vorschlag))
    return aus


def hole_kueste(demo: bool = False) -> Optional[dict]:
    """Küste und Landmaske für den Player (gespeichert in karte_kueste.json – ändert sich ja nicht)."""
    if demo:
        return demo_kueste()
    try:
        c = json.loads(KUESTE_CACHE.read_text(encoding="utf-8"))
        if c.get("gebiet") == list(KARTE_GEBIET) and c.get("version") == KUESTE_VERSION:
            versuch = c.get("osm_versuch")
            if "OpenStreetMap" not in c.get("quelle", "") and (
                    not versuch or datetime.now() - datetime.fromisoformat(versuch) > timedelta(hours=OSM_NEU_VERSUCH_H)):
                genaue_kueste(c)
                try:
                    KUESTE_CACHE.write_text(json.dumps(c), encoding="utf-8")
                except OSError:
                    pass
            return c
    except (OSError, ValueError):
        pass
    print("\r\033[2KWind-Player: Küstenlinien laden (einmalig) …", end="", file=sys.stderr, flush=True)
    if KUESTE_ART in ("see", "osm"):
        c = see_ufer() if KUESTE_ART == "see" else osm_meer_land()
        try:
            KUESTE_CACHE.write_text(json.dumps(c), encoding="utf-8")
        except OSError:
            pass
        return c
    url = MET_NORDIC_DAP + ".ascii?x,y"
    roh = _karte_get(url, 90).decode("utf-8", "replace")
    k = dap_ascii_lesen(roh)
    xa, ya = _dap_wert(k, "x"), _dap_wert(k, "y")
    x0, y0, x1, y1 = _gebiet_proj(LCC_MET, 4000.0)
    ii = [i for i, v in enumerate(xa) if v is not None and x0 <= v <= x1]
    jj = [j for j, v in enumerate(ya) if v is not None and y0 <= v <= y1]
    if not ii or not jj:
        raise RuntimeError("Gebiet liegt außerhalb von MET Nordic")
    i0, i1, j0, j1 = min(ii), max(ii), min(jj), max(jj)
    url = f"{MET_NORDIC_DAP}.ascii?land_area_fraction.land_area_fraction[{j0}:1:{j1}][{i0}:1:{i1}]"
    roh = _karte_get(url).decode("utf-8", "replace")
    werte = _dap_wert(dap_ascii_lesen(roh), "land_area_fraction")
    nx, ny = i1 - i0 + 1, j1 - j0 + 1
    if len(werte) != nx * ny:
        _karte_fehler("MET Landanteil", url, roh)
        raise RuntimeError(f"unerwartete Datenmenge ({len(werte)} statt {nx * ny})")
    f = [werte[j * nx:(j + 1) * nx] for j in range(ny)]
    xs, ys = xa[i0:i1 + 1], ya[j0:j1 + 1]
    dx, dy = (xs[-1] - xs[0]) / (nx - 1), (ys[-1] - ys[0]) / (ny - 1)
    c = kueste_aus_landanteil(f, lambda i, j: lcc_rueck(xs[0] + i * dx, ys[0] + j * dy, LCC_MET))

    def land_geo(la, lo):
        x, y = lcc_vor(la, lo, LCC_MET)
        i, j = int(round((x - xs[0]) / dx)), int(round((y - ys[0]) / dy))
        return f[j][i] if 0 <= i < nx and 0 <= j < ny else None
    c.update({"gebiet": list(KARTE_GEBIET), "version": KUESTE_VERSION, "land": _land_raster(land_geo),
              "quelle": "Landanteil MET Nordic"})
    genaue_kueste(c)                                   # genauere Linie; die Modellküste bleibt Ersatz
    try:
        KUESTE_CACHE.write_text(json.dumps(c), encoding="utf-8")
    except OSError:
        pass
    return c


def demo_kueste() -> dict:
    """Erfundene Küste für die Demo (nur zum Testen der Darstellung)."""
    def land(la, lo):
        return 1.0 if (la > 54.62 and lo < 10.05) or (la < 54.38 and lo < 10.55) or \
            ((la - 54.47) ** 2 / 0.01 + (lo - 11.15) ** 2 / 0.04 < 1) else 0.0
    n = 120
    f = [[land(53.95 + j * 1.3 / (n - 1), 9.35 + i * 2.3 / (n - 1)) for i in range(n)] for j in range(n)]
    c = kueste_aus_landanteil(f, lambda i, j: (53.95 + j * 1.3 / (n - 1), 9.35 + i * 2.3 / (n - 1)))
    c["land"] = _land_raster(land)
    return c


# =============================================================================
# PEGEL: Hoch- und Niedrigwasser an der Küste (PEGELONLINE: Messung, wo vorhanden BSH-Vorhersage WV;
# sonst Open-Meteo-Meeresspiegel als grobe Modellschätzung, am gemessenen Stand ausgerichtet)
# =============================================================================

PEGELONLINE = "https://pegelonline.wsv.de/webservices/rest-api/v2"
PEGEL_CACHE = Path(__file__).resolve().parent / "pegel_stationen.json"
HOCHWASSER_WARN_CM = 50        # ab hier Hinweis: Stehbereich tiefer, Strand schmal
HOCHWASSER_STOP_CM = 90        # ab hier (gemessen/vorhergesagt) ohne sicheren Wasserstart: nicht empfohlen
NIEDRIGWASSER_WARN_CM = -50
NIEDRIGWASSER_FLACH_CM = -25   # an flachen Spots (pegel=True, z. B. Fehmarn-Stehreviere) schon ab hier Hinweis
PEGEL_MAX_KM = 35              # Pegel weiter weg vom Spot wird nicht verwendet
PEGEL_PERSISTENZ_H = 12        # ohne Vorhersage: so lange gilt der zuletzt gemessene Stand
PEGEL_MODELL_NUTZEN = True     # Open-Meteo-Meeresspiegel als Schätzung für spätere Stunden
PEGEL_MODELL_NAH_H = 6         # so nah an der Messung gilt Messung + Modelltrend als belastbar (zählt für „nicht empfohlen“)
PEGEL: Dict[str, dict] = {}    # Spotname → Pegeldaten (wird in main gefüllt)
PEGEL_JETZT: List[dict] = []   # für die Jetzt-Box: [{name, cm, trend, t}]


def _pg_zeit(s: str) -> datetime:
    t = datetime.fromisoformat(s)
    if t.tzinfo is not None:
        t = _utc_zu_berlin(t.astimezone(timezone.utc).replace(tzinfo=None))
    return t


def _pg_json(url: str):
    return json.loads(_karte_get(url, 60, versuche=3, kopf={"User-Agent": "windsurf_spots/1.3", "Accept": "application/json"}))


def pegel_stationen() -> List[dict]:
    """Ostsee-Pegel im Kartengebiet mit Bezugswert (Mittelwasser oder NHN); eine Woche gespeichert."""
    try:
        c = json.loads(PEGEL_CACHE.read_text(encoding="utf-8"))
        if datetime.now() - datetime.fromisoformat(c["stand"]) < timedelta(days=7):
            return c["stationen"]
    except (OSError, ValueError, KeyError):
        pass
    roh = _pg_json(f"{PEGELONLINE}/stations.json?waters=OSTSEE&includeTimeseries=true"
                   "&includeCharacteristicValues=true&includeForecastTimeseries=true")
    la0, la1, lo0, lo1 = KARTE_GEBIET
    aus = []
    for s in roh if isinstance(roh, list) else []:
        la, lo = s.get("latitude"), s.get("longitude")
        if la is None or lo is None or not (la0 - 0.3 <= la <= la1 + 0.3 and lo0 - 0.3 <= lo <= lo1 + 0.3):
            continue
        reihen = {t.get("shortname"): t for t in s.get("timeseries") or []}
        w = reihen.get("W")
        if not w:
            continue
        mw = next((cv.get("value") for cv in w.get("characteristicValues") or [] if cv.get("shortname") == "MW"), None)
        gz = w.get("gaugeZero") or {}
        bezug, art = None, ""
        if mw is not None:
            bezug, art = float(mw), "über Mittelwasser"
        elif gz.get("value") is not None and "NHN" in str(gz.get("unit", "")):
            bezug, art = -float(gz["value"]) * 100, "über NHN"
        if bezug is None:
            continue
        aus.append({"uuid": s["uuid"], "name": s.get("longname") or s.get("shortname"), "lat": la, "lon": lo,
                    "bezug": bezug, "art": art, "wv": "WV" in reihen})
    try:
        PEGEL_CACHE.write_text(json.dumps({"stand": datetime.now().isoformat(timespec="minutes"),
                                           "stationen": aus}, ensure_ascii=False), encoding="utf-8")
    except OSError:
        pass
    return aus


def _stuendlich(werte: List[Tuple[datetime, float]]) -> Dict[datetime, float]:
    sammel: Dict[datetime, List[float]] = {}
    for t, v in werte:
        sammel.setdefault(t.replace(minute=0, second=0, microsecond=0) + (timedelta(hours=1) if t.minute >= 30 else
                                                                            timedelta(0)), []).append(v)
    return {t: sum(v) / len(v) for t, v in sammel.items()}


# --- BSH-Wasserstandsvorhersage (OGC-API, CC BY 4.0) – auch für die Ostsee-Pegel, die bei PEGELONLINE keine haben ---
BSH_WV_API = "https://gdi.bsh.de/ldproxy/rest/services/WaterLevelForecast/collections/waterlevelforecastdata/items"
BSH_CACHE = Path(__file__).resolve().parent / "bsh_stationen.json"
BSH_NUTZEN = True

# ---- Gezeiten (Nordsee): Hoch- und Niedrigwasser aus der BSH-Vorhersage; danach mit 12 h 25 min fortgeschrieben ----
# Spot → bevorzugte BSH-Pegel (Namensteile); sonst der nächste BSH-Pegel bis 50 km.
GEZEITEN_SPOTS: Dict[str, Tuple[str, ...]] = {"St. Peter-Ording": ("BUESUM", "EIDER", "TOENNING"),
                                              "Rømø (DK)": ("LIST",)}
GEZEIT_HALB_H = 12.42 / 2      # halbe Tide (h): Abstand HW → NW
GEZEITEN: Dict[str, dict] = {}  # Spotname → {"station": Name, "ereignisse": [(HW|NW, Zeit, geschätzt)]}


def _gezeit_station(spot: "Spot") -> Optional[dict]:
    kand = [b for b in bsh_stationen() if b.get("id") and b.get("lat") is not None and b.get("lon") is not None]
    nah = sorted((_abstand_km(spot.lat, spot.lon, b["lat"], b["lon"]), b) for b in kand)
    nah = [(d, b) for d, b in nah if d <= 50]
    for teil in GEZEITEN_SPOTS.get(spot.name, ()):
        for d, b in nah:
            if teil in _name_schluessel(b.get("name")):
                return b
    return nah[0][1] if nah else None


def gezeiten_ereignisse(props: dict) -> List[Tuple[str, datetime]]:
    """HW/NW-Zeitpunkte aus einer BSH-Vorhersage: die Liste high_water_low_water, sonst Extrema der Kurve."""
    aus = []
    for ev in props.get("high_water_low_water") or []:
        typ = str(ev.get("event") or "").upper()
        try:
            t = _pg_zeit(str(ev.get("event_timestamp")))
        except ValueError:
            continue
        if typ in ("HW", "NW"):
            aus.append((typ, t))
    if aus:
        return sorted(aus, key=lambda x: x[1])
    kurve = []
    for pkt in props.get("curve") or []:
        v = _bsh_zahl(pkt.get("automated_curve_forecast"))
        if v is None:
            continue
        try:
            kurve.append((_pg_zeit(str(pkt.get("timestamp"))), v))
        except ValueError:
            continue
    kurve.sort()
    for i in range(2, len(kurve) - 2):
        fenster = [v for _, v in kurve[i - 2:i + 3]]
        if kurve[i][1] == max(fenster) and kurve[i][1] > min(fenster):
            aus.append(("HW", kurve[i][0]))
        elif kurve[i][1] == min(fenster) and kurve[i][1] < max(fenster):
            aus.append(("NW", kurve[i][0]))
    # Doppelte (flache Scheitel) entfernen
    rein = []
    for typ, t in aus:
        if rein and rein[-1][0] == typ and t - rein[-1][1] < timedelta(hours=3):
            continue
        rein.append((typ, t))
    return rein


def gezeiten_fortschreiben(ereignisse: List[Tuple[str, datetime]], bis: datetime) -> List[Tuple[str, datetime, bool]]:
    """Gemessene/vorhergesagte Ereignisse plus geschätzte bis 'bis' (Abstand aus den letzten Ereignissen)."""
    aus = [(typ, t, False) for typ, t in ereignisse]
    if len(ereignisse) >= 2:
        typ, t = ereignisse[-1]
        abst = timedelta(hours=GEZEIT_HALB_H)
        while t + abst <= bis:
            typ, t = ("NW" if typ == "HW" else "HW"), t + abst
            aus.append((typ, t, True))
    return aus


def gezeiten_laden(spots: List["Spot"], tage: int, holer=None) -> None:
    holer = holer or (lambda sid: _pg_json(f"{BSH_WV_API}/{urllib.parse.quote(str(sid))}?f=json"))
    GEZEITEN.clear()
    bis = datetime.now() + timedelta(days=tage + 1)
    for s in spots:
        if s.name not in GEZEITEN_SPOTS:
            continue
        try:
            b = _gezeit_station(s)
            if not b:
                continue
            ev = gezeiten_ereignisse((holer(b["id"]) or {}).get("properties") or {})
        except (RuntimeError, ValueError, KeyError, TypeError) as e:
            print(f"Hinweis: Gezeiten für {s.name} nicht geladen ({e})", file=sys.stderr)
            continue
        if ev:
            GEZEITEN[s.name] = {"station": b.get("name"), "ereignisse": gezeiten_fortschreiben(ev, bis)}


def demo_gezeiten(spots: List["Spot"], tage: int) -> None:
    GEZEITEN.clear()
    t0 = datetime.combine(date.today(), time(5, 40))
    ev = [("HW" if k % 2 == 0 else "NW", t0 + timedelta(hours=GEZEIT_HALB_H * k)) for k in range(4)]
    for s in spots:
        if s.name in GEZEITEN_SPOTS:
            GEZEITEN[s.name] = {"station": "Demo-Pegel",
                                "ereignisse": gezeiten_fortschreiben(ev, datetime.now() + timedelta(days=tage + 1))}


def gezeiten_fuer(e: "Empfehlung") -> List[Tuple[str, datetime, bool]]:
    g = GEZEITEN.get(e.spot.name)
    if not g:
        return []
    return [x for x in g["ereignisse"] if x[1].date() == e.tag and 6 <= x[1].hour <= 21]


def gezeiten_text(e: "Empfehlung") -> str:
    return " · ".join(f"{typ} {'~' if gesch else ''}{t:%H:%M}" for typ, t, gesch in e.gezeiten)


def _name_schluessel(n: str) -> str:
    n = str(n or "").upper()
    for a, b in (("Ä", "AE"), ("Ö", "OE"), ("Ü", "UE"), ("ß", "SS")):
        n = n.replace(a, b)
    return re.sub(r"[^A-Z]", "", n)


def _bsh_zahl(v) -> Optional[float]:
    try:
        return float(str(v).replace(",", "."))
    except (TypeError, ValueError):
        return None


def bsh_stationen() -> List[dict]:
    """Stationen der BSH-Vorhersage (Name, Kennung, Lage); eine Woche gespeichert."""
    try:
        c = json.loads(BSH_CACHE.read_text(encoding="utf-8"))
        if datetime.now() - datetime.fromisoformat(c["stand"]) < timedelta(days=7):
            return c["stationen"]
    except (OSError, ValueError, KeyError):
        pass
    url, aus = f"{BSH_WV_API}?f=json&limit=1000", []
    for _ in range(10):
        d = _pg_json(url)
        for f in d.get("features") or []:
            pr = f.get("properties") or {}
            g = (f.get("geometry") or {}).get("coordinates") or [None, None]
            aus.append({"id": f.get("id"), "name": pr.get("gauge_label"), "gebiet": pr.get("area"),
                        "lon": g[0] if len(g) > 1 else None, "lat": g[1] if len(g) > 1 else None})
        url = next((l.get("href") for l in d.get("links") or [] if l.get("rel") == "next" and l.get("href")), None)
        if not url:
            break
    if aus:
        try:
            BSH_CACHE.write_text(json.dumps({"stand": datetime.now().isoformat(timespec="minutes"), "stationen": aus},
                                            ensure_ascii=False), encoding="utf-8")
        except OSError:
            pass
    return aus


def bsh_station_zu(st: dict) -> Optional[dict]:
    """Passende BSH-Station zum PEGELONLINE-Pegel: gleicher Name, sonst die nächste innerhalb 3 km."""
    kand = bsh_stationen()
    k = _name_schluessel(st["name"])
    for b in kand:
        if b.get("id") and _name_schluessel(b.get("name")) == k:
            return b
    nah = [(_abstand_km(st["lat"], st["lon"], b["lat"], b["lon"]), b) for b in kand
           if b.get("id") and b.get("lat") is not None and b.get("lon") is not None]
    nah = [x for x in nah if x[0] <= 3]
    return min(nah, key=lambda x: x[0])[1] if nah else None


def bsh_vorhersage(st: dict, messung: Dict[datetime, float]) -> Tuple[Dict[datetime, float], str]:
    """BSH-Vorhersagekurve stündlich in cm relativ zum Bezug von st; an der PEGELONLINE-Messung ausgerichtet
    (gleicht Bezugsunterschiede und den aktuellen Versatz aus). Rückgabe ({}, Grund) wenn nichts brauchbar."""
    b = bsh_station_zu(st)
    if not b:
        return {}, "keine BSH-Station"
    f = _pg_json(f"{BSH_WV_API}/{urllib.parse.quote(str(b['id']))}?f=json")
    kurve = (f.get("properties") or {}).get("curve") or []
    vh, gem = [], []
    for pkt in kurve:
        try:
            t = _pg_zeit(str(pkt.get("timestamp")))
        except ValueError:
            continue
        v, m = _bsh_zahl(pkt.get("automated_curve_forecast")), _bsh_zahl(pkt.get("measurement"))
        if v is not None:
            vh.append((t, v - st["bezug"]))
        if m is not None:
            gem.append((t, m - st["bezug"]))
    vh_h = _stuendlich(vh)
    if not vh_h:
        return {}, "BSH-Kurve ohne Vorhersage"
    # Versatz: BSH-Messung (bzw. erste Vorhersagestunden) gegen PEGELONLINE in denselben Stunden
    gem_h = _stuendlich(gem)
    paare = [(messung[t], gem_h[t]) for t in gem_h if t in messung][-6:]
    if not paare:
        paare = [(messung[t], vh_h[t]) for t in sorted(vh_h) if t in messung][:3]
    versatz = sum(a - b_ for a, b_ in paare) / len(paare) if paare else 0.0
    if abs(versatz) > 150:
        return {}, f"BSH-Bezug passt nicht (Versatz {versatz:+.0f} cm)"
    return {t: v + versatz for t, v in vh_h.items()}, f"BSH {b.get('name')}" + (
        f", ausgerichtet {versatz:+.0f} cm" if abs(versatz) >= 3 else "")


def pegel_station_holen(st: dict) -> dict:
    """Messung der letzten 2 Tage und (falls vorhanden) Vorhersage, beides in cm relativ zum Bezug."""
    mess = _pg_json(f"{PEGELONLINE}/stations/{st['uuid']}/W/measurements.json?start=P2D")
    roh = [(_pg_zeit(m["timestamp"]), float(m["value"]) - st["bezug"]) for m in mess if m.get("value") is not None]
    if not roh:
        raise RuntimeError("keine Messwerte")
    roh.sort()
    t_j, cm_j = roh[-1]
    vorher = [v for t, v in roh if t_j - timedelta(hours=3, minutes=10) <= t <= t_j - timedelta(hours=2, minutes=50)]
    trend = (cm_j - sum(vorher) / len(vorher)) / 3 if vorher else None
    vorhersage = {}
    if st.get("wv"):
        try:
            wv = _pg_json(f"{PEGELONLINE}/stations/{st['uuid']}/WV/measurements.json")
            vorhersage = _stuendlich([(_pg_zeit(m["timestamp"]), float(m["value"]) - st["bezug"])
                                      for m in wv if m.get("value") is not None])
        except (RuntimeError, ValueError, KeyError, TypeError):
            pass
    messung = _stuendlich(roh)
    vh_quelle = "WSV" if vorhersage else ""
    if not vorhersage and BSH_NUTZEN:
        try:
            vorhersage, vh_quelle = bsh_vorhersage(st, messung)
        except (RuntimeError, ValueError, KeyError, TypeError, AttributeError) as e:
            vh_quelle = f"BSH nicht geladen ({e})"
        if not vorhersage:
            vh_quelle = ""
    return {"name": st["name"], "art": st["art"], "messung": messung, "jetzt": (t_j, cm_j),
            "trend": trend, "vorhersage": vorhersage, "vh_quelle": vh_quelle}


def pegel_laden(spots: List["Spot"], spot_daten: List["OrtDaten"]) -> None:
    """Füllt PEGEL je Küstenspot mit dem nächsten Pegel; Binnenseen bleiben außen vor."""
    PEGEL.clear()
    PEGEL_JETZT.clear()
    stationen = pegel_stationen()
    geladen: Dict[str, dict] = {}
    for sp, d in zip(spots, spot_daten):
        if sp.see_hoehe > 0:
            continue
        kand = sorted(((_abstand_km(sp.lat, sp.lon, s["lat"], s["lon"]), s) for s in stationen), key=lambda x: x[0])
        for km, s in kand:
            if km > PEGEL_MAX_KM:
                break
            if s["uuid"] not in geladen:
                try:
                    geladen[s["uuid"]] = pegel_station_holen(s)
                except (RuntimeError, ValueError, KeyError, TypeError) as e:
                    geladen[s["uuid"]] = {"fehler": str(e)}
            p = geladen[s["uuid"]]
            if "fehler" not in p:
                PEGEL[sp.name] = dict(p, km=km, meer=d.meer)
                break
    gezeigt = set()
    for p in sorted((p for p in geladen.values() if "fehler" not in p), key=lambda p: p["name"]):
        if p["name"] not in gezeigt:
            gezeigt.add(p["name"])
            PEGEL_JETZT.append({"name": p["name"].title(), "cm": p["jetzt"][1], "trend": p["trend"], "t": p["jetzt"][0]})


def pegel_im_fenster(spot: "Spot", von: datetime, bis: datetime, jetzt: datetime
                     ) -> Optional[Tuple[float, float, str]]:
    """(höchster, tiefster Stand in cm, Quelle) im Zeitfenster, oder None ohne Daten."""
    p = PEGEL.get(spot.name)
    if not p:
        return None
    stunden = []
    t = von.replace(minute=0, second=0, microsecond=0)
    while t < bis:
        stunden.append(t)
        t += timedelta(hours=1)
    vh = [p["vorhersage"][t] for t in stunden if t in p["vorhersage"]]
    if vh and len(vh) >= len(stunden) / 2:
        return max(vh), min(vh), ("BSH-Vorhersage " if str(p.get("vh_quelle", "")).startswith("BSH")
                                  else "Vorhersage ") + p["name"].title()
    t_j, cm_j = p["jetzt"]
    meer = p.get("meer") or {}
    if PEGEL_MODELL_NUTZEN and meer:
        basis = meer.get(t_j.replace(minute=0, second=0, microsecond=0))
        werte = [meer[t] for t in stunden if t in meer]
        if werte and basis is not None:
            # Modelländerung, am gemessenen Stand ausgerichtet. Geprüft an der Sturmflut vom 18.10.2026
            # (Kiel-Holtenau): Anstieg zu ~75 % erfasst, Fehler meist unter 20 cm.
            korr = [v - basis + cm_j for v in werte]
            if (von - t_j).total_seconds() <= PEGEL_MODELL_NAH_H * 3600:
                return max(korr), min(korr), f"gemessen {p['name'].title()} {t_j:%H:%M} + Modelltrend"
            return max(korr), min(korr), "Modell, unsicher"
    if (von - t_j).total_seconds() <= PEGEL_PERSISTENZ_H * 3600 and bis > jetzt - timedelta(hours=1):
        return cm_j, cm_j, f"gemessen {p['name'].title()} {t_j:%H:%M}"
    return None


def pegel_warnungen(spot: "Spot", von: datetime, bis: datetime, jetzt: datetime,
                    tag_von: Optional[datetime] = None, tag_bis: Optional[datetime] = None
                    ) -> Tuple[List[str], float, bool]:
    """(Warnungen, Score-Faktor, Daten vorhanden). Hochwasser gilt für den besten Block (von–bis);
    Niedrigwasser für den ganzen fahrbaren Zeitraum (tag_von–tag_bis), damit Spots am selben Pegel gleich aussehen."""
    pw = pegel_im_fenster(spot, von, bis, jetzt)
    if not pw:
        return [], 1.0, False
    hoch, tief, quelle = pw
    w, f = [], 1.0
    if hoch >= HOCHWASSER_WARN_CM:
        if not OEFFENTLICH:
            w.append(f"Hochwasser +{hoch:.0f} cm ({quelle})")
        elif hoch >= HOCHWASSER_STOP_CM and "unsicher" not in quelle:
            w.append(f"Hochwasser +{hoch:.0f} cm ({quelle}) – Stehbereich weg, Shorebreak, Treibgut"
                     + ("" if OEFFENTLICH else ": nicht empfohlen"))
            f = 0.25
        else:
            w.append(f"Hochwasser +{hoch:.0f} cm ({quelle}) – Stehbereich deutlich tiefer, Strand schmal")
            f = 0.8
    tief_block = tief
    if tag_von is not None and tag_bis is not None:
        pt = pegel_im_fenster(spot, tag_von, tag_bis, jetzt)
        if pt:
            tief, quelle = min(tief, pt[1]), pt[2]
    if tief <= NIEDRIGWASSER_WARN_CM or (spot.pegel and tief <= NIEDRIGWASSER_FLACH_CM):
        zusatz = f", im besten Block {tief_block:.0f} cm" if tief_block - tief >= 5 else ""
        w.append(f"Niedrigwasser {tief:.0f} cm ({quelle}{zusatz})"
                 + (" – Sandbänke und Steine näher an der Oberfläche" if OEFFENTLICH else ""))
    return w, f, True


def lese_meer(d: dict) -> Dict[datetime, float]:
    """Open-Meteo sea_level_height_msl (m) → cm je Stunde."""
    h = d.get("hourly") or {}
    werte = h.get("sea_level_height_msl") or []
    return {datetime.fromisoformat(t): v * 100 for t, v in zip(h.get("time", []), werte) if v is not None}


def pegel_jetzt_text() -> str:
    teile = []
    for p in PEGEL_JETZT[:4]:
        tr = ""
        if p["trend"] is not None:
            tr = " steigend" if p["trend"] > 1.5 else (" fallend" if p["trend"] < -1.5 else " gleichbleibend")
        teile.append(f"{p['name']} {p['cm']:+.0f} cm{tr}")
        EN_GLEICH.add(p["name"])
    return ("Pegel: " + " · ".join(teile)) if teile else ""


def demo_pegel(jetzt: datetime) -> None:
    """Erfundene Sturmflut für die Demo: heute +95 cm, bis übermorgen abklingend."""
    PEGEL.clear()
    PEGEL_JETZT.clear()
    t0 = jetzt.replace(minute=0, second=0, microsecond=0)
    vh = {t0 + timedelta(hours=h): 95 - h * 1.6 for h in range(0, 60)}
    for sp in SPOTS:
        if sp.see_hoehe <= 0:
            PEGEL[sp.name] = {"name": "KIEL-HOLTENAU (Demo)", "art": "über Mittelwasser", "messung": {},
                              "jetzt": (t0, 95.0), "trend": -1.6, "vorhersage": vh, "km": 10, "meer": {}}
    PEGEL_JETZT.append({"name": "Kiel-Holtenau (Demo)", "cm": 95.0, "trend": -1.6, "t": t0})


def pegel_test(demo: bool = False) -> None:
    """--pegel-test: Pegel laden und Messung, Vorhersage und Open-Meteo-Meeresspiegel nebeneinander zeigen."""
    st = pegel_stationen()
    print(f"{len(st)} Ostsee-Pegel im Gebiet:")
    for s in st:
        print(f"  {s['name']:<28} {s['lat']:.3f} N {s['lon']:.3f} E · Bezug {s['bezug']:.0f} cm ({s['art']})"
              f"{' · mit Vorhersage (WV)' if s['wv'] else ''}")
    for s in st:
        if s["name"].upper() in ("HEILIGENHAFEN", "KIEL-HOLTENAU", "ECKERNFÖRDE", "FLENSBURG"):
            try:
                q = pegel_station_holen(s)
            except RuntimeError as e:
                print(f"  {s['name']}: {e}")
                continue
            vh = q["vorhersage"]
            if vh:
                tmin, tmax = min(vh, key=vh.get), max(vh, key=vh.get)
                print(f"  {q['name'].title():<16} jetzt {q['jetzt'][1]:+4.0f} cm · {q['vh_quelle']}: bis {max(vh):%a %H} Uhr, "
                      f"tiefster {vh[tmin]:+.0f} cm ({tmin:%a %H} Uhr), höchster {vh[tmax]:+.0f} cm ({tmax:%a %H} Uhr)")
            else:
                print(f"  {q['name'].title():<16} jetzt {q['jetzt'][1]:+4.0f} cm · keine Vorhersage")
    ziel = next((s for s in st if "HOLTENAU" in s["name"].upper()), st[0] if st else None)
    if not ziel:
        return
    p = pegel_station_holen(ziel)
    print(f"\n{p['name']}: jetzt {p['jetzt'][1]:+.0f} cm ({p['jetzt'][0]:%d.%m. %H:%M})"
          + (f", Trend {p['trend']:+.1f} cm/h" if p["trend"] is not None else "")
          + f" · Vorhersage: {len(p['vorhersage'])} Stunden" + (f" ({p['vh_quelle']})" if p.get("vh_quelle") else ""))
    params = {"latitude": f"{ziel['lat']:.4f}", "longitude": f"{ziel['lon']:.4f}", "hourly": "sea_level_height_msl",
              "timezone": "Europe/Berlin", "past_days": 3, "forecast_days": 3, "cell_selection": "sea"}
    try:
        meer = lese_meer(_get_json(API_MARINE + "?" + urllib.parse.urlencode(params))[0])
    except (RuntimeError, IndexError) as e:
        meer = {}
        print(f"Open-Meteo-Meeresspiegel nicht geladen ({e})")
    jetzt_h = p["jetzt"][0].replace(minute=0, second=0, microsecond=0)
    basis = meer.get(jetzt_h)
    print("\n  Zeit          Messung  Vorhersage  Modell roh  Modell ausgerichtet")
    t = jetzt_h - timedelta(hours=60)
    while t <= jetzt_h + timedelta(hours=48):
        m, v, r = p["messung"].get(t), p["vorhersage"].get(t), meer.get(t)
        if t.hour % 3 == 0 and (m is not None or v is not None or r is not None):
            k = r - basis + p["jetzt"][1] if (r is not None and basis is not None) else None
            f = lambda x: f"{x:+8.0f}" if x is not None else "       –"
            print(f"  {t:%a %d.%m. %H}h  {f(m)}  {f(v)}    {f(r)}    {f(k)}")
        t += timedelta(hours=1)
    print("\nWenn 'Modell roh' den Anstieg der letzten Tage mitmacht, taugt der Open-Meteo-Meeresspiegel als Schätzung.")


# =============================================================================
# PUSH-NACHRICHT (ntfy): meldet neue oder deutlich geänderte Windtage aufs Handy
# =============================================================================
# App „ntfy“ installieren und den Kanal NTFY_THEMA abonnieren. Der Name ist zufällig, damit ihn niemand errät –
# wer ihn kennt, kann mitlesen. None = keine Nachrichten.

# 23.11.2026 (Git): Das Thema steht nicht mehr im Skript, sondern in ntfy.json neben dem Skript ({"thema": "…"}),
# damit es nicht im Repository landet. Fehlt die Datei, gibt es keine Push-Nachrichten.
NTFY_DATEI = Path(__file__).resolve().parent / "ntfy.json"


def _ntfy_thema_laden() -> Optional[str]:
    try:
        return str(json.loads(NTFY_DATEI.read_text(encoding="utf-8")).get("thema") or "") or None
    except (OSError, ValueError, AttributeError):
        return None


NTFY_THEMA: Optional[str] = _ntfy_thema_laden()
NTFY_SERVER = "https://ntfy.sh"
# Adresse der Seite auf dem Handy (--server, z. B. über Tailscale "http://dave-asus:8765/"); "" = Push ohne Link
SEITE_URL = "http://raspberrypi:8765/privat/windsurf_spots.html"   # Pi über Tailscale (MagicDNS), 28.10.2026
NTFY_TAGE = 4                  # nur so viele Tage ab heute melden
NTFY_RUHE = (22, 7)            # in dieser Zeit nichts senden (wird beim nächsten Lauf nachgeholt)
NTFY_MIN_ENSEMBLE = 0.4        # schwächere Tage (Ensemble darunter) nicht melden
NTFY_MAX_SEGEL = 5.7           # nur Tage melden, an denen ein Spot mit diesem oder einem kleineren Segel geht (None = alle)
NTFY_STAND = Path(__file__).resolve().parent / "ntfy_stand.json"


def _ntfy_senden(titel: str, text: str, tags: str = "ocean", prio: int = 3) -> None:
    nachricht = {"topic": NTFY_THEMA, "title": titel, "message": text,
                 "tags": [t for t in tags.split(",") if t], "priority": prio}
    if SEITE_URL:
        nachricht["click"] = SEITE_URL                 # Antippen öffnet die Seite (über --server)
    daten = json.dumps(nachricht).encode("utf-8")
    _karte_get(NTFY_SERVER, 30, versuche=2, daten=daten,
               kopf={"User-Agent": "windsurf_spots/1.3", "Content-Type": "application/json"})


def _ntfy_tag(e: "Empfehlung") -> dict:
    return {"spot": e.spot.name, "kn": round(e.wind), "segel": e.segel, "richtung": e.richtung,
            "fahrbar": fahrbar_text(e) if e.verlauf else f"{e.sp_start:%H}–{e.sp_ende:%H}",
            "warn": [lab for lab in warnungen_teilen(e.warnungen)[1]]}


def ntfy_pruefen(ergebnisse, jetzt: datetime, senden=None) -> Optional[str]:
    """Vergleicht die besten Tage mit dem zuletzt gemeldeten Stand und schickt eine Nachricht bei Änderungen.
    Rückgabe: gesendeter Text (oder None)."""
    if not NTFY_THEMA:
        return None
    senden = senden or _ntfy_senden
    try:
        alt = json.loads(NTFY_STAND.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        alt = {}
    neu: Dict[str, dict] = {}
    for tag, liste, _ in ergebnisse:
        if (tag - jetzt.date()).days >= NTFY_TAGE or not liste:
            continue
        passend = [x for x in liste if NTFY_MAX_SEGEL is None or x.segel <= NTFY_MAX_SEGEL + 0.01]
        if not passend:
            continue
        e = passend[0]                                # bester Spot mit kleinem genug Segel
        if e.p_ens is not None and e.p_ens < NTFY_MIN_ENSEMBLE:
            continue
        neu[tag.isoformat()] = _ntfy_tag(e)
    zeilen, wichtig = [], False
    for k in sorted(set(neu) | set(alt)):
        if k < jetzt.date().isoformat():
            continue
        tag_t = tag_text(date.fromisoformat(k))
        a, n = alt.get(k), neu.get(k)
        if n and not a:
            zeilen.append(f"NEU {tag_t}: {n['spot']} {n['kn']} kn {n['richtung']} · {qm(n['segel'])} · "
                          f"{n['fahrbar']} Uhr" + (f" · ⚠ {', '.join(n['warn'])}" if n["warn"] else ""))
            wichtig = True
        elif a and not n:
            stunden_a = re.findall(r"\d{2}", a.get("fahrbar", ""))
            vorbei = k == jetzt.date().isoformat() and stunden_a and jetzt.hour >= int(stunden_a[-1]) - 1
            if not vorbei:                            # heute nach dem Fenster ist nichts „ausgefallen“
                zeilen.append(f"FÄLLT AUS {tag_t}: {a['spot']} reicht nicht mehr")
        elif a and n and (a["spot"] != n["spot"] or abs(a["kn"] - n["kn"]) >= 3 or a["warn"] != n["warn"]):
            zeilen.append(f"GEÄNDERT {tag_t}: {n['spot']} {n['kn']} kn {n['richtung']} · {qm(n['segel'])} · "
                          f"{n['fahrbar']} Uhr" + (f" · ⚠ {', '.join(n['warn'])}" if n["warn"] else ""))
    if not zeilen:
        return None
    a, b = NTFY_RUHE
    if (jetzt.hour >= a or jetzt.hour < b):
        return None                                   # Ruhezeit – Stand nicht speichern, also später nachholen
    text = "\n".join(zeilen)
    erster = next((neu[k] for k in sorted(neu)), None)
    titel = (f"Windsurf: {tag_text(date.fromisoformat(min(neu)))} {erster['spot']} {erster['kn']} kn"
             if erster else "Windsurf: Änderung")
    try:
        senden(titel, text, "ocean" + (",warning" if any(n["warn"] for n in neu.values()) else ""),
               4 if wichtig else 3)
    except RuntimeError as ex:
        print(f"Hinweis: Push-Nachricht nicht gesendet ({ex})", file=sys.stderr)
        return None
    try:
        NTFY_STAND.write_text(json.dumps(neu, ensure_ascii=False), encoding="utf-8")
    except OSError:
        pass
    return text


# Ausfallalarm: scheitert ein normaler Lauf (Abruf, Absturz) oder der Upload, kommt eine Nachricht auf den
# ntfy-Kanal – höchstens alle AUSFALL_ABSTAND_H Stunden, und eine Entwarnung, sobald es wieder läuft.
AUSFALL_DATEI = Path(__file__).resolve().parent / "ausfall_stand.json"
AUSFALL_ABSTAND_H = 12
AUSFALL_UEBERWACHEN = False          # True nur in einem normalen Vorhersage-Lauf (nicht Demo/Werkzeuge)


def _ausfall_lesen() -> dict:
    try:
        return json.loads(AUSFALL_DATEI.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def ausfall_melden(grund: str) -> None:
    """Fehlschlag merken und (gedrosselt) per ntfy melden. Darf selbst nie scheitern."""
    if not AUSFALL_UEBERWACHEN:
        return
    try:
        st = _ausfall_lesen()
        jetzt = datetime.now()
        st.setdefault("seit", jetzt.isoformat(timespec="minutes"))
        st["anzahl"] = int(st.get("anzahl", 0)) + 1
        st["grund"] = grund[:300]
        zuletzt = st.get("gemeldet")
        faellig = not zuletzt or (jetzt - datetime.fromisoformat(zuletzt)).total_seconds() >= AUSFALL_ABSTAND_H * 3600
        if faellig and NTFY_THEMA:
            try:
                _ntfy_senden("Windfenster: Lauf fehlgeschlagen",
                             f"{grund[:300]}\n{st['anzahl']}. Fehlschlag seit {st['seit'][11:16]} "
                             f"({st['seit'][8:10]}.{st['seit'][5:7]}.). Online steht der letzte gute Stand.",
                             "warning", 4)
                st["gemeldet"] = jetzt.isoformat(timespec="minutes")
            except Exception as ex:
                print(f"Hinweis: Ausfallalarm nicht gesendet ({ex})", file=sys.stderr)
        AUSFALL_DATEI.write_text(json.dumps(st, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass


def ausfall_ok() -> None:
    """Lauf erfolgreich: Entwarnung, falls vorher etwas gemeldet war."""
    if not AUSFALL_UEBERWACHEN or not AUSFALL_DATEI.exists():
        return
    try:
        st = _ausfall_lesen()
        AUSFALL_DATEI.unlink(missing_ok=True)
        if st.get("gemeldet") and NTFY_THEMA:
            _ntfy_senden("Windfenster läuft wieder", f"Nach {st.get('anzahl', '?')} Fehlschlägen seit "
                         f"{str(st.get('seit', ''))[11:16]} wieder ein erfolgreicher Lauf.", "white_check_mark", 3)
    except Exception:
        pass


def ntfy_test() -> None:
    if not NTFY_THEMA:
        sys.exit("NTFY_THEMA ist nicht gesetzt.")
    _ntfy_senden("Windsurf: Test", f"Wenn du das liest, kommen die Nachrichten an. Kanal: {NTFY_THEMA}", "white_check_mark")
    print(f"Testnachricht an {NTFY_SERVER}/{NTFY_THEMA} gesendet.")


def _kodiere_feld(zeiten: List[datetime], u: List[List[Optional[float]]], v: List[List[Optional[float]]],
                  max_h: int = KARTE_STUNDEN, takt_fern: int = 1) -> Tuple[List[str], List[str], List[str]]:
    """u/v (kn, geografisch) je Zeit und Zielzelle → (Zeiten, Speed-b64, Richtung-b64) im Player-Format.
    Bis KARTE_STUNDEN stündlich, danach bis max_h nur jede takt_fern-te Stunde."""
    jetzt = datetime.now().replace(minute=0, second=0, microsecond=0)
    t_aus, sp, ri = [], [], []
    for t, uu, vv in zip(zeiten, u, v):
        if t < jetzt - timedelta(hours=1) or t > jetzt + timedelta(hours=max_h):
            continue
        if t > jetzt + timedelta(hours=KARTE_STUNDEN) and t.hour % takt_fern:
            continue
        if KARTE_TAKT > 1 and t.hour % KARTE_TAKT:
            continue
        if all(a is None for a in uu):
            continue                               # Modell reicht nicht so weit (ICON-D2: 2 Tage)
        b_sp, b_ri = bytearray(), bytearray()
        for a, b in zip(uu, vv):
            if a is None or b is None:
                b_sp.append(255)
                b_ri.append(0)
                continue
            kn = math.hypot(a, b)
            b_sp.append(min(254, int(round(kn * 4))))
            b_ri.append(int(round(((math.degrees(math.atan2(-a, -b)) + 360) % 360) / 360 * 256)) % 256)
        t_aus.append(t.strftime("%Y-%m-%dT%H:%M"))
        sp.append(base64.b64encode(bytes(b_sp)).decode("ascii"))
        ri.append(base64.b64encode(bytes(b_ri)).decode("ascii"))
    return t_aus, sp, ri


def om_raster_auf_ziel(lats_g: List[float], lons_g: List[float], werte: List[Tuple[Optional[float], Optional[float]]]
                       ) -> Tuple[List[Optional[float]], List[Optional[float]]]:
    """Regelmäßiges grobes lat/lon-Gitter (Zeilen = lats_g, je Zeile lons_g) → Zielraster, bilinear in u/v."""
    lats, lons = karte_raster()
    ny, nx = len(lats_g), len(lons_g)
    dla = (lats_g[-1] - lats_g[0]) / (ny - 1)
    dlo = (lons_g[-1] - lons_g[0]) / (nx - 1)
    uo, vo = [], []
    for la in lats:
        for lo in lons:
            fj = min(max((la - lats_g[0]) / dla, 0), ny - 1)
            fi = min(max((lo - lons_g[0]) / dlo, 0), nx - 1)
            j, i = min(int(fj), ny - 2), min(int(fi), nx - 2)
            dj, di = fj - j, fi - i
            ecken = [werte[(j + a) * nx + (i + b)] for a in (0, 1) for b in (0, 1)]
            if any(e[0] is None or e[1] is None for e in ecken):
                uo.append(None)
                vo.append(None)
                continue
            g = [(1 - dj) * (1 - di), (1 - dj) * di, dj * (1 - di), dj * di]
            uo.append(sum(w * e[0] for w, e in zip(g, ecken)))
            vo.append(sum(w * e[1] for w, e in zip(g, ecken)))
    return uo, vo


def hole_om_feld(m: str) -> dict:
    """ECMWF/GFS über Open-Meteo als Punktraster; höchstens alle KARTE_OM_MAX_H Stunden neu geladen.
    Seit 01.11.2026 zuerst aus den direkten Modelldaten (direkt_feld), Open-Meteo nur noch als Rückfall."""
    f_direkt = direkt_feld(m)
    if f_direkt:
        return f_direkt
    name, modell, dla, dlo = KARTE_OM[m]
    try:
        cache = json.loads(KARTE_OM_CACHE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        cache = {}
    # Fehler bis 01.11.2026: Schlüssel war nur das Modell – alle Reviere teilten sich einen Eintrag „ecmwf“ und luden
    # deshalb in JEDEM Lauf neu (~3500 Abrufe je Lauf). Jetzt je Revier und Modell.
    schluessel = f"{KARTE_REVIER}:{m}"
    c = cache.get(schluessel)
    if c and c.get("gebiet") == list(KARTE_GEBIET) and c.get("h") == KARTE_OM_STUNDEN:
        alter = datetime.now() - datetime.fromisoformat(c["stand"])
        if alter < timedelta(hours=KARTE_OM_MAX_H):
            return c["feld"]
        if alter < timedelta(hours=48) and om_heute() > OM_SPARGRENZE:
            return c["feld"]                      # Kontingent knapp: altes Feld weiter zeigen
    la0, la1, lo0, lo1 = KARTE_GEBIET
    lats_g = [la0 - dla + k * dla for k in range(int((la1 - la0) / dla) + 3)]
    lons_g = [lo0 - dlo + k * dlo for k in range(int((lo1 - lo0) / dlo) + 3)]
    orte = [(la, lo) for la in lats_g for lo in lons_g]
    antworten = []
    global OM_ART_JETZT
    OM_ART_JETZT = "Karten"
    try:
        for k in range(0, len(orte), 100):
            print(f"\r\033[2KWind-Player: {name} lädt ({k // 100 + 1}/{(len(orte) + 99) // 100}) …",
                  end="", file=sys.stderr, flush=True)
            paket = orte[k:k + 100]
            params = {"latitude": ",".join(f"{a:.4f}" for a, _ in paket),
                      "longitude": ",".join(f"{b:.4f}" for _, b in paket),
                      "hourly": "wind_speed_10m,wind_direction_10m", "wind_speed_unit": "kn",
                      "timezone": "Europe/Berlin", "forecast_days": OM_TAGE.get(modell, min(16, KARTE_OM_STUNDEN // 24 + 2)),
                      "models": modell, "cell_selection": "nearest"}
            for versuch in range(1, VERSUCHE + 1):
                try:
                    time_mod.sleep(PAUSE_S)
                    antworten += _get_json(API + "?" + urllib.parse.urlencode(params, safe=","))
                    break
                except RuntimeError:
                    if versuch == VERSUCHE:
                        raise
                    time_mod.sleep(5 * 2 ** (versuch - 1))
    finally:
        OM_ART_JETZT = None
    if len(antworten) != len(orte):
        raise RuntimeError(f"{len(antworten)} statt {len(orte)} Punkte erhalten")
    zeiten = [datetime.fromisoformat(t) for t in antworten[0]["hourly"]["time"]]
    u_t, v_t = [], []
    for it in range(len(zeiten)):
        werte = []
        for a in antworten:
            h = a.get("hourly") or {}
            ws_, wd_ = (h.get("wind_speed_10m") or [None] * len(zeiten))[it], \
                (h.get("wind_direction_10m") or [None] * len(zeiten))[it]
            if ws_ is None or wd_ is None:
                werte.append((None, None))
            else:
                r = math.radians(wd_)
                werte.append((-ws_ * math.sin(r), -ws_ * math.cos(r)))
        uo, vo = om_raster_auf_ziel(lats_g, lons_g, werte)
        u_t.append(uo)
        v_t.append(vo)
    t_aus, sp, ri = _kodiere_feld(zeiten, u_t, v_t, KARTE_OM_STUNDEN, KARTE_OM_TAKT_FERN)
    if not t_aus:
        raise RuntimeError("keine Zeitschritte")
    feld = {"name": name, "lauf": "", "t": t_aus, "sp": sp, "ri": ri}
    cache = {k: v for k, v in cache.items() if ":" in k}        # alte Einträge ohne Revier verwerfen
    cache[schluessel] = {"stand": datetime.now().isoformat(timespec="minutes"), "gebiet": list(KARTE_GEBIET),
                         "h": KARTE_OM_STUNDEN, "feld": feld}
    try:
        KARTE_OM_CACHE.write_text(json.dumps(cache), encoding="utf-8")
    except OSError:
        pass
    return feld


# =============================================================================
# KARTEN AUS DIREKTEN MODELLDATEN (01.11.2026): ECMWF Open Data, NOAA GFS, DWD ICON-D2
# =============================================================================
#
# Die Wind-Player-Raster kosteten bei Open-Meteo je Rasterpunkt einen Abruf (~3 500 je kompletter Erneuerung). Jetzt
# kommen sie direkt aus den offenen Modelldateien (GRIB2): einmal je Lauf geladen, für alle Reviere zugeschnitten und
# gespeichert. Open-Meteo bleibt nur für Modelle/Gebiete ohne direkte Quelle (AROME Leucate, ICON-EU Tarifa,
# ICON global Teneriffa) und als Rückfall. Braucht eccodes + numpy (auf dem Pi wegen Bergwetter vorhanden).
#   ECMWF: data.ecmwf.int, IFS 0,25°, CC BY 4.0 – nur 10u/10v per Byte-Bereich aus der Indexdatei
#   GFS:   nomads.ncep.noaa.gov, Filter mit Ausschnitt Europa (klein), gemeinfrei
#   ICON-D2: opendata.dwd.de, reguläres Gitter 0,02°, CC BY 4.0 – ersetzt auf den Karten auch ICON-CH und ICON-EU (NL)

DIREKT_DATEI = Path(__file__).resolve().parent / "karte_direkt.npz"
DIREKT_META = Path(__file__).resolve().parent / "karte_direkt.json"
DIREKT_FUER = {"ecmwf_ifs": "ecmwf", "ecmwf_ifs025": "ecmwf", "gfs_seamless": "gfs", "gfs025": "gfs",
               "icon_d2": "icon-d2", "meteoswiss_icon_seamless": "icon-d2", "meteoswiss_icon_ch1": "icon-d2",
               "meteoswiss_icon_ch2": "icon-d2", "icon_eu": "icon-d2"}
DIREKT_NAME = {"ecmwf": "ECMWF IFS 25 km", "gfs": "GFS 25 km", "icon-d2": "ICON-D2 2 km"}
DIREKT_GEBIET = {"icon-d2": (43.25, 58.0, -3.85, 20.25)}        # lat0, lat1, lon0, lon1 (ECMWF/GFS: weltweit)
DIREKT_ERNEUERN_H = {"ecmwf": 24, "gfs": 12, "icon-d2": 12}    # so oft ein neuer Lauf (Datenmenge auf dem Pi)
DIREKT_STUNDEN = {"ecmwf": 168, "gfs": 168, "icon-d2": 48}
GFS_BOX = (25.0, 58.5, -18.0, 13.0)                             # Europa-Ausschnitt für den NOMADS-Filter
MS_ZU_KN = 1.943844


def _direkt_get(url: str, kopf: Optional[dict] = None, timeout: int = 120, versuche: int = 3) -> Optional[bytes]:
    """Bytes oder None bei 404 (Datei noch nicht da)."""
    h = {"User-Agent": "windsurf-spots/1.3 (private wind forecast)"}
    h.update(kopf or {})
    for v in range(1, versuche + 1):
        try:
            with urllib.request.urlopen(urllib.request.Request(url, headers=h), timeout=timeout) as r:
                return r.read()
        except urllib.error.HTTPError as e:
            if e.code in (403, 404):
                return None
            if v == versuche:
                raise RuntimeError(f"HTTP {e.code} bei {url}") from None
        except (urllib.error.URLError, OSError) as e:
            if v == versuche:
                raise RuntimeError(f"{e} bei {url}") from None
        time_mod.sleep(3 * v)
    return None


def _grib_felder(roh: bytes) -> List[dict]:
    """GRIB2-Bytes → [{name, gueltig (UTC), lats (S→N), lons (W→O, −180…180), werte [ny][nx] (numpy)}]."""
    import eccodes
    import numpy as np
    aus, pos = [], 0
    while True:
        k = roh.find(b"GRIB", pos)
        if k < 0:
            break
        laenge = int.from_bytes(roh[k + 8:k + 16], "big")          # GRIB2: Gesamtlänge in Oktett 9–16
        h = eccodes.codes_new_from_message(roh[k:k + laenge])
        try:
            ni, nj = eccodes.codes_get(h, "Ni"), eccodes.codes_get(h, "Nj")
            eccodes.codes_set(h, "missingValue", 1e20)
            w = np.asarray(eccodes.codes_get_values(h), dtype=np.float32).reshape(nj, ni)
            w[w > 1e19] = np.nan
            la1, la2 = eccodes.codes_get(h, "latitudeOfFirstGridPointInDegrees"), \
                eccodes.codes_get(h, "latitudeOfLastGridPointInDegrees")
            lo1 = eccodes.codes_get(h, "longitudeOfFirstGridPointInDegrees")
            dlo = eccodes.codes_get(h, "iDirectionIncrementInDegrees")
            lats = np.linspace(la1, la2, nj)
            lons = lo1 + dlo * np.arange(ni)
            name = eccodes.codes_get(h, "shortName")
            vd, vt = eccodes.codes_get(h, "validityDate"), eccodes.codes_get(h, "validityTime")
        finally:
            eccodes.codes_release(h)
        if lats[0] > lats[-1]:
            lats, w = lats[::-1], w[::-1]
        lons = np.where(lons > 180, lons - 360, lons)
        o = np.argsort(lons, kind="stable")
        aus.append({"name": name, "gueltig": datetime.strptime(f"{vd}{vt:04d}", "%Y%m%d%H%M"),
                    "lats": lats, "lons": lons[o], "werte": w[:, o]})
        pos = k + laenge
    return aus


def _direkt_boxen() -> Dict[str, Dict[str, Tuple[float, float, float, float]]]:
    """Je direkter Quelle: {revier: KARTE_GEBIET} für alle Reviere, deren Karte diese Quelle nutzt."""
    boxen: Dict[str, Dict[str, Tuple[float, float, float, float]]] = {}
    for r in REVIERE:
        if not r["aktiv"] or not (r["karte"] or r["id"] == "ostsee"):
            continue
        with karten_region(r["karte"]):
            for m in KARTE_MODELLE:
                q = DIREKT_FUER.get(KARTE_OM[m][1]) if m in KARTE_OM else None
                if q and _direkt_im_gebiet(q, KARTE_GEBIET):
                    boxen.setdefault(q, {})[KARTE_REVIER] = tuple(KARTE_GEBIET)
    return boxen


def _direkt_im_gebiet(q: str, g) -> bool:
    d = DIREKT_GEBIET.get(q)
    return d is None or (d[0] <= g[0] and g[1] <= d[1] and d[2] <= g[2] and g[3] <= d[3])


def _laeufe_rueckwaerts(takt_h: int, verzug_h: int, anzahl: int = 6) -> List[datetime]:
    t = datetime.now(timezone.utc).replace(tzinfo=None, minute=0, second=0, microsecond=0) - timedelta(hours=verzug_h)
    t = t.replace(hour=t.hour - t.hour % takt_h)
    return [t - timedelta(hours=takt_h * k) for k in range(anzahl)]


def _schritte(q: str, lauf: datetime) -> List[int]:
    n = DIREKT_STUNDEN[q]
    if q == "icon-d2":
        return list(range(0, n + 1))
    if q == "ecmwf":
        return list(range(0, min(n, 144) + 1, 3)) + list(range(150, n + 1, 6))
    return list(range(0, n + 1, 3))


def _ecmwf_url(lauf: datetime, f: int, endung: str) -> str:
    return (f"https://data.ecmwf.int/forecasts/{lauf:%Y%m%d}/{lauf:%H}z/ifs/0p25/oper/"
            f"{lauf:%Y%m%d%H}0000-{f}h-oper-fc.{endung}")


def _gfs_url(lauf: datetime, f: int) -> str:
    la0, la1, lo0, lo1 = GFS_BOX
    return ("https://nomads.ncep.noaa.gov/cgi-bin/filter_gfs_0p25.pl?"
            + urllib.parse.urlencode({"dir": f"/gfs.{lauf:%Y%m%d}/{lauf:%H}/atmos",
                                      "file": f"gfs.t{lauf:%H}z.pgrb2.0p25.f{f:03d}", "var_UGRD": "on",
                                      "var_VGRD": "on", "lev_10_m_above_ground": "on", "subregion": "",
                                      "leftlon": lo0, "rightlon": lo1, "toplat": la1, "bottomlat": la0}))


def _d2_url(lauf: datetime, f: int, var: str) -> str:
    return (f"https://opendata.dwd.de/weather/nwp/icon-d2/grib/{lauf:%H}/{var}/icon-d2_germany_regular-lat-lon_"
            f"single-level_{lauf:%Y%m%d%H}_{f:03d}_2d_{var}.grib2.bz2")


def _direkt_lauf_finden(q: str) -> Optional[datetime]:
    """Jüngster Lauf, dessen letzter benötigter Schritt schon da ist."""
    if q == "ecmwf":
        kand, letzter = _laeufe_rueckwaerts(12, 7), lambda l: _ecmwf_url(l, _schritte(q, l)[-1], "index")
        pruef = lambda l: _direkt_get(letzter(l), timeout=30, versuche=1) is not None
    elif q == "gfs":
        kand = _laeufe_rueckwaerts(6, 4)
        pruef = lambda l: (lambda b: b is not None and b[:4] == b"GRIB")(
            _direkt_get(_gfs_url(l, _schritte(q, l)[-1]), timeout=60, versuche=1))
    else:
        kand = _laeufe_rueckwaerts(3, 2, 8)
        pruef = lambda l: _direkt_get(_d2_url(l, 45, "v_10m"), timeout=30, versuche=1) is not None   # 03 UTC: +45 h
    for l in kand:
        try:
            if pruef(l):
                return l
        except RuntimeError:
            continue
    return None


def _direkt_schritt(q: str, lauf: datetime, f: int) -> List[dict]:
    """u/v 10 m eines Vorhersageschritts als Felder."""
    import bz2
    if q == "ecmwf":
        idx = _direkt_get(_ecmwf_url(lauf, f, "index"))
        if idx is None:
            return []
        teile = []
        for zeile in idx.decode().splitlines():
            try:
                e = json.loads(zeile)
            except ValueError:
                continue
            if e.get("param") in ("10u", "10v") and e.get("levtype") == "sfc":
                o, n = int(e["_offset"]), int(e["_length"])
                b = _direkt_get(_ecmwf_url(lauf, f, "grib2"), {"Range": f"bytes={o}-{o + n - 1}"})
                if b:
                    teile.append(b)
        return [x for b in teile for x in _grib_felder(b)]
    if q == "gfs":
        b = _direkt_get(_gfs_url(lauf, f))
        return _grib_felder(b) if b and b[:4] == b"GRIB" else []
    aus = []
    for var in ("u_10m", "v_10m"):
        b = _direkt_get(_d2_url(lauf, f, var))
        if b:
            aus += _grib_felder(bz2.decompress(b))
    return aus


def direkt_aktualisieren() -> None:
    """Je Quelle: neuen Lauf laden, wenn der gespeicherte älter ist als DIREKT_ERNEUERN_H; für jedes Revier den
    Ausschnitt (mit Rand) speichern. Fehler einer Quelle: Hinweis, die Karte nutzt den alten Stand oder Open-Meteo."""
    try:
        import numpy as np
        import importlib
        importlib.import_module("eccodes")
    except ImportError:
        print("Hinweis: eccodes/numpy fehlen – Karten weiter über Open-Meteo "
              "(sudo apt install python3-eccodes python3-numpy)", file=sys.stderr)
        return
    boxen = _direkt_boxen()
    try:
        meta = json.loads(DIREKT_META.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        meta = {}
    try:
        alt = dict(np.load(DIREKT_DATEI, allow_pickle=False)) if DIREKT_DATEI.exists() else {}
    except (OSError, ValueError):
        alt = {}
    neu = dict(alt)
    geaendert = False
    for q, bx in boxen.items():
        m = meta.get(q) or {}
        frisch = m.get("geholt") and datetime.now() - datetime.fromisoformat(m["geholt"]) < \
            timedelta(hours=DIREKT_ERNEUERN_H[q])
        if frisch and sorted(m.get("reviere", [])) == sorted(bx):
            continue
        try:
            lauf = _direkt_lauf_finden(q)
            if lauf is None:
                raise RuntimeError("kein vollständiger Lauf gefunden")
            if m.get("lauf") == lauf.isoformat() and sorted(m.get("reviere", [])) == sorted(bx):
                m["geholt"] = datetime.now().isoformat(timespec="minutes")
                meta[q] = m
                geaendert = True
                continue
            schnitte: Dict[str, Dict[str, list]] = {rid: {"t": [], "u": [], "v": []} for rid in bx}
            gitter: Dict[str, tuple] = {}
            schritte = _schritte(q, lauf)
            for k, f in enumerate(schritte):
                print(f"\r\033[2KKarten direkt: {DIREKT_NAME[q]} Lauf {lauf:%d.%m. %H} UTC, Schritt {k + 1}/"
                      f"{len(schritte)} …", end="", file=sys.stderr, flush=True)
                felder = _direkt_schritt(q, lauf, f)
                fu = next((x for x in felder if x["name"].lower() in ("10u", "u10", "u", "u_10m")), None)
                fv = next((x for x in felder if x["name"].lower() in ("10v", "v10", "v", "v_10m")), None)
                if fu is None or fv is None:
                    continue
                for rid, g in bx.items():
                    la, lo = fu["lats"], fu["lons"]
                    d_la, d_lo = abs(la[1] - la[0]), abs(lo[1] - lo[0])
                    j0 = max(0, int(np.searchsorted(la, g[0] - 2 * d_la)) - 1)
                    j1 = min(len(la), int(np.searchsorted(la, g[1] + 2 * d_la)) + 1)
                    i0 = max(0, int(np.searchsorted(lo, g[2] - 2 * d_lo)) - 1)
                    i1 = min(len(lo), int(np.searchsorted(lo, g[3] + 2 * d_lo)) + 1)
                    if j1 - j0 < 2 or i1 - i0 < 2:
                        continue
                    gitter[rid] = (la[j0:j1], lo[i0:i1])
                    s = schnitte[rid]
                    s["t"].append(fu["gueltig"].strftime("%Y-%m-%dT%H:%M"))
                    s["u"].append(fu["werte"][j0:j1, i0:i1] * MS_ZU_KN)
                    s["v"].append(fv["werte"][j0:j1, i0:i1] * MS_ZU_KN)
            neu = {k: v for k, v in neu.items() if not k.startswith(q + "|")}
            for rid, s in schnitte.items():
                if len(s["t"]) < 2 or rid not in gitter:
                    continue
                neu[f"{q}|{rid}|lat"], neu[f"{q}|{rid}|lon"] = gitter[rid]
                neu[f"{q}|{rid}|t"] = np.array(s["t"])
                neu[f"{q}|{rid}|u"] = np.array(s["u"], dtype=np.float16)
                neu[f"{q}|{rid}|v"] = np.array(s["v"], dtype=np.float16)
            meta[q] = {"lauf": lauf.isoformat(), "geholt": datetime.now().isoformat(timespec="minutes"),
                       "reviere": sorted(bx)}
            geaendert = True
        except Exception as e:                               # Zugabe, nie ein Abbruchgrund
            print(f"\r\033[2KHinweis: Karten direkt {DIREKT_NAME[q]} nicht geladen ({e}) – alter Stand bzw. "
                  "Open-Meteo", file=sys.stderr)
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    if geaendert:
        try:
            tmp = DIREKT_DATEI.with_suffix(".tmp.npz")
            np.savez_compressed(tmp, **neu)
            tmp.replace(DIREKT_DATEI)
            DIREKT_META.write_text(json.dumps(meta, indent=1), encoding="utf-8")
        except OSError as e:
            print(f"Hinweis: Karten direkt nicht gespeichert ({e})", file=sys.stderr)


def direkt_feld(m: str) -> Optional[dict]:
    """Feld für den Wind-Player aus dem direkten Speicher (aktuelles Revier), sonst None."""
    q = DIREKT_FUER.get(KARTE_OM[m][1])
    if not q or not _direkt_im_gebiet(q, KARTE_GEBIET) or not DIREKT_DATEI.exists():
        return None
    try:
        import numpy as np
        with np.load(DIREKT_DATEI, allow_pickle=False) as z:
            k = f"{q}|{KARTE_REVIER}|"
            if k + "u" not in z.files:
                return None
            la, lo, ts = z[k + "lat"], z[k + "lon"], [str(x) for x in z[k + "t"]]
            uu, vv = z[k + "u"].astype(np.float32), z[k + "v"].astype(np.float32)
    except (OSError, ValueError, ImportError):
        return None
    lats_g, lons_g = [float(x) for x in la], [float(x) for x in lo]
    zeiten, u_t, v_t = [], [], []
    for t, u2, v2 in zip(ts, uu, vv):
        werte = [(None, None) if (np.isnan(a) or np.isnan(b)) else (float(a), float(b))
                 for a, b in zip(u2.ravel(), v2.ravel())]
        uo, vo = om_raster_auf_ziel(lats_g, lons_g, werte)
        zeiten.append(_utc_zu_berlin(datetime.fromisoformat(t)))
        u_t.append(uo)
        v_t.append(vo)
    global KARTE_TAKT
    takt_alt = KARTE_TAKT
    if q != "icon-d2":
        KARTE_TAKT = 1               # schon 3-stündlich (UTC) – in Ortszeit 01/04/07 Uhr, nicht noch einmal ausdünnen
    try:
        t_aus, sp, ri = _kodiere_feld(zeiten, u_t, v_t, KARTE_OM_STUNDEN, KARTE_OM_TAKT_FERN if q == "icon-d2" else 1)
    finally:
        KARTE_TAKT = takt_alt
    if not t_aus:
        return None
    return {"name": DIREKT_NAME[q], "lauf": "", "t": t_aus, "sp": sp, "ri": ri}


# =============================================================================
# SEEWIND-INDEX: sonnige Tage mit schwachem Grundwind und warmem Land über kaltem Wasser
# =============================================================================
# Faustregeln (Küste Kieler Bucht): Seewind setzt typischerweise zwischen 11 und 14 Uhr ein und hält bis zum
# späten Nachmittag, wenn das Land mehrere Grad wärmer wird als das Wasser, die Sonne scheint und der Grundwind
# schwach ist. Ablandiger Grundwind über ~8 kn verhindert ihn. Die Modelle bilden ihn oft nur abgeschwächt ab.

SEEWIND_DT_MOEGLICH = 5.0      # K: Land (Tageshöchstwert) minus Wasser
SEEWIND_DT_WAHRSCH = 8.0
SEEWIND_GRUND_MAX = 10.0       # kn Grundwind am Vormittag (08–10 Uhr)
# Thermik-Verstärkung (29.10.2026): auflandiger Grundwind (z. B. Ost an der Eckernförder Bucht) plus sonniger Tag mit
# warmem Land über kaltem Wasser – die Seewindzirkulation legt sich auf den Grundwind, am Nachmittag oft ein paar
# Knoten mehr, als die Modelle zeigen (vor allem Frühjahr/Frühsommer). Prüfung an Messungen: --thermik-pruefen (1.1).
SEEWIND_VERST_GRUND = (6.0, 16.0)   # kn: Bereich des auflandigen Grundwinds
SEEWIND_REVIERE = ("ostsee", "westkueste")   # die Faustregeln stammen von der Kieler Bucht
# Die Faustregel selbst – --thermik-pruefen vergleicht immer gegen sie; thermik_pruefung.json kann die drei Werte
# oben beim Start ersetzen (thermik_pruefung_laden), wenn die Prüfung an Messungen klar besser abschneidet.
SEEWIND_STANDARD = (SEEWIND_DT_MOEGLICH, SEEWIND_DT_WAHRSCH, SEEWIND_GRUND_MAX)
SEEWIND: Dict[Tuple[date, str], dict] = {}     # (Tag, Spot) → Bewertung
SEEWIND_TAG: Dict[date, dict] = {}             # Tag → Landtemperatur, Wasser, Spots


def seewind_bewerten(spot: "Spot", d: "OrtDaten", tag: date, t_land: Optional[float]) -> Optional[dict]:
    if spot.strand is None or t_land is None or spot.see_hoehe > 0:
        return None
    wt = [v for t, v in d.wasser.items() if t.date() == tag]
    if not wt:
        return None
    sst = sum(wt) / len(wt)
    dt = t_land - sst
    if dt < SEEWIND_DT_MOEGLICH:
        return None
    hs = [st for st in d.stunden if st.t.date() == tag]
    morgen = [st for st in hs if 8 <= st.t.hour <= 10]
    mittag = [st for st in hs if 10 <= st.t.hour <= 15]
    nachm = [st for st in hs if 13 <= st.t.hour <= 17]
    if not morgen or not mittag or not nachm:
        return None
    if sum(1 for st in mittag if st.wc is not None and st.wc <= 2) < len(mittag) / 2:
        return None                                   # zu wolkig/regnerisch
    g_ws, g_wd = vektor_mittel([(st.ws, st.wd) for st in morgen])
    lage = lage_zum_strand(spot, g_wd)
    if lage == "auflandig" and SEEWIND_VERST_GRUND[0] <= g_ws <= SEEWIND_VERST_GRUND[1]:
        # Grundwind kommt schon von See: kein eigener Seewind, aber Verstärkung am Nachmittag
        auf = [st for st in nachm if abs((st.wd - spot.strand + 180) % 360 - 180) <= 60]
        m_kn = max((st.ws for st in auf), default=None)
        return {"art": "verstaerkt", "stufe": 2 if dt >= SEEWIND_DT_WAHRSCH else 1, "dt": dt, "land": t_land,
                "wasser": sst, "grund": g_ws, "grund_rich": kompass(g_wd), "von": kompass(spot.strand),
                "modell_kn": m_kn if (m_kn is not None and m_kn >= g_ws + 2) else None}
    if g_ws > SEEWIND_GRUND_MAX:
        return None
    ablandig = lage_zum_strand(spot, g_wd) == "ablandig"
    if ablandig and g_ws > 8:
        return None
    stufe = 2 if (dt >= SEEWIND_DT_WAHRSCH and g_ws <= 8 and not ablandig) else 1
    # Sehen die Modelle ihn? Nachmittags auflandig und stärker als am Vormittag
    auf = [st for st in nachm if abs((st.wd - spot.strand + 180) % 360 - 180) <= 60]
    m_kn = max((st.ws for st in auf), default=None)
    sieht = m_kn is not None and len(auf) >= len(nachm) / 2 and m_kn >= g_ws + 3
    return {"art": "seewind", "stufe": stufe, "dt": dt, "land": t_land, "wasser": sst, "grund": g_ws,
            "grund_rich": kompass(g_wd), "von": kompass(spot.strand), "modell_kn": m_kn if sieht else None}


def seewind_berechnen(spot_daten: List["OrtDaten"], tage: List[date]) -> None:
    SEEWIND.clear()
    SEEWIND_TAG.clear()
    # Landtemperatur: Binnensee-Spots desselben Reviers (Ostsee: Wittensee), sonst die der Ostsee – nicht mehr der
    # Mittelwert über alle Binnenseen (Gardasee, Bodensee …), der kam mit den neuen Revieren hinzu und war falsch.
    inland: Dict[str, List[OrtDaten]] = {}
    for s, d in zip(SPOTS, spot_daten):
        if s.see_hoehe > 0:
            inland.setdefault(revier_von(s), []).append(d)
    for tag in tage:
        t_land_r: Dict[str, float] = {}
        for rid_, ds in inland.items():
            werte = [max((st.temp for st in d.stunden if st.t.date() == tag and 12 <= st.t.hour <= 16
                          and st.temp is not None), default=None) for d in ds]
            werte = [w for w in werte if w is not None]
            if werte:
                t_land_r[rid_] = sum(werte) / len(werte)
        for s, d in zip(SPOTS, spot_daten):
            if s.stufe > DEINE_STUFE and not OEFFENTLICH:
                continue
            rid_ = revier_von(s)
            if rid_ not in SEEWIND_REVIERE:
                continue
            b = seewind_bewerten(s, d, tag, t_land_r.get(rid_, t_land_r.get("ostsee")))
            if b:
                SEEWIND[(tag, s.name)] = b
                info = SEEWIND_TAG.setdefault(tag, {"land": b["land"], "wasser": [], "spots": []})
                info["wasser"].append(b["wasser"])
                info["spots"].append((s.name, b))


def seewind_tag_text(tag: date, rid: Optional[str] = None) -> str:
    info = SEEWIND_TAG.get(tag)
    if not info:
        return ""
    rev = {s.name: revier_von(s) for s in SPOTS}
    spots = [(n, b) for n, b in info["spots"] if rid is None or rev.get(n) == rid]
    if not spots:
        return ""
    teile = []
    for art in ("seewind", "verstaerkt"):
        sp = [(n, b) for n, b in spots if b.get("art", "seewind") == art]
        if not sp:
            continue
        stufe = max(b["stufe"] for _, b in sp)
        wasser = sum(b["wasser"] for _, b in sp) / len(sp)
        sehen = [n for n, b in sp if b["modell_kn"]]
        namen = ", ".join(n for n, _ in sorted(sp, key=lambda x: -x[1]["stufe"])[:4])
        if art == "seewind":
            teile.append(f"Seewind {'wahrscheinlich' if stufe == 2 else 'möglich'} (Land {sp[0][1]['land']:.0f} °C, "
                         f"Wasser {wasser:.0f} °C, ab ~12 Uhr): {namen}"
                         + (" – Modelle sehen ihn" if sehen else (" – in den Modellen kaum, kann stärker kommen"
                                                                   if seewind_mehr_belegt() else " – in den Modellen kaum")))
        else:
            teile.append(f"Thermik verstärkt den auflandigen Wind {'deutlich' if stufe == 2 else 'etwas'} "
                         f"(Land {sp[0][1]['land']:.0f} °C, Wasser {wasser:.0f} °C, nachmittags): {namen}"
                         + ("" if sehen or not seewind_mehr_belegt() else " – Modelle zeigen das kaum, eher ein paar kn mehr"))
    return " · ".join(teile)


def seewind_spot_text(b: dict) -> str:
    if b.get("art") == "verstaerkt":
        return (f"Thermik verstärkt den auflandigen Grundwind ({b['grund']:.0f} kn {b['grund_rich']}) am Nachmittag – "
                f"Land {b['land']:.0f} °C, Wasser {b['wasser']:.0f} °C"
                + (f", Modelle bis {b['modell_kn']:.0f} kn" if b["modell_kn"] else
                   (", in den Modellen kaum – eher mehr" if seewind_mehr_belegt() else ", in den Modellen kaum"))
                + seewind_verst_text())
    q = seewind_quote_text(b["stufe"])
    return (f"Seewind {'wahrscheinlich' if b['stufe'] == 2 else 'möglich'} aus {b['von']} ab ~12 Uhr "
            f"(Land {b['land']:.0f} °C, Wasser {b['wasser']:.0f} °C, Grundwind {b['grund']:.0f} kn {b['grund_rich']})"
            + (f", Modelle bis {b['modell_kn']:.0f} kn" if b["modell_kn"] else ", in den Modellen kaum")
            + (f" · {q}" if q else ""))


def hole_karten(demo: bool = False) -> Optional[dict]:
    """Alle Modelle für den Wind-Player. Fehler einzelner Modelle: Hinweis, weiter mit den anderen."""
    if not KARTE_MODELLE:
        return None
    lats, lons = karte_raster()
    modelle = []
    for m in KARTE_MODELLE:
        try:
            if demo:
                modelle.append(demo_feld(m))
            elif m == "dmi":
                modelle.append(hole_dmi_feld())
            elif m == "met":
                modelle.append(hole_met_feld())
            elif m in KARTE_OM:
                modelle.append(hole_om_feld(m))
        except Exception as e:                             # Zugabe, nie ein Abbruchgrund
            print(f"\r\033[2KHinweis: Wind-Player {m.upper()} nicht geladen ({e})", file=sys.stderr)
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    if not modelle:
        return None
    kueste = None
    try:
        kueste = hole_kueste(demo)
    except Exception as e:                                 # ohne Küste läuft der Player trotzdem
        print(f"\r\033[2KHinweis: Küstenlinien nicht geladen ({e})", file=sys.stderr)
    if kueste and not demo and KUESTE_ART in ("see", "osm"):
        for name, v in spots_an_land(kueste):
            print(f"\r\033[2KHinweis: {name} liegt laut OpenStreetMap an Land – Koordinaten prüfen"
                  + (f" (nächstes Wasser ≥ 250 m vom Ufer: {v[0]}, {v[1]})" if v else ""), file=sys.stderr)
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    return {"lat": [round(v, 4) for v in lats], "lon": [round(v, 4) for v in lons], "modelle": modelle,
            "kueste": {"linien": kueste["linien"], "land": kueste["land"],
                       "quelle": kueste.get("quelle", "")} if kueste else None,
            "orte": [[n, la, lo] for n, la, lo in KARTE_ORTE],
            "spots": [{"n": s.name, "lat": s.lat, "lon": s.lon, "d": spot_datei(s)} for s in SPOTS
                      if KARTE_GEBIET[0] <= s.lat <= KARTE_GEBIET[1] and KARTE_GEBIET[2] <= s.lon <= KARTE_GEBIET[3]
                      and revier_von(s) == KARTE_REVIER]}


def karte_test(demo: bool = False) -> None:
    """--karte-test: Windfelder holen und kurz zusammenfassen (Wind am Kiel Leuchtturm, Abdeckung)."""
    k = hole_karten(demo=demo)
    if not k:
        sys.exit("Keine Windfelder geladen – Hinweise oben" + (f", Rohantwort in {KARTE_FEHLER_DATEI}"
                                                              if Path(KARTE_FEHLER_DATEI).exists() else "") + ".")
    lats, lons = k["lat"], k["lon"]
    j = min(range(len(lats)), key=lambda a: abs(lats[a] - 54.50))
    i = min(range(len(lons)), key=lambda a: abs(lons[a] - 10.27))
    q = j * len(lons) + i
    print(f"Raster {len(lats)} × {len(lons)} Zellen (~2 km), Gebiet {KARTE_GEBIET}")
    for m in k["modelle"]:
        sp0 = base64.b64decode(m["sp"][0])
        abdeckung = sum(1 for b in sp0 if b != 255) / len(sp0) * 100
        print(f"\n{m['name']} · Lauf {m['lauf'] or '?'} · {len(m['t'])} Stunden {m['t'][0]} … {m['t'][-1]} · "
              f"Abdeckung {abdeckung:.0f} %")
        zeilen = []
        for t, sp, ri in list(zip(m["t"], m["sp"], m["ri"]))[:12:2]:
            a, r = base64.b64decode(sp)[q], base64.b64decode(ri)[q]
            zeilen.append(f"{t[11:16]} " + ("–" if a == 255 else f"{a / 4:.0f} kn {kompass(r / 256 * 360)}"))
        print("  Kiel Leuchtturm: " + " · ".join(zeilen))
    if k.get("kueste"):
        print(f"\nKüste: {len(k['kueste']['linien'])} Linienzüge, "
              f"{sum(len(l) for l in k['kueste']['linien'])} Punkte · Quelle: {k['kueste'].get('quelle') or '?'}")
    else:
        print("\nKüste: nicht geladen")
    print(f"Größe im HTML: ~{len(json.dumps(k)) / 1e6:.1f} MB")


def demo_feld(m: str) -> dict:
    """Erfundenes Windfeld: Tief zieht von West nach Ost, über Land etwas schwächer (nur zum Testen)."""
    lats, lons = karte_raster()
    jetzt = datetime.now().replace(minute=0, second=0, microsecond=0)
    t, sp, ri = [], [], []
    kurz = m in ("met", "dmi") or (m in KARTE_OM and OM_TAGE.get(KARTE_OM[m][1], 99) <= 3)
    stunden = list(range(48)) if kurz else \
        list(range(KARTE_STUNDEN + 1)) + list(range(KARTE_STUNDEN + 3, KARTE_OM_STUNDEN + 1, KARTE_OM_TAKT_FERN))
    stunden = [h for h in stunden if h % max(1, KARTE_TAKT) == 0]
    for h in stunden:
        cx, cy = 8.5 + h * 0.08, 56.2 - h * 0.01
        b_sp, b_ri = bytearray(), bytearray()
        for la in lats:
            for lo in lons:
                dxk, dyk = (lo - cx) * 64, (la - cy) * 111
                r = math.hypot(dxk, dyk) + 1
                stark = 30 * math.exp(-((r - 180) / 140) ** 2) + 6 + (2 if m == "met" else 0)
                stark *= 0.75 if (la > 54.3 and lo < 10.0) or (la < 54.25 and lo > 10.6 and la > 54.0) else 1.0
                u, v = -dyk / r * stark, dxk / r * stark          # gegen den Uhrzeigersinn
                von = (math.degrees(math.atan2(-u, -v)) + 360) % 360
                b_sp.append(min(254, int(round(stark * 4))))
                b_ri.append(int(round(von / 360 * 256)) % 256)
        t.append((jetzt + timedelta(hours=h)).strftime("%Y-%m-%dT%H:%M"))
        sp.append(base64.b64encode(bytes(b_sp)).decode("ascii"))
        ri.append(base64.b64encode(bytes(b_ri)).decode("ascii"))
    return {"name": ({"dmi": "DMI HARMONIE", "met": "MET Nordic"}.get(m) or (KARTE_OM[m][0] if m in KARTE_OM else m))
            + " (Demo)", "lauf": "",
            "t": t, "sp": sp, "ri": ri}


