def wp_js(var: str = "WP", P: str = "wp", reg: str = "ostsee") -> str:
    """Player-Skript für eine Instanz: Element-IDs mit Präfix P, Daten in var, Sprunglinks der Region reg."""
    js = WP_JS.replace("document.getElementById('wp')", f"document.getElementById('{P}')")
    for x in ("info", "play", "t", "tage", "zeit", "uhr", "grob"):
        js = js.replace(f"getElementById('wp-{x}')", f"getElementById('{P}-{x}')")
    js = js.replace("L.map('wp-karte'", f"L.map('{P}-karte'")
    for c in (".wp-m", ".wp-d", ".wp-s"):
        js = js.replace(f"document.querySelectorAll('{c}')", f"box.querySelectorAll('{c}')")
    js = js.replace("document.querySelectorAll('.wp-sprung')", f"document.querySelectorAll('.wp-sprung[data-reg=\"{reg}\"]')")
    return re.sub(r"\bWP\b", var, js)


def wind_player_html(karten: Optional[dict], jetzt: datetime, P: str = "wp", var: str = "WP",
                     titel: str = "Wind-Player", reg: str = "ostsee", mit_leaflet: bool = True) -> Tuple[str, str]:
    """(HTML-Abschnitt, Script) für den Wind-Player; leer, wenn keine Daten."""
    if not karten:
        return "", ""
    daten = dict(karten)
    daten["farben"] = [[k, list(c)] for k, c in KARTE_FARBEN]
    def quelle(n):
        if n.startswith("DMI"):
            return "DMI"
        if n.startswith("MET"):
            return "MET Norway"
        if n in DIREKT_NAME.values():                       # direkt aus den Modelldateien (seit 01.11.2026)
            return {"ECMWF": "ECMWF Open Data", "GFS": "NOAA GFS", "ICON-D2": "DWD ICON-D2"}[n.split()[0]]
        if n.startswith("ECMWF") or n.startswith("GFS") or n.startswith("ICON") or n.startswith("AROME"):
            return n.split(" (")[0] + " über Open-Meteo"
        return n
    daten["quellen"] = " · ".join(dict.fromkeys(quelle(m["name"]) for m in karten["modelle"]))
    ziel = jetzt.strftime("%Y-%m-%dT%H:00")
    t0 = karten["modelle"][0]["t"]
    daten["start"] = next((i for i, s in enumerate(t0) if s >= ziel), 0)
    verh = len(karten["lon"]) / len(karten["lat"])      # Raster hat quadratische Pixel (Mercator)
    knoepfe = "".join(f'<button class="mk wp-m{" an" if i == 0 else ""}">{e_txt(m["name"])}</button>'
                      for i, m in enumerate(karten["modelle"]))
    darst = ('<button class="mk wp-d an" data-m="linien">Stromlinien</button>'
             '<button class="mk wp-d" data-m="pfeile">Pfeile</button>')
    links = " ".join(f'<a href="{e_txt(u)}" target="_blank" rel="noopener">{e_txt(n)} ↗</a>' for n, u in KARTEN_LINKS)
    stops = ", ".join(f"rgb{c} {k / 45 * 100:.1f}%" for k, c in KARTE_FARBEN)
    marken = "".join(f'<span style="left:{k / 45 * 100:.1f}%"{" class=gl" if k == 18 else ""}>{k}</span>'
                     for k in (0, 10, 14, 18, 22, 26, 30, 35))
    rep = karten.get("sessions") or []
    rep_html = ""
    if rep:
        rep_html = ('<div class="mk-leiste wp-replay"><span class="wp-rl">Session-Replay:</span>'
                    + "".join(f'<button class="mk wp-s" title="GPX-Track über der MET-Nordic-Analyse">{e_txt(r["titel"])}'
                              + (f' · {r["wind_track"][0]:.0f} kn' if r.get("wind_track") else "") + '</button>'
                              for r in rep) + '</div>')
    erkl = "Windfeld der Modelle, ohne die Korrekturen dieses Tools. Spot antippen für den Wert vor Ort."
    html = (f'<section id="{P}"><h2>{e_txt(titel)}{info_knopf(erkl)}</h2>'
            f'<div class="mk-leiste">{knoepfe}<span class="wp-trenn"></span>{darst}'
            f'<span class="mk-links">{links}</span></div>' + rep_html +
            f'<div class="karte wp-karte" id="{P}-karte" style="--wp-ar:{verh:.4f}">'
            f'<div class="wp-info" id="{P}-info"></div></div>'
            # 23.11.2026 (Anforderungen 3–4): Kurzlegende oben in der Zeitleiste, Plakette für grobe Bilder,
            # Uhrzeit mit fester Breite neben dem Regler, darunter die Tage (antippen springt auf den Vormittag)
            f'<div class="wp-unten">'
            f'<div class="wp-skala"><span class="wp-sk-t">Wind</span><div class="wp-sk-b"><div class="wp-balken" '
            f'style="background:linear-gradient(90deg,{stops})"></div><div class="wp-marken">{marken}</div></div>'
            f'<span class="wp-einh">kn</span><span class="wp-grob" id="{P}-grob" hidden></span></div>'
            f'<div class="wp-steuer"><button id="{P}-play" class="mk" aria-label="Abspielen">▶</button>'
            f'<span class="wp-uhr" id="{P}-uhr"></span>'
            f'<div class="wp-regler"><input type="range" id="{P}-t" min="0" value="0">'
            f'<div class="wp-tage" id="{P}-tage"></div></div></div>'
            f'<div class="wp-zeit" id="{P}-zeit"></div></div>'
            + '</section>')
    einbinden = ""
    if mit_leaflet:
        lf = leaflet_eingebettet() if OEFFENTLICH else None
        if lf and DATEN_ORDNER is not None:        # einmal als gemeinsame Datei statt in jeder Seite (~150 kB)
            for n_, inhalt in (("leaflet.min.css", lf[0]), ("leaflet.min.js", lf[1])):
                z_ = DATEN_ORDNER / n_
                if not z_.exists() or z_.stat().st_size != len(inhalt.encode()):
                    z_.write_text(inhalt, encoding="utf-8")
            # JS wird erst geladen, wenn die Karte in Sichtweite kommt (siehe unten); CSS ist klein
            einbinden = f'<link rel="stylesheet" href="{WURZEL}daten/leaflet.min.css">'
        elif lf:
            einbinden = f'<style>{lf[0]}</style><script>{lf[1]}</script>'
        else:
            einbinden = (f'<link rel="stylesheet" href="{LEAFLET_CDN}leaflet.min.css">'
                         f'<script src="{LEAFLET_CDN}leaflet.min.js"></script>')
    roh = json.dumps(daten, separators=(",", ":"))
    if DATEN_ORDNER is not None and OEFFENTLICH:
        # Windfelder je Revier als eigene Datei: gleich für alle Gleitgrenzen und Sprachen (Seite ~5 MB → ~100 kB)
        name = f"wp_{reg}_{var.lower()}.js"
        if (DATEN_ORDNER, name, DATEN_VERSION) not in WP_GESCHRIEBEN:     # Spotseiten nutzen dieselbe Datei
            (DATEN_ORDNER / name).write_text(f"var {var}={roh};", encoding="utf-8")
            WP_GESCHRIEBEN.add((DATEN_ORDNER, name, DATEN_VERSION))
        # Erst laden, wenn die Karte in Sichtweite kommt (oder „auf der Karte“ angetippt wird): spart am Handy
        # 0,5–5 MB (komprimiert/roh) für alle, die nur die Tageskacheln anschauen.
        lf_src = f"{WURZEL}daten/leaflet.min.js" if (DATEN_ORDNER / "leaflet.min.js").exists() else ""
        skript = (einbinden + '<script>(function(){var box=document.getElementById("' + P + '");if(!box)return;'
                  'var W=window.__wfLade||(window.__wfLade={});function lade(src){return W[src]||(W[src]=new Promise('
                  'function(ok,nein){var e=document.createElement("script");e.src=src;e.onload=ok;e.onerror=nein;'
                  'document.head.appendChild(e);}));}var los=false,warte=null;function start(){if(los)return;los=true;'
                  + (f'lade("{lf_src}")' if lf_src else 'Promise.resolve()')
                  + f'.then(function(){{return lade("{WURZEL}daten/{name}?v={DATEN_VERSION}");}}).then(function(){{'
                  + wp_js(var, P, reg)
                  + ';if(warte)warte.click();}).catch(function(){box.style.display="none";});}'
                  'if("IntersectionObserver" in window){var io=new IntersectionObserver(function(en){if(en.some('
                  'function(x){return x.isIntersecting;})){io.disconnect();start();}},{rootMargin:"800px 0px"});io.observe(box);}'
                  'else start();document.querySelectorAll(".wp-sprung").forEach(function(a){a.addEventListener("click",'
                  'function(){if(!los){warte=a;start();}});});})();</script>')
    else:
        skript = einbinden + f'<script>const {var}={roh};{wp_js(var, P, reg)}</script>'
    return html, skript


WP_GESCHRIEBEN: set = set()
LEAFLET_VOM_CDN = False      # merkt sich, ob die öffentliche Seite Leaflet doch vom CDN lädt (für den Datenschutztext)


def leaflet_eingebettet() -> Optional[Tuple[str, str]]:
    """(CSS, JS) von Leaflet aus LEAFLET_DIR; fehlen die Dateien, einmal vom CDN holen und ablegen."""
    global LEAFLET_VOM_CDN
    css_p, js_p = LEAFLET_DIR / "leaflet.min.css", LEAFLET_DIR / "leaflet.min.js"
    if not (css_p.exists() and js_p.exists()):
        if LEAFLET_VOM_CDN:                      # in diesem Lauf schon gescheitert: nicht für jede Seite neu versuchen
            return None
        try:
            LEAFLET_DIR.mkdir(exist_ok=True)
            for name, ziel in (("leaflet.min.css", css_p), ("leaflet.min.js", js_p)):
                ziel.write_bytes(_karte_get(LEAFLET_CDN + name, 60, versuche=2))
        except (RuntimeError, OSError) as e:
            print(f"Hinweis: Leaflet nicht lokal ablegbar ({e}) – öffentliche Seite lädt es vom CDN", file=sys.stderr)
            LEAFLET_VOM_CDN = True
            return None
    try:
        css = css_p.read_text(encoding="utf-8")
        js = js_p.read_text(encoding="utf-8").replace("</script", "<\\/script")
    except OSError:
        LEAFLET_VOM_CDN = True
        return None
    return css, js


def windy_url(lat: float, lon: float, zoom: int, produkt: str) -> str:
    q = {"lat": f"{lat:.3f}", "lon": f"{lon:.3f}", "zoom": zoom, "level": "surface", "overlay": "wind",
         "product": produkt, "menu": "", "message": "true", "marker": "", "calendar": "now", "pressure": "",
         "type": "map", "location": "coordinates", "detail": "", "metricWind": "kt", "metricTemp": "°C"}
    return "https://embed.windy.com/embed2.html?" + urllib.parse.urlencode(q)


def windkarte_html(k: Optional[dict] = None, links=None) -> str:
    k = k or WINDKARTE
    if not k:
        return ""
    links_l = KARTEN_LINKS if links is None else links
    knoepfe = "".join(
        f'<button class="mk{" an" if i == 0 else ""}" data-src="{e_txt(windy_url(k["lat"], k["lon"], k["zoom"], p))}">'
        f'{e_txt(n)}</button>' for i, (n, p) in enumerate(k["modelle"]))
    links = " ".join(f'<a href="{e_txt(u)}" target="_blank" rel="noopener">{e_txt(n)} ↗</a>' for n, u in links_l)
    erst = windy_url(k["lat"], k["lon"], k["zoom"], k["modelle"][0][1])
    return ('<h2 id="windkarte">Windkarte' + info_knopf(
                'Karte von Windy – rohes Modell ohne die Korrekturen dieses Tools.') + '</h2>'
            f'<div class="mk-leiste">{knoepfe}<span class="mk-links">{links}</span></div>'
            f'<div class="karte"><iframe id="windkarte" src="{e_txt(erst)}" loading="lazy" '
            'title="Windkarte (Windy)" allowfullscreen></iframe></div>')


def kurzueberblick_html(ergebnisse, ziel: str = "") -> str:
    """Oben auf der Seite: je Tag mit Wind der beste Spot – ein Klick führt zu den Karten des Tages."""
    chips = []
    for tag, liste, chancen in ergebnisse:
        if not liste:
            continue
        e = liste[0]
        bg, fg = blau_fuer(e.wind)
        zeit = fahrbar_text(e) if e.verlauf else f"{e.sp_start:%H}–{e.sp_ende:%H}"
        segel = "" if OEFFENTLICH else f" · {qm(e.segel)}"
        chips.append(f'<a class="kb" href="{ziel}#tag-{tag:%Y%m%d}"><span class="kb-kn" style="background:{bg};color:{fg}">'
                     f'{e.wind:.0f}</span><span class="kb-t"><b>{tag_text(tag)}</b> {e_txt(e.spot.name)}<br>'
                     f'{e_txt(e.richtung)}{segel} · {zeit} Uhr</span></a>')
    if not chips:
        return '<p class="sub kb-leer">Kein Tag mit passendem Wind in den nächsten Tagen.</p>'
    return '<div class="kb-reihe">' + "".join(chips) + '</div>'


REGIONEN = ["Kieler Bucht", "Schlei & Eckernförder Bucht", "Fehmarn & Lübecker Bucht", "Flensburger Förde & Als",
            "Binnenseen", "Nordsee & Nordjütland (DK)"]


def spot_gruppe(s: "Spot") -> str:
    """Gruppe in der Tabelle Spots × Tage: Teilregion an der Ostsee, sonst das Revier; höhere Stufen „Für später“."""
    if not OEFFENTLICH and s.stufe > DEINE_STUFE:
        return "Für später"
    if revier_von(s) == "ostsee":
        return region(s)
    return revier(revier_von(s))["name"]


def region(s: "Spot") -> str:
    """Grobe Region für die öffentliche Übersicht (statt Anfahrtszeit ab Achterwehr)."""
    if s.see_hoehe > 0:
        return "Binnenseen"
    if s.lon < 9.0 or s.lat > 56.2:
        return "Nordsee & Nordjütland (DK)"
    if s.lat > 54.75:
        return "Flensburger Förde & Als"
    if s.lon < 10.1:
        return "Schlei & Eckernförder Bucht"
    if s.lon < 10.7:
        return "Kieler Bucht"
    return "Fehmarn & Lübecker Bucht"


def _a(url: str, text: str) -> str:
    return f'<a href="{e_txt(url)}" target="_blank" rel="noopener">{e_txt(text)}</a>'


def impressum_laden() -> None:
    """Impressum aus impressum.json (bleibt außerhalb des Skripts, falls es geteilt wird)."""
    try:
        d = json.loads(IMPRESSUM_DATEI.read_text(encoding="utf-8"))
        if isinstance(d, dict):
            IMPRESSUM.update({k: str(v) for k, v in d.items()})
    except (OSError, ValueError):
        pass


