def info_knopf(text: str, ist_html: bool = False) -> str:
    """Kleines (i): die Erklärung erscheint beim Antippen/Überfahren – statt Erklärsätzen auf der Seite."""
    if not text:
        return ""
    inhalt = text if ist_html else e_txt(text)
    return f'<button type="button" class="info" aria-label="Erklärung" data-tip="{e_txt(inhalt)}">i</button>'


def pfeil_svg(richtung: str, px: int = 12) -> str:
    """Pfeil in Strömungsrichtung (wohin der Wind weht) für eine Kompassrichtung wie 'ONO'."""
    r = (richtung or "").split()[0] if richtung else ""
    if r not in KOMPASS:
        return ""
    grad = (KOMPASS.index(r) * 22.5 + 180) % 360
    return (f'<svg class="pf" width="{px}" height="{px}" viewBox="-10 -10 20 20" aria-hidden="true">'
            f'<path d="M0,-9 L6.5,6 L0,2.5 L-6.5,6 Z" transform="rotate({grad:.0f})" fill="currentColor"/></svg>')


def revier_kurz(r: dict) -> str:
    """'Kieler Bucht & Ostsee' -> 'Kieler Bucht', 'Westküste: St. Peter …' -> 'Westküste'."""
    return r.get("kurz") or re.split(r"[:&]", r["name"])[0].strip()


GRUPPE_KURZ = {"Nord- & Ostsee": "Nord/Ostsee", "Mittelmeer & Atlantik": "Süden"}   # Handy-Kopfleiste
TRENN = {"Neuenburgersee": "Neuen\u00adburger\u00adsee", "Westküste": "West\u00adküste"}


def revier_tab(r: dict) -> str:
    """Reviername für schmale Tabellenspalten: Umbruch nach „/“, weiche Trennstellen in langen Wörtern."""
    t = e_txt(revier_kurz(r)).replace("/", "/<wbr>")
    for w, mit in TRENN.items():
        t = t.replace(w, mit)
    return t


def gw_leiste_html(datei: str) -> str:
    """Gut sichtbarer Umschalter für die Gleitwind-Grenze (öffentliche Seiten) – direkt über der Vorhersage."""
    if not (OEFFENTLICH and GW and datei):
        return ""
    knoepfe = "".join(f'<a href="{e_txt(GW["praefix"][k] + datei)}"{" class=an" if k == GW["aktiv"] else ""}>'
                      f'{k} kn</a>' for k in GLEIT_GRENZEN)
    # 08.11.2026: Groß nur, bis man eine Grenze gewählt oder „passt“ angetippt hat – danach eine schmale Zeile.
    # Gespeichert wird nur nach dieser Handlung (localStorage „wf_gw“, im Datenschutz genannt) – kein Zähler, damit
    # nichts ohne Zutun auf dem Gerät landet (§ 25 TDDDG). Das Skript steht vor dem Kasten, damit nichts springt.
    merk = "try{localStorage.setItem('wf_gw','1')}catch(e){}"
    return ('<script>try{if(localStorage.getItem("wf_gw"))document.documentElement.classList.add("gw-klein")}'
            'catch(e){}</script>'
            f'<div class="gw-leiste"><span class="gw-frage">Ab wie viel Wind geht es los?</span>'
            f'<span class="gw-kurz">Gleitwind ab</span>'
            f'<div class="gw" onclick="{merk}">{knoepfe}</div><span class="gw-hinweis">leicht / großes Segel oder '
            f'Kite ← → schwer / kleines Material</span>'
            f'<button type="button" class="gw-ok" onclick="{merk};document.documentElement.classList.add(\'gw-klein\')">'
            f'passt ✓</button></div>')


# =============================================================================
# ENGLISCHE FASSUNG (31.10.2026): Übersetzung der fertigen deutschen Seiten
# =============================================================================
#
# Statt jede Textstelle im Skript doppelt zu pflegen, wird die fertige deutsche Seite übersetzt: Texte, Tooltips
# (data-tip/title/aria-label) und Zeichenketten in Skripten. Zahlen, Uhrzeiten, Daten, Wochentage und Windrichtungen
# werden vorher durch § ersetzt (aus „Böen 25“ wird der Schlüssel „Böen §“) und danach umgewandelt (1,2 → 1.2,
# O → E, Sa → Sat, 31.10. → 31 Oct). Teile mit „ · “ werden einzeln übersetzt; Namen (Spots, Stationen) bleiben.
# Fehlt ein Schlüssel, bleibt der deutsche Text stehen und landet in UEBERSETZUNG_FEHLT (Lauf meldet die Zahl;
# --uebersetzung-pruefen schreibt die Liste nach uebersetzung_fehlt.txt).

MONATE_KURZ_DE = ["Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez"]
EN_TAGE = {"Mo": "Mon", "Di": "Tue", "Mi": "Wed", "Do": "Thu", "Fr": "Fri", "Sa": "Sat", "So": "Sun"}
EN_MONATE = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
EN_RICHTUNG = {"N": "N", "NNO": "NNE", "NO": "NE", "ONO": "ENE", "O": "E", "OSO": "ESE", "SO": "SE", "SSO": "SSE",
               "S": "S", "SSW": "SSW", "SW": "SW", "WSW": "WSW", "W": "W", "WNW": "WNW", "NW": "NW", "NNW": "NNW"}
_EN_TOKEN = re.compile(
    r"(?<![\w.])(\d{1,2})\.(\d{1,2})\.(\d{4})?(?![\d.])"          # Datum 31.10. / 31.10.2026
    r"|(?<![\w:])(\d{1,2}:\d{2})(?![\d:])"                          # Uhrzeit
    r"|(?<![\w.,])([+−-]?\d+(?:[.,]\d+)?)(?![\d])"                  # Zahl
    r"|\b(NNO|ONO|OSO|SSO|NNW|WNW|SSW|WSW|NO|SO|NW|SW|N|O|S|W)\b"   # Windrichtung
    r"|\b(Mo|Di|Mi|Do|Fr|Sa|So)\b"                                 # Wochentag
    r"|\b(Jan|Feb|Mär|Apr|Mai|Jun|Jul|Aug|Sep|Okt|Nov|Dez)\b")      # Monat
_EN_MODELLE = re.compile(r"^(?:ICON(?:-CH|-D2|-EU)?|GFS|DMI|UKMO|UKV/UKMO|ECMWF|EC|KNMI|MET Nordic|MET|AROME(?:-HD)?|"
                         r"Météo-France)(?:, (?:ICON(?:-CH|-D2|-EU)?|GFS|DMI|UKMO|UKV/UKMO|ECMWF|EC|KNMI|MET Nordic|MET|"
                         r"AROME(?:-HD)?|Météo-France))*(?: §)?$")
_EN_QUELLE = re.compile(r"^Open-Meteo [A-Za-zé/\- ]+(?: \+ [A-Za-zé/\- ]+)*$")
UEBERSETZUNG_FEHLT: Dict[str, int] = {}
_EN_CACHE: Dict[str, str] = {}


def _en_token(m) -> str:
    if m.group(2):
        t = f"{int(m.group(1))} {EN_MONATE[int(m.group(2)) - 1]}" if 1 <= int(m.group(2)) <= 12 else m.group(0)
        return t + (f" {m.group(3)}" if m.group(3) else "")
    if m.group(4):
        return m.group(4)
    if m.group(5):
        return m.group(5).replace(",", ".")
    if m.group(6):
        return EN_RICHTUNG[m.group(6)]
    if m.group(7):
        return EN_TAGE[m.group(7)]
    return EN_MONATE[MONATE_KURZ_DE.index(m.group(8))]


def _en_kern(t: str, melden: bool = True, ist_vorlage: bool = False) -> str:
    """Einen Textteil ohne Rand-Leerzeichen übersetzen. ist_vorlage: t enthält schon §-Platzhalter (aus EN_MUSTER)."""
    if not ist_vorlage and t in _EN_CACHE:
        return _EN_CACHE[t]
    if ist_vorlage:
        rein = t
    else:
        rein = t.replace("\xad", "").replace("§", "\ue000")    # echtes Paragraphzeichen ≠ Platzhalter
    if rein in EN:
        aus = EN[rein]
    else:
        toks = [] if ist_vorlage else list(_EN_TOKEN.finditer(rein))
        vorlage = rein if ist_vorlage else _EN_TOKEN.sub("§", rein)
        werte = [_en_token(m) for m in toks]

        def fuellen(v: str) -> str:
            if re.search(r"§\d", v):
                return re.sub(r"§(\d)", lambda m: werte[int(m.group(1)) - 1], v)
            it = iter(werte)
            return re.sub("§", lambda m: next(it, "§"), v)
        if not EN_GLEICH_FERTIG:
            _en_namen()
        praefix = next((p_ for p_ in EN_PRAEFIX if rein.startswith(p_) and len(rein) > len(p_)), None)
        muster = None if vorlage in EN else next(((rx, z) for rx, z in EN_MUSTER if rx.match(vorlage)), None)
        if vorlage in EN:
            aus = fuellen(EN[vorlage])
        elif praefix:
            aus = fuellen(EN_PRAEFIX[praefix] + _en_kern(vorlage[len(praefix):], melden, True))
        elif muster:
            # Muster auf der Vorlage; Gruppen (Namen, Teilsätze) werden selbst übersetzt
            m_ = muster[0].match(vorlage)
            aus = fuellen(muster[1].format(*[_en_kern(g, melden, True) if g else "" for g in m_.groups()]))
        elif (rein in EN_GLEICH or vorlage in EN_GLEICH or t in EN_GLEICH or _EN_MODELLE.match(vorlage)
              or _EN_QUELLE.match(vorlage) or not re.search(r"[A-Za-zÄÖÜäöüß]{2,}", re.sub(r"\b(kn|km|cm|mm|hPa|Bft|°C)\b", "", vorlage))):
            aus = fuellen(vorlage)
        elif " · " in vorlage:
            aus = fuellen(" · ".join(_en_kern(x, melden, True) for x in vorlage.split(" · ")))
        elif _en_teilbar(vorlage):
            aus = fuellen(_en_teilbar(vorlage))
        elif ", " in vorlage and all(x in EN_GLEICH or x in EN or _EN_MODELLE.match(x) for x in vorlage.split(", ")):
            aus = fuellen(", ".join(EN.get(x, x) for x in vorlage.split(", ")))    # Liste von Namen (09.11.2026)
        else:
            if melden:
                UEBERSETZUNG_FEHLT[vorlage] = UEBERSETZUNG_FEHLT.get(vorlage, 0) + 1
            return t                               # Deutsch stehen lassen (inkl. Trennstellen)
    if ist_vorlage:
        return aus
    aus = re.sub(r"\b(\d{1,2}:\d{2}):00\b", r"\1", aus).replace("\ue000", "§")
    _EN_CACHE[t] = aus
    return aus


EN_GLEICH_FERTIG = False


def _en_namen() -> None:
    """Eigennamen bleiben (Spots, Stationen, Modelle) – damit sie nicht als „fehlt“ gemeldet werden."""
    global EN_GLEICH_FERTIG
    EN_GLEICH_FERTIG = True
    for sp in SPOTS:
        if sp.name not in EN:
            EN_GLEICH.add(sp.name)
    for r in REVIERE:
        for n_ in (r["name"], revier_kurz(r)):
            if n_ not in EN:
                EN_GLEICH.add(n_)
                EN_GLEICH.add(n_ + " →")
    for liste in REVIER_STATIONEN.values():
        for st in liste:
            EN_GLEICH.add(st[0])
            EN_GLEICH.add(jetzt_name(st[0]))
    EN_GLEICH.update({"Meteotrentino", "GeoSphere Austria", "(CC BY §);", "(Provincia autonoma di Trento)",
                      "(Provincia autonoma di Trento);"})
    EN_GLEICH.update(KALIB_SPOTS.values())
    for k in ("name", "adresse", "kontakt", "hoster"):         # Impressum-Angaben (Namen, Anschriften) bleiben
        for zeile in str((IMPRESSUM or {}).get(k, "")).splitlines():
            if zeile.strip():
                EN_GLEICH.add(zeile.strip())
                EN_GLEICH.add(_EN_TOKEN.sub("§", zeile.strip()))


def _en_teilbar(t: str) -> Optional[str]:
    """„Kopf: Rest“ bzw. „Text (Klammer)“ – nur wenn beide Teile bekannt sind."""
    for trenner in (": ", " – ", " ("):
        if trenner in t:
            a, b = t.split(trenner, 1)
            ka, kb = _en_kern(a, False, True), _en_kern(b.rstrip(")") if trenner == " (" else b, False, True)
            if ka != a or not re.search(r"[a-zäöüß]{3,}", a):
                if kb != (b.rstrip(")") if trenner == " (" else b) or not re.search(r"[a-zäöüß]{3,}", b):
                    return ka + trenner + kb + (")" if trenner == " (" and b.endswith(")") else "")
    return None


def _en_text(t: str, melden: bool = True) -> str:
    kern = t.strip()
    if not kern:
        return t
    i = t.index(kern[0])
    return t[:i] + _en_kern(kern, melden) + t[i + len(kern):]


_EN_TEIL = re.compile(r"(<script\b[^>]*>.*?</script>|<style\b[^>]*>.*?</style>|<!--.*?-->|<[^>]+>)", re.S | re.I)
_EN_ATTR = re.compile(r'\b(title|data-tip|aria-label|alt|placeholder|data-titel)="([^"]*)"')
_EN_JS_LIT = re.compile(r"""(['"])((?:\\.|(?!\1)[^\\\n])*)\1""")


def _en_fragment(h: str) -> str:
    """HTML-Fragment ohne Skripte (z. B. Inhalt eines data-tip): Text und Attribute übersetzen."""
    teile = _EN_TEIL.split(h)
    for i, x in enumerate(teile):
        if not x:
            continue
        if i % 2 == 0:
            teile[i] = (html.escape(_en_text(html.unescape(x)), quote=False)
                        if re.search(r"[A-Za-zÄÖÜäöü]|\d[.,]\d", x) else x)
        elif x.startswith("<script") or x.startswith("<SCRIPT"):
            teile[i] = _en_skript(x)
        elif x.startswith("<style") or x.startswith("<!--"):
            continue
        else:
            teile[i] = _EN_ATTR.sub(lambda m: f'{m.group(1)}="{_en_attr(m.group(2))}"', x)
    return "".join(teile)


def _en_attr(v: str) -> str:
    roh = html.unescape(v)
    if not re.search(r"[A-Za-zÄÖÜäöü]{2,}", roh):
        return v
    neu = _en_fragment(roh) if "<" in roh else _en_text(roh)
    return html.escape(neu, quote=True)


def _en_skript(x: str) -> str:
    """Zeichenketten in Skripten: nur Einträge aus EN_JS bzw. EN (keine Meldung, Daten bleiben unberührt)."""
    for alt, neu in EN_CODE.items():
        x = x.replace(alt, neu)

    def lit(m):
        inhalt = m.group(2)
        if not re.search(r"[A-Za-zÄÖÜäöü\\]{2,}", inhalt) or len(inhalt) > 300:
            return m.group(0)
        if inhalt in EN_JS:
            return m.group(1) + EN_JS[inhalt] + m.group(1)
        if m.group(1) == '"' and "\\" in inhalt:     # JSON (CHARTS): \u-Escapes lesen, übersetzen, wieder schreiben
            try:
                roh = json.loads('"' + inhalt + '"')
            except ValueError:
                return m.group(0)
            if not re.search(r"[A-Za-zÄÖÜäöü]{2,}", roh):
                return m.group(0)
            neu = _en_fragment(roh) if "<" in roh else (_en_text(roh, False) if (
                roh.strip() in EN or _EN_TOKEN.sub("§", roh.strip()) in EN) else roh)
            return m.group(0) if neu == roh else json.dumps(neu, ensure_ascii=False)
        if "\\" in inhalt.replace("\\'", ""):
            return m.group(0)                      # Escapes (\n, \u…): nicht anfassen
        if "<" in inhalt and not inhalt.lstrip().startswith(("<svg", "<path")):
            if not re.search(r">[^<]*[A-Za-zÄÖÜäöü]{2,}", inhalt):
                return m.group(0)                  # nur Markup-Bruchstück (z. B. '<a href="'), kein Text
            neu = _en_fragment(inhalt.replace("\\'", "'"))
        else:
            rein = inhalt.strip().replace("\xad", "")
            if rein not in EN and _EN_TOKEN.sub("§", rein) not in EN:
                return m.group(0)                  # in Skripten nur Bekanntes (Kürzel wie 'O' oder 'So' sind oft Schlüssel)
            neu = _en_text(inhalt, False)
        if neu == inhalt:
            return m.group(0)
        q = m.group(1)
        return q + neu.replace("\\", "\\\\").replace(q, "\\" + q) + q
    return _EN_JS_LIT.sub(lit, x)


def uebersetzen_html(h: str) -> str:
    """Fertige deutsche Seite → englische Seite."""
    h = h.replace('<html lang="de">', '<html lang="en">', 1)
    h = re.sub(r'(<meta name="description" content=")([^"]*)(")', lambda m: m.group(1) + _en_attr(m.group(2)) + m.group(3),
               h, count=1)
    return _en_fragment(h)





