# In Skripten (CHARTS, Wind-Player): nur exakte Zeichenketten
EN_JS: Dict[str, str] = {
    "Mittel": "Mean", "Gleitwind": "planing wind", "Nacht": "night", "Böen": "gusts", "Mittelwind": "mean wind",
    " · Küste: ": " · coast: ", "Zum Verschieben der Karte zwei Finger benutzen": "Use two fingers to move the map", " · Lauf ": " · run ", " (gleitet)": " (planing)",
    "So": "Sun", "Mo": "Mon", "Di": "Tue", "Mi": "Wed", "Do": "Thu", "Fr": "Fri", "Sa": "Sat",
}
# Code-Stellen in Skripten, die als Ganzes ersetzt werden (Datumsformat im Wind-Player)
EN_CODE: Dict[str, str] = {
    "return TAGE[d.getDay()]+' '+String(d.getDate()).padStart(2,'0')+'.'+String(d.getMonth()+1).padStart(2,'0')+'. '+s.slice(11,16)+' Uhr';}":
        "return TAGE[d.getDay()]+' '+d.getDate()+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov',"
        "'Dec'][d.getMonth()]+' '+s.slice(11,16);}",
    "sp.textContent=zeitText(s).slice(0,9);": "sp.textContent=zeitText(s).replace(/ \\d\\d:\\d\\d$/,'');",
}

