def _oeffentliche_adresse() -> str:
    """Öffentliche Basisadresse aus upload.json ("adresse", z. B. "https://windfenster.de/"); "" = unbekannt."""
    try:
        a = str(json.loads(UPLOAD_DATEI.read_text(encoding="utf-8")).get("adresse", "")).strip()
    except (OSError, ValueError):
        return ""
    return (a.rstrip("/") + "/") if a.startswith("http") else ""


OG_EN_TAGE = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
OG_EN_MONATE = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def og_marker(e) -> str:
    """Unsichtbarer Merker für die Link-Vorschau: nächster Gleittag (Tag|kn|%|Spot), seite_fertig formuliert ihn."""
    if e is None:
        return '<meta name="wf-naechster" content="-">'
    w_ = gleit_wahrsch(e)
    return (f'<meta name="wf-naechster" content="{e.tag:%Y%m%d}|{e.wind:.0f}|{"" if not w_ else round(w_["p"] * 100)}'
            f'|{e_txt(e.spot.name)}">')


def _vorschau_meta(html: str, rel: str, sprache: str, wurzel: str) -> str:
    """Open-Graph-/Twitter-Angaben, Icons und (wo vorhanden) „nächster Gleittag“ in Beschreibung und Vorschau."""
    m_t = re.search(r"<title>(.*?)</title>", html, re.S)
    if not m_t:
        return html
    titel = m_t.group(1)
    m_d = re.search(r'<meta name="description" content="([^"]*)">', html)
    beschr = m_d.group(1) if m_d else ""
    m_n = re.search(r'<meta name="wf-naechster" content="([^"]*)">', html)
    zusatz = ""
    if m_n:
        html = html.replace(m_n.group(0), "", 1)
        teile = m_n.group(1).split("|")
        if teile[0] == "-":
            zusatz = ("No planing day in sight for the next days." if sprache == "en" else
                      "In den nächsten Tagen kein Gleittag in Sicht.")
        else:
            d = datetime.strptime(teile[0], "%Y%m%d").date()
            kn, pz, spot = teile[1], teile[2], (teile[3] if len(teile) > 3 else "")
            mit_spot = spot and spot not in titel
            if sprache == "en":
                zusatz = (f"Next planing day: {OG_EN_TAGE[d.weekday()]} {d.day} {OG_EN_MONATE[d.month - 1]}"
                          + (f", {spot}" if mit_spot else "") + f" – {kn} kn" + (f", {pz}%" if pz else "") + ".")
            else:
                zusatz = (f"Nächster Gleittag: {WOCHENTAGE[d.weekday()]} {d:%d.%m.}"
                          + (f", {spot}" if mit_spot else "") + f" – {kn} kn" + (f", {pz} %" if pz else "") + ".")
    if zusatz and m_d:
        beschr = f"{zusatz} {beschr}" if beschr else zusatz          # Gleittag zuerst (Vorschau schneidet hinten ab)
        html = html.replace(m_d.group(0), f'<meta name="description" content="{beschr}">', 1)
    adresse = _oeffentliche_adresse()
    pfad = ("en/" if sprache == "en" else "") + re.sub(r"(^|/)index\.html$", r"\1", rel)
    bild = (adresse if adresse else wurzel) + f"daten/og-{sprache}.jpg"
    tags = [f'<meta property="og:type" content="website">', f'<meta property="og:site_name" content="{MARKE}">',
            f'<meta property="og:title" content="{titel}">',
            f'<meta property="og:locale" content="{"en_GB" if sprache == "en" else "de_DE"}">',
            f'<meta property="og:image" content="{bild}">', '<meta property="og:image:width" content="1200">',
            '<meta property="og:image:height" content="630">', '<meta name="twitter:card" content="summary_large_image">',
            f'<link rel="icon" href="{wurzel}daten/icon.svg" type="image/svg+xml">',
            f'<link rel="apple-touch-icon" href="{wurzel}daten/icon-180.png">',
            f'<link rel="manifest" href="{wurzel}daten/manifest-{sprache}.json">',
            '<meta name="apple-mobile-web-app-title" content="Windfenster">']
    if 'name="theme-color"' not in html:
        tags.append('<meta name="theme-color" content="#0b2540">')
    if beschr:
        tags.insert(3, f'<meta property="og:description" content="{beschr}">')
    if adresse:
        tags.insert(0, f'<meta property="og:url" content="{adresse}{pfad}">')
        # 08.11.2026 (eigene Domain): kanonische Adresse – die 12-/18-kn-Varianten verweisen auf die Standardseite –
        # und die Sprachfassungen mit vollen Adressen (hreflang)
        std = re.sub(r"^\d+/", "", re.sub(r"(^|/)index\.html$", r"\1", rel))
        tags.insert(0, f'<link rel="canonical" href="{adresse}{"en/" if sprache == "en" else ""}{std}">')
        tags += [f'<link rel="alternate" hreflang="de" href="{adresse}{std}">',
                 f'<link rel="alternate" hreflang="en" href="{adresse}en/{std}">',
                 f'<link rel="alternate" hreflang="x-default" href="{adresse}{std}">']
    return html.replace(m_t.group(0), m_t.group(0) + "".join(tags), 1)


def seite_fertig(html: str, rel: str, sprache: str = "de") -> str:
    """Platzhalter einer öffentlichen Seite auflösen. rel = Pfad der deutschen Seite ab der Wurzel (z. B. „12/x.html“).
    Deutsch liegt unter rel, Englisch unter en/rel; der Umschalter DE | EN springt zur gleichen Seite in der anderen
    Sprache (bewusst ohne Fahnen: Fahnen stehen für Länder, nicht für Sprachen).
    Ohne gespeicherte Wahl schickt die deutsche Seite Browser ohne Deutsch in den Spracheinstellungen nach /en/."""
    tiefe = rel.count("/") + (1 if sprache == "en" else 0)
    wurzel = "../" * tiefe
    if sprache == "en":
        ziel, titel, merk = wurzel + rel, "Deutsche Version", "de"
    else:
        ziel, titel, merk = wurzel + "en/" + rel, "English version", "en"
    ziel = re.sub(r"(^|/)index\.html$", r"\1", ziel) or "./"
    andere = (f'<a href="{ziel}" hreflang="{merk}" lang="{merk}" title="{titel}" '
              f'onclick="try{{localStorage.setItem(\'sprache\',\'{merk}\')}}catch(e){{}}">{merk.upper()}</a>')
    aktuell = f'<span aria-current="true">{sprache.upper()}</span>'
    teile = (aktuell, andere) if sprache == "de" else (andere, aktuell)   # immer DE links, EN rechts
    knopf = f'<span class="sprache" role="group" aria-label="Sprache / Language">{teile[0]}{teile[1]}</span>'
    html = html.replace("§SPRACHE§", knopf).replace(WURZEL, wurzel).replace("§V§", DATEN_VERSION)
    html = _vorschau_meta(html, rel, sprache, wurzel)
    if DATEN_ORDNER is not None and CSS in html:          # gemeinsames Stylesheet statt ~38 kB in jeder Seite
        html = html.replace("<style>" + CSS, f'<link rel="stylesheet" href="{wurzel}daten/stil.css?v={DATEN_VERSION}">'
                            '<style>', 1).replace("<style></style>", "")
    if sprache == "de":
        auto = ('<script>try{if(!localStorage.getItem("sprache")){var l=(navigator.languages&&navigator.languages.length?'
                'navigator.languages:[navigator.language||""]).join(",").toLowerCase();'
                f'if(l&&!/(^|,)de/.test(l)&&!/bot|crawl|spider|slurp|preview|lighthouse/i.test(navigator.userAgent))'
                f'location.replace("{ziel}"+location.hash)}}}}catch(e){{}}</script>')
        html = html.replace("<head>", "<head>" + auto, 1)
    return html


