# SUCHE (01.11.2026): Spots, Reviere und Orte (GeoNames) – läuft im Browser, keine Anfrage an fremde Dienste
# =============================================================================

ORTE_DATEI = Path(__file__).resolve().parent / "orte_cache.json"
ORTE_QUELLE = "https://download.geonames.org/export/dump/cities1000.zip"   # CC BY 4.0, Orte ab 1000 Einwohnern
ORTE_MAX_TAGE = 30
ORTE_UMKREIS_KM = 45          # Orte nur in der Nähe eines Spots


def spot_datei(sp) -> str:
    return f"spot_{spot_slug(sp.name)}.html"


def spot_slug(name: str) -> str:
    import unicodedata
    t = unicodedata.normalize("NFKD", name.replace("ø", "o").replace("æ", "ae").replace("ß", "ss"))
    return re.sub(r"[^a-z0-9]+", "-", t.encode("ascii", "ignore").decode().lower()).strip("-")


def orte_laden() -> list:
    """Orte in der Nähe der Spots aus GeoNames (einmal im Monat geholt, sonst Cache). [Name, lat, lon, Land, Einw.]"""
    try:
        c = json.loads(ORTE_DATEI.read_text(encoding="utf-8"))
        if (datetime.now() - datetime.fromisoformat(c["stand"])).days < ORTE_MAX_TAGE and \
                c.get("spots") == len(SPOTS):
            return c["orte"]
    except (OSError, ValueError, KeyError):
        c = None
    try:
        import zipfile
        req = urllib.request.Request(ORTE_QUELLE, headers={"User-Agent": "windsurf-spots/1.3"})
        with urllib.request.urlopen(req, timeout=120) as r:
            roh = r.read()
        z = zipfile.ZipFile(io.BytesIO(roh))
        orte = []
        punkte = [(sp.lat, sp.lon) for sp in SPOTS]
        for zeile in z.read("cities1000.txt").decode("utf-8").splitlines():
            f = zeile.split("\t")
            if len(f) < 15:
                continue
            la, lo = float(f[4]), float(f[5])
            if not any(abs(la - a) < 0.5 and abs(lo - b) < 0.8 and _abstand_km(la, lo, a, b) <= ORTE_UMKREIS_KM
                       for a, b in punkte):
                continue
            orte.append([f[1], round(la, 4), round(lo, 4), f[8], int(f[14] or 0)])
        orte.sort(key=lambda o: -o[4])
        ORTE_DATEI.write_text(json.dumps({"stand": datetime.now().isoformat(timespec="minutes"),
                                          "spots": len(SPOTS), "orte": orte}, ensure_ascii=False), encoding="utf-8")
        return orte
    except Exception as ex:                       # Zugabe: ohne Orte sucht man eben nur Spots und Reviere
        print(f"Hinweis: Ortsliste nicht geladen ({ex}) – Suche nur über Spots und Reviere", file=sys.stderr)
        return (c or {}).get("orte") or []


