def _neben_seite(titel: str, jetzt: datetime, quelle: str, startseite: str, inhalt: str, skript: str = "",
                 datei: str = "") -> str:
    """Rahmen für Zusatzseiten: gleiche Kopfleiste und Gestaltung wie die Übersicht."""
    t = titel + " · " + (MARKE if OEFFENTLICH else "Windsurf-Spots")
    return ('<!doctype html><html lang="de"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b2540">'
            f'<title>{e_txt(t)}</title><style>{CSS}{NEBEN_CSS}</style></head><body>'
            + kopfleiste_html("_neben", startseite, titel, jetzt, quelle, "", datei)
            + f'<main>{inhalt}<p class="fuss">{e_txt(quelle)} · Stand {jetzt:%d.%m.%Y %H:%M} · '
              f'<a href="{e_txt(startseite)}">Übersicht</a>{fuss_recht()}</p></main><div id="tip"></div>'
            f'<script>const CHARTS={{}};{JS}{skript}</script></body></html>')


def _modellnamen(liste: str) -> str:
    return ", ".join(MODELL_KURZ.get(m, m) for m in liste.split(",") if m)


def methodik_html(jetzt: datetime, quelle: str, args, startseite: str) -> str:
    """„Wie das Tool rechnet“: aus den Einstellungen des Skripts erzeugt, damit die Seite nie veraltet."""
    p = []
    p.append('<div class="doc"><h2 style="margin-top:20px">Wie das Tool rechnet</h2>'
             '<p class="kurzfassung">Wetter-Apps zeigen meist ein Modell oder mehrere nebeneinander – entscheiden muss man '
             'selbst. Dieses Tool nimmt mehrere Modelle, gewichtet sie dort, wo Messungen zeigen, welches besser trifft, '
             'korrigiert sie am einzelnen Spot und beantwortet dann eine Frage: <b>Gibt es einen Gleittag, wie '
             'wahrscheinlich ist er – und wie oft lag das Tool damit bisher richtig?</b></p>'
             '<div class="toc">' + "".join(f'<a href="#{i}">{n}</a>' for i, n in [
                 ("gleittag", "Gleittag"), ("modelle", "Modelle"), ("spot", "Spotkorrektur"),
                 ("wahrscheinlich", "Wahrscheinlichkeit"), ("treffer", "Trefferquote"), ("stationen", "Messstationen"),
                 ("saison", "Saison"), ("indikator", "Thermik & Föhn"), ("grenzen", "Grenzen"),
                 ("quellen", "Quellen")]) + '</div>')
    # Gleittag
    p.append(f'<h2 id="gleittag">Was ein Gleittag ist</h2><p>Ein Tag zählt, wenn an einem Spot mindestens '
             f'<b>{MIN_STUNDEN} Stunden am Stück</b> ein Mittelwind von <b>{args.min_kn:.0f} kn</b> oder mehr weht – bei '
             f'Tageslicht, aus einer Richtung, die zu dem Spot passt, und höchstens {MAX_KN} kn. Gemeint ist der '
             f'10-Minuten-Mittelwind in 10 m Höhe, so wie Modelle und Messstationen ihn liefern, nicht die Böen. Die große '
             f'Zahl in den Kacheln ist der Mittelwind im besten {SESSION_STUNDEN}-Stunden-Block des Tages.</p>'
             '<p>Jeder Spot hat eine eigene Richtungstabelle (z. B. „WNW–NW: Welle, sehr gut“), dazu eine Stufe von 1 '
             '(einfach) bis 5 (Experten). Die Stufe ist nur eine Information – angezeigt werden alle Spots. Die Reihenfolge '
             'der Spots eines Tages richtet sich allein nach den Bedingungen: Wind und Güte der Richtung.</p>')
    # Modelle
    zeilen = []
    for r in REVIERE:
        if not r["aktiv"]:
            continue
        zeilen.append(f'<tr><td>{e_txt(revier_kurz(r))}</td><td>{e_txt(_modellnamen(r.get("modelle") or STANDARD_MODELLE))}'
                      f'</td></tr>')
    gew = []
    namen_profil = {"kueste": "Ostseeküste mit Landeinfluss (Fehmarn, Hohwachter Bucht, Flensburger Förde …)",
                    "bodensee": "Bodensee", "westkueste": "Westküste"}
    for prof, g in MODELL_GEWICHTE.items():
        gew.append(f'<tr><td>{e_txt(namen_profil.get(prof, prof))}</td><td>' + ", ".join(
            f'{e_txt(MODELL_KURZ.get(m, m))} ×{v:.2f}'.replace(".", ",") for m, v in sorted(g.items(), key=lambda x: -x[1]))
                   + '</td></tr>')
    fak = []
    for rid, g in MODELL_FAKTOR_REVIER.items():
        if g:
            fak.append(f'{e_txt(revier_kurz(revier(rid)))}: ' + ", ".join(
                f'{e_txt(MODELL_KURZ.get(m, m))} ×{v:.2f}'.replace(".", ",") for m, v in g.items()))
    p.append('<h2 id="modelle">Modelle und wie sie gemischt werden</h2>'
             '<p>Für jeden Spot holt das Tool stündlich den Wind aller Modelle seines Reviers über '
             '<a href="https://open-meteo.com/">Open-Meteo</a>, jeweils an der nächsten Gitterzelle auf dem Wasser. Hoch '
             'aufgelöste Modelle (DMI HARMONIE, MET Nordic, KNMI, ICON-D2, ICON-CH, AROME, UKV: 1–2,5 km) reichen nur 2–3 Tage, '
             'danach bleiben die globalen (ICON 13 km, ECMWF 9 km, GFS 13–25 km, UKMO 10 km). Die angezeigte Zahl ist ein '
             '<b>gewichtetes Mittel</b> der vorhandenen Modelle.</p>'
             '<div class="mt-wrap"><table class="mt"><tr><th>Revier</th><th>Modelle</th></tr>' + "".join(zeilen)
             + '</table></div>'
             # Öffentlich nur das Prinzip – die abgestimmten Zahlen (Gewichte, Faktoren) bleiben im Skript
             + ('<h3>Gewichte und Korrekturen</h3><p>Wo Messstationen zeigen, dass einzelne Modelle besser treffen, '
                'zählen sie mehr – meist die hoch aufgelösten Regionalmodelle. Modelle, die in einem Revier systematisch '
                'zu viel oder zu wenig Wind rechnen, werden entsprechend korrigiert, und grobe Modelle zählen mit wachsendem '
                'Vorlauf weniger. Gewichte und Korrekturen stammen aus dem Vergleich mit Messungen über Monate und werden '
                'laufend überprüft.</p>' if OEFFENTLICH else
             '<h3>Gewichte</h3><p>Wo Messstationen zeigen, dass einzelne Modelle besser treffen, zählen sie mehr. Die '
             'Gewichte stammen aus dem Vergleich mit Messungen über mehrere Monate (Fehler je Modell und Station); '
             'überall sonst zählen alle Modelle gleich – über offenem Wasser ist das ungewichtete Mittel am besten.</p>'
             '<div class="mt-wrap"><table class="mt"><tr><th>Gilt für</th><th>Gewicht je Modell</th></tr>' + "".join(gew)
             + '</table></div>')
             + (f'<h3>Korrekturfaktoren je Modell</h3><p>Modelle, die in einem Revier systematisch zu viel Wind rechnen, '
                f'werden gedämpft: {"; ".join(fak)}. ICON wird nach {ICON_FEIN_H} Stunden Vorlauf grober (ICON-EU, '
                f'später global) und zählt dann nur noch {ICON_FERN_FAKTOR:.1f}-fach.</p>'.replace("0.5", "0,5") if fak and not OEFFENTLICH else ''))
    # Spotkorrektur
    kal = sorted(KALIB_SPOTS.items())
    if OEFFENTLICH:
        p.append('<h2 id="spot">Korrektur am Spot</h2>'
                 '<p>Modelle sehen eine Bucht oder eine Landzunge kaum. Deshalb gibt es je nach Spot zusätzliche Schritte:</p><ul>'
                 '<li><b>Kalibrierung an einer Messstation:</b> Wo eine passende Station in der Nähe steht, lernt das Tool aus '
                 'Jahren von Modellarchiv und Messwerten, wie stark das Modellmittel je Windrichtung, Windstärke und Schichtung '
                 '(Luft gegen Wasser) daneben liegt. Verwendet wird nur, was sich an Zeiträumen bewährt, die beim Lernen nicht '
                 'dabei waren.</li>'
                 '<li><b>Wasser statt Land:</b> Steht die Station an Land, liegt der Wind auf dem Wasser messbar höher.</li>'
                 '<li><b>Düsen:</b> Wo Küstenform oder Berge den Wind bekanntermaßen verstärken, wird das berücksichtigt.</li>'
                 '<li><b>Böen-Plausibilität:</b> Sehr hohe Böen bei schwachem Mittelwind ohne Schauer deuten auf zu wenig '
                 'Mittelwind im Modell; dann wird er angehoben.</li></ul>')
    else:
      p.append('<h2 id="spot">Korrektur am Spot</h2>'
             '<p>Modelle sehen eine Bucht oder eine Landzunge kaum. Deshalb gibt es je nach Spot zusätzliche Schritte:</p><ul>'
             '<li><b>Kalibrierung an einer Messstation:</b> Aus Jahren von Modellarchiv und Messwerten lernt das Tool, wie '
             'stark das Modellmittel je Windrichtung, Windstärke und Schichtung (Luft gegen Wasser) daneben liegt. Gelernt '
             'werden nur relative Faktoren, jeder wird bei wenigen Daten zur 1 hin gezogen und an Wochen geprüft, die beim '
             'Lernen nicht dabei waren. Nur was dort besser wird, wird verwendet. Zugeordnet: '
             + ", ".join(f'{e_txt(s)} → {e_txt(st)}' for s, st in kal) + '.</li>'
             + '<li><b>Wasser statt Land:</b> An Spots, deren Station an Land steht, liegt der Wind auf dem Wasser messbar '
             + f'höher – dort ×{WASSER_NIVEAU:.2f}'.replace(".", ",") + '.</li>'
             + '<li><b>Düse:</b> Ostwind in der Eckernförder Bucht ist meist stärker als vorhergesagt '
             + f'(×{OST_DUESE_FAKTOR:.2f})'.replace(".", ",") + '.</li>'
             '<li><b>Böen-Plausibilität:</b> Böen von mehr als dem Doppelten des Mittelwinds ohne Schauer deuten auf zu '
             'wenig Mittelwind im Modell; dann wird er auf etwa 70 % der Böen angehoben.</li>'
             + ('<li><b>Eigene Sessions:</b> Ein Logbuch (GPS-Uhr, Segel, Urteil) zeigt, wo die Vorhersage für mich '
                'systematisch daneben lag; daraus entstehen einzelne Spotfaktoren.</li>' if not OEFFENTLICH else '')
             + '</ul>')
    # Wahrscheinlichkeit
    p.append('<h2 id="wahrscheinlich">Wahrscheinlichkeit</h2>'
             '<p>Neben der Windzahl steht, wie sicher der Gleittag ist. Wo Ensembles verfügbar sind (ICON-EPS, ECMWF-ENS, '
             'GFS-ENS – zusammen rund 120 leicht verschiedene Rechnungen, jedes Modell gleich gewichtet), ist es der '
             '<b>Anteil der Ensemble-Member</b>, die im besten Block die Schwelle schaffen; sonst der Anteil der Modelle. '
             'Angezeigt werden höchstens 95 % und mindestens 5 % – Gewissheit gibt es in der Vorhersage nicht. Worte: ab 80 % '
             '„sehr wahrscheinlich“, ab 60 % „wahrscheinlich“, ab 40 % „unsicher“, ab 20 % „eher nicht“.</p>'
             + '<p>Wo die Messstationen eines Reviers genug Stunden liefern, zählt nicht mehr jedes Modell gleich: Für jedes Modell und jeden Vorlauf ist gemessen, wie viel Wind wirklich kommt, wenn es eine bestimmte Stärke ansagt, und wie stark es dabei streut. Daraus gibt jedes Modell eine eigene Wahrscheinlichkeit; genaue Modelle zählen mehr, ungenaue weniger. Die eng verwandten Modelle MET Nordic, DMI und KNMI zählen zusammen nicht dreifach. Das Ensemble wird beigemischt – am ersten Tag wenig, ab Tag 4 überwiegend, weil die fein aufgelösten Modelle nur etwa 2,5 Tage vorausrechnen.</p>'
             f'<h3>Eichung</h3><p>Ensembles sind oft zu selbstsicher. Deshalb merkt sich das Tool jede angezeigte '
             f'Wahrscheinlichkeit und vergleicht sie später mit den Messstationen des Reviers. '
             + ('Sobald genug Revier-Tage vorliegen, wird die angezeigte Zahl behutsam zur gemessenen Häufigkeit hingezogen. '
                if OEFFENTLICH else
                f'Sobald {EICH_MIN_TAGE} Revier-Tage vorliegen, wird die Zahl je 20-%-Klasse zur gemessenen Häufigkeit '
                f'hingezogen (mit {EICH_K} Tagen Vorwissen, damit wenige Fälle nichts umwerfen). ')
             + 'Geeichte Werte tragen ein ✓.</p>')
    # Trefferquote
    tz = []
    for r in REVIERE:
        z = ((TREFFER.get("reviere") or {}).get(r["id"]) or {}).get("treffer") or {}
        if not z:
            continue
        zellen = []
        for _, _, b in VORLAUF_BAENDER:
            x = z.get(b)
            if not x or not x["angesagt"]:
                zellen.append('<td>–</td>')
                continue
            gr = f' · Grundrate {x["gemessen"] / x["tage"] * 100:.0f} %' if x["tage"] else ''
            zellen.append(f'<td><b>{x["eingetroffen"] / x["angesagt"] * 100:.0f} %</b> '
                          f'<span style="color:var(--text-muted)">({x["eingetroffen"]}/{x["angesagt"]}{gr})</span></td>')
        tz.append(f'<tr><td>{e_txt(revier_kurz(r))}</td>{"".join(zellen)}</tr>')
    p.append('<h2 id="treffer">Trefferquote</h2>'
             f'<p>Jeden Lauf speichert das Tool seine Vorhersage für die Messstationen. Danach zählt es: Wie oft kam ein '
             f'angesagter Gleittag an der Station auch an (<b>Trefferquote</b>)? Und wie viele gemessene Gleittage waren '
             f'vorher angesagt (Erkennung)? Zum Vergleich die <b>Grundrate</b> – so oft war überhaupt Gleitwind; so hoch '
             f'wäre die Trefferquote mit Raten. Fenster: die letzten {TREFFER_FENSTER_TAGE} Tage.</p>'
             + ('<div class="mt-wrap"><table class="mt"><tr><th>Revier</th>'
                + "".join(f'<th>{b}</th>' for _, _, b in VORLAUF_BAENDER) + '</tr>' + "".join(tz) + '</table></div>'
                if tz else '<p><i>Noch keine ausgewerteten Tage.</i></p>')
             + '<p>Gezählt wird an den Stationen, nicht am Spot – die Station steht oft an Land oder an einer anderen '
               'Küste. Die Zahlen sagen also, wie gut die Wetterlage getroffen wird, nicht jede Bucht.</p>')
    # Stationen
    st_z = []
    for name, la, lo, q, rid in stationen_liste():
        art = ("DWD (über Bright Sky)" if q == "dwd" else "DMI" if q.startswith("dmi:") else
               "MeteoSwiss" if q.startswith("msw:") else "NOAA GHCNh" if q.startswith("ghcnh:") else
               "KNMI" if q.startswith("knmi:") else "GeoSphere Austria" if q.startswith("geosphere:") else
               "Meteotrentino" if q.startswith("trentino:") else q)
        st_z.append(f'<tr><td>{e_txt(revier_kurz(revier(rid)))}</td><td>{e_txt(name)}</td><td>{art}</td></tr>')
    p.append('<h2 id="stationen">Messstationen</h2><p>Für Trefferquote, Eichung, Kalibrierung und die „Jetzt“-Werte. '
             'Reviere ohne Station (Leucate, El Médano) laufen ohne Abgleich – dort sind die Zahlen roh.</p>'
             '<div class="mt-wrap"><table class="mt"><tr><th>Revier</th><th>Station</th><th>Quelle</th></tr>'
             + "".join(st_z) + '</table></div>')
    # Saison
    p.append('<h2 id="saison">Saison</h2><p>Die Monatswerte zählen Gleittage im Modellarchiv der letzten etwa zwei Jahre '
             '(ICON, ECMWF, GFS) – mit denselben Gewichten und Spotkorrekturen wie die Tagesvorhersage. Wo Messstationen '
             'lange genug vorliegen, ist die Zahl je Monat an sie angepasst. Zwei Jahre sind wenig: Ein windiger Oktober '
             'mehr oder weniger verschiebt den Wert spürbar. In Thermik-Revieren (Gardasee, Walensee, Achensee) sehen die '
             'Modelle den Wind kaum – dort gibt es keine Modell-Saison. <a href="' + SAISON_DATEI + '">Saison je Monat →</a></p>')
    # Indikator
    p.append('<h2 id="indikator">Thermik & Föhn</h2><p>Wo Modelle den Wind am Spot nicht auflösen, hilft ein Blick auf '
             'die Wetterlage: <b>Föhn</b> aus der Druckdifferenz Alpensüd- gegen Alpennordseite (Lugano–Zürich, '
             'Bozen–Innsbruck; Faustregel ab etwa 4 hPa möglich, ab etwa 8 hPa kräftig), <b>Thermik</b> aus sonnigem '
             'Vormittag, schwachem Höhenwind, Saison und ohne Regen oder Föhn, <b>Bise</b> aus der Druckdifferenz '
             'Zürich gegen Genf (Hochdruck im Norden, kalter Nordost zwischen Jura und Alpen), umgekehrt <b>Südwest</b> '
             '(Genf höher als Zürich, „Vent“ am Genfersee). An der Küste zusätzlich ein '
             '<b>Seewind-Index</b> aus Land-gegen-Wasser-Temperatur und Grundwind. Das sind Hinweise auf die Lage, keine '
             'Windvorhersage in Knoten.</p>'
             + ('<p>Seewind und Thermik sind rückwirkend an Messungen geprüft: dieselbe Regel, gefüttert mit den damaligen '
                'Modellvorhersagen, gegen die gemessenen Nachmittage an Uferstationen (Kiel-Holtenau, Schönhagen, Fehmarn, '
                'St. Peter-Ording; Quinten am Walensee, Achenkirch am Achensee). Wo das klar besser passte, gelten die '
                'geprüften Schwellen; dazu steht, wie oft der Wind an solchen Tagen wirklich kam. Gardasee: keine frei '
                'verfügbare Messhistorie, dort bleibt die Faustregel.</p>' if THERMIK_PRUEFUNG else
                '<p>Seewind und Thermik sind Faustregeln, noch nicht an Messungen geprüft.</p>')
             + ('<p>Der Föhn-Index für Bodensee und Walensee ist inzwischen an MeteoSwiss-Messungen geprüft: Für jede '
                'Druckklasse steht dabei, an wie vielen Tagen es an den Stationen wirklich mit mindestens 15 kn wehte.</p>'
                if (FOEHN_EICHUNG or {}).get("reviere") else ''))
    # Grenzen
    p.append('<h2 id="grenzen">Grenzen – ehrlich</h2><ul>'
             '<li>Ab Tag 4 rechnet das Modellmittel an der Ostsee im Mittel rund 3 kn zu viel; die Trefferquote zeigt das.</li>'
             '<li>Thermik, Düsen zwischen Bergen und Abschattung durch Land sehen die Modelle schlecht. Einige Spots sind '
             'deshalb ausdrücklich als Untergrenze markiert.</li>'
             '<li>Böen und Löcher bestimmen oft, ob man gleitet – die Zahl ist der Mittelwind.</li>'
             '<li>Wasserstand, Strömung, Welle und Wassertemperatur können vor Ort ganz anders sein.</li>'
             '<li>Die Wahrscheinlichkeit wird erst nach einigen Wochen Messvergleich geeicht; vorher ist sie roh.</li></ul>')
    # Quellen
    p.append('<h2 id="quellen">Daten und Lizenzen</h2><ul>'
             '<li>Wettermodelle, Ensembles, Wellen, Wassertemperatur: <a href="https://open-meteo.com/">Open-Meteo</a> '
             '(CC BY 4.0) mit Daten von DWD, DMI, KNMI, MET Norway, MeteoSwiss, Météo-France, ECMWF, NOAA, UK Met Office</li>'
             '<li>Messwerte: Deutscher Wetterdienst (über <a href="https://brightsky.dev/">Bright Sky</a>), '
             '<a href="https://opendatadocs.dmi.govcloud.dk/">DMI Open Data</a> (CC BY 4.0), MeteoSwiss Open Data, '
             '<a href="https://www.ncei.noaa.gov/products/global-historical-climatology-network-hourly">NOAA GHCNh</a></li>'
             '<li>Pegel: PEGELONLINE (WSV), Wasserstandsvorhersage BSH</li>'
             '<li>Karten: MET Nordic, DMI HARMONIE, Küstenlinie © OpenStreetMap-Mitwirkende (ODbL), Leaflet</li>'
             + '</ul></div>')
    return _neben_seite("Wie das Tool rechnet", jetzt, quelle, startseite, "".join(p), datei=METHODIK_DATEI)


def saison_seite_html(jetzt: datetime, quelle: str, startseite: str) -> str:
    """Saison je Monat: Reviere nach Ø Gleittagen, darunter je Revier die Spots."""
    k = KLIMA_DATEN or {}
    sl = _klima_schluessel()
    m0 = jetzt.month - 1
    tabs = "".join(f'<button type="button" data-m="{i}"{" class=an" if i == m0 else ""}>{m}</button>'
                   for i, m in enumerate(MONATE))
    panels = []
    for i, mname in enumerate(MONATE):
        rang, bloecke = [], []
        for gruppe, rev_liste in reviere_gruppiert():
            for r in rev_liste:
                rz = ((k.get("reviere") or {}).get(r["id"]) or {}).get(sl)
                v = _je_monat(rz)[i] if rz else None
                spots = []
                for name, sz in (k.get("spots") or {}).items():
                    if sz.get("revier") != r["id"] or not sz.get(sl):
                        continue
                    w = _je_monat(sz[sl])[i]
                    if w is not None:
                        spots.append((w, name))
                spots.sort(reverse=True)
                if r.get("thermik"):
                    bloecke.append(f'<div class="sm-rev" id="r-{r["id"]}-{i}"><div class="sm-kopf"><a href="{e_txt(r["datei"])}">'
                                   f'{e_txt(r["name"])}</a><span>Thermik-Revier</span></div><div class="sm-hinweis">'
                                   f'Die Modelle sehen den thermischen Wind kaum – keine Modell-Saison. Mehr auf der '
                                   f'Revierseite.</div></div>')
                    continue
                if v is None and not spots:
                    bloecke.append(f'<div class="sm-rev" id="r-{r["id"]}-{i}"><div class="sm-kopf"><a href="{e_txt(r["datei"])}">'
                                   f'{e_txt(r["name"])}</a><span>noch keine Saison-Daten</span></div></div>')
                    continue
                if v is not None:
                    bg, fg = blau_fuer(10 + v / 12 * 18) if v >= 0.5 else ("var(--surface-2)", "var(--text-muted)")
                    rang.append((v, f'<a href="#r-{r["id"]}-{i}"><span class="rz" style="background:{bg};color:{fg}">'
                                    f'{v:.0f}</span><span><span class="rn2">{e_txt(revier_kurz(r))}</span><br>'
                                    f'<span class="rl">{e_txt(gruppe)}</span></span></a>'))
                zeilen = []
                for w, name in spots:
                    bg, _ = blau_fuer(10 + w / 12 * 18)
                    sp = next((x for x in SPOTS if x.name == name), None)
                    st = f' <span class="st">Stufe {sp.stufe}</span>' if sp and sp.stufe >= 3 and not OEFFENTLICH else ""
                    zeilen.append(f'<div class="sm-spot"><span>{e_txt(name)}{st}</span><span class="bl">'
                                  f'<i style="width:{min(100, w / 20 * 100):.0f}%;background:{bg}"></i></span>'
                                  f'<span class="z">{w:.0f}</span></div>')
                hinweis = r.get("klima_hinweis")
                bloecke.append(f'<div class="sm-rev" id="r-{r["id"]}-{i}"><div class="sm-kopf"><a href="{e_txt(r["datei"])}">'
                               f'{e_txt(r["name"])} →</a><span>{"Ø " + format(v, ".0f") + " Gleittage" if v is not None else ""}'
                               f' (mind. ein Spot)</span></div>{"".join(zeilen)}'
                               + (f'<div class="sm-hinweis">{e_txt(hinweis)}</div>' if hinweis else '') + '</div>')
        rang.sort(key=lambda x: -x[0])
        panels.append(f'<section class="m-panel" data-m="{i}"{"" if i == m0 else " hidden"}>'
                      f'<h2>{mname}: wo am meisten geht</h2><div class="rang">{"".join(h for _, h in rang)}</div>'
                      f'<h2>Spots im {mname}</h2>{"".join(bloecke)}</section>')
    erkl = "Ø Tage mit Gleitwind je Monat, aus etwa zwei Jahren Modellarchiv – eine Näherung."
    inhalt = (f'<h2 style="margin-top:20px">Saison je Monat{info_knopf(erkl)}</h2>'
              f'<div class="m-tabs">{tabs}</div>{"".join(panels)}'
              f'<p class="sm-hinweis">Wie die Zahlen entstehen: <a href="{METHODIK_DATEI}#saison">Wie das Tool rechnet</a></p>')
    skript = ("(function(){var tabs=document.querySelectorAll('.m-tabs button'),pan=document.querySelectorAll('.m-panel');"
              "function zeige(m,ziel){tabs.forEach(function(b){b.classList.toggle('an',b.dataset.m==m);});"
              "pan.forEach(function(p){p.hidden=p.dataset.m!=m;});"
              "if(ziel){var el=document.getElementById(ziel+'-'+m);if(el)el.scrollIntoView();}}"
              "tabs.forEach(function(b){b.addEventListener('click',function(){zeige(b.dataset.m);"
              "history.replaceState(null,'','#m'+b.dataset.m);});});"
              "var h=location.hash.slice(1),mm=/^m(\\d+)$/.exec(h);"
              "if(mm)zeige(mm[1]);else if(h.indexOf('r-')==0)zeige(" + str(m0) + ",h);})();")
    return _neben_seite("Saison", jetzt, quelle, startseite, inhalt, skript, datei=SAISON_DATEI)


# „Meine Spots“: Favoriten nur im Browser (localStorage „wf_favoriten“ = Liste von Spot-Kürzeln), ohne Konto.
# Die Startseite trägt je Spot eine Kurzvorschau der 7 Tage mit; angezeigt werden nur die gemerkten Spots.
FAV_SCHLUESSEL = "wf_favoriten"
# 16.11.2026: ohne gemerkte Spots je Großraum ein, zwei bekannte Spots (nicht alle 11 Hauptspots – sonst zu lang)
BELIEBTE_SPOTS = ["Heidkate", "Westerbergen/Lemkenhafen", "Hvide Sande Fjord (DK)", "Torbole", "Hard/Rohrspitz (AT)",
                  "Valdevaqueros"]


def favoriten_daten(ergebnisse, daten_je_spot: Optional[Dict[str, "OrtDaten"]] = None,
                    jetzt: Optional[datetime] = None) -> dict:
    """{slug: [Name, Spotdatei, Tage, Kurzsatz, Chips, Stunden]} – Tage [[kn|None, p%|None, Art, bg, fg], …] mit Art
    1 = Gleitwind, 2 = Chance, 0 = nichts. 23.11.2026 (Anforderungen 2.1): Kurzsatz, Chips (Hinweise heute/morgen)
    und Stundenstreifen [[ISO-Zeit, kn, Richtung, bg, fg, Anker], …] – tagsüber ab jetzt, 10 Stunden (der Browser
    lässt vergangene weg und zeigt 8)."""
    aus: Dict[str, list] = {}
    for sp in SPOTS:
        if not revier(revier_von(sp)).get("aktiv", True):
            continue
        tage = []
        for _t, liste, chancen in ergebnisse:
            e = next((x for x in liste if x.spot.name == sp.name), None)
            if e is not None:
                w_ = gleit_wahrsch(e)
                bg, fg = blau_fuer(e.wind)
                tage.append([round(e.wind), None if not w_ else round(w_["p"] * 100), 1, bg, fg])
                continue
            c = next((x for x in chancen if x.spot.name == sp.name), None)
            tage.append([round(c.wind), None, 2, "", ""] if c is not None else [None, None, 0, "", ""])
        satz, chips, stunden = "", [], []
        d = (daten_je_spot or {}).get(sp.name)
        if d is not None and jetzt is not None:
            saetze = spot_kurzsatz(sp, d, ergebnisse, jetzt, MIN_KN if gw_aktiv() is None else gw_aktiv())
            satz = saetze[0] if saetze else ""
            arten = set()           # je Art nur ein Chip (Hochwasser heute und morgen sonst zweimal mit anderer Zahl)
            for tag, liste, chancen in ergebnisse[:2]:
                e, _ch = _spot_eintrag(sp, liste, chancen)
                if e is not None:
                    _a, labels, _k = warnungen_teilen(e.warnungen)
                    for l_ in labels:
                        art = re.sub(r"[+−-]?\d+([.,]\d+)?\s*(cm|kn|m|s)?", "", l_).strip()
                        if art not in arten:
                            arten.add(art)
                            chips.append(l_)
            t0 = jetzt.replace(minute=0, second=0, microsecond=0)
            for x in d.stunden:
                if x.t < t0:
                    continue
                sr, ss = sonnenzeiten(d, x.t.date())
                if not (sr - timedelta(hours=1) <= x.t <= ss + timedelta(hours=1)):
                    continue
                w, _g = _spot_kn(sp, d, x, jetzt)
                mk = gw_aktiv() or MIN_KN
                bg, fg = blau_fuer(w) if (w >= mk and _passt(sp, x)) else ("", "")
                stunden.append([x.t.strftime("%Y-%m-%dT%H"), round(w), kompass(x.wd), bg, fg, _h_id(x.t),
                                1 if (w >= mk and not bg) else 0])
                if len(stunden) >= 10:
                    break
        aus[spot_slug(sp.name)] = [sp.name, spot_datei(sp), tage, satz, chips[:3], stunden]
    return aus


def favoriten_block_html(ergebnisse, daten_je_spot=None, jetzt=None) -> str:
    """Startseite (23.11.2026, Anforderungen 2.1): gemerkte Spots als Karten – Kurzsatz, Hinweis-Chips, Streifen der
    nächsten Stunden, 7 Tage. „Bearbeiten“: Reihenfolge und Entfernen. Ohne gemerkte Spots: Beliebte Spots, kompakt
    (nur 7 Tage), damit die Übersicht der Reviere nicht weit nach unten rutscht."""
    tage = [t.isoformat() for t, _, _ in ergebnisse]
    daten = {"t": tage, "s": favoriten_daten(ergebnisse, daten_je_spot, jetzt), "tend": TENDENZ_AB,
             "def": [spot_slug(n) for n in BELIEBTE_SPOTS],
             "pf": {k: pfeil_svg(k, 10) for k in KOMPASS}}
    skript = r"""
(function(){var D=§D§,K="§K§",box=document.getElementById("meine"),en=document.documentElement.lang==="en";
 function lies(){try{return JSON.parse(localStorage.getItem(K)||"[]").filter(function(x){return D.s[x];});}catch(e){return [];}}
 function schreib(l){try{localStorage.setItem(K,JSON.stringify(l));}catch(e){}}
 function esc(t){return String(t).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});}
 var heute=new Date();heute.setHours(0,0,0,0);var jetztH=new Date();jetztH.setMinutes(0,0,0);
 function tage(s){var h='<div class="fav-t">';s[2].forEach(function(c,i){var d=new Date(D.t[i]+"T12:00:00"),
  wt=d.toLocaleDateString(en?"en-GB":"de-DE",{weekday:"short"}).replace(".",""),
  tend=Math.round((new Date(D.t[i]+"T00:00:00")-heute)/864e5)>=D.tend,ziel=s[1]+"#tag-"+D.t[i].replace(/-/g,"");
  if(c[2]===1)h+='<a class="fz'+(tend?" tend":"")+'" href="'+ziel+'" style="background:'+c[3]+';color:'+c[4]+'"><span>'+wt+
   '</span><b>'+(tend?"≈":"")+c[0]+'</b><small>'+(c[1]==null?"":c[1]+"%")+'</small></a>';
  else if(c[2]===2)h+='<a class="fz ch" href="'+ziel+'"><span>'+wt+'</span><b>↑'+c[0]+'</b><small></small></a>';
  else h+='<a class="fz leer" href="'+ziel+'"><span>'+wt+'</span><b>·</b><small></small></a>';});return h+'</div>';}
 function stunden(s){var st=s[5].filter(function(x){return new Date(x[0]+":00:00")>=jetztH;}).slice(0,8);if(!st.length)return "";
  var h='<div class="fav-h">',vor=null;st.forEach(function(x,i){var t=new Date(x[0]+":00:00"),hh=x[0].slice(11,13),
   lab=(+t===+jetztH)?(en?"now":"jetzt"):hh;var tag=x[0].slice(0,10);
   if(vor!==null&&tag!==vor)lab='<i>'+t.toLocaleDateString(en?"en-GB":"de-DE",{weekday:"short"}).replace(".","")+'</i>'+hh;
   else if(i===0&&t.getDate()!==new Date().getDate())lab='<i>'+t.toLocaleDateString(en?"en-GB":"de-DE",{weekday:"short"}).replace(".","")+'</i>'+hh;
   vor=tag;h+='<a class="fh'+(x[3]?" gl":"")+'" href="'+s[1]+'#'+x[5]+'"><span>'+lab+'</span><b'+(x[3]?' style="background:'+x[3]+';color:'+x[4]+'"':(x[6]?' class="fr"':''))+'>'+x[1]+
   '</b><small>'+(D.pf[x[2]]||"")+'</small></a>';});return h+'</div>';}
 function karten(l,beliebt){var h="";l.forEach(function(x){var s=D.s[x];
  h+='<div class="fav-k" data-href="'+s[1]+'"><div class="fav-kk"><a class="fav-n" href="'+s[1]+'">'+esc(s[0])+'</a>'+
   '<span class="fav-p">›</span></div>'+(beliebt?'':(s[3]?'<p class="fav-s">'+esc(s[3])+'</p>':'')+
   (s[4].length?'<div class="fav-c">'+s[4].map(function(c){return '<span class="chip warn">'+esc(c)+'</span>';}).join("")+'</div>':'')+
   stunden(s))+tage(s)+'</div>';});return h;}
 function liste(){var l=lies(),beliebt=!l.length;if(beliebt)l=D.def.filter(function(x){return D.s[x];});
  box.querySelector(".fav-h1").hidden=beliebt;box.querySelector(".fav-h2").hidden=!beliebt;
  box.querySelector(".fav-tipp").hidden=!beliebt;box.querySelector(".fav-bearb").hidden=beliebt;
  box.querySelector(".fav-liste").innerHTML=karten(l,beliebt);box.classList.remove("bearb");}
 function bearbeiten(){var l=lies(),h="";l.forEach(function(x,i){h+='<div class="fav-e" data-s="'+x+'"><span>'+esc(D.s[x][0])+'</span>'+
   '<button type="button" data-a="hoch"'+(i===0?" disabled":"")+' aria-label="'+(en?"up":"nach oben")+'">↑</button>'+
   '<button type="button" data-a="runter"'+(i===l.length-1?" disabled":"")+' aria-label="'+(en?"down":"nach unten")+'">↓</button>'+
   '<button type="button" data-a="weg" aria-label="'+(en?"remove":"entfernen")+'">×</button></div>';});
  box.querySelector(".fav-liste").innerHTML=h||'<p class="fav-tipp">'+(en?"No spots saved.":"Keine Spots gemerkt.")+'</p>';box.classList.add("bearb");}
 box.addEventListener("click",function(e){var b=e.target.closest("button");
  if(b&&b.classList.contains("fav-bearb")){if(box.classList.contains("bearb"))liste();else bearbeiten();return;}
  if(b&&b.dataset.a){var s=b.parentNode.dataset.s,l=lies(),i=l.indexOf(s);if(i<0)return;
   if(b.dataset.a==="weg")l.splice(i,1);else{var j=b.dataset.a==="hoch"?i-1:i+1;if(j<0||j>=l.length)return;l.splice(i,1);l.splice(j,0,s);}
   schreib(l);bearbeiten();return;}
  if(b&&b.classList.contains("fav-neu")){var f=document.getElementById("such-feld");if(f){f.scrollIntoView({block:"center"});f.focus();}return;}
  var k=e.target.closest(".fav-k");if(k&&!e.target.closest("a"))location.href=k.dataset.href;});
 liste();})();"""
    skript = (skript.replace("§D§", json.dumps(daten, ensure_ascii=False, separators=(",", ":")))
              .replace("§K§", FAV_SCHLUESSEL))
    return ('<section class="fav" id="meine"><h2 class="h-um"><span><span class="fav-h1">Meine Spots</span>'
            '<span class="fav-h2" hidden>Beliebte Spots</span></span><span class="fav-knoepfe">'
            '<button type="button" class="fav-neu">＋ Spot</button>'
            '<button type="button" class="fav-bearb" hidden><span class="fb-a">Bearbeiten</span>'
            '<span class="fb-b">Fertig</span></button></span></h2><div class="fav-liste"></div>'
            '<p class="fav-tipp" hidden>☆ Auf einer Spotseite „Merken“ antippen, dann steht der Spot hier.</p>'
            f'</section><script>{skript}</script>')


