def tabbar_html(erster: str = "Spots", mit_karte: bool = True) -> str:
    if not OEFFENTLICH:
        return ""
    reiter = [("spots", erster)] + ([("karte", "Karte")] if mit_karte else []) + [("reviere", "Reviere")]
    return ('<nav class="tabbar" aria-label="Ansicht">'
            + "".join(f'<a href="{"#" + k if k != "spots" else "#"}" data-tab="{k}"'
                      f'{" aria-current=page" if k == "spots" else ""}>{_TAB_ICON[k]}<span>{e_txt(n)}</span></a>'
                      for k, n in reiter)
            + f'</nav><script>{TAB_JS}</script>')


def reviere_tab_html(aktiv: Optional[str] = None) -> str:
    """Reiter „Reviere“: alle Reviere mit ihren Spots, direkt zur Vorhersage."""
    if not OEFFENTLICH:
        return ""
    teile = ['<section id="reviere-tab" class="rt"><h2>Reviere und Spots</h2>']
    for gruppe, rev_liste in reviere_gruppiert():
        teile.append(f'<h3>{e_txt(gruppe)}</h3>')
        for r in rev_liste:
            sps = sorted((sp for sp in SPOTS if revier_von(sp) == r["id"]), key=lambda x: x.name.lower())
            if not sps:
                continue
            teile.append(f'<div class="rt-r{" an" if r["id"] == aktiv else ""}"><a class="rt-n" href="{e_txt(r["datei"])}">'
                         f'{e_txt(revier_kurz(r))} <span>›</span></a><div class="rt-s">'
                         + "".join(f'<a href="{e_txt(spot_datei(sp))}">{e_txt(sp.name)}</a>' for sp in sps)
                         + '</div></div>')
    teile.append('</section>')
    return "".join(teile)


TAB_JS = r"""
(function(){const leiste=document.querySelector('.tabbar');if(!leiste)return;
 const mq=matchMedia('(max-width:899px)'),html=document.documentElement;
 function raender(box){const o=box.querySelector('.mk-leiste'),u=box.querySelector('.wp-unten');
  box._padOben=o?o.offsetTop+o.offsetHeight+6:0;box._padUnten=u?u.offsetHeight+16:0;
  box.style.setProperty('--unten-h',box._padUnten+'px');}
 function setze(t,still){if(!mq.matches)t='spots';const vorher=html.dataset.tab||'spots';html.dataset.tab=t;
  leiste.querySelectorAll('a[data-tab]').forEach(a=>{if(a.dataset.tab===t)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  const box=document.getElementById('wp');
  if(box){if(t==='karte'){box._vollbildWunsch=true;requestAnimationFrame(()=>{raender(box);if(box._vollbild)box._vollbild(true);});}
   else{box._vollbildWunsch=false;if(box._vollbild&&box.classList.contains('wp-voll'))box._vollbild(false);}}
  if(!still&&t!==vorher)window.scrollTo(0,0);}
 function ausHash(){const h=location.hash.slice(1);setze(h==='karte'||h==='wp'?'karte':h==='reviere'?'reviere':
  (h===''||h==='spots'||document.getElementById(h)?'spots':html.dataset.tab||'spots'),true);}
 leiste.addEventListener('click',e=>{const a=e.target.closest('a[data-tab]');if(!a)return;e.preventDefault();const t=a.dataset.tab;
  history.pushState(null,'',t==='spots'?location.pathname+location.search:'#'+t);setze(t);});
 document.addEventListener('click',e=>{const a=e.target.closest('a[href="#spots"]');if(!a)return;e.preventDefault();
  history.pushState(null,'',location.pathname+location.search);setze('spots');},true);
 addEventListener('popstate',ausHash);addEventListener('hashchange',ausHash);
 (mq.addEventListener?mq.addEventListener('change',ausHash):mq.addListener(ausHash));
 addEventListener('resize',()=>{const box=document.getElementById('wp');if(box&&html.dataset.tab==='karte'&&box._vollbild){raender(box);box._vollbild(true);}});
 ausHash();})();
"""


def alle_spots_html() -> str:
    """16.11.2026: Startseite – alle Spots A–Z je Revier, direkt zur Spotvorhersage (neben der Suche oben)."""
    teile = ['<details class="alle-spots" id="spots"><summary><h2>Alle Spots</h2>'
             f'<span class="mr-was">{sum(1 for sp in SPOTS if revier(revier_von(sp)).get("aktiv", True))} Spots '
             'nach Revier</span></summary>']
    for gruppe, rev_liste in reviere_gruppiert():
        for r in rev_liste:
            sps = sorted((sp for sp in SPOTS if revier_von(sp) == r["id"]), key=lambda x: x.name.lower())
            if not sps:
                continue
            teile.append(f'<div class="as-r"><a class="as-rn" href="{e_txt(r["datei"])}">{e_txt(revier_kurz(r))}</a>'
                         + "".join(f'<a href="{e_txt(spot_datei(sp))}">{e_txt(sp.name)}</a>' for sp in sps) + '</div>')
    teile.append('</details>')
    return "".join(teile)


