def beste_tage_html(ergebnisse) -> str:
    """Startseite (08.11.2026, gestrafft): je Großraum eine Zeile – Tag, Wind, Spot. Auswahl nach Stufe der
    Gleitwind-Wahrscheinlichkeit (ab Tag 4 eine Stufe tiefer, weil nur Tendenz), dann Wind, dann Prozent."""
    zeilen = []
    for gruppe, rev_liste in reviere_gruppiert():
        ids = {r["id"] for r in rev_liste}
        kand = []
        for t, liste, _ch in ergebnisse:
            for e in liste:
                if revier_von(e.spot) not in ids:
                    continue
                w_ = gleit_wahrsch(e)
                # 08.11.2026: nach Wahrscheinlichkeits-STUFE, dann Wind – nicht nach der genauen Prozentzahl.
                # Bei 12 kn liegen fast alle windigen Spots bei ~95 %, dann entschied Rauschen (96 gegen 95 %)
                # und der Tipp passte nicht zu dem bei 18 kn. Tendenz-Tage (ab Tag 4) eine Stufe tiefer.
                stufe = (w_["stufe"] if w_ else 2) - (1 if ist_tendenz(t) else 0)
                kand.append(((stufe, round(e.wind), w_["p"] if w_ else 0.5), t, e, w_))
        g_kurz = GRUPPE_KURZ.get(gruppe, gruppe)
        if not kand:
            zeilen.append(f'<div class="bt"><span class="bt-g">{e_txt(g_kurz)}</span>'
                          '<span class="bt-l">kein Gleittag in Sicht</span></div>')
            continue
        _k, t, e, w_ = max(kand, key=lambda x: x[0])
        rv = revier(revier_von(e.spot))
        bg, fg = blau_fuer(e.wind)
        tip = (f'<b>{e_txt(e.spot.name)} · {e_txt(revier_kurz(rv))}</b><br>{e_txt(tag_text(t))}, {e.wind:.0f} kn '
               f'{e_txt(e.richtung)}' + (f'<br>{e_txt(w_["wort"])} · {w_["p"] * 100:.0f} %' if w_ else '')
               + (f"<br><i>{e_txt(TENDENZ_TIP)}</i>" if ist_tendenz(t) else ''))
        zeilen.append(f'<a class="bt{" unsicher" if w_ and w_["p"] < UNSICHER_P else ""}" '
                      f'href="{e_txt(rv["datei"])}#tag-{t:%Y%m%d}" data-tip="{e_txt(tip)}">'
                      f'<span class="bt-g">{e_txt(g_kurz)}</span><span class="bt-d">{e_txt(tag_text(t))}</span>'
                      f'<b class="bt-w" style="background:{bg};color:{fg}">{"≈" if ist_tendenz(t) else ""}{e.wind:.0f}</b>'
                      f'<span class="bt-s">{e_txt(e.spot.name)}</span></a>')
    return ('<section class="beste"><h2>Am besten in den nächsten Tagen'
            + info_knopf("Je Großraum der sicherste Gleittag (ab Tag 4 etwas abgewertet, weil nur Tendenz); unter "
                         "gleich sicheren der mit dem meisten Wind. Antippen führt zum Tag im Revier.")
            + f'</h2><div class="bt-liste">{"".join(zeilen)}</div></section>')


def startseite_html(ergebnisse, jetzt: datetime, quelle: str, args, startseite: str, daten_je_spot=None) -> str:
    """Übersicht: Matrix Reviere × Tage, Reiseplaner, Revierkarten (Klick führt auf die Revierseite)."""
    titel = MARKE_UNTERTITEL if OEFFENTLICH else "Windsurf-Spots"
    hinweis = (f'<a href="{RECHTLICHES_DATEI}">Hinweise & Impressum</a>'
               if OEFFENTLICH else "")
    teile = ['<!doctype html><html lang="de"><head><meta charset="utf-8">',
             '<meta name="viewport" content="width=device-width,initial-scale=1">',
             '<meta name="theme-color" content="#0b2540">',
             (f'<meta name="description" content="{e_txt(MARKE)} – {e_txt(MARKE_UNTERTITEL)}: Wahrscheinlichkeit für '
              'Gleitwind an Spots in Nord- und Ostsee, den Alpen und im Süden, aus mehreren Wettermodellen">'
              if OEFFENTLICH else ''),
             f'<title>{e_txt(f"{MARKE} – {MARKE_UNTERTITEL}" if OEFFENTLICH else titel)}</title>'
             f'<style>{CSS}</style></head><body>',
             kopfleiste_html(None, startseite, titel, jetzt, quelle, hinweis, startseite), '<main>']
    # 16.11.2026 (David: „leichter zur Spotvorhersage, wie bei Windfinder“): erst die Spots, dann die Reviere
    if OEFFENTLICH:
        teile.append(favoriten_block_html(ergebnisse, daten_je_spot, jetzt))
    teile.append(gw_leiste_html(startseite))
    teile.append(beste_tage_html(ergebnisse))
    teile.append('<h2>Nächste Tage je Revier' + info_knopf(
        f"Bester Wind je Revier und Tag in kn; blau ab {args.min_kn:.0f} kn, orange ↑ = nur ein Modell.") + '</h2>')
    teile.append(wochen_matrix_html(ergebnisse, reise_fuer(args.min_kn)))
    if OEFFENTLICH:
        teile.append(alle_spots_html())
    if OEFFENTLICH:                                # Erklär-Themen direkt erreichbar (07.11.2026)
        teile.append('<nav class="themen" aria-label="Erklärungen"><span class="th-t">Wie lese ich das?</span>'
                     + "".join(f'<a href="{METHODIK_DATEI}#{i}">{n}</a>' for i, n in THEMEN_START)
                     + f'<a href="{METHODIK_DATEI}">Alles zur Methode →</a></nav>')
    # 08.11.2026: Saison ist Planungswissen, nicht täglich – zugeklappt
    teile.append('<details class="saison-zu"><summary><h2>Saison je Revier</h2></summary>'
                 f'<p class="sub">Ø Tage mit Gleitwind je Monat, aus etwa zwei Jahren Modellarchiv · '
                 f'<a href="{SAISON_DATEI}">alle Monate im Vergleich →</a></p>')
    for gruppe, rev_liste in reviere_gruppiert():
        teile.append(f'<h3 class="rk-gr">{e_txt(gruppe)}</h3><div class="rk-grid">')
        for r in rev_liste:
            teile.append(revier_karte_html(r, ergebnisse, jetzt))
        teile.append('</div>')
    teile.append('</details>')
    teile.append(unterstuetzung_html())
    teile.append(f'<p class="fuss">{e_txt(quelle)} · Stand {jetzt:%d.%m.%Y %H:%M} · '
                 f'<a href="{METHODIK_DATEI}">Wie das Tool rechnet</a>{fuss_recht()}</p>')
    teile.append(reviere_tab_html())
    teile.append(f'</main><div id="tip"></div><script>const CHARTS={{}};{JS}</script>'
                 f'{tabbar_html("Spots", mit_karte=False)}</body></html>')
    return "".join(teile)


def reviere_leiste(aktiv: Optional[str], start: str) -> str:
    """Kopfzeile jeder Seite: Übersicht › Land › Revier, dazu die anderen Reviere."""
    teile = [f'<a href="{e_txt(start)}">Übersicht</a>']
    for r in REVIERE:
        if not r["aktiv"]:
            continue
        name = e_txt(r["name"])
        teile.append(f'<b>{name}</b>' if r["id"] == aktiv else f'<a href="{e_txt(r["datei"])}">{name}</a>')
    return '<div class="reviere">' + " · ".join(teile) + '</div>'


