FAHNEN_AUF_REVIERSEITE = False
GUETE_WORT = {3: "sehr gut", 2: "gut", 1: "geht"}


def fahne_legende_html(d: OrtDaten, mit_ens: bool) -> str:
    leg = ['<span><i class="strich" style="background:var(--text-primary)"></i>Mittel</span>']
    for m in d.modelle:
        leg.append(f'<span class="lg-m"><i class="strich" style="background:{MODELL_FARBE.get(m, "#8f8e86")}"></i>'
                   f'{e_txt(MODELL_KURZ.get(m, m))}</span>')
    if mit_ens:
        leg.append('<span><i class="strich" style="background:var(--series-1);opacity:.35;height:10px"></i>'
                   'Ensemble 10–90 % (hell: min–max) · gestrichelt Median</span>')
    return f'<div class="legende">{"".join(leg)}</div>'


def stunden_tabelle_html(d: OrtDaten, tag: date, min_kn: float, schritt: int = 1) -> str:
    """16.11.2026 (David: „so wie bei Windfinder“): Stunde für Stunde – Wind (farbig ab der Gleitgrenze), Böen,
    Richtung, Welle, Luft, Regen; von Sonnenaufgang − 1 h bis Sonnenuntergang + 1 h."""
    sr, ss = sonnenzeiten(d, tag)
    a, b = (sr - timedelta(hours=1)).hour, min(23, (ss + timedelta(hours=1)).hour)
    st = [x for x in d.stunden if x.t.date() == tag and a <= x.t.hour <= b and (x.t.hour - a) % schritt == 0]
    if not st:
        return ""
    mit_welle = any(x.t in d.wellen for x in st)
    kopf = ('<tr><th>Uhr</th><th>kn</th><th>Böen</th><th>aus</th>' + ('<th>Welle</th>' if mit_welle else '')
            + '<th>°C</th><th>Regen</th></tr>')
    zeilen = []
    for x in st:
        r = kompass(x.wd)
        if x.ws >= min_kn:
            bg, fg = blau_fuer(x.ws)
            wz = f'<td class="st-w gl" style="background:{bg};color:{fg}">{x.ws:.0f}</td>'
        else:
            wz = f'<td class="st-w">{x.ws:.0f}</td>'
        w_ = d.wellen.get(x.t)
        welle = ""
        if mit_welle:
            welle = (f'<td class="st-n">{w_[0]:.1f} m'.replace(".", ",") + (f' · {w_[1]:.0f} s' if w_[1] else '')
                     + '</td>') if w_ else '<td></td>'
        zeilen.append(f'<tr{" class=nacht" if not (sr <= x.t <= ss) else ""}><th>{x.t:%H}</th>{wz}'
                      f'<td class="st-n">{"" if x.wg is None else f"{x.wg:.0f}"}</td>'
                      f'<td class="st-r">{pfeil_svg(r, 11)} {e_txt(r)}</td>{welle}'
                      f'<td class="st-n">{"" if x.temp is None else f"{x.temp:.0f}°"}</td>'
                      f'<td class="st-n">{f"{x.pr:.1f}".replace(".", ",") if x.pr >= 0.1 else ""}</td></tr>')
    return f'<div class="st-box"><table class="st-tab">{kopf}{"".join(zeilen)}</table></div>'


def tagesprofil_html(sp: "Spot", d: Optional[OrtDaten], ens_q: Optional[dict], tag: date, min_kn: float, key: str,
                     charts: dict, link: Optional[str] = None) -> str:
    """15.11.2026 (David): Tagesprofil in Knoten – jedes Modell als Linie, Mittel fett, Ensemble-Band, Grenze
    gestrichelt; Sonnenaufgang − 1 h bis Sonnenuntergang + 1 h. Steckt aufgeklappt in „Tage im Detail“."""
    if d is None:
        return ""
    sr, ss = sonnenzeiten(d, tag)
    start = (sr - timedelta(hours=1)).replace(minute=0, second=0, microsecond=0)
    ende = (ss + timedelta(hours=2)).replace(minute=0, second=0, microsecond=0)
    svg, pts = svg_fahne(sp, d, ens_q or {}, start, ende, min_kn, key, breite=560, hoehe=240, stundenachse=True,
                         raster=5)
    if not svg:
        return ""
    charts[key] = pts
    return (f'<div class="tp"><div class="tp-kopf">Tagesprofil · Wind in kn'
            + info_knopf("Jede farbige Linie ist ein Modell, fett das Mittel, das Band die Spanne der Ensemble-"
                         "Rechnungen (10–90 %, hell min–max). Gestrichelt: die gewählte Gleitgrenze. Antippen oder "
                         "Drüberfahren zeigt die Werte je Stunde.")
            + (f'<a class="tp-link" href="{e_txt(link)}">Spotseite ›</a>' if link else '')
            + f'</div>{fahne_legende_html(d, bool(ens_q))}<div class="tp-svg">{svg}</div></div>')


def richtungen_tabelle(sp: "Spot") -> List[Tuple[str, str]]:
    """Zusammenhängende Richtungen mit gleicher Güte/Art/Stufe → [(„W–NW“, „Welle, sehr gut · Stufe 3“)]."""
    zeilen = []
    ks = KOMPASS
    eintr = [sp.richtungen.get(k) for k in ks]
    if all(e is not None and e == eintr[0] for e in eintr):
        q, art, st = eintr[0]
        return [("alle Richtungen", f"{art}, {GUETE_WORT.get(q, '')}" + (f" · Stufe {st}" if st and not OEFFENTLICH
                                                                          else ""))]
    start = next((j for j in range(16) if eintr[j] is not None and eintr[j - 1] != eintr[j]), 0)
    j = start
    besucht = 0
    while besucht < 16:
        e = eintr[j % 16]
        if e is None:
            j += 1
            besucht += 1
            continue
        k = j
        while besucht < 16 and eintr[(k + 1) % 16] == e and (k + 1) % 16 != start % 16:
            k += 1
            besucht += 1
        a, b = ks[j % 16], ks[k % 16]
        q, art, st = e
        zeilen.append((a if a == b else f"{a}–{b}",
                       f"{art}, {GUETE_WORT.get(q, '')}" + (f" · Stufe {st}" if st and not OEFFENTLICH else "")))
        j = k + 1
        besucht += 1
    return zeilen


# =============================================================================
# SPOTSEITE 23.11.2026 (Anforderungsliste Bedienbarkeit, Abschnitte 2.2–2.5): erst die Antwort (Kurzsatz, Kennzahl-
# Kacheln, Hinweise einzeilig), dann Nächste Tage (eine Zeile je Tag, Balken auf gemeinsamer Skala) und EINE
# Zeitleiste „Stunde für Stunde“ über alle Tage (waagerecht, Liste | Grafik). Tagesdetails zugeklappt darunter.
# =============================================================================

def _wetter_zeichen(wc: Optional[int], nacht: bool) -> str:
    """Wettercode (WMO, ungünstigstes Modell) → kleines Zeichen."""
    if wc is None:
        return ""
    if wc >= 95:
        return "⛈"
    if wc >= 85 or 71 <= wc <= 77:
        return "🌨"
    if wc >= 80 or 61 <= wc <= 67:
        return "🌧"
    if 51 <= wc <= 57:
        return "🌦"
    if wc in (45, 48):
        return "🌫"
    if wc == 3:
        return "☁"
    if wc in (1, 2):
        return "☾" if nacht else "⛅"
    return "☾" if nacht else "☀"


def _spot_kn(sp: "Spot", d: OrtDaten, st: Stunde, jetzt: datetime) -> Tuple[float, Optional[float]]:
    """Wind und Böen am Spot – mit denselben Spotkorrekturen wie Kacheln und Gleitfenster (eff_wind). Die Böen
    werden im selben Verhältnis mitgezogen, sonst lägen sie an korrigierten Spots unter dem Mittelwind."""
    w = eff_wind(sp, st, None, wasser_zu(d, st.t), jetzt)[0]
    g = None if st.wg is None else (st.wg * w / st.ws if st.ws > 0.5 else st.wg)
    return w, (None if g is None else max(g, w))


def _passt(sp: "Spot", st: Stunde) -> bool:
    """Geht der Spot bei der Windrichtung dieser Stunde? (gleiche Prüfung wie bei den Gleitfenstern)"""
    return richtung_eintrag(sp, wd_bewertung(st, False)) is not None


def _tag_wort(tag: date, jetzt: datetime, kurz: bool = False) -> str:
    n = (tag - jetzt.date()).days
    return "Heute" if n == 0 else "Morgen" if n == 1 else (WOCHENTAGE[tag.weekday()] if kurz else tag_text(tag))


def _spot_eintrag(sp: "Spot", liste, chancen):
    """(Empfehlung, ist_chance) des Spots an einem Tag, sonst (None, False)."""
    e = next((x for x in liste if x.spot.name == sp.name), None)
    if e is not None:
        return e, False
    e = next((x for x in chancen if x.spot.name == sp.name), None)
    return e, e is not None


def _gleit_stunden(sp, d, e, jetzt) -> List[Tuple[Stunde, float, Optional[float]]]:
    """Stunden des Gleitfensters (alle fahrbaren Stunden, sonst der beste Block) mit Wind/Böen am Spot."""
    zeiten = {t for t, _w in (e.verlauf or [])}
    st = [x for x in d.stunden if (x.t in zeiten if zeiten else
                                   (e.sp_start is not None and e.sp_start <= x.t < e.sp_ende))]
    return [(x, *_spot_kn(sp, d, x, jetzt)) for x in st]


def _zeit_spanne(e) -> str:
    return (e.verlauf and fahrbar_text(e)) or (f"{e.sp_start:%H}–{e.sp_ende:%H}" if e.sp_start else "")


def _tag_hell(sp, d, tag, jetzt) -> List[Tuple[Stunde, float, Optional[float]]]:
    """Tageslichtstunden (ab jetzt) mit Wind/Böen am Spot."""
    sr, ss = sonnenzeiten(d, tag)
    t0 = jetzt.replace(minute=0, second=0, microsecond=0)
    return [(x, *_spot_kn(sp, d, x, jetzt)) for x in d.stunden
            if x.t.date() == tag and sr - timedelta(minutes=30) <= x.t <= ss and x.t >= t0]


def spot_kurzsatz(sp, d, ergebnisse, jetzt, min_kn) -> List[str]:
    """Ein Kurzsatz für heute und morgen, z. B. „Heute 10–18 Uhr Gleitwind 17–19 kn aus WSW, Böen bis 23.“"""
    saetze = []
    for tag, liste, chancen in ergebnisse[:2]:
        e, ch = _spot_eintrag(sp, liste, chancen)
        wort = _tag_wort(tag, jetzt)
        if e is not None and not ch:
            gs = _gleit_stunden(sp, d, e, jetzt)
            if gs:
                lo, hi = min(w for _x, w, _g in gs), max(w for _x, w, _g in gs)
                boe = max((g for _x, _w, g in gs if g is not None), default=None)
                kn = f"{lo:.0f}" if round(lo) == round(hi) else f"{lo:.0f}–{hi:.0f}"
                saetze.append(f"{wort} {_zeit_spanne(e)} Uhr Gleitwind {kn} kn aus {e.richtung}"
                              + (f", Böen bis {boe:.0f}" if boe is not None else "") + ".")
                continue
        hell = _tag_hell(sp, d, tag, jetzt)
        if not hell:
            continue
        x_max = max(hell, key=lambda z: z[1])
        if ch:
            saetze.append(f"{wort} nur einzelne Modelle mit Gleitwind, im Mittel bis {x_max[1]:.0f} kn aus "
                          f"{kompass(x_max[0].wd)}.")
        elif x_max[1] >= min_kn and not any(w >= min_kn and _passt(sp, x) for x, w, _g in hell):
            saetze.append(f"{wort} kein Gleitwind: bis {x_max[1]:.0f} kn aus {kompass(x_max[0].wd)}, die Richtung "
                          f"passt hier nicht.")
        else:
            saetze.append(f"{wort} kein Gleitwind, tagsüber bis {x_max[1]:.0f} kn aus {kompass(x_max[0].wd)}.")
    if not any("Gleitwind " in s and "kein" not in s and "einzelne" not in s for s in saetze):
        for tag, liste, chancen in ergebnisse[2:]:
            e, ch = _spot_eintrag(sp, liste, chancen)
            if e is not None and not ch:
                saetze.append(f"Nächster Gleittag {tag_text(tag)} mit {e.wind:.0f} kn aus {e.richtung}"
                              + (" (Tendenz)" if ist_tendenz(tag) else "") + ".")
                break
        else:
            if len(ergebnisse) > 2:
                saetze.append(f"Bis {tag_text(ergebnisse[-1][0])} kein Gleittag in Sicht.")
    return saetze


def _kz(titel: str, wert: str, zusatz: str, ziel: str, extra: bool = False, wert_html: bool = False) -> str:
    return (f'<a class="kz{" kz-x" if extra else ""}" href="{ziel}"><span class="kz-t">{e_txt(titel)}</span>'
            f'<span class="kz-w">{wert if wert_html else e_txt(wert)}</span>'
            f'<span class="kz-z">{e_txt(zusatz)}</span></a>')


def _h_id(t: datetime) -> str:
    return f"h-{t:%Y%m%d%H}"


def spot_kennzahlen_html(sp, d, ergebnisse, jetzt, min_kn, spalten: List[datetime]) -> str:
    """Kennzahl-Kacheln (Handy 4, Desktop 6), jede springt zur passenden Stunde in „Stunde für Stunde“."""
    def ziel(t: Optional[datetime]) -> str:
        """nächste vorhandene Spalte zur Zeit t (die Liste ist nachts und ab Tag 4 nur 3-stündlich)"""
        if t is None or not spalten:
            return "#stunden"
        return "#" + _h_id(min(spalten, key=lambda s: abs((s - t).total_seconds())))
    kacheln = []
    # 1) nächstes Gleitfenster, 2) bester Tag
    naechst = best = None
    for tag, liste, chancen in ergebnisse:
        e, ch = _spot_eintrag(sp, liste, chancen)
        if e is None or ch:
            continue
        if naechst is None:
            naechst = (tag, e)
        if best is None or e.wind > best[1].wind:
            best = (tag, e)
    if naechst:
        tag, e = naechst
        gs = _gleit_stunden(sp, d, e, jetzt)
        lo = min((w for _x, w, _g in gs), default=e.wind)
        hi = max((w for _x, w, _g in gs), default=e.wind)
        kn = f"{lo:.0f}" if round(lo) == round(hi) else f"{lo:.0f}–{hi:.0f}"
        kacheln.append(_kz("Nächster Gleitwind", f"{kn} kn", f"{_tag_wort(tag, jetzt)} {_zeit_spanne(e)} Uhr",
                           ziel(gs[0][0].t if gs else e.sp_start)))
    else:
        kacheln.append(_kz("Nächster Gleitwind", "–", f"kein Gleittag bis {tag_text(ergebnisse[-1][0])}",
                           "#tage"))
    if best:
        tag, e = best
        w_ = gleit_wahrsch(e)
        kacheln.append(_kz("Bester Tag", f"{e.wind:.0f} kn", ("≈ " if ist_tendenz(tag) else "")
                           + f"{_tag_wort(tag, jetzt)}" + (f" · {w_['p'] * 100:.0f} %" if w_ else ""),
                           ziel(e.sp_start)))
    # 3) stärkste Böe und 4) höchste Welle bei Tageslicht in den nächsten 48 h
    hell48 = []
    for tag, _l, _c in ergebnisse[:3]:
        hell48 += [z for z in _tag_hell(sp, d, tag, jetzt) if z[0].t < jetzt + timedelta(hours=48)]
    boe = max((z for z in hell48 if z[2] is not None), key=lambda z: z[2], default=None)
    if boe:
        kacheln.append(_kz("Stärkste Böe · 48 h", f"{boe[2]:.0f} kn", f"{_tag_wort(boe[0].t.date(), jetzt, True)} "
                           f"{boe[0].t:%H} Uhr", ziel(boe[0].t)))
    wl = max(((z[0].t, d.wellen[z[0].t]) for z in hell48 if z[0].t in d.wellen),
             key=lambda tw: tw[1][0], default=None)
    welle_k = None
    if wl:
        h_, p_ = wl[1][0], wl[1][1]
        welle_k = _kz("Höchste Welle · 48 h", f"{h_:.1f} m".replace(".", ",") + (f" · {p_:.0f} s" if p_ else ""),
                      f"{_tag_wort(wl[0].date(), jetzt, True)} {wl[0]:%H} Uhr · draußen", ziel(wl[0]))
    # Richtung im nächsten Fenster (sonst jetzt) und wie der Spot dabei geht
    if naechst:
        r_ = naechst[1].richtung
    else:
        x0 = next((x for x in d.stunden if x.t >= jetzt.replace(minute=0, second=0, microsecond=0)), None)
        r_ = kompass(x0.wd) if x0 else ""
    bed = sp.richtungen.get(r_) if r_ else None
    bed_txt = (f"{bed[1]}, {GUETE_WORT.get(bed[0], '')}".rstrip(", ") if bed else "passt hier nicht")
    richt_k = _kz("Richtung" + (" im Fenster" if naechst else " jetzt"),
                  f'{pfeil_svg(r_, 15)} {e_txt(r_)}', bed_txt, "#spot", wert_html=True) if r_ else None
    # Wasser / Luft
    heute = [v for t, v in d.wasser.items() if t.date() == jetzt.date()]
    luft = [z[0].temp for z in hell48 if z[0].temp is not None and z[0].t.date() == hell48[0][0].t.date()] if hell48 else []
    wasser_k = None
    if heute or luft:
        wasser_k = _kz("Wasser" if heute else "Luft",
                       f"{sum(heute) / len(heute):.0f} °C" if heute else f"{min(luft):.0f}–{max(luft):.0f} °C",
                       (f"Luft {min(luft):.0f}–{max(luft):.0f} °C tagsüber" if heute and luft else "tagsüber"),
                       ziel(hell48[0][0].t if hell48 else None))
    rest = [k for k in (welle_k, richt_k, wasser_k) if k]
    kacheln += rest
    kacheln = kacheln[:6]
    html_k = [k.replace('class="kz"', 'class="kz kz-x"') if i >= 4 else k for i, k in enumerate(kacheln)]
    mehr = (f'<button type="button" class="kz-mehr" onclick="this.parentNode.classList.add(\'kz-alle\');'
            f'this.remove()">+ {len(kacheln) - 4} weitere</button>' if len(kacheln) > 4 else '')
    return f'<div class="kz-reihe">{"".join(html_k)}{mehr}</div>'


DWD_LABELS = {"Unwetter (DWD)", "Gewitter (DWD)", "Sturm (DWD)", "DWD-Warnung"}


def spot_hinweise_html(ergebnisse, sp, jetzt) -> str:
    """Hinweise der nächsten zwei Tage einzeilig; Antippen zeigt die ganzen Sätze."""
    kurz, lang = [], []
    for tag, liste, chancen in ergebnisse[:2]:
        e, _ch = _spot_eintrag(sp, liste, chancen)
        if e is None:
            continue
        achtung, labels, _k = warnungen_teilen(e.warnungen)
        wort = _tag_wort(tag, jetzt)
        for l_ in labels:
            if l_ not in DWD_LABELS:          # stehen im Kasten „Amtliche Warnungen“
                kurz.append(f"{wort}: {l_}")
        for a_ in achtung:
            if not re.match(r"(Unwetter|Gewitter|Sturm)warnung|DWD-Warnung", a_):
                lang.append(f"<li><b>{e_txt(wort)}</b> {e_txt(a_)}</li>")
    if not kurz:
        return ""
    return (f'<details class="hw"><summary><span class="hw-i">⚠</span><span class="hw-t">'
            f'{e_txt(" · ".join(kurz))}</span></summary><ul>{"".join(lang)}</ul></details>')


def spot_spalten(d: OrtDaten, tage: List[date], jetzt: datetime) -> List[Tuple[Stunde, bool]]:
    """Spalten der Zeitleiste: Tage 1–3 tagsüber stündlich, nachts alle 3 h; ab Tag 4 alle 3 h. (Stunde, nacht)"""
    t0 = jetzt.replace(minute=0, second=0, microsecond=0)
    je_tag: Dict[date, List[Stunde]] = {}
    for x in d.stunden:
        if x.t >= t0:
            je_tag.setdefault(x.t.date(), []).append(x)
    aus = []
    for i, tag in enumerate(tage):
        sr, ss = sonnenzeiten(d, tag)
        a, b = sr - timedelta(hours=1), ss + timedelta(hours=1)
        for x in je_tag.get(tag, []):
            hell = a <= x.t <= b
            if (i < TENDENZ_AB and hell) or x.t.hour % 3 == 0 or x.t == t0:
                aus.append((x, not (sr - timedelta(minutes=30) <= x.t <= ss)))
    return aus


def stunden_leiste_html(sp, d, ens_q, tage, jetzt, min_kn, charts) -> Tuple[str, List[datetime]]:
    """Eine Zeitleiste über alle Tage (Spalten = Stunden, waagerecht scrollbar) mit Umschalter Liste | Grafik."""
    spalten = spot_spalten(d, tage, jetzt)
    if not spalten:
        return "", []
    mit_welle = any(x.t in d.wellen for x, _n in spalten)
    werte = [(x, n, *_spot_kn(sp, d, x, jetzt)) for x, n in spalten]
    # Tageskopf (colspan) und Tagesknöpfe
    tage_sp: List[Tuple[date, int]] = []
    for x, *_r in werte:
        if tage_sp and tage_sp[-1][0] == x.t.date():
            tage_sp[-1] = (tage_sp[-1][0], tage_sp[-1][1] + 1)
        else:
            tage_sp.append((x.t.date(), 1))
    knoepfe = "".join(f'<button type="button" data-tag="{t:%Y%m%d}"{" class=an" if i == 0 else ""}>'
                      f'{WOCHENTAGE[t.weekday()]} {t.day}.</button>' for i, (t, _n) in enumerate(tage_sp))
    z_tag = ['<tr class="sl-tg"><th></th>'] + [
        f'<td colspan="{n}" class="tw"><span>{e_txt(tag_text(t))}{" · Tendenz" if ist_tendenz(t) else ""}</span></td>'
        for t, n in tage_sp]
    zeilen: Dict[str, List[str]] = {k: [] for k in ("uhr", "wx", "kn", "boe", "aus", "welle", "per", "temp", "regen")}
    vor_tag = None
    max_r = max(4.0, max((x.pr for x, *_r in werte), default=0))
    for i, (x, nacht, w, g) in enumerate(werte):
        tw = x.t.date() != vor_tag
        vor_tag = x.t.date()
        sr, ss = sonnenzeiten(d, x.t.date())
        naechste = werte[i + 1][0].t if i + 1 < len(werte) else x.t + timedelta(hours=3)
        sonne = (f'<small>↑{sr:%H:%M}</small>' if x.t <= sr < naechste else
                 f'<small>↓{ss:%H:%M}</small>' if x.t <= ss < naechste else '')
        kl = " ".join(k for k, ja in (("tw", tw), ("na", nacht)) if ja)
        a = f' data-c="{i}"' + (f' class="{kl}"' if kl else '')
        zeilen["uhr"].append(f'<td id="{_h_id(x.t)}" data-tag="{x.t:%Y%m%d}"{a}>'
                             f'{x.t:%H}{sonne}</td>')
        zeilen["wx"].append(f'<td{a}>{_wetter_zeichen(x.wc, nacht)}</td>')
        if w >= min_kn and _passt(sp, x):
            bg, fg = blau_fuer(w)
            zeilen["kn"].append(f'<td{a}><b class="gl" style="background:{bg};color:{fg}">{w:.0f}</b></td>')
        elif w >= min_kn:       # Wind reicht, Richtung geht hier nicht
            zeilen["kn"].append(f'<td{a}><b class="fr">{w:.0f}</b></td>')
        else:
            zeilen["kn"].append(f'<td{a}><b>{w:.0f}</b></td>')
        zeilen["boe"].append(f'<td{a}>{"" if g is None else f"{g:.0f}"}</td>')
        r = kompass(x.wd)
        zeilen["aus"].append(f'<td{a}>{pfeil_svg(r, 12)}<small>{e_txt(r)}</small></td>')
        wl = d.wellen.get(x.t)
        zeilen["welle"].append(f'<td{a}>{f"{wl[0]:.1f}".replace(".", ",") if wl else ""}</td>')
        zeilen["per"].append(f'<td{a}>{f"{wl[1]:.0f}" if wl and wl[1] else ""}</td>')
        zeilen["temp"].append(f'<td{a}>{"" if x.temp is None else f"{x.temp:.0f}°"}</td>')
        hoehe = 0 if x.pr < 0.1 else max(2, round(min(x.pr, max_r) / max_r * 18))
        zeilen["regen"].append(f'<td{a}>' + (f'<i style="height:{hoehe}px"></i><small>{f"{x.pr:.1f}".replace(".", ",")}'
                                             f'</small>' if hoehe else '') + '</td>')
    namen = [("uhr", "Uhr"), ("wx", ""), ("kn", "kn"), ("boe", "Böen"), ("aus", "aus")]
    if mit_welle:
        namen += [("welle", "Welle m"), ("per", "Periode s")]
    namen += [("temp", "Luft"), ("regen", "Regen mm")]
    tab = ["<table class=\"sl-tab\">", "".join(z_tag) + "</tr>"]
    for k, n in namen:
        tab.append(f'<tr class="sl-{k}"><th>{e_txt(n)}</th>{"".join(zeilen[k])}</tr>')
    tab.append("</table>")
    ab_tend = next((t for t in tage if ist_tendenz(t)), None)
    fuss = (f"kn = Mittel der Modelle am Spot (mit Spotkorrektur), blau ab {min_kn:.0f} kn · umrandet: Wind reicht, "
            f"Richtung geht hier nicht · Nacht dunkler und alle 3 h"
            + (f" · ab {tag_text(ab_tend)} alle 3 h, nur Tendenz" if ab_tend else "")
            + " · Zeichen: ungünstigstes Modell")
    # Grafik: dieselbe Zeit als Verlauf (Mittel am Spot fett, Modelle, Ensemble-Band)
    start = spalten[0][0].t
    ende = datetime.combine(tage[-1], time(0)) + timedelta(days=1)
    mittel = {x.t: w for x, _n, w, _g in werte}
    for x in d.stunden:
        if start <= x.t < ende and x.t not in mittel:
            mittel[x.t] = _spot_kn(sp, d, x, jetzt)[0]
    svg, pts = svg_fahne(sp, d, ens_q or {}, start, ende, min_kn, "f0", breite=1600, hoehe=260, raster=5,
                         mittel=mittel)
    graf = ""
    if svg:
        charts["f0"] = pts
        um = ('<button type="button" class="mod-um" onclick="this.closest(\'.zl\').classList.toggle(\'nur-mittel\')">'
              '<span class="mu-a">Modelle einzeln zeigen</span><span class="mu-b">nur Mittel zeigen</span></button>'
              if len(d.modelle) > 1 else '')
        graf = (f'<div class="sl-graf" hidden>{fahne_legende_html(d, bool(ens_q)).replace(">Mittel<", ">Mittel am Spot<")}'
                f'{um}<div class="sl-gbox">{svg}</div></div>')
    erkl = ("Mittelwind der Modelle am Spot in kn (blau ab der Gleitgrenze), Böen, Richtung, Welle draußen, Luft und "
            "Regen. Tagsüber stündlich, nachts und ab Tag 4 alle 3 Stunden. „Grafik“ zeigt dieselbe Zeit als "
            "Verlauf mit jedem Modell und der Spanne der Ensemble-Rechnungen.")
    umsch = ('<span class="lg-um" role="group"><button type="button" data-v="liste" aria-pressed="true">Liste</button>'
             '<button type="button" data-v="grafik" aria-pressed="false">Grafik</button></span>' if graf else '')
    html_ = (f'<section class="zl nur-mittel" id="sl"><h2 id="stunden" class="h-um"><span>Stunde für Stunde'
             f'{info_knopf(erkl)}</span>{umsch}</h2>'
             f'<div class="sl-liste"><div class="sl-tage">{knoepfe}</div>'
             f'<div class="sl-scroll">{"".join(tab)}</div><p class="sl-fuss">{e_txt(fuss)}</p></div>{graf}</section>')
    return html_, [x.t for x, _n in spalten]


def tage_liste_html(sp, d, ergebnisse, jetzt, min_kn, spalten: List[datetime]) -> str:
    """Nächste Tage: eine Zeile je Tag – Wind tagsüber als Balken auf gemeinsamer Skala (Gleitgrenze markiert),
    Richtung, Gleitwind-Zeit, Wahrscheinlichkeit, Böen und Welle. Antippen springt in die Zeitleiste."""
    zeilen_d = []
    for tag, liste, chancen in ergebnisse:
        hell = _tag_hell(sp, d, tag, jetzt)
        e, ch = _spot_eintrag(sp, liste, chancen)
        zeilen_d.append((tag, hell, e, ch))
    hoch = [max(w for _x, w, _g in h) for _t, h, _e, _c in zeilen_d if h]
    skala = max(25.0, min_kn + 8, max(hoch, default=0) + 2)
    pz = lambda v: f"{max(0.0, min(100.0, v / skala * 100)):.1f}%"
    zeilen = []
    for tag, hell, e, ch in zeilen_d:
        tend = ist_tendenz(tag)
        kopf = (f'<span class="tl-d"><b>{WOCHENTAGE[tag.weekday()]}</b> {tag.day}.'
                + ('<i class="ca">≈</i>' if tend else '') + '</span>')
        if not hell:
            zeilen.append(f'<div class="tl-z vorbei" id="tag-{tag:%Y%m%d}">{kopf}<span class="tl-r"></span>'
                          f'<span class="tl-b"><span class="tl-n">heute vorbei</span></span>'
                          f'<span class="tl-g"></span><span class="tl-p"></span></div>')
            continue
        lo, hi = min(w for _x, w, _g in hell), max(w for _x, w, _g in hell)
        x_max = max(hell, key=lambda z: z[1])
        boe = max((g for _x, _w, g in hell if g is not None), default=None)
        wl = max((d.wellen[x.t][0] for x, _w, _g in hell if x.t in d.wellen), default=None)
        r_ = e.richtung if (e is not None and not ch) else kompass(x_max[0].wd)
        passt_hi = [w for x, w, _g in hell if w >= min_kn and _passt(sp, x)]
        if passt_hi:
            bg, _fg = blau_fuer(max(passt_hi))
            ant = 0 if lo >= min_kn else (min_kn - lo) / max(hi - lo, 0.1) * 100
            farbe = f"linear-gradient(90deg,var(--tl-grau) {ant:.0f}%,{bg} {ant:.0f}%)"
        else:
            farbe = "var(--tl-grau)"
        balken = (f'<span class="tl-bar"><i class="tl-s" style="left:{pz(min_kn)}"></i>'
                  f'<i class="tl-w" style="left:{pz(lo)};width:calc({pz(hi)} - {pz(lo)} + 4px);background:{farbe}"></i></span>')
        neben = " · ".join(x for x in ((f"Böen {boe:.0f}" if boe is not None else ""),
                                       (f"Welle {wl:.1f} m".replace(".", ",") if wl is not None else "")) if x)
        if e is not None and not ch:
            g_txt, g_kl = f"{_zeit_spanne(e)} Uhr", "ja"
            ziel_t = next((x.t for x, w, _g in hell if w >= min_kn), e.sp_start)
        elif ch:
            g_txt, g_kl, ziel_t = "Chance", "ch", x_max[0].t
        elif hi >= min_kn and not passt_hi:
            g_txt, g_kl, ziel_t = "Richtung passt nicht", "nein fr", x_max[0].t
        else:
            g_txt, g_kl, ziel_t = "–", "nein", x_max[0].t
        w_ = gleit_wahrsch(e) if e is not None else None
        p_txt = f'{w_["p"] * 100:.0f} %' if w_ else ""
        ziel = "#" + _h_id(min(spalten, key=lambda s: abs((s - ziel_t).total_seconds()))) if spalten and ziel_t else "#stunden"
        zeilen.append(
            f'<a class="tl-z{" tend" if tend else ""}" id="tag-{tag:%Y%m%d}" href="{ziel}">{kopf}'
            f'<span class="tl-r">{pfeil_svg(r_, 12)}<small>{e_txt(r_)}</small></span>'
            f'<span class="tl-b"><span class="tl-k"><b>{lo:.0f}–{hi:.0f}</b>{balken}</span>'
            f'<span class="tl-n">{e_txt(neben)}</span></span>'
            f'<span class="tl-g {g_kl}">{e_txt(g_txt)}</span>'
            f'<span class="tl-p{" p" + str(w_["stufe"]) if w_ else ""}">{p_txt}</span></a>')
    kopfz = ('<div class="tl-kopf"><span>Tag</span><span>aus</span><span>Wind tagsüber, kn</span>'
             '<span>Gleitwind</span><span>Chance</span></div>')
    erkl = ("Je Tag der Wind am Spot bei Tageslicht von schwach bis stark, alle Tage auf derselben Skala; der Strich "
            "markiert die Gleitgrenze. Rechts die Zeit mit Gleitwind und wie wahrscheinlich er ist (gemessene "
            "Treffsicherheit der Modelle). ≈ = ab Tag 4 nur Tendenz. Antippen springt zu den Stunden des Tages.")
    return (f'<h2 id="tage">Nächste Tage{info_knopf(erkl)}</h2>'
            f'<div class="tl">{kopfz}{"".join(zeilen)}</div>')


def tage_details_html(sp, d, ens_q, ergebnisse, min_kn, charts) -> str:
    """Zugeklappt: je Tag das Tagesprofil der Modelle und die Details (Segel, Pegel, Korrekturen)."""
    teile = []
    for tag, liste, chancen in ergebnisse:
        e, _ch = _spot_eintrag(sp, liste, chancen)
        prof = tagesprofil_html(sp, d, ens_q, tag, min_kn, f"tp{tag:%Y%m%d}", charts)
        inhalt = prof + (karte_html(e, len(d.modelle) > 1) if e is not None else "")
        if not inhalt:
            continue
        teile.append(f'<details class="td" id="td-{tag:%Y%m%d}"><summary>{e_txt(tag_text(tag))}'
                     f'{" · Tendenz" if ist_tendenz(tag) else ""}</summary>{inhalt}</details>')
    if not teile:
        return ""
    return ('<details class="mehr-box"><summary><h2 id="details">Tage im Detail</h2>'
            '<span class="h-sub">Modelle je Tag, Segel, Pegel</span></summary>'
            f'<div class="td-liste">{"".join(teile)}</div></details>')


SL_JS = r"""
(function(){const L=document.getElementById('sl');if(!L)return;
 const sc=L.querySelector('.sl-scroll'),kn=[...L.querySelectorAll('.sl-tage button')],th=L.querySelector('.sl-tab th');
 function links(td){return td.offsetLeft-(th?th.offsetWidth:0)-6;}
 function zeigeListe(){L.querySelector('.sl-liste').hidden=false;const g=L.querySelector('.sl-graf');if(g)g.hidden=true;
  L.querySelectorAll('.lg-um button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.v==='liste'));}
 function zu(td,mark,sanft){if(!td)return;sc.scrollTo({left:Math.max(0,links(td)),behavior:sanft===false?'auto':'smooth'});
  if(mark){L.querySelectorAll('.mark').forEach(e=>e.classList.remove('mark'));
   L.querySelectorAll('[data-c="'+td.dataset.c+'"]').forEach(e=>e.classList.add('mark'));
   setTimeout(()=>L.querySelectorAll('.mark').forEach(e=>e.classList.remove('mark')),2600);}}
 function ersteSpalte(tag){return L.querySelector('.sl-uhr td[data-tag="'+tag+'"]');}
 kn.forEach(b=>b.addEventListener('click',()=>zu(ersteSpalte(b.dataset.tag))));
 let warte=0;sc.addEventListener('scroll',()=>{cancelAnimationFrame(warte);warte=requestAnimationFrame(()=>{
  const x=sc.scrollLeft+(th?th.offsetWidth:0)+8;let tag=null;
  for(const td of L.querySelectorAll('.sl-uhr td')){if(td.offsetLeft+td.offsetWidth>x){tag=td.dataset.tag;break;}}
  kn.forEach(b=>b.classList.toggle('an',b.dataset.tag===tag));});},{passive:true});
 L.querySelectorAll('.lg-um button').forEach(b=>b.addEventListener('click',()=>{const g=b.dataset.v==='grafik';
  L.querySelector('.sl-liste').hidden=g;L.querySelector('.sl-graf').hidden=!g;
  L.querySelectorAll('.lg-um button').forEach(x=>x.setAttribute('aria-pressed',x===b));}));
 function springe(id,sanft){const td=document.getElementById(id);if(!td||!L.contains(td))return false;zeigeListe();
  L.scrollIntoView({behavior:sanft===false?'auto':'smooth',block:'start'});setTimeout(()=>zu(td,true,sanft),sanft===false?0:250);return true;}
 document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#h-"]');if(!a)return;
  if(springe(a.getAttribute('href').slice(1)))e.preventDefault();});
 function hash(){const h=location.hash.slice(1);if(h.indexOf('h-')===0)springe(h,false);
  else if(h.indexOf('tag-')===0){const td=ersteSpalte(h.slice(4));if(td)zu(td,false,false);}}
 if(location.hash)setTimeout(hash,60);addEventListener('hashchange',hash);})();
"""

def spot_beschreibung(sp, d, rev) -> str:
    """23.11.2026 (Auffindbarkeit): Beschreibung für Suchmaschinen und Linkvorschau – „Welle“ nur mit Wellendaten,
    „Wind aktuell“ nur mit Messstation in der Nähe."""
    welle = bool(d is not None and d.wellen and sp.see_hoehe <= 0)      # Binnenseen: keine Welle
    messung = bool(spot_jetzt_html(sp, MIN_KN))
    return (f"{sp.name}, {revier_kurz(rev)}: Windvorhersage Stunde für Stunde, Böen"
            + (", Welle" if welle else "") + (", Wind aktuell" if messung else "")
            + " und Gleitwind-Chance für Windsurfen, Kiten und Wingen.")


def revier_beschreibung(rev, rid) -> str:
    n = len([x for x in SPOTS if rev and revier_von(x) == rid])
    return (f"{revier_kurz(rev) if rev else ''}: Windvorhersage für {n} {'Spot' if n == 1 else 'Spots'}"
            + (", Wind aktuell an den Messstationen" if JETZT_ALLE.get(rid) else "")
            + " und Gleitwind-Chance für Windsurfen, Kiten und Wingen.")


def spot_hauptteil_html(sp, d, ens_q, ergebnisse, tage, args, jetzt, karten, charts, datei, rev, rid):
    """Öffentliche Spotseite ab dem Kopf (23.11.2026): (Teile, Karten-HTML, Skripte)."""
    min_kn = args.min_kn
    sl_html, spalten = stunden_leiste_html(sp, d, ens_q, tage, jetzt, min_kn, charts)
    teile = []
    satz = spot_kurzsatz(sp, d, ergebnisse, jetzt, min_kn)
    if satz:        # je Satz ein eigener Textknoten (Übersetzung je Satz)
        teile.append('<p class="kurzsatz">' + " ".join(f"<span>{e_txt(x)}</span>" for x in satz) + '</p>')
    teile.append(spot_jetzt_html(sp, min_kn, messverlauf_spot_html(sp, jetzt, min_kn, charts)))
    teile.append(spot_kennzahlen_html(sp, d, ergebnisse, jetzt, min_kn, spalten))
    teile.append(amtliche_warnungen_html(DWD_WARNUNGEN.get(sp.name, [])))
    teile.append(spot_hinweise_html(ergebnisse, sp, jetzt))
    teile.append(gw_leiste_html(datei).replace('<div class="gw-leiste">', '<div class="gw-leiste gw-schmal">'))
    teile.append(tage_liste_html(sp, d, ergebnisse, jetzt, min_kn, spalten))
    teile.append(sl_html)
    wp_html, wp_skript = "", ""
    if karten and DATEN_ORDNER is not None:
        with karten_region(rev["karte"]):
            wp_html, wp_skript = wind_player_html(karten, jetzt, titel="Karte", reg=rid)
        if wp_html:
            teile.append(wp_html.replace('class="karte wp-karte"', 'class="karte wp-karte wp-klein"'))
            wp_skript = f'<script>var WP_FOKUS={json.dumps([sp.lat, sp.lon, sp.name])};</script>' + wp_skript
    teile.append(tage_details_html(sp, d, ens_q, ergebnisse, min_kn, charts))
    return teile, wp_html, wp_skript + f"<script>{SL_JS}</script>"


def spot_seite_html(sp: "Spot", d: OrtDaten, ens_q: dict, ergebnisse, tage: List[date], args, quelle: str,
                    jetzt: datetime, startseite: str, karten: Optional[dict] = None) -> str:
    rid = revier_von(sp)
    rev = revier(rid)
