def jetzt_name(name: str) -> str:
    """Stationsname ohne Betreiber-Vorsilbe („MeteoSwiss Steckborn“ → „Steckborn“) für die Jetzt-Karten."""
    return re.sub(r"^(DWD|DMI|MeteoSwiss|KNMI|AEMET|BSH|GeoSphere|Meteotrentino)\s+", "", name)


def jetzt_abschnitt(jc: List[dict], min_kn: float, badges_html: Optional[str] = None, rid: Optional[str] = None,
                    mv: Optional[Dict[str, str]] = None) -> str:
    """Abschnitt „Jetzt“ (Messung gegen Vorhersage). badges_html=None: Pegel/Warnungen aus diesem Lauf.
    08.11.2026: kompakte Liste – eine Zeile je Station; die Abweichung zur Vorhersage nur ab 3 kn.
    09.11.2026: mv = Messverlauf je Station (Name → Inhalt); Antippen der Zeile klappt ihn darunter auf. jetzt.json
    (10-Minuten-Erneuerung) kommt ohne – das Skript im Browser hängt die vorhandenen Verläufe in den neuen Abschnitt um."""
    teile: List[str] = []
    mv = mv or {}
    erkl = ("Gemessener Mittelwind an den Stationen des Reviers, wird alle 10 Minuten erneuert. Blau = ab der "
            "gewählten Gleitgrenze. Weicht die Messung um 3 kn oder mehr von der Vorhersage ab, steht das dabei."
            + (" Antippen einer Station zeigt die Messung der letzten 2 Tage." if mv else ""))
    t_mess = max(r["t"] for r in jc)
    attr = f' data-t="{t_mess:%Y-%m-%dT%H:%M}"' + (f' data-r="{e_txt(rid)}"' if rid else '')
    alter = f'<span class="js-alter" data-zeit="{t_mess:%Y-%m-%dT%H:%M}"></span>'
    teile.append(f'<section id="jetzt"{attr}><h2>Jetzt <span class="h-sub">{t_mess:%H:%M} Uhr</span>'
                 f'{alter}{info_knopf(erkl)}</h2><div class="jl">')
    for r in jc:
        if r.get("kn") is None:
            continue
        b = r["bias"]
        abw = (f'<span class="jl-d {"mehr" if b > 0 else "weniger"}">{abs(b):.0f} kn {"über" if b > 0 else "unter"} '
               f'Vorhersage</span>' if b is not None and abs(b) >= 3 else "")
        tip = f'{r["name"]} · {r["t"]:%H:%M} Uhr' + (f' · {r["trend"]}' if r["trend"] else "")
        gleit = r["kn"] >= min_kn
        stil = (lambda f: f' style="background:{f[0]};color:{f[1]}"')(blau_fuer(r["kn"])) if gleit else ""
        klapp = (' mv-z" role="button" tabindex="0" aria-expanded="false' if r["name"] in mv else "")
        teile.append(f'<div class="jl-z{klapp}" data-st="{e_txt(r["name"])}" title="{e_txt(tip)}">'
                     f'<span class="jl-n">{e_txt(jetzt_name(r["name"]))}</span>'
                     f'<span class="jl-w"><b class="js-z{" gl" if gleit else ""}"{stil}>{r["kn"]:.0f}</b> '
                     f'{pfeil_svg(r["richtung"] or "", 11)}{e_txt(r["richtung"] or "")}</span>'
                     f'<span class="jl-b">{"Böen " + format(r["boe"], ".0f") if r["boe"] else ""}</span>{abw}</div>')
        if r["name"] in mv:
            teile.append(f'<div class="mv-c" data-st="{e_txt(r["name"])}" hidden>{mv[r["name"]]}</div>')
    teile.append('</div>')
    badges = []
    if badges_html is not None:
        badges = [badges_html] if badges_html else []
    elif rid in (None, "ostsee") and PEGEL_JETZT:
        hoch = any(abs(x["cm"]) >= HOCHWASSER_WARN_CM for x in PEGEL_JETZT)
        badges.append(f'<span class="badge{" warn" if hoch else ""}">🌊 {e_txt(pegel_jetzt_text())}</span>')
    for z in (warnungen_uebersicht() if badges_html is None and rid in (None, "ostsee") and not OEFFENTLICH else []):
        badges.append(f'<span class="badge warn">⚠ DWD: {e_txt(z)}</span>')
    if badges:
        teile.append('<div class="badges">' + "".join(badges) + '</div>')
    teile.append('</section>')
    return "".join(teile)


def jetzt_badges_html() -> str:
    """Nur die Pegel-/Warnplaketten (für den 10-Minuten-Lauf aus dem Hauptlauf gemerkt)."""
    h = jetzt_abschnitt([{"t": datetime.now(), "kn": 0, "bias": None, "trend": None, "name": "", "richtung": None,
                          "boe": None}], 99.0)
    m = re.search(r'<div class="badges">(.*?)</div>', h, re.S)
    return m.group(1) if m else ""


# =============================================================================
# JETZT AUF START- UND SPOTSEITEN (08.11.2026): Die Übersicht hat eine Spalte „jetzt“ (stärkster aktueller Messwert
# je Revier, jetzt_zelle_html), jede Spotseite die nächste Live-Station (bis JETZT_SPOT_KM). Beides erneuert sich mit
# daten/jetzt.json.
# =============================================================================
JETZT_SPOT_KM = 40


# =============================================================================
# MESSVERLAUF (08.11.2026): je Live-Station die letzten 48 h Messung (Mittel, Böen, Richtung), gestrichelt was etwa
# einen Tag vorher vorhergesagt war (Mittel der Modelle aus prognosen.jsonl, roh), rechts 24 h aktuelle Vorhersage.
# =============================================================================
def vortag_prognosen(namen: set, von: datetime, bis: datetime) -> Dict[str, Dict[datetime, float]]:
    """{Station: {Stunde: Modellmittel}} aus dem Lauf, der der Stunde etwa 24 h (18–30 h) vorausging."""
    beste: Dict[Tuple[str, datetime], Tuple[float, float]] = {}
    try:
        with open(ARCHIV, "rb") as f:
            f.seek(0, 2)
            groesse = f.tell()
            f.seek(max(0, groesse - VORTAG_BYTES))
            text = f.read().decode("utf-8", "replace")
    except OSError:
        return {}
    zeilen = text.splitlines()
    if groesse > VORTAG_BYTES:
        zeilen = zeilen[1:]                  # erste Zeile ist angeschnitten
    for zeile in zeilen:
        try:
            d = json.loads(zeile)
            lauf = datetime.fromisoformat(d["lauf"])
        except (ValueError, KeyError, TypeError):
            continue
        if lauf < von - timedelta(hours=31) or lauf > bis:
            continue
        for name, pk in (d.get("punkte") or {}).items():
            if name not in namen:
                continue
            try:
                t0 = datetime.fromisoformat(pk["t0"])
            except (KeyError, ValueError, TypeError):
                continue
            ws = pk.get("ws") or {}
            n = max((len(v) for v in ws.values()), default=0)
            for i in range(n):
                t = t0 + timedelta(hours=i)
                vor = (t - lauf).total_seconds() / 3600
                if not (von <= t <= bis) or not (18 <= vor <= 30):
                    continue
                werte = [v[i] for v in ws.values() if i < len(v) and v[i] is not None]
                if werte and ((name, t) not in beste or abs(vor - 24) < beste[(name, t)][0]):
                    beste[(name, t)] = (abs(vor - 24), sum(werte) / len(werte))
    aus: Dict[str, Dict[datetime, float]] = {}
    for (name, t), (_a, w) in beste.items():
        aus.setdefault(name, {})[t] = w
    return aus


_VORTAG: Optional[Dict[str, Dict[datetime, float]]] = None


def vortag_cache(jetzt: datetime) -> Dict[str, Dict[datetime, float]]:
    global _VORTAG
    if _VORTAG is None:
        namen = {r["name"] for jc in JETZT_ALLE.values() for r in jc}
        _VORTAG = vortag_prognosen(namen, jetzt - timedelta(hours=VERLAUF_STUNDEN), jetzt) if namen else {}
    return _VORTAG


def svg_messverlauf(r: dict, jetzt: datetime, min_kn: float, key: str) -> Tuple[str, list]:
    """Messung der letzten VERLAUF_STUNDEN (Mittel, Böen), gestrichelt die Vortags-Vorhersage, danach 24 h Vorhersage."""
    reihe = r.get("reihe") or {}
    od = r.get("od")
    t0 = (jetzt - timedelta(hours=VERLAUF_STUNDEN)).replace(minute=0, second=0, microsecond=0)
    t1 = jetzt + timedelta(hours=24)
    mess = sorted((t, v) for t, v in reihe.items() if t0 <= t <= jetzt and v and v[0] is not None)
    if len(mess) < 3:
        return "", []
    vort = {t: w for t, w in vortag_cache(jetzt).get(r["name"], {}).items() if t0 <= t <= jetzt}
    zuk = [st for st in (od.stunden if od else []) if jetzt - timedelta(minutes=30) <= st.t <= t1]
    W, H, L, Rr, T, B = 1000, 250, 42, 14, 34, 30
    span = (t1 - t0).total_seconds()
    werte = [v[0] for _t, v in mess] + [v[1] for _t, v in mess if v[1] is not None] + list(vort.values()) + \
        [st.ws for st in zuk]
    ymax = int(math.ceil(max(25, max(werte) + 3) / 5) * 5)

    def x(t):
        return L + (t - t0).total_seconds() / span * (W - L - Rr)

    def y(v):
        return H - B - v / ymax * (H - T - B)

    teile = [f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Messverlauf">']
    if od is not None:
        tag = t0.date()
        while tag <= t1.date():
            sr, ss = sonnenzeiten(od, tag)
            for a, b in [(datetime.combine(tag, time(0)), sr), (ss, datetime.combine(tag, time(0)) + timedelta(days=1))]:
                a, b = max(a, t0), min(b, t1)
                if b > a:
                    teile.append(f'<rect x="{x(a):.1f}" y="{T}" width="{x(b) - x(a):.1f}" height="{H - T - B}" class="nacht"/>')
            tag += timedelta(days=1)
    for v in range(0, ymax + 1, 10):
        teile.append(f'<line x1="{L}" x2="{W - Rr}" y1="{y(v):.1f}" y2="{y(v):.1f}" class="grid"/>')
        teile.append(f'<text x="{L - 6}" y="{y(v) + 4:.1f}" class="achse" text-anchor="end">{v}</text>')
    teile.append(f'<text x="{L - 6}" y="{T - 18}" class="achse" text-anchor="end">kn</text>')
    tag = t0.date() + timedelta(days=1)
    while datetime.combine(tag, time(0)) <= t1:
        xm = x(datetime.combine(tag, time(0)))
        teile.append(f'<line x1="{xm:.1f}" x2="{xm:.1f}" y1="{T}" y2="{H - B}" class="tagesgrenze"/>')
        tag += timedelta(days=1)
    tag = t0.date()
    while tag <= t1.date():
        mittag = datetime.combine(tag, time(12))
        if t0 <= mittag <= t1:
            teile.append(f'<text x="{x(mittag):.1f}" y="{H - 10}" class="achse" text-anchor="middle">{tag_text(tag)}</text>')
        tag += timedelta(days=1)
    teile.append(f'<line x1="{L}" x2="{W - Rr}" y1="{y(min_kn):.1f}" y2="{y(min_kn):.1f}" class="schwelle"/>')
    xj = x(jetzt)
    teile.append(f'<line x1="{xj:.1f}" x2="{xj:.1f}" y1="{T - 4}" y2="{H - B}" class="jetzt-linie"/>'
                 f'<text x="{xj + 4:.1f}" y="{T + 10}" class="achse">jetzt</text>')
    # Vortags-Vorhersage (gestrichelt), Böen, Mittel, aktuelle Vorhersage
    vs = sorted(vort.items())
    if len(vs) >= 2:
        teile.append('<polyline points="' + " ".join(f"{x(t):.1f},{y(w):.1f}" for t, w in vs)
                     + '" class="linie vortag"/>')
    bo = [(t, v[1]) for t, v in mess if v[1] is not None]
    if len(bo) >= 2:
        teile.append('<polyline points="' + " ".join(f"{x(t):.1f},{y(w):.1f}" for t, w in bo)
                     + '" class="linie boeen"/>')
    teile.append('<polyline points="' + " ".join(f"{x(t):.1f},{y(v[0]):.1f}" for t, v in mess)
                 + '" class="linie mittel"/>')
    if len(zuk) >= 2:
        teile.append('<polyline points="' + " ".join(f"{x(st.t):.1f},{y(st.ws):.1f}" for st in zuk)
                     + '" class="linie prognose"/>')
    # Richtungspfeile alle 3 h (gemessen, danach Vorhersage)
    for t, v in mess:
        if t.minute == 0 and t.hour % 3 == 0 and v[2] is not None:
            teile.append(f'<g transform="translate({x(t):.1f},{T - 14}) rotate({v[2]:.0f})">'
                         f'<path d="M0,6 L-3.5,-4 L0,-2 L3.5,-4 Z" class="pfeil"/></g>')
    for st in zuk:
        if st.t.hour % 3 == 0 and st.t > jetzt:
            teile.append(f'<g transform="translate({x(st.t):.1f},{T - 14}) rotate({st.wd:.0f})" opacity=".45">'
                         f'<path d="M0,6 L-3.5,-4 L0,-2 L3.5,-4 Z" class="pfeil"/></g>')
    teile.append(f'<line x1="0" x2="0" y1="{T}" y2="{H - B}" class="kreuz" visibility="hidden"/>')
    teile.append(f'<rect class="hov" data-key="{key}" x="{L}" y="0" width="{W - L - Rr}" height="{H}" fill="transparent"/>')
    teile.append("</svg>")
    punkte = []
    for t, v in mess:
        if t.minute:
            continue
        h = f"<b>{tag_text(t.date())} {t:%H} Uhr</b><br>gemessen {v[0]:.0f} kn"
        if v[1] is not None:
            h += f" · Böen {v[1]:.0f}"
        if v[2] is not None:
            h += f" · {kompass(v[2])}"
        if t in vort:
            h += f"<br>am Vortag vorhergesagt {vort[t]:.0f} kn"
        punkte.append({"x": round(x(t), 1), "h": h})
    for st in zuk:
        if st.t > jetzt:
            punkte.append({"x": round(x(st.t), 1),
                           "h": f"<b>{tag_text(st.t.date())} {st.t:%H} Uhr</b><br>Vorhersage {st.ws:.0f} kn · {kompass(st.wd)}"})
    return "".join(teile), punkte


MV_LEGENDE = ('<div class="legende"><span><i class="strich" style="background:var(--series-1)"></i>gemessen</span>'
              '<span><i class="strich" style="background:var(--series-2)"></i>Böen</span>'
              '<span><i class="strich mv-vt"></i>am Vortag vorhergesagt</span>'
              '<span><i class="strich mv-pg"></i>Vorhersage</span></div>')
MV_ERKL = ("Gemessener Mittelwind und Böen der letzten zwei Tage. Gestrichelt: was die Modelle etwa einen Tag vorher "
           "für diese Station vorhergesagt hatten (Mittel der Modelle, ohne Korrekturen) – so ist zu sehen, ob sie "
           "gerade zu stark oder zu schwach liegen. Rechts von „jetzt“ die aktuelle Vorhersage. Aktualisiert alle 3 Stunden.")


def mv_inhalt(svg: str) -> str:
    """Aufgeklappter Messverlauf unter einer Jetzt-Zeile: kurze Überschrift mit (i), Legende, Diagramm."""
    return (f'<div class="mv-k">Letzte 2 Tage{info_knopf(MV_ERKL)}</div>{MV_LEGENDE}'
            f'<div class="mv-svg">{svg}</div>')


def messverlauf_revier(rid: Optional[str], jetzt: datetime, min_kn: float, charts: dict) -> Dict[str, str]:
    """Revierseite: Messverlauf je Live-Station (Name → Inhalt), aufklappbar unter der jeweiligen Jetzt-Zeile.
    09.11.2026: vorher eigener Abschnitt „Messung der letzten 2 Tage“ – wirkte wie die Überschrift der Vorhersage."""
    aus: Dict[str, str] = {}
    for r in JETZT_ALLE.get(rid or "ostsee") or []:
        key = f"mv{len(aus)}"
        svg, pk = svg_messverlauf(r, jetzt, min_kn, key)
        if svg:
            charts[key] = pk
            aus[r["name"]] = mv_inhalt(svg)
    return aus


def messverlauf_spot_html(sp: "Spot", jetzt: datetime, min_kn: float, charts: dict) -> Tuple[str, str]:
    """Spotseite: Messverlauf der nächsten Live-Station (dieselbe wie in der Jetzt-Zeile) → (Stationsname, Inhalt)."""
    koord = {n: (la, lo) for n, la, lo, *_ in stationen_liste()}
    best = None
    for r in JETZT_ALLE.get(revier_von(sp)) or []:
        if r["name"] in koord and r.get("reihe"):
            km = _abstand_km(sp.lat, sp.lon, *koord[r["name"]])
            if km <= JETZT_SPOT_KM and (best is None or km < best[0]):
                best = (km, r)
    if not best:
        return "", ""
    svg, pk = svg_messverlauf(best[1], jetzt, min_kn, "mv")
    if not svg:
        return "", ""
    charts["mv"] = pk
    return best[1]["name"], mv_inhalt(svg)


def jetzt_wert_html(r: dict, min_kn: float, boeen: bool = True) -> str:
    """„21 kn ➘ WSW · Böen 26“ – Zahl ab der Gleitgrenze in der Blauskala (ohne Böen: kurz, ohne „kn“)."""
    gleit = r["kn"] >= min_kn
    stil = (lambda f: f' style="background:{f[0]};color:{f[1]}"')(blau_fuer(r["kn"])) if gleit else ""
    return (f'<b class="js-z{" gl" if gleit else ""}"{stil}>{r["kn"]:.0f}</b>{" kn" if boeen else ""} '
            f'{pfeil_svg(r["richtung"] or "", 12)}{e_txt(r["richtung"] or "")}'
            + (f' <span class="spj-b">· Böen {r["boe"]:.0f}</span>' if boeen and r.get("boe") else ""))


def spot_jetzt_html(sp: "Spot", min_kn: float, mv: Tuple[str, str] = ("", "")) -> str:
    """Spotseite: nächste Station mit zeitnaher Messung im selben Revier. mv = (Station, Messverlauf): passt die
    Station, klappt Antippen der Zeile den Verlauf darunter auf (09.11.2026)."""
    koord = {n: (la, lo) for n, la, lo, *_ in stationen_liste()}
    best = None
    for r in JETZT_ALLE.get(revier_von(sp)) or []:
        if r.get("kn") is None or r["name"] not in koord:
            continue
        km = _abstand_km(sp.lat, sp.lon, *koord[r["name"]])
        if km <= JETZT_SPOT_KM and (best is None or km < best[0]):
            best = (km, r)
    if not best:
        return ""
    km, r = best
    mit = bool(mv[1]) and mv[0] == r["name"]
    erkl = ("Gemessener Mittelwind an der nächsten Station mit aktuellen Werten, wird alle 10 Minuten erneuert. "
            "Die Station steht nicht am Spot – Richtung und Stärke können dort anders sein."
            + (" Antippen zeigt die Messung der letzten 2 Tage." if mit else ""))
    klapp = ' mv-z" role="button" tabindex="0" aria-expanded="false' if mit else ""
    return (f'<div class="sp-jetzt{klapp}" data-st="{e_txt(r["name"])}" data-t="{r["t"]:%Y-%m-%dT%H:%M}">'
            f'<span class="spj-t">Jetzt</span><span class="spj-w">{jetzt_wert_html(r, min_kn)}</span>'
            f'<span class="spj-n">{e_txt(jetzt_name(r["name"]))} · {km:.0f} km'
            f'<span class="js-alter" data-zeit="{r["t"]:%Y-%m-%dT%H:%M}"></span></span>{info_knopf(erkl)}</div>'
            + (f'<div class="mv-c solo" data-st="{e_txt(r["name"])}" hidden>{mv[1]}</div>' if mit else ""))


def revier_kurzsatz(ergebnisse, rid: str, jetzt: datetime) -> List[str]:
    """Revierseite (23.11.2026): ein Kurzsatz für heute und morgen – bester Spot, Wind, Zeit."""
    saetze = []
    for tag, liste, chancen in ergebnisse[:2]:
        wort = _tag_wort(tag, jetzt)
        b_, e, art = anzeige_wahl(rid, tag, liste, chancen)
        n = len([x for x in liste if revier_von(x.spot) == rid])
        if art == "gleit" and e is not None:
            w = b_.wind if b_ is not None else e.wind
            saetze.append(f"{wort} Gleitwind in {e.spot.name}: {w:.0f} kn aus {e.richtung}, {_zeit_spanne(e)} Uhr"
                          + (f" (und {n - 1} weitere Spots)." if n > 2 else " (und ein weiterer Spot)." if n == 2 else "."))
        elif art == "chance" and e is not None:
            saetze.append(f"{wort} nur einzelne Modelle mit Gleitwind ({e.spot.name}).")
        elif b_ is not None and not b_.vorbei:
            saetze.append(f"{wort} kein Gleitwind, am meisten Wind in {b_.spot.name} mit {b_.wind:.0f} kn aus {b_.richtung}"
                          + ("." if b_.passt else ", die Richtung passt dort aber nicht."))
    if not any(" Gleitwind in " in x for x in saetze):
        for tag, liste, chancen in ergebnisse[2:]:
            b_, e, art = anzeige_wahl(rid, tag, liste, chancen)
            if art == "gleit" and e is not None:
                saetze.append(f"Nächster Gleittag {tag_text(tag)} in {e.spot.name} mit {(b_ or e).wind:.0f} kn"
                              + (" (Tendenz)." if ist_tendenz(tag) else "."))
                break
        else:
            if len(ergebnisse) > 2:
                saetze.append(f"Bis {tag_text(ergebnisse[-1][0])} kein Gleittag in Sicht.")
    return saetze


def revier_tage_html(ergebnisse, rid: str, args, ref, daten_je_spot, ens_je, charts) -> str:
    """Revierseite (23.11.2026): Nächste Tage als Liste – eine Zeile je Tag (bester Spot, Wind, Zeit, Chance,
    Hinweise wie Föhn/Seewind); Antippen klappt die Spots des Tages auf. Ersetzt Tageskacheln + „Tage im Detail“."""
    zeilen = []
    for tag, liste, chancen in ergebnisse:
        b_, e, art = anzeige_wahl(rid, tag, liste, chancen)
        frei = WENN_FREI_R.get((tag, rid)) if not liste else None
        tend = ist_tendenz(tag)
        sw = SEEWIND_BADGE(tag, rid)
        extra = indikator_badges(rid, tag) + sw
        kopf = (f'<span class="tl-d"><b>{WOCHENTAGE[tag.weekday()]}</b> {tag.day}.'
                + ('<i class="ca">≈</i>' if tend else '') + '</span>')
        if e is not None:
            w = b_.wind if b_ is not None else e.wind
            r_ = b_.richtung if b_ is not None else e.richtung
            if art == "chance":
                kn = f'<span class="rt-kn ch">↑{w:.0f}</span>'
            else:
                bg, fg = blau_fuer(w)
                kn = f'<span class="rt-kn" style="background:{bg};color:{fg}">{"≈" if tend else ""}{w:.0f}</span>'
            w_ = gleit_wahrsch(e) if art == "gleit" else None
            g_txt = "Chance" if art == "chance" else f"{_zeit_spanne(e)} Uhr"
            name = e.spot.name
        else:
            r_ = b_.richtung if b_ is not None else ""
            kn = f'<span class="rt-kn leer">{"–" if b_ is None else f"{b_.wind:.0f}"}</span>'
            w_ = None
            g_txt = "heute vorbei" if (b_ is not None and b_.vorbei) else "–"
            name = (b_.spot.name if b_ is not None else "") + ("" if b_ is None or b_.passt else " · Richtung passt nicht")
        mitte = (f'<span class="rt-m"><span class="rt-sp">{e_txt(name)}</span>'
                 f'<span class="rt-r2">{pfeil_svg(r_, 10) if r_ else ""}{e_txt(r_)}'
                 + ('' if e is not None else ' · kein Gleitwind') + f'{extra}</span></span>')
        rechts = (f'<span class="tl-g {"ja" if art == "gleit" else "ch" if art == "chance" else "nein"}">{e_txt(g_txt)}</span>'
                  f'<span class="tl-p{" p" + str(w_["stufe"]) if w_ else ""}">{"" if not w_ else format(w_["p"] * 100, ".0f") + " %"}</span>')
        eintraege = ([(x, len(ref.modelle) > 1) for x in liste[:args.top]]
                     + [(c, True) for c in chancen[:args.top if not liste else 1]]
                     + ([(frei, len(ref.modelle) > 1)] if frei else []))
        if e is not None and liste and e is not liste[0]:
            eintraege = [(e, len(ref.modelle) > 1)] + [x for x in eintraege if x[0] is not e]
        innen = []
        for i_, (x, mehr_) in enumerate(eintraege):
            if i_ == SPOTS_SICHTBAR and len(eintraege) > SPOTS_SICHTBAR:
                n_w = len(eintraege) - SPOTS_SICHTBAR
                innen.append('<details class="ez-weitere"><summary>'
                             + ("1 weiterer Spot" if n_w == 1 else f"{n_w} weitere Spots") + '</summary>')
            prof = (tagesprofil_html(x.spot, (daten_je_spot or {}).get(x.spot.name), ens_je.get(x.spot.name), tag,
                                     args.min_kn, f"tp{tag:%Y%m%d}", charts,
                                     link=spot_datei(x.spot) + f"#tag-{tag:%Y%m%d}") if i_ == 0 else "")
            innen.append(spot_zeile_html(x, mehr_, profil=prof))
        if len(eintraege) > SPOTS_SICHTBAR:
            innen.append('</details>')
        sw_text = seewind_tag_text(tag, rid)
        if sw_text:
            innen.insert(0, f'<p class="rt-hinw">☀ {e_txt(sw_text)}</p>')
        if innen:
            zeilen.append(f'<details class="rtag{" tend" if tend else ""}" id="tag-{tag:%Y%m%d}"><summary>{kopf}{kn}{mitte}'
                          f'{rechts}</summary><div class="rtag-in">{"".join(innen)}</div></details>')
        else:
            zeilen.append(f'<div class="rtag leer{" tend" if tend else ""}" id="tag-{tag:%Y%m%d}"><div class="rtag-z">'
                          f'{kopf}{kn}{mitte}{rechts}</div></div>')
    erkl = ("Je Tag der beste Spot im Revier: Wind im windigsten 2-Stunden-Block, Zeit mit Gleitwind und wie "
            "wahrscheinlich er ist (gemessene Treffsicherheit der Modelle). Antippen zeigt alle Spots des Tages mit "
            "Stundenprofil, Segel und Hinweisen. ≈ = ab Tag " + str(TENDENZ_AB + 1) + " nur Tendenz."
            + treffer_text(rid))
    return f'<h2 id="empfehlungen">Nächste Tage{info_knopf(erkl)}</h2><div class="rtl">{"".join(zeilen)}</div>'


def SEEWIND_BADGE(tag: date, rid: str) -> str:
    sw_d = [b for (t_, n_), b in SEEWIND.items() if t_ == tag and
            revier_von(next(x for x in SPOTS if x.name == n_)) == rid]
    if not sw_d:
        return ""
    verst = any(b.get("art") == "verstaerkt" for b in sw_d)
    gut = max(b["stufe"] for b in sw_d) == 2
    return f'<span class="tb t-{"gut" if gut else "mog"}">☀ ' + ("Thermik +" if verst else "Seewind") + '</span>'


def html_seite(ref: OrtDaten, ergebnisse, raster, tage: List[date], args, quelle: str,
               jetzt: datetime, fahnen=None, jc=None, karten=None, rev: Optional[dict] = None,
               kopf_ref: Optional[OrtDaten] = None, startseite: str = "windsurf_spots.html",
               daten_je_spot: Optional[Dict[str, OrtDaten]] = None) -> str:
    rid = rev["id"] if rev else None
    if rev:
        im = lambda e: revier_von(e.spot) == rid
        ergebnisse = [(t, [e for e in l if im(e)], [c for c in ch if im(c)]) for t, l, ch in ergebnisse]
        fahnen = [f for f in (fahnen or []) if revier_von(f[0]) == rid]
        jc = JETZT_ALLE.get(rid) or (jc if rev.get("jetzt") else None)
    ens_je = {f[0].name: f[2] for f in (fahnen or [])}
    kopf_ref = kopf_ref or ref
    titel = ((f"{rev['name']} – Windvorhersage{' & Wind aktuell' if JETZT_ALLE.get(rid) else ''} · {MARKE}" if rev
              else MARKE) if OEFFENTLICH else
             "Windsurf-Spots" + (f" · {rev['name']}" if rev else ""))
    teile = ['<!doctype html><html lang="de"><head><meta charset="utf-8">',
             '<meta name="viewport" content="width=device-width,initial-scale=1">',
             f'<title>{e_txt(titel)}</title>'
             + (f'<meta name="description" content="{e_txt(revier_beschreibung(rev, rid))}">' if OEFFENTLICH else '')
             + (og_marker(next((l_[0] for _t, l_, _c in ergebnisse if l_), None)) if OEFFENTLICH and rev else '')
             + f'<meta name="theme-color" content="#0b2540"><style>{CSS}</style></head><body>',
             kopfleiste_html(rid, startseite,
                             rev["name"] if rev else (MARKE_UNTERTITEL if OEFFENTLICH else "Windsurf-Spots ab Achterwehr"),
                             jetzt, quelle + (f" · Spots ab {args.min_kn:.0f} kn Mittelwind" if OEFFENTLICH else
                                              f" · Gleitwind ab {args.min_kn:.0f} kn · Setup für 90 kg"),
                             f'<a href="{RECHTLICHES_DATEI}">Hinweise & Impressum</a>'
                             if OEFFENTLICH else "", rev["datei"] if rev else startseite),
             '<main>']
    teile.append("§jetzt")
    charts = {}
    mv_html = {}
    if jc:
        # 09.11.2026: Messverlauf je Station unter der jeweiligen Jetzt-Zeile (Antippen klappt auf)
        mv_html = messverlauf_revier(rid, jetzt, args.min_kn, charts) if OEFFENTLICH else {}
        teile.append(jetzt_abschnitt(jc, args.min_kn, rid=rid, mv=mv_html))

    # 1) Wind-Verlauf
    teile.append("§indikator")
    teile.append(indikator_html(rid, tage))
    teile.append("§verlauf")
    start = datetime.combine(tage[0], time(0))
    ende = datetime.combine(tage[-1], time(0)) + timedelta(days=1)
    mit_leuchtturm = (not rev or rev.get("jetzt")) and not mv_html
    if mit_leuchtturm:
        svg, punkte = svg_windverlauf(ref, start, ende, args.min_kn)
        charts["ref"] = punkte
        teile.append('<h2 id="leuchtturm">Kiel Leuchtturm' + info_knopf(
            "Modellmittel am Leuchtturm; Linie gestrichelt = Gleitwind-Schwelle, grau = Nacht.") + '</h2>')
        teile.append('<div class="legende"><span><i class="strich" style="background:var(--series-1)"></i>'
                     'Mittelwind</span><span><i class="strich" style="background:var(--series-2)"></i>'
                     'Böen</span></div>')
        teile.append(f'<div class="box">{svg}</div>')

    # 2) Heatmap Spots × Tage
    teile.append("§heatmap")
    mit_karten = {tag for tag, liste, chancen in ergebnisse if liste or chancen}
    teile.append('<details class="spots-klapp" id="uebersicht"><summary><h2><span class="pfeil-klapp">▸</span>'
                 'Alle Spots im Vergleich' + info_knopf(
        'Bester Block je Spot und Tag in kn mit Richtung und Startzeit; grau = kein Gleitwind.') + '</h2></summary>')
    skala = "".join(f'<i style="background:{b}"></i>' for b in BLAU)
    teile.append(f'<div class="skala">10 kn {skala} 34 kn</div>')
    teile.append('<div class="box"><table class="hm"><thead><tr><th class="spot">Spot</th>')
    for t in tage:
        ziel = f"#tag-{t:%Y%m%d}" if t in mit_karten else "#empfehlungen"
        teile.append(f'<th><a class="tag-link" href="{ziel}">{tag_text(t)}</a></th>')
    teile.append('</tr></thead><tbody>')
    spalten = len(tage) + 1
    im_rev = [s for s in SPOTS if not rev or revier_von(s) == rid]
    gruppen = list(dict.fromkeys(spot_gruppe(s) for s in im_rev))
    gruppen = [g for g in gruppen if g != "Für später"] + (["Für später"] if "Für später" in gruppen else [])
    for gruppe in gruppen:
        spots = [s for s in im_rev if spot_gruppe(s) == gruppe]
        if not spots:
            continue
        if gruppe == "Für später":
            teile.append(f'<tr class="gruppe klapp" data-klapp="spaeter"><td colspan="{spalten}">'
                         f'<span class="pfeil-klapp">▸</span> {gruppe} ({len(spots)} Spots) – antippen zum Aufklappen'
                         f'</td></tr>')
        else:
            if len(gruppen) > 1:
                teile.append(f'<tr class="gruppe"><td colspan="{spalten}">{e_txt(gruppe)}</td></tr>')
        for s in spots:
            zeile_klasse = ' class="spaeter zu"' if gruppe == "Für später" else ""
            teile.append(f'<tr{zeile_klasse} id="spot-{spot_slug(s.name)}"><td class="name">'
                         f'<a href="{spot_datei(s)}">{e_txt(s.name)}</a></td>'
                         )
            for t in tage:
                e, ch = raster[(s.name, t)]
                tw = TAGESWIND.get((s.name, t)) or {}
                b_ = tw.get("passt") or tw.get("alle")
                if e is None and ch is None:
                    if b_ is None:
                        teile.append('<td class="zelle leer">·</td>')
                    else:
                        tip_r = (f"<b>{e_txt(s.name)}</b> · {tag_text(t)}<br>Kein Gleitwind · bester Wind "
                                 f"{b_.wind:.0f} kn {e_txt(b_.richtung)} · {b_.start:%H}–{b_.ende:%H} Uhr"
                                 + (" (heute schon vorbei)" if b_.vorbei else "")
                                 + ("" if b_.passt else " · Richtung passt hier nicht"))
                        teile.append(f'<td class="zelle leer ruhig{"" if b_.passt else " fremd"}" '
                                     f'data-tip="{e_txt(tip_r)}">{b_.wind:.0f}<small>{e_txt(b_.richtung)} '
                                     f'{b_.start:%H}h</small></td>')
                    continue
                if e is not None:
                    bg, fg = blau_fuer(e.wind)
                    gut = e.wind >= args.min_kn and (e.stufe <= DEINE_STUFE or args.alle)
                    klasse = "gut" if gut else ("" if e.wind >= args.min_kn else "knapp")
                    haupt, klein = f"{e.wind:.0f}", f"{e.richtung} {e.sp_start:%H}h"
                else:
                    bg, fg, klasse, klein = "var(--surface-2)", "var(--text-secondary)", "", ""
                    haupt = f"{b_.wind:.0f}" if b_ else "–"
                if ch is not None:
                    klasse += " chance"
                    bester = modell_zelle(ch.modelle_ok[0]) if ch.modelle_ok else ""
                    klein = f"↑{ch.wind:.0f} {bester} {ch.sp_start:%H}h".strip()
                tip = kachel_tip(e, ch, s.name, t, args.min_kn)
                if args.werktags_ab is not None and ist_arbeitstag(t):
                    klasse += " arbeit"
                teile.append(f'<td class="zelle {klasse}" style="background:{bg};color:{fg}" '
                             f'data-tip="{e_txt(tip)}">{haupt}<small>{e_txt(klein)}</small></td>')
            teile.append('</tr>')
    teile.append('</tbody></table></div></details>')

    # Wind-Player (eigene Daten von DMI/MET); ohne Daten ersatzweise Windy
    teile.append("§player")
    wp_html, wp_skript = wind_player_html(karten, jetzt, reg=rid or "ostsee",
                                          titel="Wind-Karte" if OEFFENTLICH else "Wind-Player")
    if wp_html or OEFFENTLICH:                                            # öffentlich: kein Windy-iframe
        teile.append(wp_html)
    elif rev and not rev.get("karte"):
        # Revier ohne eigene Karte (spart Open-Meteo-Abrufe): Windy, zentriert auf den Referenzspot
        sp_r = next((x for x in SPOTS if x.name == rev.get("referenz")), None) or \
            next((x for x in SPOTS if revier_von(x) == rid), None)
        if sp_r:
            teile.append(windkarte_html(
                {"lat": sp_r.lat, "lon": sp_r.lon, "zoom": 10, "modelle": [("ECMWF", "ecmwf"), ("ICON-EU", "iconEu")]},
                [("Windy", f"https://www.windy.com/{sp_r.lat:.2f}/{sp_r.lon:.2f}?wind,{sp_r.lat:.2f},{sp_r.lon:.2f},10")]))
    else:
        teile.append(windkarte_html())

    # 3) Rauchfahnen für die Hauptspots
    teile.append("§fahnen")
    if fahnen and FAHNEN_AUF_REVIERSEITE:       # seit 02.11.2026 je Spot auf der Spotseite
        start_f = max(start, jetzt.replace(minute=0, second=0, microsecond=0) - timedelta(hours=3))
        hat_ens = any(q for _, _, q in fahnen)
        teile.append('<h2 id="modelle">Modelle je Spot</h2>')    # (i) wird unten nach der Legende ergänzt
        legende = ['<span><i class="strich" style="background:var(--text-primary)"></i>Mittel</span>']
        gesehen = []
        for _, d, _ in fahnen:
            for m in d.modelle:
                if m not in gesehen:
                    gesehen.append(m)
        for m in gesehen:
            legende.append(f'<span><i class="strich" style="background:{MODELL_FARBE.get(m, "#8f8e86")}">'
                           f'</i>{e_txt(MODELL_KURZ.get(m, m))}</span>')
        if hat_ens:
            legende.append('<span><i class="strich" style="background:var(--series-1);opacity:.35;height:10px">'
                           f'</i>Ensemble 10–90 % (hell: min–max) · gestrichelt Median</span>')
        teile.append(f'<div class="legende">{"".join(legende)}</div>')
        teile[-2] = teile[-2].replace('</h2>', info_knopf(
            'Jede Linie ein Modell, fett das Mittel, Band = Spanne der Ensemble-Rechnungen.') + '</h2>')
        teile.append('<div class="fahne">')
        ym = fahne_ymax([v for _, d, q in fahnen for s_ in d.stunden if start_f <= s_.t < ende
                         for v in list(s_.werte.values()) + ([q[s_.t][3]] if s_.t in q else [])])
        # Zuerst der Spot, der in den nächsten Tagen am häufigsten vorn liegt; die übrigen eingeklappt
        namen = [sp.name for sp, _, _ in fahnen]
        vorn = [l[0].spot.name for _, l, _ in ergebnisse if l and l[0].spot.name in namen]
        haupt = max(namen, key=lambda n: (vorn.count(n), -namen.index(n))) if vorn else namen[0]
        reihe = sorted(enumerate(fahnen), key=lambda x: x[1][0].name != haupt)
        weitere = 0
        for k_, (i, (sp, d, q)) in enumerate(reihe):
            svg_f, p_f = svg_fahne(sp, d, q, start_f, ende, args.min_kn, f"f{i}", ym)
            if not svg_f:
                continue
            charts[f"f{i}"] = p_f
            if k_ == 1:
                teile.append(f'<details class="fahne-mehr"><summary>§WEITERE§</summary>')
            weitere += k_ >= 1
            teile.append(f'<h3>{e_txt(sp.name)} <span>· '
                         + f'{e_txt(richtung_text(sp.richtungen))}</span> <span class="links">{links_html(sp)}</span></h3>'
                         f'<div class="box">{svg_f}</div>')
        if weitere:
            teile.append('</details>')
            i_w = max(i for i, t_ in enumerate(teile) if isinstance(t_, str) and "§WEITERE§" in t_)
            teile[i_w] = teile[i_w].replace("§WEITERE§", f'<span class="pfeil-klapp">▸</span> Weitere Spots ({weitere})')
        teile.append('</div>')

    # 4) Empfehlungen: kompakte Karten, nur Tage mit Wind
    teile.append("§emp")
    if OEFFENTLICH and rev:      # 23.11.2026: eine Zeile je Tag statt Kacheln + „Tage im Detail“
        teile.append(revier_tage_html(ergebnisse, rid, args, ref, daten_je_spot, ens_je, charts))
    else:
        teile.append('<h2 id="empfehlungen">Tage im Detail' + info_knopf(
            ('Die besten Spots je Tag – Antippen zeigt Stunde für Stunde, Warnungen und Details. Blass = unsicher '
             '(unter 60 %).' if OEFFENTLICH else
             'Die besten Spots je Tag; die Leiste zeigt Stunde für Stunde Wind und passendes Segel.')
            + (treffer_text(rid) if OEFFENTLICH else '')) + '</h2><div class="tage-liste">')
        leer = []
        erster_offen = next((t for t, l, _ in ergebnisse if l), None)
        for tag, liste, chancen in ergebnisse:
            sw_text = seewind_tag_text(tag, rid)
            frei = (WENN_FREI_R.get((tag, rid)) if rev else WENN_FREI.get(tag)) if not liste else None
            if not liste and not chancen and not sw_text and not frei:
                leer.append(tag_text(tag))
                continue
            kopf = tageskopf(kopf_ref, tag)
            kopf_kurz = " · ".join(x for x in kopf.split(" · ") if not re.match(r"\d+ Modelle", x))
            kopf_mod = " · ".join(x for x in kopf.split(" · ") if re.match(r"\d+ Modelle", x))
            label = (f'<b>{tag_text(tag)}</b><span title="{e_txt(kopf_mod)}">{e_txt(kopf_kurz)}</span>'
                     + (f'<span class="sw">☀ {e_txt(sw_text)}</span>' if sw_text else ''))
            if tag != erster_offen:
                # Nur der nächste Gleittag ist aufgeklappt; die übrigen öffnen sich per Tipp auf Zeile oder Kachel
                bw_, ew_, _ = anzeige_wahl(rid, tag, liste, chancen)
                b_ = ew_ if ew_ is not None else (frei if not liste and not chancen else None)
                w_ = gleit_wahrsch(b_) if b_ is not None and liste else None
                kurz = ""
                if b_ is not None:
                    w_anz = bw_.wind if bw_ is not None else b_.wind
                    kurz = (f'<span class="tk-b">{"" if liste else ("Chance · " if chancen else "frei · ")}'
                            f'{e_txt(b_.spot.name)} <b>{w_anz:.0f} kn</b></span>'
                            + (f'<span class="ts-p p{w_["stufe"]}">{w_["wort"]} · {w_["p"] * 100:.0f} %</span>'
                               if w_ else ''))
                teile.append(f'<details class="tag-klapp" id="tag-{tag:%Y%m%d}"><summary class="tag-label">'
                             f'<span class="pfeil-klapp">▸</span>{label}{kurz}</summary>'
                             '<div class="tag-zeile"><div class="emp-liste">')
                ende_tag = "</div></div></details>"
            else:
                teile.append(f'<div class="tag-zeile" id="tag-{tag:%Y%m%d}"><div class="tag-label">{label}'
                             '</div><div class="emp-liste">')
                ende_tag = "</div></div>"
            _, vorn_, _ = anzeige_wahl(rid, tag, liste, [])
            if vorn_ is not None and liste and vorn_ is not liste[0]:   # gleicher Spot vorn wie in der Tageskachel
                liste = [vorn_] + [x for x in liste if x is not vorn_]
            eintraege = ([(e, len(ref.modelle) > 1) for e in liste[:args.top]]
                         + [(c, True) for c in chancen[:args.top if not liste else 1]]
                         + ([(frei, len(ref.modelle) > 1)] if frei else []))
            if OEFFENTLICH:       # 08.11.2026: eine Zeile je Spot, Antippen klappt die Karte auf; ab dem 4. unter „weitere“
                for i_, (e, mehr_) in enumerate(eintraege):
                    if i_ == SPOTS_SICHTBAR and len(eintraege) > SPOTS_SICHTBAR:
                        n_w = len(eintraege) - SPOTS_SICHTBAR
                        teile.append(f'<details class="ez-weitere"><summary>'
                                     + ("1 weiterer Spot" if n_w == 1 else f"{n_w} weitere Spots") + '</summary>')
                    # 15.11.2026: Tagesprofil in kn beim ersten Spot des Tages (die Tageskachel klappt genau ihn auf);
                    # bei den übrigen nicht – sonst wird die Seite zu schwer (dort führt die Spotseite weiter)
                    prof = (tagesprofil_html(e.spot, (daten_je_spot or {}).get(e.spot.name), ens_je.get(e.spot.name),
                                             tag, args.min_kn, f"tp{tag:%Y%m%d}", charts, link=spot_datei(e.spot) +
                                             f"#tag-{tag:%Y%m%d}") if i_ == 0 else "")
                    teile.append(spot_zeile_html(e, mehr_, profil=prof))
                if len(eintraege) > SPOTS_SICHTBAR:
                    teile.append('</details>')
            else:
                for e, mehr_ in eintraege:
                    teile.append(karte_html(e, mehr_))
            teile.append(ende_tag)
        teile.append('</div>')
    teile.append("§saison")
    if rev:
        teile.append(klima_revier_html(rid))
    teile.append("§fuss")
    teile.append(f'<p class="fuss">Ab Tag {TENDENZ_AB + 1} nur noch Tendenz'
                 + (' · die Seite wird etwa alle 3 Stunden neu berechnet' if OEFFENTLICH else '')
                 + f'<br>{e_txt(quelle)} · Stand {jetzt:%d.%m.%Y %H:%M} · <a href="{METHODIK_DATEI}">Wie das Tool '
                   f'rechnet</a>{fuss_recht()}</p>')
    teile.append("§ende")
    teile.append('</main><div id="tip"></div>')
    teile.append(f'<script>const CHARTS={json.dumps(charts)};{JS}</script>{wp_skript}'
                 f'{tabbar_html("Spots", mit_karte=bool(wp_html))}</body></html>')
    # Reihenfolge für die Nutzung: erst die Antwort (Überblick, Empfehlungen), dann Übersicht und Details
    teile_d: Dict[str, list] = {"kopf": []}
    akt = "kopf"
    for t_ in teile:
        if isinstance(t_, str) and t_.startswith("§"):
            akt = t_[1:]
            teile_d.setdefault(akt, [])
            continue
        teile_d[akt].append(t_)
    nav = [("empfehlungen", "Tage"), ("uebersicht", "Alle Spots"),
           ("wp" if wp_html else ("" if OEFFENTLICH else "windkarte"), "Karte"),
           ("modelle", "Modelle"), ("leuchtturm" if mit_leuchtturm else "", "Leuchtturm"),
           ("saison" if rev and 'id="saison"' in "".join(teile_d.get("saison", [])) else "", "Saison")]
    if jc:
        nav.insert(0, ("jetzt", "Jetzt"))
    if 'id="indikator"' in "".join(teile_d.get("indikator", [])):
        nav.insert(2 if jc else 1, ("indikator", indikator_name(rid, "/")))
    nav = [(i, n) for i, n in nav if i and (i != "modelle" or (fahnen and FAHNEN_AUF_REVIERSEITE))]
    haupt = [x for x in nav if x[0] in NAV_HAUPT]
    rest = [x for x in nav if x[0] not in NAV_HAUPT]
    nav_html = ('<nav class="sprung">' + "".join(f'<a href="#{i}">{e_txt(n)}</a>' for i, n in haupt)
                + ('<button type="button" class="nav-mehr" aria-expanded="false">Mehr</button>'
                   + "".join(f'<a class="nb" href="#{i}">{e_txt(n)}</a>' for i, n in rest)
                   + f'<a class="nb" href="{SAISON_DATEI}#r-{rid}">Saison je Monat</a>'
                   + f'<a class="nb" href="{METHODIK_DATEI}">Methode</a>' if rest else '')
                + '</nav>')
    # 08.11.2026: „Jetzt“ direkt unter die Gleitgrenze, vor die Tage – am Strand ist das die erste Frage
    # 14.11.2026: Karte direkt unter die Tageskacheln (vorher unten in „Mehr zum Revier“ – kaum gefunden)
    reihen = ["kopf", "nav", "gw", "jetzt", "kurz", "player", "indikator", "emp", "verlauf", "heatmap", "saison",
              "fuss", "ende"]
    if OEFFENTLICH and rev:
        # 23.11.2026 (Anforderungen 1–2): erst die Antwort (Kurzsatz), Jetzt, amtliche Warnungen, Grenze, Nächste Tage
        # als Liste, dann alle Spots im Vergleich, Föhn/Thermik, Karte (am Handy im Reiter „Karte“), Mehr zum Revier.
        # Die Sprungleiste und die Tageskacheln entfallen (doppelt zu Liste bzw. unterer Leiste).
        reihen = ["kopf", "satz", "jetzt", "amtlich", "gw", "emp", "heatmap", "indikator", "player", "verlauf",
                  "reviere", "fuss", "ende"]
        satz_ = revier_kurzsatz(ergebnisse, rid, jetzt)
        teile_d["satz"] = (['<p class="kurzsatz">' + " ".join(f"<span>{e_txt(x)}</span>" for x in satz_) + '</p>']
                           if satz_ else [])
        teile_d["amtlich"] = [amtliche_warnungen_html(warnungen_fuer_revier(rid))]
        teile_d["reviere"] = [reviere_tab_html(rid)]
    teile_d["nav"] = [nav_html]
    teile_d["gw"] = [gw_leiste_html(rev["datei"] if rev else startseite)]
    if OEFFENTLICH and rev:               # 23.11.2026: die große Frage nur auf der Startseite
        teile_d["gw"] = [teile_d["gw"][0].replace('<div class="gw-leiste">', '<div class="gw-leiste gw-schmal">')]
    teile_d["kurz"] = [tagesstreifen_html(ergebnisse, rid)] + ([] if OEFFENTLICH else [treffer_html(rid)])
    # 08.11.2026: Messstation, Spot-Vergleich und Saison zusammen unter „Mehr zum Revier“ (öffentlich);
    # 14.11.2026: die Karte nicht mehr – sie steht offen unter den Tageskacheln
    if OEFFENTLICH and rev:
        # 23.11.2026: „Alle Spots im Vergleich“ steht offen über der Karte (Weg zur Spotvorhersage); unter „Mehr zum
        # Revier“ bleiben Messstation und Saison
        teile_d["heatmap"] = [x.replace('<details class="spots-klapp" id="uebersicht">',
                                        '<details class="spots-klapp" id="uebersicht" open>', 1)
                              for x in teile_d.get("heatmap", [])]
        innen = "".join(x for k in ("verlauf", "saison") for x in teile_d.get(k, []))
        if innen.strip():
            was = [n for k, n in (("verlauf", "Leuchtturm"), ("saison", "Saison"))
                   if "".join(teile_d.get(k, [])).strip()]
            teile_d["verlauf"] = [f'<details class="mehr-revier" id="mehr"><summary><h2>Mehr zum Revier</h2>'
                                  f'<span class="mr-was">{e_txt(" · ".join(was))}</span></summary>{innen}</details>']
            teile_d["saison"] = []
    return "".join(x for k in reihen for x in teile_d.get(k, []))


# =============================================================================
# KALIBRIERUNG: Korrektur nach Richtung, Stabilität und Windstärke aus Archivdaten
# =============================================================================
#
# Idee: Die Modelle (13 km … 2 km) lösen Küstengradient, Düsen und Schichtung nicht auf. Aus Jahren
# von Modell-Archivdaten und DWD-Messungen lässt sich lernen, wie stark das Modellmittel je
# Windrichtung, Stabilität (Lufttemperatur minus Wassertemperatur) und Windstärke daneben liegt.
# Gelernt werden nur RELATIVE Faktoren (Messung/Modell geteilt durch den Gesamtwert der Station),
# weil die Station höher misst (Leuchtturm) und in einer anderen Gitterzelle liegt als der Spot.
# Jeder Faktor wird zur Null hin gezogen (Shrinkage), wenn wenige Stunden dahinterstehen, und an
# nicht gesehenen Wochen geprüft (4-fach Blockvalidierung). Nur was dort besser wird, wird benutzt.

API_HIST = "https://historical-forecast-api.open-meteo.com/v1/forecast"
KALIB_DATEI = Path(__file__).resolve().parent / "kalibrierung.json"
KALIB_ROHDATEN = Path(__file__).resolve().parent / "kalibrierung_rohdaten.json"
KALIB_MODELLE = "icon_seamless,ecmwf_ifs025,gfs_seamless"   # Modelle des Archivs (Mittelwert)
KALIB_ANWENDEN = True          # --keine-kalib schaltet für einen Lauf ab
KALIB_STAB_GRENZEN = (-1.0, 1.0)   # Luft − Wasser in K: unter −1 labil, über +1 stabil
STAB_NAMEN = ("labil", "neutral", "stabil")
KALIB_WIND_KLASSEN = (12.0, 18.0)  # Modellwind in kn: unter 12 / 12–18 / ab 18
KALIB_MIN_MODELL_KN = 8.0      # nur Stunden, die für dich eine Rolle spielen
KALIB_K = 30                   # Shrinkage: so viele Stunden zählen wie „Vorwissen = kein Effekt“
KALIB_MIN_N = 300              # weniger Stunden: keine Kalibrierung
KALIB_MIN_GEWINN = 0.03        # Wirkung erst ab 3 % kleinerem MAE an ungesehenen Wochen
KALIB_REICHWEITE_KM = 25       # nur für die Kandidatenliste im Bericht
KALIB_GRENZEN = (0.8, 1.3)     # ein Faktor bleibt in diesem Bereich
KALIB_SAISON = True            # Stabilität relativ zum Monatsmittel von Luft−Wasser (trennt Schichtung von Jahreszeit)
KALIB_STAB_ANWENDEN = True     # False: nur Richtung × Windklasse anwenden, den Stabilitätsterm weglassen
KALIB_MONAT_ANWENDEN = False   # den Jahresgang des Stationsfaktors (Bewuchs, Messhöhe) NICHT auf Spots übertragen
KALIB: Dict[str, dict] = {}    # wird in main() aus kalibrierung.json geladen
# Welche Spots die Faktoren welcher Station bekommen – bewusst von Hand, weil die Faktoren auch den
# Standort der Station enthalten (Land/Wasser-Anströmung) und nur für Spots passen, deren Umgebung
# der Station ähnelt. Leer = die Kalibrierung ändert nichts; --kalibrieren schlägt Kandidaten vor.
# Beispiel: {"Westerbergen/Lemkenhafen": "Fehmarn", "Laboe": "Kiel Leuchtturm"}
KALIB_SPOTS: Dict[str, str] = {s: "Kiel Leuchtturm" for s in
    ("Heidkate", "Dänisch-Nienhof", "Laboe", "Schönberger Strand", "Kalifornien", "Brasilien")}
# 08.11.2026: Bülk (3 km neben dem Leuchtturm) und Stein (zwischen Laboe und Heidkate) – gleiche Anströmung wie die
# übrigen Probstei-Spots. Das Wasser-Niveau (WASSER_NIVEAU_SPOTS) bekommen sie erst mit einem Beleg aus dem Logbuch.
KALIB_SPOTS.update({"Bülk": "Kiel Leuchtturm", "Stein": "Kiel Leuchtturm"})
KALIB_SPOTS["Kegnæs (DK)"] = "DMI Kegnæs"          # Station 2 km entfernt, gleiche Landzunge
# --kalibrieren --revier westkueste (27.10.2026): Station 4 km vom Spot, gleiche Küste; MAE −26 % an ungesehenen Wochen.
# Auflandig (WSW–NNW) ×1,05–1,09, ablandig (ONO–S) ×0,8–0,85 – Landwind kommt am Strand schwächer an.
KALIB_SPOTS["St. Peter-Ording"] = "DWD St. Peter-Ording"
# Hvide Sande: Station 1,7 km vom Spot auf der Nehrung zwischen Meer und Fjord; MAE −32 %. W/WNW ×0,84–0,86 (Wind
# kommt über Nehrung und Ort), O–S ×1,1–1,2 (über den offenen Fjord unterschätzt). Rømø: Juvre 8 km, MAE −9 %, ±8 %.
# Hanstholm/Klitmøller bewusst nicht: Station auf dem Plateau, N–ONO ×1,1–1,14 passt kaum zum Strand.
KALIB_SPOTS["Hvide Sande Fjord (DK)"] = "DMI Hvide Sande"
KALIB_SPOTS["Rømø (DK)"] = "DMI Rømø/Juvre"
# Bodensee (--klima-check 27.10.2026): Steckborn misst 42 Gleitwindtage/Jahr, das Modell zeigt dort 7 – die
# Kanalisierung längs des Untersees fehlt. Für Reichenau Sandseele (5 km östlich, gleiches Becken) wird deshalb das
# Modell AM SPOT (Wasserzelle wie im Livelauf) gegen die Messung in Steckborn gelernt, und auch das Gesamtniveau
# angewandt (SwissMetNet misst in 10 m, kein Leuchtturm). Wirkt nur, wenn es an ungesehenen Wochen besser wird.
KALIB_SPOTS["Reichenau Sandseele"] = "MeteoSwiss Steckborn"
# Ergebnis --kalibrieren 27.10.2026: Niveau ×1,26 (Modell am Spot), Gesamtwirkung an ungesehenen Wochen MAE 3,39 → 2,33 kn
# (−31 %), Bias −2,83 → +0,12 kn. Gleitwindtage Steckborn gemessen 43/Jahr, Modell am Spot 9, kalibriert 32.
# Hard/Rohrspitz: Altenrhein 5 km, gleiches Rheindelta; nur relative Faktoren (MAE −7,5 %, Süd/Föhn ×1,38 → Grenze 1,3).
KALIB_SPOTS["Hard/Rohrspitz (AT)"] = "MeteoSwiss Altenrhein"
# --kalibrieren --revier romandie (29.10.2026): Station Neuchâtel 2 km von St-Blaise, gleiche Lage am Nordostende;
# MAE −8,5 % an ungesehenen Wochen (Bise ONO ×1,08, Vent SSW ×0,91/WSW ×0,96). Nur relativ, kein Niveau.
KALIB_SPOTS["St-Blaise (CH)"] = "MeteoSwiss Neuchâtel"
# Station → Spot, an dessen Punkt (cell_selection=sea) das Modell für --kalibrieren geholt wird (sonst an der Station)
KALIB_MODELLPUNKT: Dict[str, str] = {"MeteoSwiss Steckborn": "Reichenau Sandseele", "AEMET Tarifa": "Los Lances"}
# Stationen, deren Gesamtwert Messung/Modell mit angewandt wird (sonst nur die relativen Faktoren)
# Tarifa (--kalibrieren 27.10.2026, GHCNh, nur April–Oktober 2026): Modell am Spot Los Lances gegen AEMET Tarifa
# Niveau ×1,03, Ost ×1,05, West ×0,83–0,94 (MAE −8 %). --klima-check: Gleitwindtage Apr–Okt gemessen 19/11/15/14/9/22/14,
# Modell 16/11/10/11/2/16/11 – das Modellmittel glättet die Spitzen (wie Steckborn). Nicht in KALIB_SPOTS: die Station steht am Ortsrand, bei West im
# Lee der Stadt – die West-Faktoren wären Lage der Station, nicht des Strandes; das Niveau passt ohnehin.
KALIB_NIVEAU = {"MeteoSwiss Steckborn", "AEMET Tarifa"}
KALIB_NIVEAU_GRENZEN = (0.7, 2.0)


def kalib_modellpunkt(name: str, lat: float, lon: float) -> Tuple[float, float, str]:
    """(Breite, Länge, Gitterzelle) für die Modellwerte einer Kalibrierstation."""
    sp = next((x for x in SPOTS if x.name == KALIB_MODELLPUNKT.get(name)), None)
    return (sp.lat, sp.lon, "sea") if sp else (lat, lon, "nearest")


def _med(werte: List[float]) -> float:
    return median(werte) if werte else 0.0


def kalib_klassen(wd: float, ws: float, dt: Optional[float]) -> Tuple[int, Optional[int], int]:
    """(Sektor 0–11 in 30°-Schritten um N, Stabilität 0–2 oder None, Windklasse 0–2)."""
    s = int(((wd + 15) % 360) // 30)
    b = None if dt is None else (0 if dt < KALIB_STAB_GRENZEN[0] else 1 if dt < KALIB_STAB_GRENZEN[1] else 2)
    k = 0 if ws < KALIB_WIND_KLASSEN[0] else 1 if ws < KALIB_WIND_KLASSEN[1] else 2
    return s, b, k


def kalib_dt_adj(tab: dict, dt: Optional[float], monat: Optional[int]) -> Optional[float]:
    """Luft−Wasser relativ zum Monatsmittel der Station (wenn Saisonbereinigung gelernt wurde)."""
    if dt is not None and monat and tab.get("dt_monat"):
        return dt - tab["dt_monat"][monat - 1]
    return dt


def kalib_lernen(zeilen: list, saison: Optional[bool] = None) -> Optional[dict]:
    """zeilen: (wd, modell_kn, luft−wasser oder None, messung_kn, monat 1–12). Log-Verhältnisse werden
    schrittweise zerlegt: Gesamtwert, Windklasse, [Monat], Sektor, Sektor×Stabilität – jeder Schritt zur
    Null hin gezogen. Mit saison=True gilt die Stabilität relativ zum Monatsmittel, und der Jahresgang
    des Verhältnisses steckt in einem eigenen Monatsterm, damit er nicht der Stabilität zugeschlagen wird."""
    saison = KALIB_SAISON if saison is None else saison
    ok = [z for z in zeilen if z[1] >= KALIB_MIN_MODELL_KN and z[3] >= 1.0]
    if len(ok) < KALIB_MIN_N:
        return None
    dt_monat = [0.0] * 12
    if saison:
        for m in range(12):
            v = [z[2] for z in ok if z[4] == m + 1 and z[2] is not None]
            dt_monat[m] = _med(v) if len(v) >= 50 else 0.0
    lr = [math.log(z[3] / z[1]) for z in ok]
    g = _med(lr)
    kl = [kalib_klassen(z[0], z[1], None if z[2] is None else z[2] - dt_monat[z[4] - 1]) for z in ok]
    res = [x - g for x in lr]
    speed = []
    for k in range(3):
        v = [r for r, c in zip(res, kl) if c[2] == k]
        speed.append(len(v) / (len(v) + KALIB_K) * _med(v))
    res = [r - speed[c[2]] for r, c in zip(res, kl)]
    monat = [0.0] * 12
    if saison:
        for m in range(12):
            v = [r for r, z in zip(res, ok) if z[4] == m + 1]
            monat[m] = len(v) / (len(v) + KALIB_K) * _med(v)
        res = [r - monat[z[4] - 1] for r, z in zip(res, ok)]
    sektor, n_sektor = [], []
    for s in range(12):
        v = [r for r, c in zip(res, kl) if c[0] == s]
        n_sektor.append(len(v))
        sektor.append(len(v) / (len(v) + KALIB_K) * _med(v))
    res = [r - sektor[c[0]] for r, c in zip(res, kl)]
    zelle, n_zelle = [], []
    for s in range(12):
        zr, nr = [], []
        for b in range(3):
            v = [r for r, c in zip(res, kl) if c[0] == s and c[1] == b]
            nr.append(len(v))
            zr.append(len(v) / (len(v) + KALIB_K) * _med(v))
        zelle.append(zr)
        n_zelle.append(nr)
    return {"n": len(ok), "g": g, "speed": speed, "sektor": sektor, "n_sektor": n_sektor,
            "zelle": zelle, "n_zelle": n_zelle, "monat": monat, "dt_monat": dt_monat if saison else [],
            "saison": saison}


def kalib_stab_effekt(tab: dict) -> Optional[float]:
    """Faktor „stabil gegenüber labil“, gewichtet über die Sektoren, die in beiden Klassen Stunden haben."""
    num = den = 0.0
    for s in range(12):
        n0, n2 = tab["n_zelle"][s][0], tab["n_zelle"][s][2]
        if n0 >= 10 and n2 >= 10:
            w = min(n0, n2)
            num += w * (tab["zelle"][s][2] - tab["zelle"][s][0])
            den += w
    return math.exp(num / den) if den else None


def kalib_rel(tab: dict, wd: float, ws: float, dt: Optional[float], monat: Optional[int] = None,
              gated: bool = True) -> float:
    """Relativer Faktor (Gesamtwert der Station ausgenommen) für diese Stunde."""
    s, b, k = kalib_klassen(wd, ws, kalib_dt_adj(tab, dt, monat))
    x = tab["speed"][k]
    if KALIB_MONAT_ANWENDEN and monat and tab.get("monat"):
        x += tab["monat"][monat - 1]
    if not (gated and tab.get("ok") and not tab["ok"][s]):
        x += tab["sektor"][s]
        if b is not None and (KALIB_STAB_ANWENDEN or not gated):
            x += tab["zelle"][s][b]
    return min(KALIB_GRENZEN[1], max(KALIB_GRENZEN[0], math.exp(x)))


def kalib_pruefen(zeilen_t: list) -> dict:
    """Blockvalidierung über Kalenderwochen (4 Faltungen): Fehler gegen die Messung mit und ohne
    die gelernten relativen Faktoren. Beide Varianten bekommen den Gesamtwert der Trainingswochen."""
    ok = [z for z in zeilen_t if z[2] >= KALIB_MIN_MODELL_KN and z[4] >= 1.0]
    summe = {"n": 0, "ae0": 0.0, "ae1": 0.0, "se0": 0.0, "se1": 0.0, "b0": 0.0, "b1": 0.0, "aer": 0.0, "br": 0.0}
    je_sektor = {s: [0, 0.0, 0.0] for s in range(12)}
    for f in range(4):
        train = [z for z in ok if (z[0].toordinal() // 7) % 4 != f]
        test = [z for z in ok if (z[0].toordinal() // 7) % 4 == f]
        tab = kalib_lernen([(z[1], z[2], z[3], z[4], z[0].month) for z in train])
        if not tab or not test:
            continue
        gf = math.exp(tab["g"])
        for z in test:
            basis = z[2] * gf
            korr = basis * kalib_rel(tab, z[1], z[2], z[3], z[0].month, gated=False)
            e0, e1 = basis - z[4], korr - z[4]
            summe["n"] += 1
            summe["ae0"] += abs(e0)
            summe["ae1"] += abs(e1)
            summe["se0"] += e0 * e0
            summe["se1"] += e1 * e1
            summe["b0"] += e0
            summe["b1"] += e1
            summe["aer"] += abs(z[2] - z[4])
            summe["br"] += z[2] - z[4]
            s = kalib_klassen(z[1], z[2], None)[0]
            je_sektor[s][0] += 1
            je_sektor[s][1] += abs(e0)
            je_sektor[s][2] += abs(e1)
    n = summe["n"]
    if not n:
        return {"n": 0}
    return {"n": n, "mae0": summe["ae0"] / n, "mae1": summe["ae1"] / n,
            "rmse0": math.sqrt(summe["se0"] / n), "rmse1": math.sqrt(summe["se1"] / n),
            "bias0": summe["b0"] / n, "bias1": summe["b1"] / n,
            "gewinn": 1 - summe["ae1"] / summe["ae0"] if summe["ae0"] else 0.0,
            "mae_roh": summe["aer"] / n, "bias_roh": summe["br"] / n,
            "gewinn_gesamt": 1 - summe["ae1"] / summe["aer"] if summe["aer"] else 0.0,
            "sektor": {s: {"n": v[0], "mae0": v[1] / v[0] if v[0] else None,
                           "mae1": v[2] / v[0] if v[0] else None} for s, v in je_sektor.items()}}


def kalib_auswerten(zeilen_t: list, name: str = "") -> Optional[dict]:
    """zeilen_t: (t, wd, modell_kn, luft−wasser oder None, messung_kn). Tabelle + Prüfung + Freigabe."""
    mz = [(z[1], z[2], z[3], z[4], z[0].month) for z in zeilen_t]
    tab = kalib_lernen(mz)
    if not tab:
        return None
    if tab["saison"]:       # zum Vergleich: dieselbe Stabilitätsspanne ohne Saisonbereinigung
        roh = kalib_lernen(mz, saison=False)
        tab["stab_ohne"] = kalib_stab_effekt(roh) if roh else None
    tab["stab_mit"] = kalib_stab_effekt(tab)
    pr = kalib_pruefen(zeilen_t)
    tab["pruef"] = pr
    tab["ok"] = []
    for s in range(12):
        v = (pr.get("sektor") or {}).get(s) or {}
        tab["ok"].append(bool(v.get("n", 0) >= 20 and v.get("mae0") is not None and v["mae1"] < v["mae0"]))
    tab["niveau"] = name in KALIB_NIVEAU
    tab["wirkt"] = bool(pr.get("n") and pr["gewinn_gesamt" if tab["niveau"] else "gewinn"] >= KALIB_MIN_GEWINN)
    return tab


# ---- Daten holen -------------------------------------------------------------

def _hole_wiederholt(url: str) -> list:
    for versuch in range(1, VERSUCHE + 1):
        try:
            time_mod.sleep(PAUSE_S)
            return _get_json(url)
        except RuntimeError as e:
            if versuch == VERSUCHE or "meldet einen Fehler" in str(e) or isinstance(e, OmLimit):
                raise
            time_mod.sleep(5 * 2 ** (versuch - 1))
    return []


def _spalte(h: dict, var: str, modell: str) -> Optional[list]:
    for key in (f"{var}_{modell}", var):
        if key in h:
            return h[key]
    return None


def _historie_stuecke(lat: float, lon: float, start: date, ende: date, modelle: str,
                      zelle: str = "nearest") -> List[dict]:
    """Holt start…ende; meldet die API einen Fehler (z. B. Archiv reicht nicht so weit zurück), wird der
    Abschnitt halbiert, bis nur noch ein Rest von höchstens einer Woche übrig bleibt, der entfällt."""
    print(f"\r\033[2K  Modellarchiv {start:%d.%m.%Y}–{ende:%d.%m.%Y}", end="", file=sys.stderr, flush=True)
    params = {"latitude": f"{lat:.4f}", "longitude": f"{lon:.4f}",
              "start_date": start.isoformat(), "end_date": ende.isoformat(),
              "hourly": "wind_speed_10m,wind_direction_10m,temperature_2m",
              "wind_speed_unit": "kn", "timezone": "Europe/Berlin",
              "models": modelle, "cell_selection": zelle}
    try:
        return [_hole_wiederholt(API_HIST + "?" + urllib.parse.urlencode(params, safe=","))[0].get("hourly") or {}]
    except RuntimeError as e:
        if "meldet einen Fehler" not in str(e):
            raise
        tage = (ende - start).days
        if tage <= 7:
            print(f"\r\033[2K  Hinweis: Modellarchiv {start:%d.%m.%Y}–{ende:%d.%m.%Y} nicht verfügbar "
                  f"({str(e)[:60]})", file=sys.stderr)
            return []
        mitte = start + timedelta(days=tage // 2)
        return (_historie_stuecke(lat, lon, start, mitte, modelle, zelle)
                + _historie_stuecke(lat, lon, mitte + timedelta(days=1), ende, modelle, zelle))


def hole_modellhistorie(lat: float, lon: float, von: date, bis: date, modelle: str, zelle: str = "nearest"
                        ) -> Dict[datetime, Tuple[float, float, Optional[float]]]:
    """Archivierte Modellprognosen (Open-Meteo Historical Forecast, nächste Gitterzelle):
    {Zeit: (Wind kn, Richtung °, Lufttemperatur °C)} als Mittel der Modelle, die Daten haben (mind. 2,
    wenn mehrere angefragt sind). Hinweis: Das sind die jeweils ersten Stunden jedes Modelllaufs –
    sie zeigen die systematische Abweichung, nicht die Güte nach 3 Tagen Vorlauf."""
    liste = [m.strip() for m in modelle.split(",") if m.strip()]
    nötig = 2 if len(liste) > 1 else 1
    aus: Dict[datetime, Tuple[float, float, Optional[float]]] = {}
    start = von
    while start <= bis:
        ende = min(start + timedelta(days=89), bis)
        for h in _historie_stuecke(lat, lon, start, ende, modelle, zelle):
            for i, t_s in enumerate(h.get("time", [])):
                paare, temps = [], []
                for m in liste:
                    ws_, wd_, tt_ = (_spalte(h, v, m) for v in ("wind_speed_10m", "wind_direction_10m", "temperature_2m"))
                    if ws_ and wd_ and i < len(ws_) and ws_[i] is not None and wd_[i] is not None:
                        paare.append((ws_[i], wd_[i]))
                    if tt_ and i < len(tt_) and tt_[i] is not None:
                        temps.append(tt_[i])
                if len(paare) >= nötig:
                    aus[datetime.fromisoformat(t_s)] = (sum(p[0] for p in paare) / len(paare),
                                                        vektor_mittel(paare)[1],
                                                        sum(temps) / len(temps) if temps else None)
        start = ende + timedelta(days=1)
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    return aus


def hole_sst_historie(lat: float, lon: float, von: date, bis: date) -> Dict[datetime, float]:
    """Wassertemperatur aus der Marine-API; Lücken werden später mit dem Tagesmittel gefüllt."""
    aus: Dict[datetime, float] = {}
    start = von
    while start <= bis:
        ende = min(start + timedelta(days=179), bis)
        params = {"latitude": f"{lat:.4f}", "longitude": f"{lon:.4f}",
                  "start_date": start.isoformat(), "end_date": ende.isoformat(),
                  "hourly": "sea_surface_temperature", "timezone": "Europe/Berlin"}
        daten = _hole_wiederholt(API_MARINE + "?" + urllib.parse.urlencode(params, safe=","))[0]
        aus.update(lese_wasser(daten))
        start = ende + timedelta(days=1)
    return aus


def sst_zu(sst: Dict[datetime, float], t: datetime, tagesmittel: Dict[date, float]) -> Optional[float]:
    v = sst.get(t)
    return v if v is not None else tagesmittel.get(t.date())


def _tagesmittel(sst: Dict[datetime, float]) -> Dict[date, float]:
    tage: Dict[date, List[float]] = {}
    for t, v in sst.items():
        tage.setdefault(t.date(), []).append(v)
    return {d: sum(v) / len(v) for d, v in tage.items()}


# ---- BSH-Messnetz MARNET als Messquelle für --kalibrieren -----------------------

def _utc_zu_berlin(t: datetime) -> datetime:
    """UTC → Ortszeit Berlin (Sommerzeit von letztem Märzsonntag 01:00 UTC bis letztem Oktobersonntag 01:00 UTC)."""
    def letzter_sonntag(jahr: int, monat: int) -> date:
        d = date(jahr, monat, 31)
        return d - timedelta(days=(d.weekday() + 1) % 7)
    sommer = datetime.combine(letzter_sonntag(t.year, 3), time(1)) <= t < datetime.combine(letzter_sonntag(t.year, 10), time(1))
    return t + timedelta(hours=2 if sommer else 1)


def bsh_zeilen_lesen(zeilen, station: str) -> Tuple[Dict[datetime, float], Optional[float]]:
    """Tabgetrennte BSH-Zeilen (SeaDataNet-Format) → ({Zeit wie in der Datei: Wind in kn}, Sensorhöhe in m).
    Spalten: 1 Station, 7 Zeit, 9 Tiefe (−34 = 34 m über dem Wasser), 11 Wind in m/s, 12 Qualitätsflag.
    Kopf- und Kommentarzeilen werden übersprungen, Flags 3/4/9 (schlecht/fehlt) ebenfalls."""
    aus: Dict[datetime, float] = {}
    hoehen: List[float] = []
    for z in zeilen:
        if z.startswith("//") or z.startswith("Cruise"):
            continue
        f = z.rstrip("\r\n").split("\t")
        if len(f) < 12 or f[1].strip() != station:
            continue
        try:
            t = datetime.fromisoformat(f[7].strip())
            v = float(f[11])
        except ValueError:
            continue
        if len(f) > 12 and f[12].strip() in ("3", "4", "9"):
            continue
        if v != v or v < 0:
            continue
        aus[t] = v * 1.943844
        try:
            hoehen.append(-float(f[9]))
        except ValueError:
            pass
    return aus, (median(hoehen) if hoehen else None)


def _bsh_herunterladen(jahr: int, namen: set) -> Optional[Path]:
    """Lädt die Jahresdatei Wind von gdi.bsh.de und legt nur die gewünschten Stationen in bsh/ ab."""
    ziel = BSH_ORDNER / f"wind-speed-{jahr}-gefiltert.txt"
    if ziel.exists():
        return ziel
    url = f"https://gdi.bsh.de/de/data/Timeseries-of-wind-speed-{jahr}.txt"
    print(f"  BSH {jahr}: lade {url} (nur einmal) …", file=sys.stderr)
    behalten = []
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "windsurf_spots"})
        with urllib.request.urlopen(req, timeout=180) as r:
            for zeile in io.TextIOWrapper(r, encoding="utf-8", errors="replace"):
                f = zeile.split("\t", 2)
                if len(f) > 1 and f[1].strip() in namen:
                    behalten.append(zeile if zeile.endswith("\n") else zeile + "\n")
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        raise RuntimeError(f"BSH-Download {jahr}: HTTP {e.code}")
    except (urllib.error.URLError, OSError) as e:
        raise RuntimeError(f"BSH-Download {jahr}: {e}")
    BSH_ORDNER.mkdir(exist_ok=True)
    ziel.write_text("".join(behalten), encoding="utf-8")
    return ziel


class BshQuelle:
    """Messquelle wie hole_messreihe, aber aus den BSH-Jahresdateien (bsh/ oder Download).
    Dateien, die du von Hand in den Ordner bsh/ legst, werden mitgelesen (Endung .txt)."""

    def __init__(self, station: str):
        self.station = station
        self.reihe: Dict[datetime, float] = {}
        self.hoehe: Optional[float] = None
        self._jahre: set = set()

    def _umrechnen(self, t: datetime) -> datetime:
        if BSH_ZEIT == "Ortszeit":
            return t
        return _utc_zu_berlin(t - timedelta(hours=1) if BSH_ZEIT == "MEZ" else t)

    def _laden(self, jahre: List[int]) -> None:
        neu = [j for j in jahre if j not in self._jahre]
        if not neu:
            return
        namen = {n for n, _, _ in BSH_STATIONEN.values()}
        for j in neu:
            try:
                _bsh_herunterladen(j, namen)
            except RuntimeError as e:
                print(f"  Hinweis: {e} – nutze nur lokal vorhandene Dateien", file=sys.stderr)
            self._jahre.add(j)
        if BSH_ORDNER.exists():
            for pfad in sorted(BSH_ORDNER.glob("*.txt")):
                try:
                    with open(pfad, encoding="utf-8", errors="replace") as fh:
                        werte, h = bsh_zeilen_lesen(fh, self.station)
                except OSError:
                    continue
                for t, v in werte.items():
                    self.reihe[self._umrechnen(t)] = v
                if h:
                    self.hoehe = h

    def bereich(self, von: date, bis: date) -> Optional[Tuple[date, date]]:
        """Zeitraum innerhalb von von…bis, für den Daten vorliegen (None = keine)."""
        self._laden(list(range(von.year, min(bis.year, BSH_JAHRE_MAX) + 1)))
        tage = [t.date() for t in self.reihe if von <= t.date() <= bis]
        return (min(tage), max(tage)) if tage else None

    def __call__(self, lat: float, lon: float, von: datetime, bis: datetime
                 ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
        return ({t: (v, None, None) for t, v in self.reihe.items() if von <= t < bis},
                f"BSH MARNET {self.station}")


def _dmi_json(url: str) -> dict:
    """GET gegen die DMI-API; bei Fehlern steht der Antworttext des Dienstes in der Meldung."""
    for versuch in range(1, VERSUCHE + 1):
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (windsurf_spots)",
                                                   "Accept": "application/json"})
        try:
            time_mod.sleep(PAUSE_S)
            with urllib.request.urlopen(req, timeout=TIMEOUT_S) as r:
                daten = json.load(r)
            return daten if isinstance(daten, dict) else {"features": daten}
        except urllib.error.HTTPError as e:
            try:
                text = e.read().decode("utf-8", "replace").strip()[:300]
            except Exception:
                text = ""
            if (e.code == 429 or e.code >= 500) and versuch < VERSUCHE:
                time_mod.sleep(5 * versuch)
                continue
            raise RuntimeError(f"DMI HTTP {e.code} {e.reason}: {text or '(keine Antwort)'} – URL: {url}") from None
        except (urllib.error.URLError, TimeoutError, OSError) as e:
            if versuch == VERSUCHE:
                raise RuntimeError(f"DMI nicht erreichbar ({e})") from None
            time_mod.sleep(5 * versuch)
    return {}


class DmiQuelle:
    """Messquelle wie hole_messreihe, aus dem DMI-Open-Data-Dienst (Stundenmittel wind_speed_past1h, m/s)."""

    def __init__(self, station_id: str):
        self.id = station_id
        self.name: Optional[str] = None
        self.reihe: Dict[datetime, float] = {}
        self.boe: Dict[datetime, float] = {}          # 09.11.2026: Böe und Richtung – nur für kurze Zeiträume
        self.richtung: Dict[datetime, float] = {}     # (Jetzt/Messverlauf), nicht für Monate der Validierung
        self._geladen: List[Tuple[date, date]] = []
        self._extra: List[Tuple[date, date]] = []

    # zum Mittelwind passende Böe/Richtung: Stundenwerte bzw. 10-Minuten-Werte zur vollen Stunde
    EXTRA = {"wind_speed_past1h": ("wind_gust_always_past1h", "wind_dir_past1h"), "wind_speed": ("wind_max", "wind_dir")}

    def _extra_holen(self, von: date, bis: date) -> None:
        if any(a <= von and bis <= b for a, b in self._extra) or not getattr(self, "param", None):
            return
        for par, ziel in zip(self.EXTRA.get(self.param, ()), (self.boe, self.richtung)):
            try:
                for f in self._abschnitt(von, bis, par):
                    p = f.get("properties") or {}
                    try:
                        t = datetime.fromisoformat(p["observed"].replace("Z", "+00:00")).replace(tzinfo=None)
                        v = float(p["value"])
                    except (KeyError, ValueError, TypeError, AttributeError):
                        continue
                    if self.param == "wind_speed" and t.minute:
                        continue
                    ziel[_utc_zu_berlin(t)] = v * 1.943844 if ziel is self.boe else v
            except RuntimeError as ex:                  # Zugabe – ohne Böe bleibt der Mittelwind
                print(f"Hinweis: DMI {self.id} {par} nicht geladen ({ex})", file=sys.stderr)
        self._extra.append((von, bis))

    def koordinaten(self, ersatz: Tuple[float, float]) -> Tuple[float, float]:
        try:
            d = _dmi_json(f"{DMI_API}/station/items?stationId={self.id}")
            fs = d.get("features") or []
            f = fs[-1] if fs else None      # jüngster Eintrag (Stationen werden mit Gültigkeitszeiträumen geführt)
            lon, lat = f["geometry"]["coordinates"][:2]
            self.name = (f.get("properties") or {}).get("name")
            return float(lat), float(lon)
        except (RuntimeError, KeyError, TypeError, IndexError, ValueError, AttributeError):
            return ersatz

    # Stundenmittel; manche Stationen (z. B. Hanstholm 06021) liefern nur den 10-Minuten-Mittelwind "wind_speed" –
    # dann zählt der Wert zur vollen Stunde (wie beim DWD).
    PARAMETER = ("wind_speed_past1h", "wind_speed")

    def _abschnitt(self, start: date, ende: date, param: str) -> list:
        features: list = []
        offset = 0
        while True:
            url = (f"{DMI_API}/observation/items?datetime={start.isoformat()}T00:00:00Z/"
                   f"{ende.isoformat()}T23:59:59Z&limit=1000&stationId={self.id}"
                   f"&parameterId={param}" + (f"&offset={offset}" if offset else ""))
            teil = _dmi_json(url).get("features", [])
            features += teil
            if len(teil) < 1000:
                break
            offset += 1000
        return features

    def _holen(self, von: date, bis: date) -> None:
        start = von
        while start <= bis:
            ende = min(start + timedelta(days=29), bis)
            features, param = [], None
            for param in ([self.param] if getattr(self, "param", None) else list(self.PARAMETER)):
                features = self._abschnitt(start, ende, param)
                if features:
                    self.param = param                  # einmal gefunden: dabei bleiben
                    break
            for f in features:
                p = f.get("properties") or {}
                try:
                    t = datetime.fromisoformat(p["observed"].replace("Z", "+00:00")).replace(tzinfo=None)
                    v = float(p["value"])
                except (KeyError, ValueError, TypeError, AttributeError):
                    continue
                if param == "wind_speed" and t.minute:
                    continue
                if v >= 0:
                    self.reihe[_utc_zu_berlin(t)] = v * 1.943844
            start = ende + timedelta(days=1)
        print("\r\033[2K", end="", file=sys.stderr, flush=True)

    def bereich(self, von: date, bis: date) -> Optional[Tuple[date, date]]:
        if not any(a <= von and bis <= b for a, b in self._geladen):
            print(f"  DMI {self.id}: lade {von:%d.%m.%Y} – {bis:%d.%m.%Y} …", file=sys.stderr)
            self._holen(von, bis)
            self._geladen.append((von, bis))
        tage = [t.date() for t in self.reihe if von <= t.date() <= bis]
        return (min(tage), max(tage)) if tage else None

    def __call__(self, lat: float, lon: float, von: datetime, bis: datetime
                 ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
        self.bereich(von.date(), bis.date())
        if (bis - von).days <= 4:
            self._extra_holen(von.date(), bis.date())
        return ({t: (v, self.boe.get(t), self.richtung.get(t)) for t, v in self.reihe.items() if von <= t < bis},
                f"DMI {self.id}")

    def aktuell(self) -> Optional[Tuple[datetime, float, Optional[float], Optional[float]]]:
        """Neuester 10-Minuten-Wert (wind_speed, dazu wind_max als Böe und wind_dir) der letzten 3 Stunden."""
        jetzt_utc = datetime.now(timezone.utc).replace(tzinfo=None)
        a, b = jetzt_utc - timedelta(hours=3), jetzt_utc + timedelta(minutes=10)
        werte: Dict[str, Dict[datetime, float]] = {}
        for par in ("wind_speed", "wind_max", "wind_dir"):
            url = (f"{DMI_API}/observation/items?datetime={a:%Y-%m-%dT%H:%M:%S}Z/{b:%Y-%m-%dT%H:%M:%S}Z"
                   f"&limit=100&stationId={self.id}&parameterId={par}")
            for f in _dmi_json(url).get("features", []):
                p = f.get("properties") or {}
                try:
                    t = datetime.fromisoformat(p["observed"].replace("Z", "+00:00")).replace(tzinfo=None)
                    werte.setdefault(par, {})[t] = float(p["value"])
                except (KeyError, ValueError, TypeError, AttributeError):
                    continue
        ws = werte.get("wind_speed") or {}
        if not ws:
            return None
        t = max(ws)
        g = (werte.get("wind_max") or {}).get(t)
        return (_utc_zu_berlin(t), ws[t] * 1.943844, None if g is None else g * 1.943844,
                (werte.get("wind_dir") or {}).get(t))


def msw_csv_lesen(text: str, alle_minuten: bool = False) -> Dict[datetime, Tuple[float, Optional[float], Optional[float]]]:
    """SwissMetNet-CSV (Semikolon, Zeit UTC am Ende des Intervalls) → {Ortszeit: (Mittelwind kn, Böe kn, Richtung °)}.
    Stundenwerte: fkl010h0 (m/s) bzw. fu3010h0 (km/h), Richtung dkl010h0, Böe fkl010h1/fu3010h1. Liegen nur
    10-Minuten-Werte (…z0) vor, wird der Wert zur vollen Stunde genommen (wie beim DWD)."""
    zeilen = [z for z in text.splitlines() if z.strip()]
    if not zeilen:
        return {}
    kopf = [k.strip().lower() for k in zeilen[0].split(";")]

    def spalte(*namen):
        return next((kopf.index(n) for n in namen if n in kopf), None)
    i_t = spalte("reference_timestamp", "referencets", "time", "date")
    if i_t is None:
        i_t = next((i for i, k in enumerate(kopf) if "time" in k or k.endswith("ts")), None)
    for suf in ("h", "z"):
        i_ms, i_kmh = spalte(f"fkl010{suf}0"), spalte(f"fu3010{suf}0")
        if i_ms is not None or i_kmh is not None:
            break
    if i_t is None or (i_ms is None and i_kmh is None):
        raise RuntimeError("keine Zeit- oder Windspalte in der MeteoSwiss-Datei")
    i_dir = spalte(f"dkl010{suf}0")
    i_g_ms, i_g_kmh = spalte(f"fkl010{suf}1"), spalte(f"fu3010{suf}1")

    def zahl(f, i, faktor):
        try:
            return float(f[i]) * faktor if i is not None and f[i].strip() not in ("", "-") else None
        except (ValueError, IndexError):
            return None
    aus = {}
    for z in zeilen[1:]:
        f = z.split(";")
        try:
            t = datetime.strptime(f[i_t].strip(), "%d.%m.%Y %H:%M")
        except (ValueError, IndexError):
            try:
                t = datetime.fromisoformat(f[i_t].strip().replace("Z", "")).replace(tzinfo=None)
            except (ValueError, IndexError):
                continue
        if suf == "z" and t.minute and not alle_minuten:
            continue
        v = zahl(f, i_ms, 1.943844) if i_ms is not None else zahl(f, i_kmh, 1 / 1.852)
        if v is None or v < 0:
            continue
        g = zahl(f, i_g_ms, 1.943844) if i_g_ms is not None else zahl(f, i_g_kmh, 1 / 1.852)
        aus[_utc_zu_berlin(t)] = (v, g, zahl(f, i_dir, 1.0))
    return aus


class MeteoSwissQuelle:
    """Messquelle wie hole_messreihe, aus den SwissMetNet-Dateien von MeteoSwiss (STAC-API von data.geo.admin.ch):
    _h_now (seit gestern 12 UTC), _h_recent (laufendes Jahr bis gestern), _h_historical_JJJJ-JJJJ (Jahrzehnte)."""

    def __init__(self, kuerzel: str):
        self.id = kuerzel.lower()
        self.name: Optional[str] = None
        self.reihe: Dict[datetime, Tuple[float, Optional[float], Optional[float]]] = {}
        self._assets: Optional[Dict[str, str]] = None
        self._geladen: set = set()

    def _json(self, url: str) -> dict:
        return json.loads(_karte_get(url, 60, versuche=3).decode("utf-8", "replace"))

    def assets(self) -> Dict[str, str]:
        if self._assets is None:
            d = self._json(f"{MSW_STAC}/items/{self.id}")
            self._assets = {k: (v or {}).get("href", "") for k, v in (d.get("assets") or {}).items()}
            if not self._assets:
                raise RuntimeError(f"MeteoSwiss: keine Dateien für Station {self.id.upper()}")
        return self._assets

    def koordinaten(self, ersatz: Tuple[float, float]) -> Tuple[float, float]:
        """Lage und Name aus ogd-smn_meta_stations.csv; sonst ersatz."""
        try:
            d = self._json(MSW_STAC)
            href = ((d.get("assets") or {}).get("ogd-smn_meta_stations.csv") or {}).get("href")
            text = _karte_get(href, 60, versuche=2).decode("cp1252", "replace")
            z = text.splitlines()
            kopf = [k.strip().lower() for k in z[0].split(";")]
            i_id = kopf.index("station_abbr")
            i_la = next(i for i, k in enumerate(kopf) if "wgs84_lat" in k)
            i_lo = next(i for i, k in enumerate(kopf) if "wgs84_lon" in k)
            i_n = kopf.index("station_name") if "station_name" in kopf else None
            for zeile in z[1:]:
                f = zeile.split(";")
                if f[i_id].strip().lower() == self.id:
                    self.name = f[i_n].strip() if i_n is not None else None
                    return float(f[i_la]), float(f[i_lo])
        except (RuntimeError, ValueError, StopIteration, IndexError, AttributeError, TypeError):
            pass
        return ersatz

    def _dateien(self, von: date, bis: date) -> List[str]:
        heute = date.today()
        namen = []
        for k in self.assets():
            if "_h_" not in k or not k.endswith(".csv"):
                continue
            if k.endswith("_h_now.csv"):
                if bis >= heute - timedelta(days=2):
                    namen.append(k)
            elif k.endswith("_h_recent.csv"):
                if bis >= date(heute.year, 1, 1):
                    namen.append(k)
            else:
                m = re.search(r"_h_historical_(\d{4})-(\d{4})\.csv$", k) or re.search(r"_h_historical\.csv$", k)
                if m is None:
                    continue
                if m.groups() and not (int(m.group(1)) <= bis.year and von.year <= int(m.group(2))):
                    continue
                if von.year < heute.year:
                    namen.append(k)
        return sorted(namen, key=lambda k: ("historical" not in k, "recent" not in k))

    def _laden(self, von: date, bis: date) -> None:
        for k in self._dateien(von, bis):
            if k in self._geladen:
                continue
            print(f"\r\033[2K  MeteoSwiss {self.id.upper()}: lade {k} …", end="", file=sys.stderr, flush=True)
            text = _karte_get(self.assets()[k], 240, versuche=3).decode("cp1252", "replace")
            self.reihe.update(msw_csv_lesen(text))
            self._geladen.add(k)
        print("\r\033[2K", end="", file=sys.stderr, flush=True)

    def bereich(self, von: date, bis: date) -> Optional[Tuple[date, date]]:
        self._laden(von, bis)
        tage = [t.date() for t in self.reihe if von <= t.date() <= bis]
        return (min(tage), max(tage)) if tage else None

    def __call__(self, lat: float, lon: float, von: datetime, bis: datetime
                 ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
        self._laden(von.date(), bis.date())
        return ({t: v for t, v in self.reihe.items() if von <= t < bis},
                f"MeteoSwiss {self.name or self.id.upper()}")

    def aktuell(self) -> Optional[Tuple[datetime, float, Optional[float], Optional[float]]]:
        """Neuester 10-Minuten-Wert aus _t_now.csv (für „Jetzt“)."""
        k = next((k for k in self.assets() if k.endswith("_t_now.csv")), None)
        if not k:
            return None
        r = msw_csv_lesen(_karte_get(self.assets()[k], 60, versuche=2).decode("cp1252", "replace"), alle_minuten=True)
        if not r:
            return None
        t = max(r)
        return (t,) + tuple(r[t])


# NOAA GHCNh (Global Historical Climatology Network – hourly): Nachfolger von ISD (ISD ohne Daten nach 08/2025, Download
# bei NCEI seit 31.07.2026 abgeschaltet). Frei, ohne Schlüssel; SYNOP/METAR weltweit, eine PSV-Datei je Station und Jahr.
GHCNH_BASIS = "https://www.ncei.noaa.gov/oa/global-historical-climatology-network/hourly"
GHCNH_LISTEN = (GHCNH_BASIS + "/doc/ghcnh-station-list.csv", GHCNH_BASIS + "/doc/ghcnh-station-list.txt")
GHCNH_DATEN = (GHCNH_BASIS + "/access/by-year/{jahr}/psv/GHCNh_{id}_{jahr}.psv",)
GHCNH_LISTE_CACHE = Path(__file__).resolve().parent / "ghcnh_stationen.txt"
GHCNH_AUTO_KM = 15                # ghcnh:auto nimmt die nächste Station bis zu dieser Entfernung


def _ist_html(text: str) -> bool:
    return text.lstrip()[:15].lower().startswith(("<!doctype", "<html", "<?xml"))


def ghcnh_liste_lesen(text: str) -> List[dict]:
    """Stationsliste als CSV (mit oder ohne Kopf) oder im festen GHCN-Format (ID LAT LON ELEV ST NAME …)."""
    aus = []
    for z in text.lstrip("﻿").splitlines():
        if not z.strip():
            continue
        f = next(csv.reader([z])) if "," in z else None
        try:
            if f and len(f) >= 3:
                sid, lat, lon = f[0].strip(), float(f[1]), float(f[2])
                rest = [x.strip() for x in f[3:]]
            else:                                          # feste Spalten: ID LAT LON ELEV [ST] NAME [GSN …] [WMO]
                tok = z.split()
                sid, lat, lon = tok[0], float(tok[1]), float(tok[2])
                namen = [x for x in tok[4:] if re.search(r"[A-Za-z]", x) and x not in ("GSN", "HCN", "CRN")]
                rest = [" ".join(namen)] + [x for x in tok[4:] if re.fullmatch(r"\d{5}", x)]
        except (ValueError, IndexError):
            continue                                       # Kopfzeile o. Ä.
        texte = [x for x in rest if re.search(r"[A-Za-z]{3}", x)]
        name = max(texte, key=len) if texte else ""
        wmo = next((x for x in rest if re.fullmatch(r"\d{5}", x)), "")
        aus.append({"id": sid, "lat": lat, "lon": lon, "name": name, "wmo": wmo})
    return aus


def ghcnh_stationsliste() -> List[dict]:
    """GHCNh-Stationsliste, 30 Tage zwischengespeichert."""
    try:
        if GHCNH_LISTE_CACHE.exists() and time_mod.time() - GHCNH_LISTE_CACHE.stat().st_mtime < 30 * 86400:
            liste = ghcnh_liste_lesen(GHCNH_LISTE_CACHE.read_text(encoding="utf-8", errors="replace"))
            if liste:
                return liste
    except OSError:
        pass
    fehler = []
    for url in GHCNH_LISTEN:
        try:
            text = _karte_get(url, 180, versuche=3).decode("utf-8", "replace")
        except RuntimeError as e:
            fehler.append(f"{url.rsplit('/', 1)[-1]}: {e}")
            continue
        liste = [] if _ist_html(text) else ghcnh_liste_lesen(text)
        if liste:
            try:
                GHCNH_LISTE_CACHE.write_text(text, encoding="utf-8")
            except OSError:
                pass
            return liste
        fehler.append(f"{url.rsplit('/', 1)[-1]}: nicht lesbar ({len(text)} Zeichen, Anfang {text[:80]!r})")
    raise RuntimeError("GHCNh-Stationsliste nicht erhalten – " + "; ".join(fehler))


def ghcnh_nahe(lat: float, lon: float, km: float, liste: Optional[List[dict]] = None) -> List[Tuple[float, dict]]:
    aus = []
    for st in (liste if liste is not None else ghcnh_stationsliste()):
        if abs(st["lat"] - lat) > 1 or abs(st["lon"] - lon) > 1.5:
            continue
        d = _abstand_km(lat, lon, st["lat"], st["lon"])
        if d <= km:
            aus.append((d, st))
    return sorted(aus, key=lambda x: x[0])


def ghcnh_psv_lesen(text: str) -> Dict[datetime, Tuple[float, Optional[float], Optional[float]]]:
    """GHCNh-PSV: Zeit UTC (DATE oder Year/Month/Day/Hour/Minute), wind_speed/wind_gust in m/s, wind_direction in Grad.
    Werte, deren *_Quality_Code eine nicht bestandene Prüfung anzeigt, entfallen. Je Stunde die Meldung nächst der vollen Stunde."""
    zeilen = text.lstrip("﻿").splitlines()
    if not zeilen or "|" not in zeilen[0]:
        return {}
    kopf = [k.strip() for k in zeilen[0].split("|")]
    ix = {k.lower(): i for i, k in enumerate(kopf)}

    def wert(f, name):
        i = ix.get(name)
        if i is None or i >= len(f) or not f[i].strip():
            return None
        q = ix.get(name + "_quality_code")
        # Ältere Jahrgänge tragen den ISD-Qualitätscode der Quelle (0/1/4/5 = bestanden, 2/3/6/7 = verdächtig/falsch);
        # die eigenen GHCNh-Prüfungen setzen Buchstaben. Bis 31.10.2026 fiel jeder gesetzte Code raus – damit fehlten
        # alle Jahre vor 2026 (z. B. Tarifa, Terschelling, Hoek van Holland: „0 Stunden mit Wind“).
        if q is not None and q < len(f):
            code = f[q].strip()
            if code and (code.isalpha() or code in ("2", "3", "6", "7")):
                return None
        try:
            return float(f[i])
        except ValueError:
            return None

    beste: Dict[datetime, Tuple[int, Tuple[float, Optional[float], Optional[float]]]] = {}
    for z in zeilen[1:]:
        f = z.split("|")
        try:
            if "date" in ix:
                t = datetime.fromisoformat(f[ix["date"]].strip()[:19])
            else:
                t = datetime(int(f[ix["year"]]), int(f[ix["month"]]), int(f[ix["day"]]), int(f[ix["hour"]]),
                             int(f[ix["minute"]]) if "minute" in ix and f[ix["minute"]].strip() else 0)
        except (KeyError, ValueError, IndexError):
            continue
        ws = wert(f, "wind_speed")
        if ws is None or ws < 0 or ws > 75:
            continue
        wd = wert(f, "wind_direction")
        boe = wert(f, "wind_gust")
        voll = (t + timedelta(minutes=30)).replace(minute=0, second=0)
        abstand = abs(int((t - voll).total_seconds() // 60))
        if abstand > 20:
            continue
        lokal = _utc_zu_berlin(voll)
        v = (round(ws * 1.943844, 1), None if boe is None else round(boe * 1.943844, 1),
             None if (wd is None or wd <= 0 or wd > 360) else wd % 360)
        if lokal not in beste or abstand < beste[lokal][0]:
            beste[lokal] = (abstand, v)
    return {t: v for t, (_, v) in beste.items()}


# KNMI Data Platform, EDR-API: 10-Minuten-Stationswerte nahezu in Echtzeit, CoverageJSON. Schlüssel kostenlos nach
# Anmeldung unter https://developer.dataplatform.knmi.nl/ („EDR API“), abgelegt als knmi_zugang.json {"schluessel": "…"}
# (nur auf dem Pi, nicht ins Chat). Grenzen: 1000 Abrufe/Stunde. Ohne Schlüssel → GHCNh-Ersatz.
KNMI_ZUGANG = Path(__file__).resolve().parent / "knmi_zugang.json"
KNMI_EDR = "https://api.dataplatform.knmi.nl/edr/v1/collections/10-minute-in-situ-meteorological-observations"


def knmi_schluessel() -> str:
    try:
        return str(json.loads(KNMI_ZUGANG.read_text(encoding="utf-8")).get("schluessel", "")).strip()
    except (OSError, ValueError):
        return ""


def covjson_reihe(d: dict) -> Dict[datetime, Dict[str, float]]:
    """CoverageJSON (Coverage oder CoverageCollection) → {UTC-Zeit: {Parameter: Wert}}."""
    aus: Dict[datetime, Dict[str, float]] = {}
    for c in (d.get("coverages") or [d]):
        axes = ((c.get("domain") or {}).get("axes") or {})
        ts = (axes.get("t") or {}).get("values") or []
        for par, r in (c.get("ranges") or {}).items():
            werte = r.get("values") or []
            if len(werte) != len(ts):
                continue
            for t, v in zip(ts, werte):
                if v is None:
                    continue
                try:
                    zt = datetime.fromisoformat(str(t).replace("Z", "+00:00")).replace(tzinfo=None)
                    aus.setdefault(zt, {})[par.lower()] = float(v)
                except (ValueError, TypeError):
                    pass
    return aus


class KnmiQuelle:
    """Messquelle wie hole_messreihe: KNMI-Station über die EDR-API (Wert zur vollen Stunde, wie beim DWD)."""

    def __init__(self, kennung: str):
        wmo, _, ersatz = kennung.partition(":")
        self.wmo = wmo.zfill(5)
        self.ersatz = GhcnhQuelle(ersatz) if ersatz else None
        self.name: Optional[str] = None
        self.reihe: Dict[datetime, Tuple[float, Optional[float], Optional[float]]] = {}
        self._tage: set = set()
        self.aktuell_wert: Optional[Tuple[datetime, float, Optional[float], Optional[float]]] = None

    def koordinaten(self, ersatz: Tuple[float, float]) -> Tuple[float, float]:
        if not knmi_schluessel() and self.ersatz is not None:
            return self.ersatz.koordinaten(ersatz)
        return ersatz

    def _laden(self, von: date, bis: date) -> None:
        sch = knmi_schluessel()
        heute = datetime.now(timezone.utc).date()
        tage = [von + timedelta(days=i) for i in range((bis - von).days + 1)]
        offen = [t for t in tage if t not in self._tage or t >= heute - timedelta(days=1)]
        for i in range(0, len(offen), 7):
            a, b = offen[i], offen[min(i + 6, len(offen) - 1)]
            url = (f"{KNMI_EDR}/locations/0-20000-0-{self.wmo}?datetime={a:%Y-%m-%d}T00:00:00Z/"
                   f"{b:%Y-%m-%d}T23:59:59Z&parameter-name=ff,dd,gff")
            print(f"\r\033[2K  KNMI {self.wmo}: lade {a:%d.%m.}–{b:%d.%m.} …", end="", file=sys.stderr, flush=True)
            d = json.loads(_karte_get(url, 90, versuche=3, kopf={"Authorization": sch, "Accept": "application/json",
                                                                  "User-Agent": "windfenster/1.0"}).decode("utf-8"))
            for t, w in covjson_reihe(d).items():
                if "ff" in w and (self.aktuell_wert is None or _utc_zu_berlin(t) > self.aktuell_wert[0]):
                    g_ = w.get("gff")
                    self.aktuell_wert = (_utc_zu_berlin(t), w["ff"] * 1.943844, None if g_ is None else g_ * 1.943844,
                                         w.get("dd"))
                if t.minute or "ff" not in w:
                    continue
                g = w.get("gff")
                self.reihe[_utc_zu_berlin(t)] = (w["ff"] * 1.943844, None if g is None else g * 1.943844, w.get("dd"))
            self._tage.update(t for t in offen[i:i + 7] if t < heute - timedelta(days=1))
        print("\r\033[2K", end="", file=sys.stderr, flush=True)

    def __call__(self, lat: float, lon: float, von: datetime, bis: datetime
                 ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
        if not knmi_schluessel():
            if self.ersatz is None:
                raise RuntimeError("KNMI: kein Schlüssel (knmi_zugang.json)")
            return self.ersatz(lat, lon, von, bis)
        self._laden(von.date(), bis.date())
        return ({t: v for t, v in self.reihe.items() if von <= t < bis}, f"KNMI {self.wmo}")

    def aktuell(self) -> Optional[Tuple[datetime, float, Optional[float], Optional[float]]]:
        """Neuester 10-Minuten-Wert – fällt beim Laden der Stundenwerte mit ab."""
        return self.aktuell_wert if knmi_schluessel() else None


def knmi_test() -> None:
    """--knmi-test: Schlüssel und Abruf prüfen, die letzten Stundenwerte je NL-Station zeigen."""
    if not knmi_schluessel():
        print(f"Kein Schlüssel: {KNMI_ZUGANG.name} mit {{\"schluessel\": \"…\"}} anlegen "
              "(kostenlos: developer.dataplatform.knmi.nl → EDR API).")
        return
    bis = datetime.now()
    for name, _la, _lo, q, _r in [x for x in stationen_liste() if x[3].startswith("knmi:")]:
        try:
            reihe, quelle = messquelle(q)(0, 0, bis - timedelta(hours=12), bis)
            letzte = sorted(reihe.items())[-4:]
            print(f"  {name}: {len(reihe)} Stundenwerte in 12 h · " + " · ".join(
                f"{t:%H:%M} {v[0]:.0f} kn" + (f" ({v[2]:.0f}°)" if v[2] is not None else "") for t, v in letzte))
        except Exception as ex:
            print(f"  {name}: Fehler – {ex}")


class GhcnhQuelle:
    """Messquelle wie hole_messreihe aus NOAA GHCNh (eine PSV-Datei je Station und Jahr)."""

    def __init__(self, kennung: str):
        self.id = kennung
        self.name: Optional[str] = None
        self.reihe: Dict[datetime, Tuple[float, Optional[float], Optional[float]]] = {}
        self._jahre: set = set()
        self.lage: Optional[Tuple[float, float]] = None
        self.status: Dict[int, str] = {}                 # je Jahr: was beim Laden herauskam (für die Fehlersuche)
        self.probe: Dict[int, str] = {}                  # je Jahr: Anfang der Datei, wenn nichts lesbar war

    def koordinaten(self, ersatz: Tuple[float, float]) -> Tuple[float, float]:
        """ghcnh:auto → nächste Station bis GHCNH_AUTO_KM; sonst Lage aus der Stationsliste."""
        try:
            if self.id == "auto":
                nah = ghcnh_nahe(ersatz[0], ersatz[1], GHCNH_AUTO_KM)
                if not nah:
                    raise RuntimeError(f"keine GHCNh-Station bis {GHCNH_AUTO_KM} km (--ghcnh-stationen zeigt den Umkreis)")
                st = nah[0][1]
            else:
                st = next((x for x in ghcnh_stationsliste() if x["id"] == self.id), None)
                if st is None:
                    return ersatz
            self.id, self.name, self.lage = st["id"], st["name"].title(), (st["lat"], st["lon"])
            return self.lage
        except RuntimeError:
            if self.id == "auto":
                raise
            return ersatz

    def _laden(self, von: date, bis: date) -> None:
        if self.id == "auto":
            raise RuntimeError("GHCNh: Station noch nicht bestimmt (ghcnh:auto braucht koordinaten())")
        for jahr in range(von.year, bis.year + 1):
            if jahr in self._jahre:
                continue
            print(f"\r\033[2K  NOAA GHCNh {self.id}: lade {jahr} …", end="", file=sys.stderr, flush=True)
            text = ""
            for muster in GHCNH_DATEN:
                try:
                    text = _karte_get(muster.format(jahr=jahr, id=self.id), 240, versuche=3).decode("utf-8", "replace")
                    break
                except RuntimeError as e:
                    if "HTTP 404" not in str(e):
                        raise
                    self.status[jahr] = "keine Datei (HTTP 404)"
            neu = {} if _ist_html(text) else ghcnh_psv_lesen(text)
            self.reihe.update(neu)
            if text:
                self.status[jahr] = ("HTML-Seite statt Daten" if _ist_html(text) else
                                     f"{len(text) // 1024} kB, {max(0, text.count(chr(10)) - 1)} Zeilen, "
                                     f"{len(neu)} Stunden mit Wind")
                if not neu:
                    self.probe[jahr] = "\n".join(z[:400] for z in text.splitlines()[:2])
            self._jahre.add(jahr)
        print("\r\033[2K", end="", file=sys.stderr, flush=True)

    def bereich(self, von: date, bis: date) -> Optional[Tuple[date, date]]:
        self._laden(von, bis)
        tage = [t.date() for t in self.reihe if von <= t.date() <= bis]
        return (min(tage), max(tage)) if tage else None

    def __call__(self, lat: float, lon: float, von: datetime, bis: datetime
                 ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
        if self.id == "auto":
            self.koordinaten((lat, lon))
        self._laden(von.date(), bis.date())
        return ({t: v for t, v in self.reihe.items() if von <= t < bis}, f"NOAA GHCNh {self.name or self.id}")


class GeosphereQuelle:
    """Messquelle wie hole_messreihe aus GeoSphere Austria (TAWES, 10 min; Dataset-API, CC BY 4.0). 09.11.2026.
    Stundenreihe = Wert zur vollen Stunde (wie beim DWD); aktuell() = neuester 10-Minuten-Wert."""
    PAR = "FFAM,FFX,DD"

    def __init__(self, station_id: str):
        self.id = station_id
        self.name: Optional[str] = None
        self.reihe: Dict[datetime, Tuple[float, Optional[float], Optional[float]]] = {}
        self._geladen: List[Tuple[date, date]] = []

    def _json(self, url: str) -> dict:
        return json.loads(_karte_get(url, 90, versuche=3).decode("utf-8", "replace"))

    def koordinaten(self, ersatz: Tuple[float, float]) -> Tuple[float, float]:
        try:
            meta = self._json(f"{GEOSPHERE_API}/station/current/tawes-v1-10min/metadata")
            st = next(x for x in meta.get("stations") or [] if str(x.get("id")) == self.id)
            self.name = str(st.get("name") or "").title() or None
            return float(st["lat"]), float(st["lon"])
        except (RuntimeError, StopIteration, KeyError, TypeError, ValueError):
            return ersatz

    @staticmethod
    def _lesen(d: dict) -> Dict[datetime, Tuple[Optional[float], Optional[float], Optional[float]]]:
        ts = d.get("timestamps") or []
        aus: Dict[datetime, Tuple[Optional[float], Optional[float], Optional[float]]] = {}
        for ft in d.get("features") or []:
            par = (ft.get("properties") or {}).get("parameters") or {}
            reihen = [((par.get(k) or {}).get("data") or []) for k in ("FFAM", "FFX", "DD")]
            for i, t_txt in enumerate(ts):
                try:
                    t = datetime.fromisoformat(t_txt).astimezone(timezone.utc).replace(tzinfo=None)
                except ValueError:
                    continue
                v = [r[i] if i < len(r) else None for r in reihen]
                if v[0] is None or v[0] < 0:
                    continue
                aus[_utc_zu_berlin(t)] = (v[0] * 1.943844, None if v[1] is None else v[1] * 1.943844, v[2])
        return aus

    def bereich(self, von: date, bis: date) -> Optional[Tuple[date, date]]:
        if not any(a <= von and bis <= b for a, b in self._geladen):
            start = von
            while start <= bis:                      # Abschnitte zu 30 Tagen (Größenbegrenzung der API)
                ende = min(start + timedelta(days=29), bis)
                print(f"\r\033[2K  GeoSphere {self.id}: lade {start:%d.%m.%Y} – {ende:%d.%m.%Y} …", end="",
                      file=sys.stderr, flush=True)
                d = self._json(f"{GEOSPHERE_API}/station/historical/tawes-v1-10min?parameters={self.PAR}"
                               f"&station_ids={self.id}&start={start - timedelta(days=1):%Y-%m-%d}T22:00"
                               f"&end={ende:%Y-%m-%d}T23:50&output_format=geojson")
                for t, v in self._lesen(d).items():
                    if t.minute == 0:
                        self.reihe[t] = v
                start = ende + timedelta(days=1)
            print("\r\033[2K", end="", file=sys.stderr, flush=True)
            self._geladen.append((von, bis))
        tage = [t.date() for t in self.reihe if von <= t.date() <= bis]
        return (min(tage), max(tage)) if tage else None

    def __call__(self, lat: float, lon: float, von: datetime, bis: datetime
                 ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
        try:
            self.bereich(von.date(), bis.date())
        except RuntimeError as ex:                   # die letzten Stunden gibt es auch über „current“
            print(f"Hinweis: GeoSphere {self.id} Archiv nicht geladen ({ex})", file=sys.stderr)
        try:
            a = self.aktuell()
        except RuntimeError:
            a = None
        if a and a[0].minute == 0:
            self.reihe.setdefault(a[0], a[1:])
        return ({t: v for t, v in self.reihe.items() if von <= t < bis}, f"GeoSphere {self.name or self.id}")

    def aktuell(self) -> Optional[Tuple[datetime, float, Optional[float], Optional[float]]]:
        d = self._json(f"{GEOSPHERE_API}/station/current/tawes-v1-10min?parameters={self.PAR}&station_ids={self.id}")
        w = self._lesen(d)
        if not w:
            return None
        t = max(w)
        return (t,) + w[t]


class TrentinoQuelle:
    """Messquelle aus Meteotrentino (Provincia autonoma di Trento): ultimiDatiStazione liefert die Werte des
    laufenden Tages (Ortszeit, m/s). Ältere Stunden kommen aus der eigenen Mitschrift. 09.11.2026."""

    def __init__(self, code: str):
        self.id = code
        self.name: Optional[str] = None
        self.reihe: Dict[datetime, Tuple[float, Optional[float], Optional[float]]] = {}
        self._stand: Optional[datetime] = None

    def koordinaten(self, ersatz: Tuple[float, float]) -> Tuple[float, float]:
        return ersatz

    def _holen(self) -> Dict[datetime, Tuple[float, Optional[float], Optional[float]]]:
        if self._stand and datetime.now() - self._stand < timedelta(minutes=5):
            return self.reihe
        w = _xml_ohne_ns(_karte_get(f"{TRENTINO_API}/ultimiDatiStazione?codice={self.id}", 60, versuche=3))
        for el in w.iter():
            if el.tag.lower() != "vento_al_suolo":
                continue
            f = {c.tag.lower(): (c.text or "").strip() for c in list(el)}
            try:
                t = datetime.fromisoformat(f["data"][:19])
                v = float(f["v"].replace(",", "."))
            except (KeyError, ValueError):
                continue
            def z(k):
                try:
                    return float(f[k].replace(",", "."))
                except (KeyError, ValueError):
                    return None
            g = z("vmax")
            if v >= 0:
                self.reihe[t] = (v * 1.943844, None if g is None else g * 1.943844, z("d"))
        self._stand = datetime.now()
        return self.reihe

    def bereich(self, von: date, bis: date) -> Optional[Tuple[date, date]]:
        tage = [t.date() for t in self._holen() if von <= t.date() <= bis]
        return (min(tage), max(tage)) if tage else None

    def __call__(self, lat: float, lon: float, von: datetime, bis: datetime
                 ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
        r = self._holen()
        return ({t: v for t, v in r.items() if von <= t < bis and t.minute == 0}, f"Meteotrentino {self.id}")

    def aktuell(self) -> Optional[Tuple[datetime, float, Optional[float], Optional[float]]]:
        r = self._holen()
        if not r:
            return None
        t = max(r)
        return (t,) + r[t]


_MESSQUELLEN: Dict[str, object] = {}


def messquelle(quelle: str):
    """Quelle aus REVIER_STATIONEN → Messer-Objekt (None = DWD über Bright Sky); je Station nur einmal angelegt."""
    if quelle.startswith("msw:"):
        return _MESSQUELLEN.setdefault(quelle, MeteoSwissQuelle(quelle[4:]))
    if quelle.startswith("dmi:"):
        return _MESSQUELLEN.setdefault(quelle, DmiQuelle(quelle[4:]))
    if quelle.startswith("ghcnh:"):
        return _MESSQUELLEN.setdefault(quelle, GhcnhQuelle(quelle[6:]))
    if quelle.startswith("knmi:"):
        return _MESSQUELLEN.setdefault(quelle, KnmiQuelle(quelle[5:]))
    if quelle.startswith("geosphere:"):
        return _MESSQUELLEN.setdefault(quelle, GeosphereQuelle(quelle[10:]))
    if quelle.startswith("trentino:"):
        return _MESSQUELLEN.setdefault(quelle, TrentinoQuelle(quelle[9:]))
    return None


def stationen_liste(rid: Optional[str] = None) -> List[Tuple[str, float, float, str, str]]:
    """(Name, Breite, Länge, Quelle, Revier) aller Validierungsstationen, optional nur eines Reviers.
    Ostsee = VALIDIERUNG (DWD); dazu REVIER_STATIONEN der aktiven Reviere."""
    aus = []
    if rid in (None, "ostsee"):
        aus += [(n, la, lo, "dwd", "ostsee") for n, la, lo in VALIDIERUNG]
    for r, liste in REVIER_STATIONEN.items():
        if rid in (None, r) and any(x["id"] == r and x["aktiv"] for x in REVIERE):
            aus += [(n, la, lo, q, r) for n, la, lo, q in liste]
    return aus


def _zeitpruefung_text(rows: list) -> str:
    zv = bsh_zeitversatz(rows) if rows else None
    if not zv:
        return ""
    deutlich = zv[1][zv[0]] - zv[1][0] >= 0.02      # kleinere Unterschiede sind Rauschen
    return (f"\n  Zeitprüfung (Korrelation Modell/Messung bei Verschiebung −2…+2 h): beste bei {zv[0]:+d} h "
            f"(r = {zv[1][zv[0]]:.3f}, bei 0 h {zv[1][0]:.3f})"
            + (" – ZEITSTEMPEL PASSEN NICHT!" if deutlich and zv[0] != 0 else " – kein Zeitversatz erkennbar"))


def bsh_zeitversatz(rows: list) -> Optional[Tuple[int, Dict[int, float]]]:
    """Korrelation Modellwind ↔ Messung bei Verschiebung der Messung um −2…+2 h: (beste Verschiebung, Korrelationen).
    Prüft, ob die Zeitstempel der Messdatei zur Ortszeit der Modelle passen."""
    modell = {datetime.fromisoformat(r[0]): r[2] for r in rows}
    mess = {datetime.fromisoformat(r[0]): r[5] for r in rows}
    erg: Dict[int, float] = {}
    for k in range(-2, 3):
        paare = [(modell[t], mess[t + timedelta(hours=k)]) for t in modell
                 if t + timedelta(hours=k) in mess and modell[t] >= 5]
        if len(paare) < 200:
            return None
        mx = sum(a for a, _ in paare) / len(paare)
        my = sum(b for _, b in paare) / len(paare)
        sxy = sum((a - mx) * (b - my) for a, b in paare)
        sxx = sum((a - mx) ** 2 for a, _ in paare)
        syy = sum((b - my) ** 2 for _, b in paare)
        erg[k] = sxy / math.sqrt(sxx * syy) if sxx > 0 and syy > 0 else 0.0
    return max(erg, key=erg.get), erg


def _kalib_abschnitt(name: str, lat: float, lon: float, start: date, ende: date,
                     sst_punkt: Optional[Tuple[float, float]], messer=None) -> list:
    """Zeilen [t, wd, modell_kn, luft, wasser, messung_kn, böe_kn] für start…ende.
    messer = alternative Messquelle (BshQuelle); sonst DWD über Bright Sky."""
    if messer is not None and hasattr(messer, "bereich"):
        b = messer.bereich(start, ende)
        if b is None:
            return []
        start, ende = max(start, b[0]), min(ende, b[1])
    holer = messer or hole_messreihe
    print(f"  {name}: lade {start:%d.%m.%Y} – {ende:%d.%m.%Y} …", file=sys.stderr)
    mlat, mlon, zelle = kalib_modellpunkt(name, lat, lon)
    modell = (hole_modellhistorie(mlat, mlon, start, ende, KALIB_MODELLE) if zelle == "nearest"
              else hole_modellhistorie(mlat, mlon, start, ende, KALIB_MODELLE, zelle))
    sst = hole_sst_historie(sst_punkt[0], sst_punkt[1], start, ende) if sst_punkt else {}
    tm = _tagesmittel(sst)
    neu: Dict[datetime, tuple] = {}
    t0 = datetime.combine(start, time(0))
    t_ende = datetime.combine(ende + timedelta(days=1), time(0))
    while t0 < t_ende:
        t1 = min(t0 + timedelta(days=45), t_ende)
        print(f"\r\033[2K  Messung {name} {t0:%d.%m.%Y} …", end="", file=sys.stderr, flush=True)
        reihe, _ = holer(lat, lon, t0, t1)
        neu.update(reihe)
        t0 = t1
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    rows = []
    for t in sorted(set(modell) & set(neu)):
        ws_, wd_, lt_ = modell[t]
        kn, boe, _ = neu[t]
        rows.append([t.isoformat(timespec="minutes"), round(wd_), round(ws_, 1),
                     None if lt_ is None else round(lt_, 1), sst_zu(sst, t, tm), round(kn, 1),
                     None if boe is None else round(boe, 1)])
    return rows


def kalib_zeilen_holen(name: str, lat: float, lon: float, jahre: float, cache: dict,
                       sst_punkt: Optional[Tuple[float, float]], messer=None) -> list:
    """Alle Zeilen einer Station für die letzten `jahre` Jahre. Der Zwischenspeicher wird nach hinten
    (neue Tage) und nach vorn (größeres --jahre) erweitert; "ab" merkt sich, bis wohin schon gefragt wurde,
    damit Lücken im Archiv nicht bei jedem Lauf neu angefragt werden."""
    heute = date.today()
    ende = heute - timedelta(days=2)          # das Archiv hinkt ein bis zwei Tage hinterher
    anfang = heute - timedelta(days=int(365 * jahre))
    eintrag = cache.get(name) or {}
    mp = list(kalib_modellpunkt(name, lat, lon)) if name in KALIB_MODELLPUNKT else None
    if eintrag.get("modellpunkt") != mp:          # Modellpunkt geändert: Modellwerte im Speicher passen nicht mehr
        eintrag = {}
    rows = [r for r in eintrag.get("rows", []) if datetime.fromisoformat(r[0]).date() >= anfang]
    bisher_ab = date.fromisoformat(eintrag["ab"]) if eintrag.get("ab") else None
    if not rows:
        rows = _kalib_abschnitt(name, lat, lon, anfang, ende, sst_punkt, messer) if anfang <= ende else []
    else:
        if bisher_ab is None or bisher_ab > anfang + timedelta(days=2):
            erste = datetime.fromisoformat(rows[0][0]).date()
            if erste > anfang + timedelta(days=2):
                rows = _kalib_abschnitt(name, lat, lon, anfang, erste - timedelta(days=1), sst_punkt, messer) + rows
        letzte = datetime.fromisoformat(rows[-1][0]).date()
        start = letzte - timedelta(days=1)
        if start < ende:
            rows = [r for r in rows if datetime.fromisoformat(r[0]).date() < start] + \
                   _kalib_abschnitt(name, lat, lon, start, ende, sst_punkt, messer)
    cache[name] = {"rows": rows, "ab": min(bisher_ab, anfang).isoformat() if bisher_ab else anfang.isoformat()}
    if mp:
        cache[name]["modellpunkt"] = mp
    return rows


def kalib_zeilen_t(rows: list) -> list:
    """Rohzeilen → (t, wd, modell_kn, luft−wasser oder None, messung_kn)."""
    aus = []
    for r in rows:
        dt = None if (r[3] is None or r[4] is None) else r[3] - r[4]
        aus.append((datetime.fromisoformat(r[0]), r[1], r[2], dt, r[5]))
    return aus


# ---- Bericht -----------------------------------------------------------------

def kalib_bericht(name: str, rows: list, tab: Optional[dict], info: str = "") -> None:
    zt = kalib_zeilen_t(rows)
    von, bis = (min(z[0] for z in zt), max(z[0] for z in zt)) if zt else (None, None)
    n_wind = sum(1 for z in zt if z[2] >= KALIB_MIN_MODELL_KN and z[4] >= 1.0)
    print(f"\n{name.upper()} · {len(zt)} Stunden mit Modell und Messung"
          + (f" ({von:%d.%m.%Y}–{bis:%d.%m.%Y})" if von else "") + f", davon {n_wind} ab {KALIB_MIN_MODELL_KN:.0f} kn Modellwind")
    if info:
        print(info)
    if not tab:
        if not zt:
            print("  Keine Überschneidung von Modell- und Messdaten – diese Station liefert vermutlich keinen Wind "
                  "(prüfen mit --stationen).")
        else:
            print(f"  Zu wenig Daten (mind. {KALIB_MIN_N} Stunden ab {KALIB_MIN_MODELL_KN:.0f} kn) – keine Kalibrierung.")
        return
    pr = tab["pruef"]
    if tab.get("niveau"):
        print(f"  Gesamtwert Messung/Modell: ×{math.exp(tab['g']):.2f}  – wird angewandt (×{kalib_niveau(tab):.2f}, "
              f"Grenzen {KALIB_NIVEAU_GRENZEN[0]}–{KALIB_NIVEAU_GRENZEN[1]})")
        if name in KALIB_MODELLPUNKT:
            print(f"  Modellwerte am Spot {KALIB_MODELLPUNKT[name]} (Wasserzelle wie im Livelauf), nicht an der Station.")
        if pr.get("n"):
            print(f"  Gesamtwirkung an nicht gesehenen Wochen: MAE {pr['mae_roh']:.2f} → {pr['mae1']:.2f} kn "
                  f"({-pr['gewinn_gesamt'] * 100:+.1f} %), Bias {pr['bias_roh']:+.2f} → {pr['bias1']:+.2f} kn")
    else:
        print(f"  Gesamtwert Messung/Modell: ×{math.exp(tab['g']):.2f}  (Messhöhe und Zellvergleich – wird NICHT angewandt)")
    if pr.get("n"):
        print("  Prüfung an nicht gesehenen Wochen (4-fach Blockvalidierung):")
        print(f"    Fehler MAE   {pr['mae0']:.2f} → {pr['mae1']:.2f} kn  ({-pr['gewinn'] * 100:+.1f} %)"
              f"    RMSE {pr['rmse0']:.2f} → {pr['rmse1']:.2f}    Bias {pr['bias0']:+.2f} → {pr['bias1']:+.2f}")
    print("  Windklassen (rel. zum Gesamtwert): "
          + ", ".join(f"{l} ×{math.exp(v):.2f}" for l, v in zip(
              (f"<{KALIB_WIND_KLASSEN[0]:.0f} kn", f"{KALIB_WIND_KLASSEN[0]:.0f}–{KALIB_WIND_KLASSEN[1]:.0f} kn",
               f"≥{KALIB_WIND_KLASSEN[1]:.0f} kn"), tab["speed"])))
    if tab.get("saison"):
        print("  Jahresgang des Stationsfaktors (rel.; wird nicht auf Spots übertragen): "
              + " ".join(f"{m} ×{math.exp(v):.2f}" for m, v in zip(
                  ("Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez"), tab["monat"])))
        mit_stab = any(z[3] is not None for z in zt)
        if mit_stab:
            print("  Luft − Wasser im Monatsmittel (K): "
              + " ".join(f"{m} {v:+.1f}" for m, v in zip(
                  ("Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez"), tab["dt_monat"])))
        if mit_stab and tab.get("stab_ohne") and tab.get("stab_mit"):
            print(f"  Stabil gegenüber labil (n-gewichtet über Sektoren): ohne Saisonbereinigung ×{tab['stab_ohne']:.2f}"
                  f" → mit ×{tab['stab_mit']:.2f}")
        if mit_stab:
            print("  Labil/neutral/stabil gelten relativ zum Monatsmittel (stabiler bzw. labiler als sonst in diesem Monat).")
    mit_stab = any(z[3] is not None for z in zt)
    print(f"\n  {'Richtung':<9}{'Std.':>6}{'Sektor':>8}   " + ("".join(f"{b:>15}" for b in STAB_NAMEN) if mit_stab else "")
          + f"{'MAE vorher→nachher':>20}")
    for s in range(12):
        sv = (pr.get("sektor") or {}).get(s) or {}
        mae = (f"{sv['mae0']:.2f} → {sv['mae1']:.2f}" + ("" if tab["ok"][s] else " (aus)")) if sv.get("n") else "–"
        zellen = []
        for b in range(3):
            n = tab["n_zelle"][s][b]
            zellen.append(f"×{math.exp(tab['sektor'][s] + tab['zelle'][s][b]):.2f} ({n})" if n >= 10 else f"– ({n})")
        print(f"  {kompass(s * 30):<9}{tab['n_sektor'][s]:>6}{'×%.2f' % math.exp(tab['sektor'][s]):>8}   "
              + ("".join(f"{z:>15}" for z in zellen) if mit_stab else "") + f"{mae:>20}")
    # Böigkeit nach Stabilität (nur informativ): gemessene Böe / gemessener Mittelwind
    boe: Dict[int, List[float]] = {0: [], 1: [], 2: []}
    for r, z in zip(rows, zt):
        if z[3] is not None and r[6] is not None and r[5] >= 8:
            boe[kalib_klassen(z[1], z[2], kalib_dt_adj(tab, z[3], z[0].month))[1]].append(r[6] / r[5])
    if any(boe.values()):
        print("\n  Gemessene Böigkeit (Böe/Mittelwind, Mittelwind ab 8 kn): "
              + ", ".join(f"{STAB_NAMEN[b]} {sum(v) / len(v):.2f} ({len(v)} h)" for b, v in boe.items() if v))
    wirkt = tab["wirkt"]
    print(f"\n  Ergebnis: {'GEWINN an der Station – angewandt nur für Spots in KALIB_SPOTS' if wirkt else 'bringt keinen belastbaren Gewinn – wird NICHT angewandt'}"
          f" (Schwelle {KALIB_MIN_GEWINN * 100:.0f} % kleinerer MAE an ungesehenen Wochen).")


def demo_kalib_rows(jahre: float = 2.0) -> list:
    """Erfundene Archivzeilen mit eingebauter Richtungs-/Stabilitätsabhängigkeit (nur für --demo)."""
    import random
    rnd = random.Random(7)
    rows = []
    t = datetime.combine(date.today() - timedelta(days=int(365 * jahre)), time(0))
    ende = datetime.combine(date.today() - timedelta(days=2), time(0))
    wd, ws = 240.0, 12.0
    while t < ende:
        wd = (wd + rnd.gauss(0, 12)) % 360
        ws = max(1.0, min(35.0, ws + rnd.gauss(0, 1.2) + (12 - ws) * 0.03))
        tag = t.timetuple().tm_yday
        wasser = 11 + 7 * math.sin((tag - 110) / 365 * 2 * math.pi)
        luft = wasser + 2.5 * math.sin((tag - 95) / 365 * 2 * math.pi) * 1.4 + rnd.gauss(0, 2) + 1.5 * math.sin((t.hour - 9) / 24 * 2 * math.pi)
        dt = luft - wasser
        s, b, _ = kalib_klassen(wd, ws, dt)
        rel = 1.0
        if s in (1, 2, 3):                 # N–O: Düse
            rel *= 1.10
        if s in (8, 9) and b == 2:         # W bei stabiler Schichtung: schwächer
            rel *= 0.88
        mess = max(0.5, ws * 1.15 * rel * (1 + rnd.gauss(0, 0.12)))
        rows.append([t.isoformat(timespec="minutes"), round(wd), round(ws, 1), round(luft, 1),
                     round(wasser, 1), round(mess, 1), round(mess * (1.3 + 0.05 * (2 - b)), 1)])
        t += timedelta(hours=1)
    return rows


def kalibrieren(args) -> None:
    jahre = args.jahre
    wahl = getattr(args, "revier", None)
    print(f"KALIBRIERUNG · Modellarchiv ({', '.join(MODELL_KURZ.get(m, m) for m in KALIB_MODELLE.split(','))})"
          f" gegen Messung, {jahre:g} Jahre" + (f", Revier {wahl}" if wahl else "") + "\n")
    if args.demo:
        print("DEMO-DATEN – erfundene Zeitreihe, nur zur Ansicht des Berichts. Es wird nichts gespeichert.")
    try:
        cache = {} if args.demo else (json.loads(KALIB_ROHDATEN.read_text(encoding="utf-8"))
                                      if KALIB_ROHDATEN.exists() else {})
    except (OSError, ValueError):
        cache = {}
    ergebnis = {}
    bsh = {n: BshQuelle(st) for n, (st, _, _) in BSH_STATIONEN.items()}
    if cache.get("_bsh_zeit") != BSH_ZEIT:      # Zeitannahme geändert: die BSH-Zeilen im Zwischenspeicher sind veraltet
        for n in bsh:
            cache.pop(n, None)
        cache["_bsh_zeit"] = BSH_ZEIT
    dmi = {n: DmiQuelle(d[0]) for n, d in DMI_STATIONEN.items()}
    stationen = []
    if wahl in (None, "ostsee"):
        stationen = VALIDIERUNG + KALIB_ZUSATZ + [(n, b[1], b[2]) for n, b in BSH_STATIONEN.items()]
        for n, q in dmi.items():
            if not args.demo:
                stationen.append((n, *q.koordinaten((DMI_STATIONEN[n][1], DMI_STATIONEN[n][2]))))
    # übrige Reviere: Quelle und Wassertemperatur-Punkt je Station
    rev_quelle: Dict[str, object] = {}
    rev_sst: Dict[str, Optional[Tuple[float, float]]] = {}
    rev_id: Dict[str, str] = {}
    for name, lat, lon, quelle, rid in stationen_liste(wahl):
        if rid == "ostsee":
            continue
        q = messquelle(quelle)
        if q is not None and hasattr(q, "koordinaten") and not args.demo:
            try:
                lat, lon = q.koordinaten((lat, lon))
            except RuntimeError as e:
                print(f"\n{name}: {e}")
                continue
        stationen.append((name, lat, lon))
        rev_quelle[name], rev_sst[name], rev_id[name] = q, STATION_SST_PUNKT.get(name, REVIER_SST_PUNKT.get(rid)), rid
    if not stationen:
        sys.exit(f"Keine Stationen für Revier {wahl} (REVIER_STATIONEN).")
    for name, lat, lon in stationen:
        if args.demo and name in bsh:
            continue
        if args.demo:
            rows = demo_kalib_rows(jahre)
        else:
            try:
                if name in rev_id:
                    rows = kalib_zeilen_holen(name, lat, lon, jahre, cache, rev_sst[name], rev_quelle[name])
                else:
                    rows = kalib_zeilen_holen(name, lat, lon, jahre, cache, REFERENZ, bsh.get(name) or dmi.get(name))
            except OmLimit:
                raise
            except RuntimeError as e:
                print(f"\n{name}: Daten nicht abrufbar ({e})")
                continue
            try:
                KALIB_ROHDATEN.write_text(json.dumps(cache), encoding="utf-8")
            except OSError as e:
                print(f"Hinweis: Zwischenspeicher nicht geschrieben ({e})", file=sys.stderr)
        tab = kalib_auswerten(kalib_zeilen_t(rows), name) if rows else None
        info = ""
        if name in bsh and bsh[name].reihe:
            q = bsh[name]
            info = (f"  Quelle: BSH MARNET, Station {q.station}, Sensorhöhe laut Datei "
                    f"{('%.0f m' % q.hoehe) if q.hoehe else 'unbekannt'}; Daten in der Datei "
                    f"{min(q.reihe):%d.%m.%Y}–{max(q.reihe):%d.%m.%Y}; "
                    f"Zeitstempel als {BSH_ZEIT} gelesen.")
            info += _zeitpruefung_text(rows).replace("PASSEN NICHT!", "PASSEN NICHT, BSH_ZEIT prüfen!")
        elif name in dmi and dmi[name].reihe:
            q = dmi[name]
            info = (f"  Quelle: DMI Open Data, Station \"{q.name or '?'}\" ({q.id}), Stundenmittel Wind; Daten "
                    f"{min(q.reihe):%d.%m.%Y}–{max(q.reihe):%d.%m.%Y}; Zeitstempel als UTC gelesen."
                    + _zeitpruefung_text(rows))
        elif isinstance(rev_quelle.get(name), MeteoSwissQuelle) and rev_quelle[name].reihe:
            q = rev_quelle[name]
            info = (f"  Quelle: MeteoSwiss SwissMetNet, Station {q.name or q.id.upper()} ({q.id.upper()}), Stundenmittel; "
                    f"Daten {min(q.reihe):%d.%m.%Y}–{max(q.reihe):%d.%m.%Y}; Zeitstempel UTC, Ende der Stunde."
                    + ("" if rev_sst.get(name) else " Ohne Wassertemperatur (Binnensee): keine Stabilitätsklassen.")
                    + _zeitpruefung_text(rows))
        elif isinstance(rev_quelle.get(name), DmiQuelle):
            q = rev_quelle[name]
            info = (f"  Quelle: DMI Open Data, Station \"{q.name or '?'}\" ({q.id}), "
                    + ("10-Minuten-Mittel zur vollen Stunde" if getattr(q, "param", None) == "wind_speed"
                       else "Stundenmittel Wind")
                    + (f"; Daten {min(q.reihe):%d.%m.%Y}–{max(q.reihe):%d.%m.%Y}; Zeitstempel als UTC gelesen."
                       if q.reihe else "; keine Winddaten von DMI erhalten.")
                    + _zeitpruefung_text(rows))
        elif isinstance(rev_quelle.get(name), GhcnhQuelle):
            q = rev_quelle[name]
            info = (f"  Quelle: NOAA GHCNh (SYNOP/METAR), Station {q.name or q.id} ({q.id})"
                    + ("; Jahre: " + ", ".join(f"{j} {t}" for j, t in sorted(q.status.items())) if not q.reihe else "")
                    + (f"; Daten {min(q.reihe):%d.%m.%Y}–{max(q.reihe):%d.%m.%Y}" if q.reihe else "; keine Daten")
                    + "; Zeitstempel UTC, Wert zur vollen Stunde (10-min-Mittel)."
                    + ("" if rev_sst.get(name) else " Ohne Wassertemperatur: keine Stabilitätsklassen.")
                    + _zeitpruefung_text(rows))
        elif name in rev_id:
            info = ("  Quelle: DWD über Bright Sky (nächste Station bis 5 km)."
                    + ("" if rev_sst.get(name) else " Ohne Wassertemperatur (Binnensee): keine Stabilitätsklassen.")
                    + _zeitpruefung_text(rows))
        kalib_bericht(name, rows, tab, info)
        if tab:
            ergebnis[name] = {"lat": lat, "lon": lon, "revier": rev_id.get(name, "ostsee"), **tab}
    if args.demo:
        return
    if not ergebnis:
        sys.exit("\nKeine Kalibrierung berechnet.")
    # zusammenführen: Stationen anderer Reviere (oder dieses Mal nicht gerechnete) bleiben erhalten
    alle = {n: t for n, t in kalib_laden().items() if n not in ergebnis}
    alle.update(ergebnis)
    KALIB_DATEI.write_text(json.dumps({"erstellt": datetime.now().isoformat(timespec="minutes"),
                                       "modelle": KALIB_MODELLE, "stationen": alle}), encoding="utf-8")
    wirken = [n for n, t in ergebnis.items() if t["wirkt"]]
    print(f"\nGeschrieben: {KALIB_DATEI.name}. Stationen mit belastbarem Gewinn: "
          f"{', '.join(wirken) if wirken else 'keine'}.")
    print("Angewandt wird nur für Spots, die du im Skript in KALIB_SPOTS einer Station zuordnest – die")
    print("Faktoren enthalten auch den Standort der Station (Anströmung über Land oder Wasser) und passen")
    print("nur für Spots mit ähnlicher Umgebung. Spots im Umkreis der Stationen (Entfernung):")
    for n in wirken:
        km = sorted((_abstand_km(sp.lat, sp.lon, ergebnis[n]["lat"], ergebnis[n]["lon"]), sp.name) for sp in SPOTS)
        nah = [f"{name} ({d:.0f} km)" for d, name in km if d <= KALIB_REICHWEITE_KM]
        print(f"  {n}: {', '.join(nah) if nah else 'keiner im Umkreis'}")
    print('Beispiel: KALIB_SPOTS = {"Westerbergen/Lemkenhafen": "Fehmarn"}. Prüf die Wirkung mit dem Logbuch.')


# ---- Modellvergleich: welches Modell trifft die Messung am besten? --------------------------------------

# Ab wann das Open-Meteo-Archiv (Historical Forecast, jeweils die ersten Stunden jedes Laufs) ein Modell enthält.
MODELL_ARCHIV_AB = {"icon_seamless": date(2022, 11, 24), "gfs_seamless": date(2022, 11, 24),
                    "metno_nordic": date(2022, 11, 24), "ukmo_seamless": date(2022, 11, 24),
                    "ecmwf_ifs025": date(2024, 2, 3),
                    "dmi_harmonie_arome_europe": date(2024, 7, 1), "knmi_harmonie_arome_europe": date(2024, 7, 1)}
# Zusatzmodelle nur für --modelldifferenz: Im Livelauf ist "icon_seamless" nur bis ~48 h ICON-D2 (2 km), danach ICON-EU
# (6,5 km) und ab ~5 Tagen ICON global (13 km). Das Archiv (erste Stunden jedes Laufs) kennt nur das feine ICON.
# So lässt sich prüfen, was ein 13-km-Produkt (vergleichbar mit dem Windfinder-Superforecast) in der Bucht anders macht.
MODELL_13KM = {"icon_eu": date(2022, 11, 24), "icon_global": date(2022, 11, 24)}
# Archivmodelle je Revier (nur Modelle, deren Gebiet das Revier abdeckt; MeteoSwiss erst ab 29.07.2025)
MODELL_ARCHIV_REVIER: Dict[str, Dict[str, date]] = {
    "bodensee": {"icon_seamless": date(2022, 11, 24), "gfs_seamless": date(2022, 11, 24),
                 "ukmo_seamless": date(2022, 11, 24), "ecmwf_ifs025": date(2024, 2, 3),
                 "meteoswiss_icon_seamless": date(2025, 7, 29)},
}
for _r in ("walensee", "achensee", "romandie"):
    MODELL_ARCHIV_REVIER[_r] = dict(MODELL_ARCHIV_REVIER["bodensee"])
MODELL_BASIS = ("icon_seamless", "ecmwf_ifs025", "gfs_seamless")      # die drei, auf denen die Kalibrierung beruht


def _pearson(paare: List[Tuple[float, float]]) -> float:
    n = len(paare)
    mx, my = sum(a for a, _ in paare) / n, sum(b for _, b in paare) / n
    sxx = sum((a - mx) ** 2 for a, _ in paare)
    syy = sum((b - my) ** 2 for _, b in paare)
    return sum((a - mx) * (b - my) for a, b in paare) / math.sqrt(sxx * syy) if sxx > 0 and syy > 0 else 0.0


def modell_metriken(mess: Dict[datetime, float], reihen: Dict[str, Dict[datetime, float]],
                    min_kn: float = 8.0, min_n: int = 300, profile: Optional[List[str]] = None) -> Optional[dict]:
    """Vergleich auf gemeinsamen Stunden: Messung ≥ min_kn und alle Modelle mit genug Daten vorhanden.
    Je Modell: Faktor Messung/Modell (Median), MAE roh und nach Skalierung mit diesem Faktor, Korrelation.
    Dazu zwei Mittel: die drei Basismodelle und alle Modelle."""
    brauchbar = [m for m, r in reihen.items() if sum(1 for t in r if mess.get(t, 0) >= min_kn) >= min_n]
    if len(brauchbar) < 2:
        return None
    stunden = sorted(t for t in mess if mess[t] >= min_kn and all(t in reihen[m] for m in brauchbar))
    if len(stunden) < min_n:
        return None
    ergebnis: Dict[str, dict] = {}

    def auswerten(name: str, werte: List[float]) -> None:
        ms = [mess[t] for t in stunden]
        f = median([a / b for a, b in zip(ms, werte) if b > 1.0] or [1.0])
        ergebnis[name] = {"f": f, "mae0": sum(abs(b - a) for a, b in zip(ms, werte)) / len(ms),
                          "mae1": sum(abs(b * f - a) for a, b in zip(ms, werte)) / len(ms),
                          "r": _pearson(list(zip(werte, ms)))}

    for m in brauchbar:
        auswerten(m, [reihen[m][t] for t in stunden])
    basis = [m for m in MODELL_BASIS if m in brauchbar]
    if len(basis) >= 2:
        auswerten("Mittel Basis (" + "+".join(MODELL_KURZ.get(m, m) for m in basis) + ")",
                  [sum(reihen[m][t] for m in basis) / len(basis) for t in stunden])
    auswerten("Mittel alle", [sum(reihen[m][t] for m in brauchbar) / len(brauchbar) for t in stunden])
    for profil, gw in MODELL_GEWICHTE.items():
        if profile is not None and profil not in profile:
            continue
        summe = sum(_modell_gewicht(gw, m) for m in brauchbar)
        auswerten(f"Mittel gewichtet (Profil {profil})",
                  [sum(_modell_gewicht(gw, m) * reihen[m][t] for m in brauchbar) / summe for t in stunden])
    return {"n": len(stunden), "von": stunden[0], "bis": stunden[-1], "modelle": ergebnis,
            "ohne": [m for m in reihen if m not in brauchbar]}


def modell_sektoren(mess: Dict[datetime, float], reihen: Dict[str, Dict[datetime, float]],
                    wd: Dict[datetime, float], min_kn: float = 8.0, min_n: int = 300,
                    min_sektor: int = 30) -> Optional[dict]:
    """Faktor Messung/Modell (Median) je Windrichtungssektor (30°, nach Modell-Mittelrichtung) und Modell – auf den
    gleichen Stunden wie modell_metriken. Zeigt, welche Modelle bei einer Richtung das Niveau der Messung treffen."""
    brauchbar = [m for m, r in reihen.items() if sum(1 for t in r if mess.get(t, 0) >= min_kn) >= min_n]
    if len(brauchbar) < 2:
        return None
    stunden = [t for t in sorted(mess) if mess[t] >= min_kn and t in wd and all(t in reihen[m] for m in brauchbar)]
    if len(stunden) < min_n:
        return None
    je_sektor: Dict[int, List[datetime]] = {}
    for t in stunden:
        je_sektor.setdefault(int(((wd[t] + 15) % 360) // 30), []).append(t)
    erg: Dict[int, dict] = {}
    for k, ts in je_sektor.items():
        if len(ts) < min_sektor:
            continue
        z = {}
        for m in brauchbar:
            z[m] = median([mess[t] / reihen[m][t] for t in ts if reihen[m][t] > 1.0] or [1.0])
        z["Mittel alle"] = median([mess[t] / (sum(reihen[m][t] for m in brauchbar) / len(brauchbar))
                                   for t in ts])
        erg[k] = {"f": z, "n": len(ts), "tage": len({t.date() for t in ts})}
    return {"sektoren": erg, "modelle": brauchbar}


def modell_reihen_holen(lat: float, lon: float, von: date, bis: date,
                        zelle: str = "nearest", richtung: Optional[dict] = None, zusatz: bool = False,
                        modelle: Optional[Dict[str, date]] = None) -> Dict[str, Dict[datetime, float]]:
    """Modellwind (kn) je Modell einzeln aus dem Archiv; jedes Modell erst ab seinem Archivbeginn.
    Mit richtung={} wird zusätzlich {Modell: {Zeit: Windrichtung °}} eingetragen. modelle = andere Modellauswahl
    {Modell: Archivbeginn} (Reviere außerhalb von MET Nordic/DMI)."""
    quellen = dict(modelle or MODELL_ARCHIV_AB)
    if zusatz:
        quellen.update(MODELL_13KM)
    reihen: Dict[str, Dict[datetime, float]] = {m: {} for m in quellen}
    gruppen: Dict[date, List[str]] = {}
    for m, ab in quellen.items():
        gruppen.setdefault(ab, []).append(m)
    for ab, ms in sorted(gruppen.items()):
        start = max(von, ab)
        while start <= bis:
            ende = min(start + timedelta(days=89), bis)
            for h in _historie_stuecke(lat, lon, start, ende, ",".join(ms), zelle):
                for m in ms:
                    ws_ = _spalte(h, "wind_speed_10m", m)
                    if not ws_:
                        continue
                    for t_s, v in zip(h.get("time", []), ws_):
                        if v is not None:
                            reihen[m][datetime.fromisoformat(t_s)] = v
                    if richtung is not None:
                        wd_ = _spalte(h, "wind_direction_10m", m) or []
                        for t_s, v in zip(h.get("time", []), wd_):
                            if v is not None:
                                richtung.setdefault(m, {})[datetime.fromisoformat(t_s)] = v
            start = ende + timedelta(days=1)
    print("\r\033[2K", end="", file=sys.stderr, flush=True)
    return reihen


def modellvergleich(args, holer=None) -> None:
    """--modellvergleich [STATION …]: nutzt die Messreihen aus kalibrierung_rohdaten.json (erst --kalibrieren
    ausführen) und holt die Modelle einzeln. holer = Ersatz für modell_reihen_holen (Tests)."""
    holer = holer or modell_reihen_holen
    try:
        cache = json.loads(KALIB_ROHDATEN.read_text(encoding="utf-8"))
        koord = json.loads(KALIB_DATEI.read_text(encoding="utf-8")).get("stationen", {})
    except (OSError, ValueError):
        sys.exit("Erst `--kalibrieren` ausführen (liefert Messreihen und Stationskoordinaten).")
    namen = [n for n in koord if isinstance(cache.get(n), dict) and cache[n].get("rows")]
    if getattr(args, "revier", None):
        namen = [n for n in namen if koord[n].get("revier", "ostsee") == args.revier]
    if args.modellvergleich:
        wahl = [w.lower() for w in args.modellvergleich]
        namen = [n for n in namen if any(w in n.lower() for w in wahl)]
    if not namen:
        sys.exit("Keine passende Station mit Messreihe gefunden.")
    print("MODELLVERGLEICH · jedes Modell einzeln gegen die Messung (Archiv = erste Stunden jedes Modelllaufs)")
    print(f"Gitterzelle: {getattr(args, 'zelle', 'nearest')} ('sea' = wie die Spots im Livelauf, 'nearest' = nächste Zelle der Station)")
    print("Gemeinsame Stunden mit Messung ≥ 8 kn. 'Faktor' = Median Messung/Modell; 'MAE skal.' = Fehler nach Anwendung")
    print("dieses Faktors, also die Treffsicherheit unabhängig vom Niveau. Die Modelle haben unterschiedlich langes Archiv –")
    print("DMI und KNMI erst ab 07/2024, ECMWF ab 02/2024 –, der Vergleich gilt deshalb nur für die gemeinsame Zeit.")
    for n in namen:
        lat, lon = koord[n]["lat"], koord[n]["lon"]
        mess = {datetime.fromisoformat(r[0]): r[5] for r in cache[n]["rows"]}
        wd_modell = {datetime.fromisoformat(r[0]): r[1] for r in cache[n]["rows"]}
        von, bis = min(mess).date(), max(mess).date()
        print(f"\n{n.upper()} ({von:%d.%m.%Y}–{bis:%d.%m.%Y}) …", file=sys.stderr)
        rid = koord[n].get("revier", "ostsee")
        quellen = MODELL_ARCHIV_REVIER.get(rid) or MODELL_ARCHIV_AB
        try:
            if rid in MODELL_ARCHIV_REVIER:
                reihen = holer(lat, lon, von, bis, getattr(args, "zelle", "nearest"), modelle=quellen)
            else:
                reihen = holer(lat, lon, von, bis, getattr(args, "zelle", "nearest"))
        except RuntimeError as e:
            print(f"\n{n}: Modelle nicht abrufbar ({e})")
            continue
        revier_ids = {r["id"] for r in REVIERE}
        erg = modell_metriken(mess, reihen, profile=[rid] if rid != "ostsee"
                              else [p for p in MODELL_GEWICHTE if p not in revier_ids])
        if not erg:
            print(f"\n{n}: zu wenig gemeinsame Stunden für einen Vergleich.")
            continue
        print(f"\n{n.upper()} · {erg['n']} gemeinsame Stunden ({erg['von']:%d.%m.%Y}–{erg['bis']:%d.%m.%Y})"
              + (f" · ohne Daten: {', '.join(MODELL_KURZ.get(m, m) for m in erg['ohne'])}" if erg["ohne"] else ""))
        print(f"  {'Modell':<42}{'Faktor':>8}{'MAE roh':>10}{'MAE skal.':>11}{'r':>8}")
        for m, v in sorted(erg["modelle"].items(), key=lambda kv: kv[1]["mae1"]):
            print(f"  {MODELL_KURZ.get(m, m):<42}{'×%.2f' % v['f']:>8}{v['mae0']:>9.2f} {v['mae1']:>10.2f}{v['r']:>8.3f}")
        einzel = {m: v for m, v in erg["modelle"].items() if m in quellen}
        beste = min(v["mae1"] for v in einzel.values())
        vorschlag = {m: round((beste / v["mae1"]) ** 2, 1) for m, v in einzel.items()}
        print(f"  Gewichte aus der Treffsicherheit, (beste/MAE)² – nur ein Hinweis für MODELL_GEWICHTE"
              f"{'' if rid == 'ostsee' else '[' + chr(34) + rid + chr(34) + ']'}: "
              + ", ".join(f"{m} {x:g}" for m, x in sorted(vorschlag.items(), key=lambda kv: -kv[1])))
        if getattr(args, "sektoren", False):
            sek = modell_sektoren(mess, reihen, wd_modell)
            if not sek:
                print("  (zu wenig Stunden für die Auswertung nach Richtung)")
                continue
            ms = sorted(sek["modelle"], key=lambda m: (m not in MODELL_FEIN, m))
            print(f"\n  Faktor Messung/Modell je Richtung (Median; Sektor nach Modell-Mittelrichtung, ≥ 30 Stunden)."
                  f"\n  Ein Modell trifft das Niveau, wenn sein Faktor bei ×1,00 liegt; fein = {', '.join(MODELL_KURZ.get(m, m) for m in ms if m in MODELL_FEIN)}")
            print(f"  {'Richtung':<9}{'Std/Tage':>12}" + "".join(f"{MODELL_KURZ.get(m, m)[:10]:>12}" for m in ms) + f"{'Mittel alle':>12}")
            for k in range(12):
                e = sek["sektoren"].get(k)
                if not e:
                    continue
                print(f"  {kompass(k * 30):<9}{('%d/%dd' % (e['n'], e['tage'])):>12}"
                      + "".join(f"{'×%.2f' % e['f'][m]:>12}" for m in ms) + f"{'×%.2f' % e['f']['Mittel alle']:>12}"
                      + ("   ← Ost" if k in DIFF_SEKTOREN_OST else ""))


# ---- Modelldifferenz: feine gegen grobe Modelle, ohne Messung -------------------------------------------
MODELL_FEIN = ("icon_seamless", "dmi_harmonie_arome_europe", "knmi_harmonie_arome_europe", "metno_nordic",
               "ukmo_seamless", "meteoswiss_icon_seamless")                    # 1–5,5 km (ICON-D2, AROME, MET Nordic, UKV)
MODELL_GROB = ("ecmwf_ifs025", "gfs_seamless")     # ≈ 25 km
DIFF_STANDARD_SPOTS = ["Grönwohld", "Heidkate"]
# Keine Referenz ist frei von Küsteneinfluss: Leuchtturm = Mündung der Kieler Förde, Fehmarnbelt = Meerenge (eigene
# Kanalisierung). Deshalb zusätzlich zwei Punkte im offenen Wasser, je ≥ 15–25 km von der nächsten Küste.
DIFF_REFERENZ = [("Kiel Leuchtturm", 54.4997, 10.2736), ("Fehmarnbelt", 54.60, 11.15),
                 ("Kieler Bucht offen", 54.62, 10.55), ("Mecklenb. Bucht", 54.25, 11.30)]
DIFF_SEKTOREN_OST = (2, 3)                         # ONO, O (45–105°); OSO bleibt draußen: dort kommt der Wind über Land


def modelldifferenz_reihe(reihen: Dict[str, Dict[datetime, float]], rich: Dict[str, Dict[datetime, float]],
                          min_kn: float = 8.0) -> Optional[dict]:
    """Je Stunde ln(Mittel feine Modelle / Mittel grobe Modelle), nach 30°-Sektor der Mittelrichtung sortiert.
    Nur Modelle mit mindestens 80 % der Stunden des vollsten Modells, nur Stunden, in denen alle da sind –
    die Zusammensetzung bleibt so über die Zeit gleich. Stunden mit Mittelwind aller Modelle < min_kn entfallen."""
    anzahl = {m: len(r) for m, r in reihen.items() if r and rich.get(m)}
    if not anzahl:
        return None
    voll = max(anzahl.values())
    fein = [m for m in MODELL_FEIN if anzahl.get(m, 0) >= 0.8 * voll]
    grob = [m for m in MODELL_GROB if anzahl.get(m, 0) >= 0.8 * voll]
    if len(fein) < 2 or not grob:
        return None
    alle = fein + grob
    stunden = sorted(set.intersection(*(set(reihen[m]) & set(rich[m]) for m in alle)))
    sektor: Dict[int, List[Tuple[datetime, float]]] = {}
    einzel: Dict[str, Dict[int, List[Tuple[datetime, float]]]] = {m: {} for m in fein}
    zusatz = [m for m in MODELL_13KM if anzahl.get(m, 0) >= 0.8 * voll]
    km13: Dict[str, Dict[int, List[Tuple[datetime, float]]]] = {m: {} for m in zusatz}
    for t in stunden:
        w_f = sum(reihen[m][t] for m in fein) / len(fein)
        w_g = sum(reihen[m][t] for m in grob) / len(grob)
        mittel = sum(reihen[m][t] for m in alle) / len(alle)
        if mittel < min_kn or w_f <= 0.5 or w_g <= 0.5:
            continue
        wd = vektor_mittel([(reihen[m][t], rich[m][t]) for m in alle])[1]
        k = int(((wd + 15) % 360) // 30)
        sektor.setdefault(k, []).append((t, math.log(w_f / w_g)))
        for m in fein:
            if reihen[m][t] > 0.5:
                einzel[m].setdefault(k, []).append((t, math.log(reihen[m][t] / w_g)))
        for m in zusatz:
            if t in reihen[m] and reihen[m][t] > 0.5:
                km13[m].setdefault(k, []).append((t, math.log(w_f / reihen[m][t])))     # >0: 13-km-Modell niedriger als fein
    return {"fein": fein, "grob": grob, "sektor": sektor, "einzel": einzel, "km13": km13,
            "n": sum(len(v) for v in sektor.values())}


def _diff_zelle(eintraege: List[Tuple[datetime, float]]) -> Optional[Tuple[float, int, int]]:
    """(Median-Verhältnis fein/grob, Stunden, verschiedene Tage) oder None bei zu wenig Daten."""
    if len(eintraege) < 30:
        return None
    return math.exp(median(x for _, x in eintraege)), len(eintraege), len({t.date() for t, _ in eintraege})


def modelldifferenz(args, holer=None) -> None:
    """--modelldifferenz [SPOT …]: Verhältnis feine/grobe Modelle je Windrichtung am Spot und an zwei
    Referenzpunkten über offenem Wasser. Keine Messung nötig – es zeigt, ob die feinen Modelle in einer Bucht
    für bestimmte Richtungen systematisch mehr Wind rechnen als am freien Wasser (Düse/Kanalisierung, die
    das grobe Gitter nicht auflöst) oder nur überall mehr (bessere Wasser-/Landdarstellung)."""
    holer = holer or modell_reihen_holen
    namen = args.modelldifferenz or DIFF_STANDARD_SPOTS
    orte = []
    for n in namen:
        sp = [s for s in SPOTS if n.lower() in s.name.lower()]
        if not sp:
            sys.exit(f"Spot '{n}' nicht gefunden.")
        orte.append((sp[0].name, sp[0].lat, sp[0].lon))
    orte += [o for o in DIFF_REFERENZ if o[0] not in {x[0] for x in orte}]
    bis = date.today() - timedelta(days=3)
    von = bis - timedelta(days=int(365 * getattr(args, "jahre", 2.0)))
    zelle = getattr(args, "zelle", "sea")
    erg = {}
    for name, lat, lon in orte:
        print(f"\n{name} …", file=sys.stderr)
        rich: dict = {}
        try:
            reihen = holer(lat, lon, von, bis, zelle, rich, zusatz=True)
        except RuntimeError as e:
            print(f"\n{name}: Modelle nicht abrufbar ({e})")
            continue
        r = modelldifferenz_reihe(reihen, rich)
        if r:
            erg[name] = r
    if not erg:
        sys.exit("Keine auswertbaren Modellreihen.")
    erste = next(iter(erg.values()))
    print("MODELLDIFFERENZ · feine gegen grobe Modelle (Archiv, ohne Messung)")
    print(f"Fein: {', '.join(MODELL_KURZ.get(m, m) for m in erste['fein'])} · Grob: "
          f"{', '.join(MODELL_KURZ.get(m, m) for m in erste['grob'])}")
    print(f"Zeitraum {von:%d.%m.%Y}–{bis:%d.%m.%Y}, Gitterzelle {zelle}, nur Stunden mit Mittelwind aller Modelle ≥ 8 kn.")
    print("Zahl = Median Wind fein / Wind grob je Sektor der Mittelrichtung; ×1,00 = gleich. (Stunden/Tage) – die Stunden")
    print("sind stark korreliert, belastbar ist eher die Zahl der Tage. Zellen mit < 30 Stunden bleiben leer.")
    spalten = list(erg)
    print(f"\n  {'Richtung':<10}" + "".join(f"{n[:16]:>20}" for n in spalten))
    for k in range(12):
        zeile = f"  {kompass(k * 30):<10}"
        for n in spalten:
            z = _diff_zelle(erg[n]["sektor"].get(k, []))
            zeile += f"{('×%.2f (%d/%dd)' % (z[0], z[1], z[2])) if z else '–':>20}"
        print(zeile + ("   ← Ost" if k in DIFF_SEKTOREN_OST else ""))
    print()
    ost = {}
    for n in spalten:
        z = _diff_zelle([x for k in DIFF_SEKTOREN_OST for x in erg[n]["sektor"].get(k, [])])
        ost[n] = z
    zeile = f"  {'Ost ONO+O':<10}"
    for n in spalten:
        z = ost[n]
        zeile += f"{('×%.2f (%d/%dd)' % (z[0], z[1], z[2])) if z else '–':>20}"
    print(zeile)
    ref = [ost[n][0] for n, _, _ in DIFF_REFERENZ if n in ost and ost[n]]
    if ref:
        r0 = sum(ref) / len(ref)
        print(f"\nReferenz über freiem Wasser (Ost): ×{r0:.2f}. Bucht-Effekt = Spot / Referenz:")
        for n, *_ in orte:
            if n in ost and ost[n] and n not in {x[0] for x in DIFF_REFERENZ}:
                print(f"  {n}: ×{ost[n][0] / r0:.2f}")
        # jedes feine Modell einzeln gegen das grobe Mittel (Ost = ONO+O) – ein einzelnes Modell kann im Mittel untergehen
        print("\nEinzelmodelle gegen das grobe Mittel, Ost (ONO+O), und Bucht-Effekt je Modell (Spot / Mittel der Referenzen):")
        print(f"  {'Modell':<14}" + "".join(f"{n[:16]:>20}" for n in spalten) + "".join(
            f"{('Effekt ' + n[:9]):>18}" for n, *_ in orte if n not in {x[0] for x in DIFF_REFERENZ}))
        for m in erste["fein"]:
            zeile, wert = f"  {MODELL_KURZ.get(m, m):<14}", {}
            for n in spalten:
                z = _diff_zelle([x for k in DIFF_SEKTOREN_OST for x in erg[n]["einzel"].get(m, {}).get(k, [])])
                wert[n] = z[0] if z else None
                zeile += f"{('×%.2f' % z[0]) if z else '–':>20}"
            refm = [wert[n] for n, _, _ in DIFF_REFERENZ if wert.get(n)]
            for n, *_ in orte:
                if n in {x[0] for x in DIFF_REFERENZ}:
                    continue
                zeile += f"{('×%.2f' % (wert[n] / (sum(refm) / len(refm)))) if wert.get(n) and refm else '–':>18}"
            print(zeile)
        # 13-km-Produkte (ICON-EU/global, wie sie der Livelauf ab Tag 3 benutzt und wie ein 13-km-Superforecast): fein / 13 km,
        # getrennt nach Ost (ONO+O) und allen übrigen Richtungen. Nur ein Effekt, der bei Ost in der Bucht stärker ist
        # als bei den übrigen Richtungen und als an den Referenzen, spräche für "das grobe Gitter übersieht die Bucht".
        m13 = [m for m in MODELL_13KM if any(m in erg[n]["km13"] for n in spalten)]
        if m13:
            print("\nFein / 13-km-Modell (>×1,00 = das 13-km-Modell rechnet weniger Wind als die feinen), Ost gegen übrige Richtungen:")
            print(f"  {'':<26}" + "".join(f"{n[:16]:>20}" for n in spalten))
            eff_orte = [n for n, *_ in orte if n not in {x[0] for x in DIFF_REFERENZ}]
            for m in m13:
                wert = {"Ost": {}, "übrige": {}}
                for art, sek in (("Ost", DIFF_SEKTOREN_OST), ("übrige", tuple(k for k in range(12) if k not in DIFF_SEKTOREN_OST))):
                    zeile = f"  {MODELL_KURZ.get(m, m) + ' ' + art:<26}"
                    for n in spalten:
                        z = _diff_zelle([x for k in sek for x in erg[n]["km13"].get(m, {}).get(k, [])])
                        wert[art][n] = z[0] if z else None
                        zeile += f"{('×%.2f (%d/%dd)' % (z[0], z[1], z[2])) if z else '–':>20}"
                    print(zeile)
                for art in ("Ost", "übrige"):
                    refm = [wert[art][n] for n, _, _ in DIFF_REFERENZ if wert[art].get(n)]
                    if refm:
                        r0 = sum(refm) / len(refm)
                        print(f"  Bucht-Effekt {MODELL_KURZ.get(m, m)} {art} (Spot / Referenz ×{r0:.2f}): "
                              + ", ".join(f"{n} ×{wert[art][n] / r0:.2f}" for n in eff_orte if wert[art].get(n)))
        print("Deutung: Liegt ein Spot deutlich über der Referenz (> ×1,05) und über mehrere Dutzend Tage, rechnen die feinen")
        print("Modelle dort für Ost etwas, das die groben nicht sehen – passend zu einer Düse in der Bucht. Liegt er bei der")
        print("Referenz, sind feine Modelle nur überall etwas windiger (bessere Wasserdarstellung) und es gibt keinen Hinweis")
        print("auf eine Düse. Ob die feinen Modelle recht haben, zeigt nur eine Messung in der Bucht.")


def kalib_laden() -> Dict[str, dict]:
    try:
        return json.loads(KALIB_DATEI.read_text(encoding="utf-8")).get("stationen", {})
    except (OSError, ValueError):
        return {}


def kalib_niveau(tab: dict) -> float:
    return min(KALIB_NIVEAU_GRENZEN[1], max(KALIB_NIVEAU_GRENZEN[0], math.exp(tab["g"])))


def kalib_faktor(spot: "Spot", wd: float, ws: float, luft: Optional[float], wasser: Optional[float],
                 monat: Optional[int] = None) -> Tuple[float, Optional[str]]:
    """Faktor der in KALIB_SPOTS zugeordneten Station und Hinweistext; (1.0, None), wenn nichts zugeordnet
    ist oder die Station keinen belastbaren Gewinn zeigt. (Zusammen mit dem Ostwind-Düse-Faktor eines
    Spots multipliziert sich beides – dann bewusst einen von beiden weglassen.)"""
    name = KALIB_SPOTS.get(spot.name)
    if not KALIB or not name or name not in KALIB:
        return 1.0, None
    dt = None if (luft is None or wasser is None) else luft - wasser
    f = kalib_rel(KALIB[name], wd, ws, dt, monat)
    if KALIB[name].get("niveau"):
        f *= kalib_niveau(KALIB[name])
    if abs(f - 1) < 0.02:
        return 1.0, None
    b = kalib_klassen(wd, ws, kalib_dt_adj(KALIB[name], dt, monat))[1]
    return f, f"Kalibrierung {name} ×{f:.2f} ({kompass(wd)}" + (f", {STAB_NAMEN[b]})" if b is not None and KALIB_STAB_ANWENDEN else ")")


def wasser_zu(d: "OrtDaten", t: datetime) -> Optional[float]:
    """Wassertemperatur zur Stunde, sonst Mittel des Tages."""
    v = d.wasser.get(t)
    if v is not None:
        return v
    tag = [x for t_, x in d.wasser.items() if t_.date() == t.date()]
    return sum(tag) / len(tag) if tag else None


# =============================================================================
# VALIDIERUNG: Prognosen archivieren und mit DWD-Messwerten vergleichen
# =============================================================================

def archiv_speichern(punkte: List[OrtDaten], jetzt: datetime, namen: Optional[List[str]] = None) -> None:
    """Hängt pro Lauf eine Zeile an prognosen.jsonl an: Mittelwind je Modell und Stunde
    für die Validierungspunkte, ab jetzt bis Vorhersageende (ohne Korrekturfaktoren)."""
    eintrag = {"lauf": jetzt.isoformat(timespec="minutes"), "punkte": {}}
    for name, od in zip(namen or [n for n, _, _ in VALIDIERUNG], punkte):
        nach_zeit = {st.t: st for st in od.stunden if st.t >= jetzt - timedelta(hours=1)}
        if not nach_zeit:
            continue
        t0, t1 = min(nach_zeit), max(nach_zeit)
        n = int((t1 - t0).total_seconds() // 3600) + 1
        zeiten = [t0 + timedelta(hours=i) for i in range(n)]
        modelle = {}
        for m in od.modelle:
            werte = [round(nach_zeit[t].werte[m], 1) if t in nach_zeit and m in nach_zeit[t].werte
                     else None for t in zeiten]
            if any(v is not None for v in werte):
                modelle[m] = werte
        eintrag["punkte"][name] = {"t0": t0.isoformat(timespec="minutes"), "ws": modelle,
                                   "wd": [round(nach_zeit[t].wd) if t in nach_zeit else None for t in zeiten]}
    if eintrag["punkte"]:
        with open(ARCHIV, "a", encoding="utf-8") as f:
            f.write(json.dumps(eintrag) + "\n")


def hole_messreihe(lat: float, lon: float, von: datetime, bis: datetime
                   ) -> Tuple[Dict[datetime, Tuple[float, Optional[float], Optional[float]]], str]:
    """Stündliche Messwerte der nächsten DWD-Station über Bright Sky:
    {Zeit: (Mittelwind kn, Böe kn oder None, Richtung ° oder None)}."""
    werte: Dict[datetime, Tuple[float, Optional[float], Optional[float]]] = {}
    stationen = set()
    start = von.replace(minute=0)
    while start < bis:
        ende = min(start + timedelta(days=7), bis)
        params = {"lat": lat, "lon": lon, "date": start.strftime("%Y-%m-%dT%H:%M"),
                  "last_date": ende.strftime("%Y-%m-%dT%H:%M"), "max_dist": 5000,
                  "tz": "Europe/Berlin"}
        url = BRIGHTSKY + "?" + urllib.parse.urlencode(params)
        daten = None
        for versuch in range(1, VERSUCHE + 1):
            try:
                time_mod.sleep(PAUSE_S)
                daten = _get_json(url)[0]
                break
            except RuntimeError as e:
                if "404" in str(e):          # Bright Sky: für diese Woche keine Station/Daten
                    break
                if versuch == VERSUCHE:
                    raise
                time_mod.sleep(5 * versuch)
        quellen = {q.get("id"): q for q in (daten or {}).get("sources", [])}
        for r in (daten or {}).get("weather", []):
            q = quellen.get(r.get("source_id"), {})
            if q.get("observation_type") == "forecast" or r.get("wind_speed") is None:
                continue
            t = datetime.fromisoformat(r["timestamp"]).replace(tzinfo=None)
            boe = r.get("wind_gust_speed")
            werte[t] = (r["wind_speed"] / 1.852,                       # km/h → kn
                        None if boe is None else boe / 1.852,
                        r.get("wind_direction"))
            if q.get("station_name"):
                stationen.add(f'{q["station_name"]} ({q.get("observation_type", "?")})')
        start = ende
    return werte, ", ".join(sorted(stationen)) or "keine Station gefunden"


def hole_messwerte(lat: float, lon: float, von: datetime, bis: datetime) -> Tuple[Dict[datetime, float], str]:
    """Stündliche Messwerte (Mittelwind in kn) der nächsten DWD-Station über Bright Sky."""
    reihe, quelle = hole_messreihe(lat, lon, von, bis)
    return {t: v[0] for t, v in reihe.items()}, quelle


# =============================================================================
# JETZT-CHECK: Messung der letzten Stunden gegen die Vorhersage
# =============================================================================

JETZT_STUNDEN = 3          # so viele Stunden zurück werden verglichen
VERLAUF_STUNDEN = 48       # Messverlauf (Revier- und Spotseite): so weit zurück, dazu 24 h Vorhersage (08.11.2026)
VORTAG_BYTES = 14_000_000  # so viel vom Ende von prognosen.jsonl lesen (reicht für gut 3 Tage Läufe)
# Jede Jetzt-Messung wird mitgeschrieben: Bright Sky liefert für manche Stationen (Kiel Leuchtturm) nur die letzten
# Stunden, nicht die Vergangenheit – --validieren nimmt dann diese Mitschrift.
MESS_ARCHIV = Path(__file__).resolve().parent / "messung_archiv.jsonl"


def mess_archiv_schreiben(name: str, reihe: Dict[datetime, tuple]) -> None:
    try:
        with MESS_ARCHIV.open("a", encoding="utf-8") as f:
            z = {"name": name, "w": {t.strftime("%Y-%m-%dT%H:%M"): v[0] for t, v in reihe.items()
                                     if v and v[0] is not None}}
            d_ = {t.strftime("%Y-%m-%dT%H:%M"): round(v[2]) for t, v in reihe.items()      # 23.11.2026: Richtung
                  if v and v[0] is not None and len(v) > 2 and v[2] is not None}
            if d_:
                z["d"] = d_
            f.write(json.dumps(z) + "\n")
    except OSError:
        pass


_MESS_CACHE: Optional[Dict[str, Dict[datetime, float]]] = None


def mess_archiv_cache(name: str) -> Dict[datetime, float]:
    """Wie mess_archiv_lesen, aber die Datei nur einmal je Lauf lesen (nur die letzten Tage)."""
    global _MESS_CACHE
    if _MESS_CACHE is None:
        _MESS_CACHE = {}
        grenze = datetime.now() - timedelta(days=4)
        try:
            for z in MESS_ARCHIV.read_text(encoding="utf-8").splitlines()[-20000:]:
                try:
                    d = json.loads(z)
                except ValueError:
                    continue
                ziel = _MESS_CACHE.setdefault(d.get("name", ""), {})
                for t, v in (d.get("w") or {}).items():
                    tt = datetime.fromisoformat(t)
                    if tt >= grenze:
                        ziel[tt] = v
        except OSError:
            pass
    return _MESS_CACHE.get(name, {})


def mess_archiv_lesen_voll(name: str) -> Dict[datetime, Tuple[float, Optional[float]]]:
    """Eigene Mitschrift mit Richtung (die steht erst seit 23.11.2026 drin, sonst None)."""
    aus: Dict[datetime, Tuple[float, Optional[float]]] = {}
    try:
        for z in MESS_ARCHIV.read_text(encoding="utf-8").splitlines():
            if f'"name": "{name}"' not in z:
                continue
            try:
                d = json.loads(z)
            except ValueError:
                continue
            ri = d.get("d") or {}
            aus.update({datetime.fromisoformat(t): (v, ri.get(t)) for t, v in d.get("w", {}).items()})
    except OSError:
        pass
    return aus


def mess_archiv_lesen(name: str) -> Dict[datetime, float]:
    aus: Dict[datetime, float] = {}
    try:
        for z in MESS_ARCHIV.read_text(encoding="utf-8").splitlines():
            try:
                d = json.loads(z)
            except ValueError:
                continue
            if d.get("name") == name:
                aus.update({datetime.fromisoformat(t): v for t, v in d.get("w", {}).items()})
    except OSError:
        pass
    return aus


BRIGHTSKY_AKTUELL = BRIGHTSKY.replace("/weather", "/current_weather")
JETZT_BASIS = Path(__file__).resolve().parent / "jetzt_basis.json"   # Vorhersage je Station für den 10-Minuten-Lauf
JETZT_DATEI = "jetzt.json"                                          # in daten/: frischer Jetzt-Abschnitt (DE/EN)
JETZT_TAKT_MIN = 10                                                 # so oft holt die Seite jetzt.json neu


def hole_aktuell(lat: float, lon: float) -> Optional[Tuple[datetime, float, Optional[float], Optional[float]]]:
    """Neueste Messung (10-Minuten-Mittel, sonst 30/60) der nächsten DWD-Station über Bright Sky – oder None."""
    url = BRIGHTSKY_AKTUELL + "?" + urllib.parse.urlencode({"lat": lat, "lon": lon, "max_dist": 5000,
                                                              "tz": "Europe/Berlin"})
    try:
        d = _get_json(url)[0]
    except (RuntimeError, IndexError):
        return None
    w = (d or {}).get("weather") or {}

    def erst(*k):
        return next((w[x] for x in k if w.get(x) is not None), None)
    ws = erst("wind_speed_10", "wind_speed_30", "wind_speed_60", "wind_speed")
    if ws is None or not w.get("timestamp"):
        return None
    boe = erst("wind_gust_speed_10", "wind_gust_speed_30", "wind_gust_speed_60", "wind_gust_speed")
    try:
        t = datetime.fromisoformat(w["timestamp"]).replace(tzinfo=None)
    except ValueError:
        return None
    return t, ws / 1.852, None if boe is None else boe / 1.852, erst("wind_direction_10", "wind_direction_30",
                                                                        "wind_direction_60", "wind_direction")


def jetzt_live(quelle: str) -> bool:
    """Liefert die Quelle zeitnah (für „Jetzt“)? DWD, DMI, MeteoSwiss, KNMI mit Schlüssel – GHCNh kommt Stunden später."""
    return (quelle == "dwd" or quelle.startswith(("dmi:", "msw:", "geosphere:", "trentino:"))
            or (quelle.startswith("knmi:") and bool(knmi_schluessel())))


def jetzt_stationen() -> List[Tuple[str, float, float, str, str]]:
    """(Name, Breite, Länge, Quelle, Revier) aller Stationen mit zeitnahen Messungen – Ostsee zuerst."""
    return [x for x in stationen_liste() if jetzt_live(x[3]) and x[0] not in VALID_GETRENNT]


def jetzt_aktuell(quelle: str, lat: float, lon: float) -> Optional[Tuple[datetime, float, Optional[float], Optional[float]]]:
    """Neueste (10-Minuten-)Messung einer Quelle oder None – nie ein Abbruchgrund."""
    try:
        if quelle == "dwd":
            return hole_aktuell(lat, lon)
        q = messquelle(quelle)
        return q.aktuell() if q is not None and hasattr(q, "aktuell") else None
    except Exception:                        # Zugabe: ohne 10-Minuten-Wert bleibt der Stundenwert
        return None


def jetzt_check_alle(eintraege: List[Tuple[str, float, float, str, str, OrtDaten]], jetzt: datetime,
                     holer=None, archiv: bool = True, zurueck_h: Optional[float] = None) -> Dict[str, List[dict]]:
    """Jetzt-Check für beliebige Stationen: [(Name, Br., Lä., Quelle, Revier, Vorhersage)] → {Revier: [Ergebnis]}.
    holer (Demo/Test) ersetzt alle Quellen; archiv=False im 10-Minuten-Lauf (Mitschrift nur im Hauptlauf)."""
    aus: Dict[str, List[dict]] = {}
    for name, lat, lon, quelle, rid, od in eintraege:
        if holer is not None:
            h, akt = holer, (lambda a, b: None)
        else:
            q = messquelle(quelle)
            h = q if q is not None else hole_messreihe
            akt = (lambda a, b, _q=quelle: jetzt_aktuell(_q, a, b))
        z_h = zurueck_h
        if z_h and quelle.startswith("msw:"):
            # MeteoSwiss: weiter zurück als „seit gestern Mittag“ stünde nur in der Jahresdatei (mehrere MB) –
            # der Rest kommt aus der eigenen Mitschrift
            z_h = min(z_h, (jetzt - datetime.combine(jetzt.date() - timedelta(days=1), time(14))).total_seconds() / 3600)
        try:
            erg = jetzt_check([od], jetzt, h, akt, stationen=[(name, lat, lon)], mitschreiben=archiv and holer is None,
                              zurueck_h=z_h)
            if z_h != zurueck_h and zurueck_h:      # Lücke aus der Mitschrift füllen
                for r in erg:
                    if r.get("reihe") is None:
                        r["reihe"] = {}
                    ab = jetzt - timedelta(hours=zurueck_h)
                    for t, v in mess_archiv_cache(name).items():
                        if ab <= t <= jetzt and t not in r["reihe"] and t.minute == 0:
                            r["reihe"][t] = (v, None, None)
        except Exception as ex:              # eine Station darf die anderen nicht aufhalten
            print(f"Hinweis: Jetzt {name} nicht geladen ({ex})", file=sys.stderr)
            continue
        for r in erg:
            r["revier"], r["quelle"] = rid, quelle
            aus.setdefault(rid, []).append(r)
    return aus


def jetzt_check(punkte: List[OrtDaten], jetzt: datetime, holer=None, aktuell=None,
                stationen: Optional[List[Tuple[str, float, float]]] = None, mitschreiben: Optional[bool] = None,
                zurueck_h: Optional[float] = None) -> List[dict]:
    """Je Messstation (VALIDIERUNG): letzte Messung, Abweichung zur Vorhersage, Trend, bestes Modell.
    holer = Funktion wie hole_messreihe (zum Testen austauschbar)."""
    if mitschreiben is None:
        mitschreiben = holer is None
    akt_vorgabe = aktuell or (hole_aktuell if holer is None else (lambda a, b: None))
    holer = holer or hole_messreihe
    ergebnis = []
    for (name, lat, lon), od in zip(stationen or VALIDIERUNG, punkte):
        try:
            reihe, station = holer(lat, lon, jetzt - timedelta(hours=zurueck_h or (JETZT_STUNDEN + 2)),
                                   jetzt + timedelta(hours=1))
        except RuntimeError as e:
            print(f"Hinweis: Messung {name} nicht geladen ({e})", file=sys.stderr)
            continue
        reihe = {t: v for t, v in reihe.items() if t <= jetzt + timedelta(minutes=5)}
        if mitschreiben and reihe:          # nur die letzten Stunden mitschreiben (sonst Dubletten bei langem Rückblick)
            mess_archiv_schreiben(name, {t: v for t, v in reihe.items()
                                         if t >= jetzt - timedelta(hours=JETZT_STUNDEN + 2)})
        if zurueck_h and zurueck_h > JETZT_STUNDEN + 2:
            # 08.11.2026 (Messverlauf): Lücken (Quelle liefert nicht so weit zurück, z. B. Kiel Leuchtturm über Bright
            # Sky) aus der eigenen Mitschrift füllen – dort nur Mittelwind
            ab = jetzt - timedelta(hours=zurueck_h)
            for t, v in mess_archiv_cache(name).items():
                if ab <= t <= jetzt and t not in reihe and t.minute == 0:
                    reihe[t] = (v, None, None)
        if not reihe:
            continue
        t_last = max(reihe)
        kn, boe, richtung = reihe[t_last]
        # Stundenwerte für Abweichung/Trend; angezeigt wird die neueste 10-Minuten-Messung, wenn es eine gibt
        akt = akt_vorgabe(lat, lon)
        t_anz = t_last
        if akt and t_last < akt[0] <= jetzt + timedelta(minutes=5):
            t_anz, kn, boe, richtung = akt[0], akt[1], akt[2], akt[3]
        fc = {st.t: st for st in od.stunden}
        recht = sorted(t for t in reihe if t > t_last - timedelta(hours=JETZT_STUNDEN) and t in fc)
        diffs = [reihe[t][0] - fc[t].ws for t in recht]
        # welches Modell lag in diesen Stunden am nächsten?
        fehler: Dict[str, List[float]] = {}
        for t in recht:
            for m, v in fc[t].werte.items():
                fehler.setdefault(m, []).append(abs(v - reihe[t][0]))
        bester = min(((sum(v) / len(v), m) for m, v in fehler.items() if len(v) >= max(2, len(recht) - 1)),
                     default=None)
        zeiten = sorted(t for t in reihe if t > t_last - timedelta(hours=JETZT_STUNDEN))
        trend = None
        if len(zeiten) >= 2:
            d_kn = reihe[zeiten[-1]][0] - reihe[zeiten[0]][0]
            trend = "zunehmend" if d_kn >= 2 else "nachlassend" if d_kn <= -2 else "gleichbleibend"
        bias = sum(diffs) / len(diffs) if diffs else None
        ausblick = []
        for k in range(1, 4):
            t = (t_last + timedelta(hours=k)).replace(minute=0)
            if t in fc:
                modell = fc[t].ws
                ausblick.append((t, modell, modell + (bias or 0.0)))
        ergebnis.append({"name": name, "station": station, "t": t_anz, "kn": kn, "boe": boe,
                         "richtung": None if richtung is None else kompass(richtung),
                         "alter_min": int((jetzt - t_anz).total_seconds() // 60),
                         "bias": bias, "n": len(diffs), "trend": trend,
                         "bestes": None if bester is None else (bester[1], bester[0]),
                         "ausblick": ausblick,
                         # für den Messverlauf (nur bei langem Rückblick, also im Hauptlauf)
                         "reihe": reihe if zurueck_h and zurueck_h > JETZT_STUNDEN + 2 else None, "od": od})
    return ergebnis


def vz(x: float) -> str:
    return f"{x:+.0f}".replace("-", "−")


def jetzt_basis_speichern(eintraege: list, min_kn: float, badges: str, jetzt: datetime) -> None:
    """Vorhersage je Station (−8 h … +30 h) für den 10-Minuten-Lauf merken – der rechnet dann ohne Open-Meteo."""
    st = []
    for name, lat, lon, quelle, rid, od in eintraege:
        st.append({"name": name, "lat": lat, "lon": lon, "quelle": quelle, "revier": rid,
                   "h": [[x.t.strftime("%Y-%m-%dT%H:%M"), round(x.ws, 2), {m: round(v, 2) for m, v in x.werte.items()}]
                         for x in od.stunden if jetzt - timedelta(hours=8) <= x.t <= jetzt + timedelta(hours=30)]})
    try:
        JETZT_BASIS.write_text(json.dumps({"erstellt": jetzt.isoformat(timespec="minutes"), "min_kn": min_kn,
                                           "badges": badges, "stationen": st}, ensure_ascii=False), encoding="utf-8")
    except OSError as ex:
        print(f"Hinweis: {JETZT_BASIS.name} nicht geschrieben ({ex})", file=sys.stderr)


def jetzt_datei_schreiben(ordner: Path, alle: Dict[str, List[dict]], min_kn: float, badges: Optional[str]) -> None:
    """daten/jetzt.json – die Seiten holen sie alle 10 Minuten. 08.11.2026: je Gleitgrenze (12/15/18, Blau ab der
    Grenze) unter "g": "r" Revier-Abschnitte, "s" Einzelwerte je Station (Spotseiten), "z" Zellen der Spalte „jetzt“
    der Übersicht samt "zt" (Uhrzeit). Plaketten (Pegel/Warnungen) gehören nur zur Kieler Bucht."""
    def zwei(html: str) -> dict:
        try:
            en = _en_fragment(html)
        except Exception:                    # Übersetzung nie ein Abbruchgrund
            en = html
        return {"de": html, "en": en}

    zeiten = [r["t"] for jc in alle.values() for r in jc if r.get("t")]
    if not zeiten:
        return
    t_all = max(zeiten)
    d = {"t": t_all.strftime("%Y-%m-%dT%H:%M"), "g": {}}
    for k in GLEIT_GRENZEN:
        g = {"r": {}, "s": {}, "z": {}, "zt": f"{t_all:%H:%M}"}
        for rid, jc in alle.items():
            if not jc:
                continue
            t = max(r["t"] for r in jc).strftime("%Y-%m-%dT%H:%M")
            g["r"][rid] = {"t": t, **zwei(jetzt_abschnitt(jc, float(k), badges if rid == "ostsee" else "", rid=rid))}
            g["z"][rid] = zwei(jetzt_zelle_html(rid, float(k), alle))
            for r in jc:
                if r.get("kn") is not None:
                    g["s"][r["name"]] = {"t": r["t"].strftime("%Y-%m-%dT%H:%M"), **zwei(jetzt_wert_html(r, float(k)))}
        d["g"][str(k)] = g
    tmp = ordner / (JETZT_DATEI + ".tmp")
    tmp.write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    tmp.replace(ordner / JETZT_DATEI)


def nur_jetzt(args) -> None:
    """--nur-jetzt (Cron alle 10 Minuten): nur die Messungen neu holen, Abschnitte „Jetzt“ als daten/jetzt.json
    schreiben und hochladen. Keine Open-Meteo-Abrufe; läuft gerade ein Hauptlauf, wird still ausgesetzt."""
    if lauf_sperren(still=True) is False:
        print("Hauptlauf aktiv – Jetzt-Lauf ausgesetzt.")
        return
    try:
        b = json.loads(JETZT_BASIS.read_text(encoding="utf-8"))
        erstellt = datetime.fromisoformat(b["erstellt"])
    except (OSError, ValueError, KeyError):
        print(f"{JETZT_BASIS.name} fehlt – erst einen normalen Lauf abwarten.")
        return
    jetzt = datetime.now()
    if jetzt - erstellt > timedelta(hours=9):
        print(f"{JETZT_BASIS.name} ist von {erstellt:%d.%m. %H:%M} – zu alt, Jetzt-Lauf ausgesetzt.")
        return
    eintraege = []
    for x in b.get("stationen", []):
        quelle, rid = x.get("quelle", "dwd"), x.get("revier", "ostsee")
        if not jetzt_live(quelle):
            continue
        stunden = [SimpleNamespace(t=datetime.fromisoformat(t), ws=ws, werte=werte) for t, ws, werte in x["h"]]
        eintraege.append((x["name"], x["lat"], x["lon"], quelle, rid, SimpleNamespace(stunden=stunden)))
    alle = jetzt_check_alle(eintraege, jetzt, archiv=False)
    if not alle:
        print("Keine Messungen erhalten.")
        return
    ordner = Path(OEFFENTLICH_HTML).resolve().parent / "daten"
    ordner.mkdir(parents=True, exist_ok=True)
    jetzt_datei_schreiben(ordner, alle, float(b.get("min_kn", MIN_KN)), b.get("badges", ""))
    for rid, jc in alle.items():
        print(f"Jetzt {rid}: " + " · ".join(f"{jetzt_name(r['name'])} {r['kn']:.0f} kn ({r['t']:%H:%M})" for r in jc))
    if not args.kein_upload:
        seiten_hochladen(Path(OEFFENTLICH_HTML).resolve().parent)


def jetzt_zeilen(jc: List[dict]) -> List[str]:
    zeilen = []
    for r in jc:
        z = f"{r['name']}: {r['kn']:.0f} kn"
        if r["richtung"]:
            z += f" {r['richtung']}"
        if r["boe"]:
            z += f", Böen {r['boe']:.0f}"
        z += f" ({r['t']:%H:%M}" + (f", vor {r['alter_min']} min" if r["alter_min"] > 20 else "") + ")"
        if r["trend"]:
            z += f" · {r['trend']}"
        zeilen.append(z)
        if r["bias"] is not None:
            if abs(r["bias"]) < 1.5:
                z2 = "Vorhersage passt (Abweichung unter 1,5 kn)"
            else:
                z2 = f"läuft {abs(r['bias']):.0f} kn {'stärker' if r['bias'] > 0 else 'schwächer'} als vorhergesagt"
            z2 += f" (Ø der letzten {r['n']} h)"
            if r["bestes"]:
                z2 += f" · am nächsten dran: {MODELL_KURZ.get(r['bestes'][0], r['bestes'][0])}"
            zeilen.append("   " + z2)
        if r["ausblick"]:
            teile = [f"{t:%H} Uhr {m:.0f}" + (f"→{a:.0f}" if abs(a - m) >= 1.5 else "")
                     for t, m, a in r["ausblick"]]
            zeilen.append("   Nächste Stunden (Modell" + ("→mit Abweichung" if r["bias"] and abs(r["bias"]) >= 1.5 else "")
                          + "): " + ", ".join(teile))
    return zeilen


