# Windfinder-Kürzel (aus den Windfinder-Webcam-Seiten …/webcams/<kürzel>). Weitere Spots einfach ergänzen.
WINDFINDER = {"Heidkate": "heidkate", "Laboe": "laboe", "Heiligenhafen": "heiligenhafen",
              "Pelzerhaken": "pelzerhaken", "Westerbergen/Lemkenhafen": "lemkenhafen"}
PEGEL_NAME = "Pegel Heiligenhafen"       # PEGELONLINE, Messstelle 9610070 (Ostsee)
PEGEL_URL = "https://www.pegelonline.wsv.de/gast/stammdaten?pegelnr=9610070"
# Eigene Links, überschreiben/ergänzen die automatischen. Beispiel:
# LINKS_EIGEN = {"Grönwohld": {"Webcam": "https://…"}, "Laboe": {"Parkplatz": "https://…"}}
LINKS_EIGEN: Dict[str, Dict[str, str]] = {}
AKTUELL: Dict[str, float] = {}           # aktuelle Messung je Station (vom Jetzt-Check gefüllt)
JETZT_ALLE: Dict[str, List[dict]] = {}   # Revier → Jetzt-Ergebnisse (seit 08.11.2026 alle Reviere mit Live-Stationen)
JETZT_EINTRAEGE: list = []               # (Name, Br., Lä., Quelle, Revier, Vorhersage) – für jetzt_basis.json


def spot_links(spot: "Spot") -> List[Tuple[str, str]]:
    """(Beschriftung, URL). Windfinder/Pegel sind feste Seiten; 'Webcam suchen' und 'Parkplatz' sind
    Suchlinks (Karte bzw. Websuche) und treffen den Spot nur ungefähr."""
    q = urllib.parse.quote_plus
    ort = spot.name.replace("(", "").replace(")", "")
    links: Dict[str, str] = {}
    slug = WINDFINDER.get(spot.name)
    if slug:
        links["Windfinder"] = f"https://www.windfinder.com/forecast/{slug}"
        links["Webcam"] = f"https://www.windfinder.com/webcams/{slug}"
    else:
        links["Webcam suchen"] = f"https://www.google.com/search?q={q('Webcam ' + ort + ' Strand')}"
    links["Windy"] = f"https://www.windy.com/{spot.lat:.3f}/{spot.lon:.3f}?wind,{spot.lat:.3f},{spot.lon:.3f},11"
    links["Parkplatz"] = f"https://www.google.com/maps/search/?api=1&query={q('Parkplatz ' + ort)}"
    if spot.pegel:
        links[PEGEL_NAME] = PEGEL_URL
    links.update(LINKS_EIGEN.get(spot.name, {}))
    return list(links.items())


def naechste_station(spot: "Spot") -> Tuple[str, float]:
    return min(((n, _abstand_km(spot.lat, spot.lon, la, lo)) for n, la, lo in VALIDIERUNG), key=lambda x: x[1])


def links_html(spot: "Spot") -> str:
    return " ".join(f'<a href="{e_txt(u)}" target="_blank" rel="noopener">{e_txt(l)}</a>'
                    for l, u in spot_links(spot))


