def demo_klima() -> dict:
    import random
    rnd = random.Random(3)
    k = {"erstellt": "demo", "von": "2024-10-27", "bis": "2026-10-25", "min_kn": MIN_KN, "stufe": DEINE_STUFE,
         "spots": {}, "reviere": {}}
    for r in REVIERE:
        basis = {"ostsee": 8, "westkueste": 10, "bodensee": 3, "garda": 6, "leucate": 12, "tarifa": 14}.get(r["id"], 5)
        z = [[max(0, round(basis * (1.3 if m in (0, 1, 2, 9, 10, 11) else 0.7) + rnd.gauss(0, 1.5))), 30, 2, 8] for m in range(12)]
        za = [[m[0] + (6 if 4 <= i <= 8 else 1), m[1], m[2], m[3]] for i, m in enumerate(z)]
        k["reviere"][r["id"]] = {"du": z, "alle": za}
        for sp in SPOTS:
            if revier_von(sp) == r["id"]:
                zs = [[max(0, round(m[0] * rnd.uniform(0.3, 0.9))), 30, 1, 8] for m in z]
                zsa = [[m[0] + (5 if 4 <= i <= 8 else 0), m[1], m[2], m[3]] for i, m in enumerate(zs)]
                k["spots"][sp.name] = {"revier": r["id"], "du": zs if sp.stufe <= DEINE_STUFE else None, "alle": zsa}
    return k


