def demo_ensemble(fahne_spots) -> List[dict]:
    """Erfundene Ensemble-Member: um das Modellmittel gestreut, Streuung wächst mit der Vorlaufzeit."""
    aus = []
    for k, (_, d) in enumerate(fahne_spots):
        zeiten = [s.t.strftime("%Y-%m-%dT%H:%M") for s in d.stunden]
        member = {}
        for m, n in (("icon_seamless", 20), ("ecmwf_ifs025", 30), ("gfs_seamless", 20)):
            reihen = []
            for j in range(n):
                reihen.append([max(0.0, round(s.ws * (1 + (i / 24) * 0.05 * math.sin(j * 1.7 + k + i / 11)), 1))
                               for i, s in enumerate(d.stunden)])
            member[m] = reihen
        aus.append({"time": zeiten, "member": member})
    return aus


def demo_rohdaten(anzahl_orte: int, tage: int) -> list:
    """Erfundene Wetterlage im Open-Meteo-Format zum Testen."""
    # (Richtung morgens, Richtung abends, kn morgens, kn abends, Regen-Stunde oder None)
    muster = [
        (240, 250, 20, 22, None),   # gestern: SW (für die Pegel-Warnung)
        (250, 265, 17, 13, None),
        (95, 100, 17, 19, None),    # Ost
        (55, 70, 21, 24, 15),       # Nordost, kräftig, Schauer
        (315, 355, 18, 19, None),   # NW dreht auf N
        (30, 40, 10, 8, None),      # zu schwach
        (225, 235, 19, 25, None),   # SW zunehmend
        (165, 175, 15, 18, None),   # Süd
        (300, 305, 26, 29, 11),     # Sturm-NW
    ]
    start = datetime.combine(date.today() - timedelta(days=1), time(0))
    roh = []
    for o in range(anzahl_orte):
        versatz = ((o * 37) % 7 - 3) * 0.5
        zeiten, ws, wg, wd, pr, wc = [], [], [], [], [], []
        for h in range((tage + 1) * 24):
            t = start + timedelta(hours=h)
            r1, r2, k1, k2, regen = muster[(h // 24) % len(muster)]
            x = t.hour / 23
            tagesgang = 1.0 + 0.12 * math.sin(math.pi * max(0, min(1, (t.hour - 8) / 10)))
            s = max(0.0, (k1 + (k2 - k1) * x) * tagesgang + versatz)
            zeiten.append(t.strftime("%Y-%m-%dT%H:%M"))
            ws.append(round(s, 1))
            wg.append(round(s * 1.25, 1))
            wd.append(round((r1 + (r2 - r1) * x) % 360))
            pr.append(1.5 if regen is not None and t.hour == regen else 0.0)
            wc.append(80 if regen is not None and t.hour == regen else 2)
        tage_liste = [(start + timedelta(days=i)).date() for i in range(tage + 1)]
        stunden = {"time": zeiten}
        for m, f, reichweite in DEMO_MODELLE:
            for var, werte in (("wind_speed_10m", ws), ("wind_gusts_10m", wg)):
                stunden[f"{var}_{m}"] = [round(v * f * (1 + 0.04 * math.sin(i / 7 + f * 9)), 1)
                                         if i < reichweite else None for i, v in enumerate(werte)]
            stunden[f"wind_direction_10m_{m}"] = wd
            stunden[f"temperature_2m_{m}"] = [round(9 + 3.5 * math.sin((t_h - 9) / 24 * 2 * math.pi) - 0.4 * (t_h // 24), 1)
                                              for t_h in range(len(zeiten))]
            stunden[f"precipitation_{m}"] = pr
            stunden[f"weather_code_{m}"] = wc
        roh.append({
            "hourly": stunden,
            "daily": {"time": [d.isoformat() for d in tage_liste],
                      "sunrise": [f"{d.isoformat()}T07:40" for d in tage_liste],
                      "sunset": [f"{d.isoformat()}T18:20" for d in tage_liste]},
        })
    return roh


